window.PATIMUNDO_CUIDADOS_PERROS = {
  "chapi": {
    "nombre": "Chapi",
    "etapas": {
      "cachorro": {
        "tituloOriginal": "CHAPI CACHORRO (DE 0 A 12 MESES)",
        "temas": {
          "alimentacion": {
            "titulo": "1. ALIMENTACIÓN",
            "secciones": [
              {
                "titulo": "ALIMENTACIÓN SALUDABLE",
                "items": [
                  "1. Alimento adecuado para cachorros: El chapi cachorro necesita un alimento completo y equilibrado para su etapa de crecimiento. Debe aportar proteínas, grasas, vitaminas y minerales que favorezcan el desarrollo de sus músculos, huesos, dientes y órganos. Lo más recomendable es elegir un alimento formulado específicamente para cachorros y adaptado a su tamaño.",
                  "2. Frecuencia de las comidas: Durante los primeros meses suele necesitar entre tres y cuatro comidas pequeñas al día, dependiendo de su edad y tamaño. Conforme crece, puede pasar gradualmente a tres comidas diarias. Mantener horarios regulares ayuda a controlar su apetito y establecer una rutina para hacer sus necesidades.",
                  "3. Agua fresca: Debe disponer de agua potable y limpia durante todo el día. El recipiente debe lavarse regularmente y el agua cambiarse cuando esté sucia. La hidratación es esencial para la digestión, la circulación y el funcionamiento de sus órganos.",
                  "4. Proteínas: Son necesarias para formar músculos y reparar tejidos. Un alimento completo para cachorros debe aportar proteínas suficientes para su desarrollo. No es necesario añadir carne a todas sus comidas si ya recibe una dieta equilibrada.",
                  "5. Grasas saludables: Proporcionan energía y ácidos grasos importantes para el desarrollo y el mantenimiento de la piel. Si consume un alimento completo, no necesita suplementos de aceite para mejorar el pelo, salvo indicación veterinaria.",
                  "6. Vitaminas y minerales: Participan en el desarrollo de los huesos, dientes y sistema inmunitario. No deben administrarse suplementos de calcio o vitaminas sin supervisión veterinaria, porque el exceso también puede perjudicarlo.",
                  "7. Porciones controladas: La cantidad de comida depende de su edad, peso, actividad y condición corporal. Conviene medir la ración diaria y ajustarla según su crecimiento, en lugar de servirle cantidades excesivas.",
                  "8. Cambios de alimento: Si es necesario cambiar su comida, hazlo gradualmente durante varios días. Los cambios bruscos pueden producir diarrea o molestias digestivas.",
                  "9. Premios saludables: Para el entrenamiento se pueden utilizar premios pequeños y apropiados para cachorros. No deben sustituir sus comidas ni representar una parte excesiva de su alimentación.",
                  "10. Alimentación casera equilibrada: Si deseas prepararle comida en casa, debe formularla un veterinario especializado en nutrición. Darle solamente pollo, arroz o verduras no garantiza que reciba todos los nutrientes necesarios para crecer.",
                  "11. Alimentación durante el destete: El destete suele comenzar alrededor de las tres o cuatro semanas de vida. Se introduce gradualmente alimento completo para cachorros humedecido, mientras se mantiene el cuidado materno cuando sea posible.",
                  "12. Leche para recién nacidos: La leche materna es preferible. Si el cachorro es huérfano o no puede mamar, necesita una fórmula específica para cachorros y orientación veterinaria. La leche de vaca no es un sustituto adecuado."
                ]
              },
              {
                "titulo": "ALIMENTACIÓN NO SALUDABLE",
                "items": [
                  "1. Chocolate y cafeína: Pueden provocar intoxicación y afectar el corazón y el sistema nervioso.",
                  "2. Uvas y pasas: Pueden ocasionar daño renal grave. Si las consume, debe recibir orientación veterinaria inmediata.",
                  "3. Cebolla y ajo: Pueden dañar los glóbulos rojos, incluso cuando forman parte de comidas cocinadas.",
                  "4. Xilitol: Este edulcorante presente en ciertos productos sin azúcar puede provocar una bajada peligrosa de glucosa.",
                  "5. Huesos cocidos: Pueden astillarse, causar atragantamiento u ocasionar lesiones digestivas.",
                  "6. Frituras y alimentos grasosos: Pueden provocar problemas digestivos y aumentar el riesgo de pancreatitis.",
                  "7. Comidas saladas o condimentadas: Los embutidos, las salsas y las sobras muy saladas no son adecuados para su alimentación habitual.",
                  "8. Leche de vaca: Puede causar gases, molestias abdominales y diarrea.",
                  "9. Carne y huevos crudos: Pueden contener microorganismos perjudiciales para el cachorro y las personas.",
                  "10. Suplementos innecesarios: El exceso de calcio, vitaminas y minerales puede alterar su desarrollo.",
                  "11. Alimentos en mal estado: Pueden contener microorganismos o toxinas peligrosas.",
                  "12. Exceso de comida: Puede favorecer el sobrepeso y aumentar la carga sobre sus articulaciones.",
                  "13. Dietas improvisadas: Alimentarlo exclusivamente con arroz, pan o carne no proporciona necesariamente todos los nutrientes que necesita.",
                  "14. Ayunos prolongados: Son especialmente preocupantes en cachorros pequeños, que pueden debilitarse rápidamente si no reciben suficiente alimento."
                ]
              }
            ]
          },
          "salud": {
            "titulo": "2. SALUD",
            "secciones": [
              {
                "titulo": "SEÑALES DE BUENA SALUD",
                "items": [
                  "1. Buen apetito: Come con regularidad y mantiene un patrón de alimentación estable.",
                  "2. Energía adecuada: Juega, explora y responde a su entorno cuando está despierto, aunque necesita dormir muchas horas durante el día.",
                  "3. Ojos limpios: No presenta enrojecimiento persistente, dolor ni secreciones abundantes.",
                  "4. Respiración normal: Respira sin esfuerzo y no presenta tos persistente ni ruidos respiratorios inusuales.",
                  "5. Oídos saludables: No tienen mal olor intenso, secreciones abundantes ni enrojecimiento.",
                  "6. Piel sana: No presenta heridas que empeoran, pérdida extensa de pelo o picazón constante.",
                  "7. Pelaje cuidado: Su pelo puede ser ondulado, rizado o esponjoso, pero debe mantenerse limpio y sin nudos que tiren de la piel.",
                  "8. Heces normales: Generalmente son consistentes y no contienen sangre. Los cambios persistentes necesitan evaluación.",
                  "9. Orina habitual: Orina sin dolor ni esfuerzo y mantiene un patrón relativamente estable.",
                  "10. Crecimiento progresivo: Aumenta de peso y desarrolla sus habilidades de acuerdo con su edad y constitución.",
                  "11. Movimiento coordinado: Camina y juega sin cojera persistente ni dificultad para levantarse.",
                  "12. Comportamiento curioso: Muestra interés por las personas y su entorno, aunque al principio pueda sentir temor ante situaciones nuevas."
                ]
              },
              {
                "titulo": "SEÑALES DE MALA SALUD",
                "items": [
                  "1. Falta de apetito: Puede indicar estrés, dolor, infección u otros problemas. En cachorros pequeños, no conviene esperar demasiado para consultar.",
                  "2. Vómitos repetidos: Pueden relacionarse con infecciones, parásitos, intoxicaciones o ingestión de objetos.",
                  "3. Diarrea: Puede provocar deshidratación rápidamente. Si es intensa, contiene sangre o se acompaña de vómitos y debilidad, requiere atención urgente.",
                  "4. Abdomen hinchado: Puede relacionarse con parásitos u otros problemas. Si aparece repentinamente y se acompaña de dolor o arcadas, es una emergencia.",
                  "5. Debilidad excesiva: Si no quiere levantarse, está muy decaído o responde poco al entorno, necesita evaluación.",
                  "6. Dificultad para respirar: La respiración trabajosa, el colapso o las encías azuladas son señales de emergencia.",
                  "7. Picazón constante: Puede deberse a pulgas, ácaros, alergias o enfermedades de la piel.",
                  "8. Secreciones anormales: El pus, el mal olor y el enrojecimiento intenso de ojos u oídos requieren revisión.",
                  "9. Cojera: Si evita apoyar una pata o llora al caminar, puede tener una lesión o sentir dolor.",
                  "10. Encías pálidas: Pueden indicar anemia, pérdida de sangre o problemas circulatorios.",
                  "11. Convulsiones: Necesitan atención veterinaria urgente, incluso si el cachorro parece recuperarse.",
                  "12. Cambios repentinos de conducta: Esconderse constantemente, llorar al tocarlo o dejar de jugar puede indicar miedo, dolor o enfermedad."
                ]
              }
            ]
          },
          "primeros": {
            "titulo": "3. PRIMEROS AUXILIOS",
            "secciones": [
              {
                "titulo": "QUÉ HACER CUANDO LE SUCEDEN ACCIDENTES",
                "items": [
                  
                  "1. Caídas y golpes: Mantén al cachorro tranquilo y evita que siga corriendo o saltando. Si no puede levantarse, presenta dolor intenso o respira con dificultad, acude inmediatamente al veterinario. No intentes enderezar patas ni manipular posibles fracturas.",
                  "2. Heridas y sangrado: Aplica presión continua con una gasa limpia. Si se empapa, coloca otra encima sin retirar la primera. No viertas alcohol ni agua oxigenada dentro de la herida. Las lesiones profundas o el sangrado abundante necesitan atención urgente.",
                  "3. Atragantamiento: Si puede respirar y toser, busca ayuda veterinaria sin introducir objetos en su boca. No metas los dedos a ciegas en la garganta ni intentes empujar el objeto con comida o agua. Si no puede respirar, es una emergencia.",
                  "4. Intoxicación: Aléjalo de la sustancia y conserva el envase para identificarla. Contacta inmediatamente con un veterinario. No provoques el vómito ni le administres leche, aceite, sal o remedios caseros.",
                ]
              },
              {
                "titulo": "QUÉ HACER CUANDO LE SUCEDEN ACCIDENTES",
                "items": [
                  
                  "5. Quemaduras: En una quemadura térmica, enfría la zona con agua corriente fresca durante unos 20 minutos si es posible. No uses hielo, mantequilla ni cremas humanas. Busca atención veterinaria.",
                  "6. Mordeduras y picaduras: Mantén al cachorro tranquilo. Si existe sangrado, aplica presión con una gasa limpia. Las mordeduras deben revisarse aunque parezcan pequeñas. Si presenta hinchazón facial o dificultad respiratoria después de una picadura, acude a urgencias.",
                  "7. Vómitos y diarrea: Observa la frecuencia y si existe sangre. No le des medicamentos humanos ni lo sometas a un ayuno prolongado sin orientación. Si vomita repetidamente, no puede retener agua o está débil, necesita atención rápida.",
                  "8. Golpe de calor: Trasládalo a un lugar fresco y humedece su cuerpo con agua fresca, no helada. No lo obligues a beber. Busca atención veterinaria urgente si presenta jadeo excesivo, vómitos, debilidad o confusión."
                ]
              }
            ]
          },
          "cuidados": {
            "titulo": "4. CUIDADOS",
            "secciones": [
              {
                "titulo": "CÓMO MANTENERLO BIEN CUIDADO",
                "items": [
                  "1. Cepillado del pelo: El chapi de pelo medio, ondulado o rizado necesita cepillados frecuentes para evitar nudos. Presta especial atención detrás de las orejas, debajo de las patas, en el pecho y alrededor de la cola.",
                  "2. Baño adecuado: Utiliza champú específico para perros y evita bañarlo innecesariamente. Después del baño, sécalo bien para que no permanezca húmedo durante mucho tiempo, especialmente si hace frío.",
                  "3. Limpieza de los ojos: Retira suavemente las secreciones superficiales con una gasa limpia humedecida con suero fisiológico. Si presenta dolor, enrojecimiento o secreción persistente, consulta al veterinario.",
                  "4. Cuidado de los oídos: Revisa sus orejas regularmente. No introduzcas bastoncillos profundamente ni utilices productos sin saber si son apropiados.",
                  "5. Higiene dental: Acostúmbralo progresivamente al cepillado con pasta dental formulada para perros. No utilices pasta dental humana.",
                  "6. Corte de uñas: Revisa su longitud y evita cortar la parte sensible de la uña. Si no sabes hacerlo de forma segura, pide ayuda a un veterinario o peluquero canino.",
                  "7. Descanso: Proporciónale una cama cómoda, seca y protegida de corrientes de aire. Los cachorros necesitan dormir muchas horas para recuperarse del juego y desarrollarse adecuadamente.",
                  "8. Ejercicio apropiado: Ofrécele juegos cortos, exploración supervisada y actividades de olfato. Evita obligarlo a realizar ejercicio intenso o saltos repetidos mientras está creciendo.",
                  "9. Seguridad en casa: Guarda medicamentos, productos de limpieza, cables y objetos pequeños fuera de su alcance. Protege balcones y ventanas para evitar caídas.",
                  "10. Temperatura adecuada: En épocas frías, proporciónale un lugar seco y protegido. En días calurosos, necesita sombra, ventilación y agua fresca. Nunca lo dejes dentro de un vehículo cerrado.",
                  "11. Socialización segura: Permítele conocer personas, sonidos y perros sanos de forma gradual y positiva. Consulta al veterinario sobre los lugares seguros antes de completar su vacunación.",
                  "12. Atención y compañía: Dedícale tiempo todos los días para jugar, enseñarle y acostumbrarlo a la convivencia familiar. También debe aprender gradualmente a descansar solo durante períodos apropiados para su edad."
                ]
              },
              {
                "titulo": "CÓMO SABER SI NO TIENE UN BUEN CUIDADO",
                "items": [
                  "1. Pelaje lleno de nudos: Puede indicar que necesita más cepillado. Los nudos apretados pueden tirar de la piel, retener humedad y provocar irritación.",
                  "2. Mal olor persistente: Un olor fuerte procedente de la piel, la boca o los oídos puede indicar falta de higiene o un problema médico.",
                  "3. Uñas excesivamente largas: Pueden dificultar la marcha y causar molestias.",
                  "4. Ojos u oídos sucios de forma persistente: Si hay secreciones abundantes, mal olor o inflamación, necesita revisión y una higiene apropiada.",
                  "5. Falta de agua o comida: No tener acceso constante a agua limpia o recibir alimentación insuficiente compromete su bienestar.",
                  "6. Espacio sucio o inseguro: La acumulación de heces, basura y objetos peligrosos aumenta el riesgo de infecciones, intoxicaciones y accidentes.",
                  "7. Falta de descanso: Si no dispone de un lugar tranquilo donde dormir, puede estar constantemente cansado o irritable.",
                  "8. Falta de ejercicio y estimulación: El aburrimiento puede favorecer conductas como morder objetos, ladrar excesivamente o buscar atención de manera insistente.",
                  "9. Exposición al frío o al calor extremos: Puede ocasionar problemas de salud, especialmente en cachorros muy pequeños.",
                  "10. Ausencia de atención veterinaria: No recibir vacunas, controles de parásitos ni revisiones cuando está enfermo aumenta el riesgo de complicaciones.",
                  "11. Miedo constante: Esconderse, temblar o intentar escapar repetidamente puede indicar que necesita un entorno más seguro y un trato respetuoso.",
                  "12. Castigos físicos: Golpearlo, asustarlo o gritarle puede generar miedo y problemas de comportamiento, además de perjudicar la relación con su familia."
                ]
              }
            ]
          },
          "comportamiento": {
            "titulo": "5. COMPORTAMIENTO",
            "secciones": [
              {
                "titulo": "ADIESTRAMIENTO DESDE CACHORRO",
                "items": [
                  "1. Enseñarle su nombre: Pronuncia su nombre con tono amable y prémialo cuando te mire. Practica durante períodos cortos, en lugares tranquilos, antes de añadir distracciones.",
                  "2. Enseñarle dónde hacer sus necesidades: Llévalo al lugar indicado después de dormir, comer, beber y jugar. Cuando lo haga correctamente, prémialo inmediatamente. Si ocurre un accidente, limpia sin castigarlo.",
                  "3. Enseñarle a acudir cuando lo llamas: Comienza a poca distancia y utiliza una palabra constante, como «ven». Cuando se acerque, recompénsalo. No lo llames para castigarlo, porque podría dejar de acudir.",
                  "4. Enseñarle a sentarse: Utiliza un premio para guiarlo suavemente hasta la posición de sentado. Cuando lo haga, recompénsalo y añade gradualmente la palabra que utilizarás como señal.",
                  "5. Acostumbrarlo a la correa: Empieza en casa con un arnés bien ajustado y una correa segura. Premia que camine contigo sin tirar. Aumenta poco a poco la dificultad del entorno.",
                  "6. Enseñarle a soltar objetos: Ofrécele un intercambio por un premio o un juguete apropiado. No lo persigas ni le arranques objetos de la boca de forma brusca.",
                  "7. Evitar que muerda las manos: Si durante el juego aprieta demasiado, interrumpe brevemente la interacción y redirígelo hacia un juguete. La constancia ayuda a que aprenda a controlar la fuerza de su mordida.",
                  "8. Enseñarle a descansar en su cama: Anímalo a acercarse y recompénsalo cuando se acueste voluntariamente. Su cama debe ser un espacio agradable y seguro, nunca un castigo.",
                  "9. Acostumbrarlo al cepillado: Empieza tocando suavemente el pelo durante unos segundos y recompénsalo. Aumenta gradualmente el tiempo para que aprenda a tolerar el cuidado sin miedo.",
                  "10. Socializarlo: Preséntale de manera gradual personas, sonidos, superficies y perros sanos. No lo obligues a acercarse a aquello que le provoca miedo; dale tiempo y distancia.",
                  "11. Enseñarle a quedarse solo: Empieza con períodos muy cortos y aumenta la duración según su tranquilidad. No lo dejes solo durante períodos demasiado largos para su edad.",
                  "12. Reforzar las conductas positivas: Premia la calma, la atención y las respuestas adecuadas. Las sesiones cortas y repetidas suelen ser más útiles que los entrenamientos largos que lo cansan o frustran."
                ]
              },
              {
                "titulo": "CÓMO MEJORAR SU COMPORTAMIENTO SI NO FUE ADIESTRADO",
                "items": [
                  "1. Identificar la causa: Antes de corregir una conducta, intenta comprender por qué ocurre. Puede deberse a miedo, aburrimiento, falta de aprendizaje, estrés o dolor.",
                  "2. Establecer rutinas: Mantén horarios relativamente constantes para comer, jugar, descansar y hacer sus necesidades. La previsibilidad puede ayudarlo a sentirse más seguro.",
                  "3. Enseñar una conducta alternativa: Si salta sobre las personas, prémialo cuando mantenga las cuatro patas en el suelo. Si muerde objetos, redirígelo hacia juguetes apropiados.",
                  "4. Practicar en lugares tranquilos: Si no responde en ambientes con muchas distracciones, vuelve a practicar en un sitio más sencillo y aumenta la dificultad gradualmente.",
                  "5. Evitar los castigos físicos: Golpearlo o asustarlo puede empeorar el miedo y no le enseña qué conducta debería realizar en su lugar.",
                  "6. Premiar los avances pequeños: Si antes no respondía a su nombre y ahora te mira algunas veces, recompénsalo. El aprendizaje requiere repetición y paciencia.",
                  "7. Evitar exigir demasiado: Los cachorros tienen una capacidad de atención limitada. Realiza sesiones breves y termina con una actividad sencilla que pueda completar.",
                  "8. Consultar si existe agresividad o miedo intenso: Si gruñe, intenta morder o reacciona con mucho temor, evita castigarlo y busca orientación de un veterinario o profesional de comportamiento que utilice métodos respetuosos."
                ]
              }
            ]
          },
          "vacunacion": {
            "titulo": "6. VACUNACIÓN",
            "secciones": [
              {
                "titulo": "TODAS LAS VACUNAS QUE DEBE TENER DURANTE SU VIDA",
                "items": [
                  "1. Vacuna contra el moquillo canino: Protege frente a una enfermedad infecciosa que puede afectar el sistema respiratorio, digestivo y nervioso. Puede ser especialmente grave en cachorros sin protección suficiente.",
                  "2. Vacuna contra el parvovirus canino: Ayuda a prevenir una enfermedad que puede causar vómitos, diarrea intensa, deshidratación y complicaciones graves. La protección es especialmente importante durante los primeros meses.",
                  "3. Vacuna contra el adenovirus canino: Protege frente a agentes asociados con la hepatitis infecciosa canina y forma parte de las vacunas esenciales recomendadas.",
                  "Estas vacunas suelen administrarse combinadas. La serie inicial comienza habitualmente alrededor de las 6–8 semanas y se repite cada 2–4 semanas hasta que el cachorro tenga al menos 16 semanas, según el protocolo veterinario y el producto utilizado.",
                  "4. Vacuna contra la rabia: Es fundamental porque la rabia es mortal y puede transmitirse a las personas. Debe administrarse conforme a la edad autorizada del producto y a las normas sanitarias vigentes en Bolivia.",
                  "5. Vacuna contra la leptospirosis: El veterinario puede recomendarla según la exposición a roedores, agua contaminada y otros riesgos del entorno.",
                  "6. Vacuna contra la tos infecciosa canina: Puede recomendarse si el cachorro tendrá contacto frecuente con muchos perros, por ejemplo, en guarderías, residencias o determinadas actividades grupales.",
                  "7. Refuerzos vacunales: Después de completar la serie inicial, necesitará refuerzos según la vacuna aplicada, su edad y las recomendaciones veterinarias. No todas las vacunas tienen el mismo intervalo.",
                  "8. Carnet de vacunación: Guarda el registro con las fechas, el nombre de las vacunas y los próximos refuerzos. No consideres que una sola dosis garantiza protección completa.",
                  "Importante: el calendario exacto debe establecerlo un veterinario de acuerdo con el historial del cachorro, los productos disponibles y las normas locales. No todas las vacunas adicionales son necesarias para todos los perros."
                ]
              },
              {
                "titulo": "DESPARASITACIÓN INTERNA Y EXTERNA",
                "items": [
                  "1. Desparasitación interna: Los cachorros pueden adquirir parásitos intestinales que afectan su digestión y crecimiento. El veterinario establecerá cuándo comenzar, con qué producto y con qué frecuencia repetir el tratamiento.",
                  "2. Desparasitación externa: Las pulgas y garrapatas pueden causar picazón, irritación y otros problemas. Utiliza un producto autorizado para perros que sea adecuado para su edad y peso.",
                  "3. Control del peso: Pesa al cachorro antes de administrar un antiparasitario. La dosis debe corresponder a su peso real y a las instrucciones del producto.",
                  "4. Higiene del entorno: Recoge las heces, limpia su espacio de descanso y lava los recipientes de comida y agua. Esto ayuda a reducir la exposición a determinados parásitos.",
                  "5. Revisión del pelaje: Examina el pelo y la piel regularmente, sobre todo detrás de las orejas, en el cuello, las axilas y entre los dedos.",
                  "6. Evitar productos inadecuados: No uses antiparasitarios para ganado, productos destinados a otras especies ni remedios caseros. Algunos ingredientes pueden resultar tóxicos para los perros.",
                  "7. Señales de posibles parásitos: La diarrea, la pérdida de peso, el abdomen hinchado, la picazón intensa o la presencia de parásitos visibles requieren evaluación veterinaria.",
                  "8. Análisis de heces: El veterinario puede recomendar un examen para identificar parásitos y elegir el tratamiento más apropiado."
                ]
              }
            ]
          },
          "veterinario": {
            "titulo": "8. CUÁNDO LLEVAR AL VETERINARIO",
            "secciones": [
              {
                "titulo": "REVISIONES RUTINARIAS",
                "items": [
                  "1. Primera revisión: Es recomendable realizar una evaluación cuando el cachorro llega a casa para comprobar su estado general y establecer un plan de prevención.",
                  "2. Durante el crecimiento: Necesita controles para evaluar el peso, el desarrollo, la alimentación, los dientes y la condición corporal.",
                  "3. Vacunación: Acude en las fechas indicadas para completar las dosis iniciales y programar los refuerzos.",
                  "4. Desparasitación: Consulta qué tratamientos necesita de acuerdo con su edad, peso y exposición a parásitos.",
                  "5. Revisión dental: El veterinario puede comprobar el desarrollo de los dientes y orientarte sobre su higiene bucal.",
                  "6. Esterilización: Consulta cuál es el momento apropiado según su tamaño, desarrollo y situación individual."
                ]
              },
              {
                "titulo": "SEÑALES DE ALERTA",
                "items": [
                  "1. Si deja de comer o bebe mucho menos de lo habitual.",
                  "2. Si presenta vómitos o diarrea que se repiten.",
                  "3. Si se rasca constantemente o aparecen heridas en la piel.",
                  "4. Si cojea, evita caminar o parece sentir dolor.",
                  "5. Si presenta secreciones persistentes en los ojos o los oídos.",
                  "6. Si pierde peso, no crece como se espera o muestra debilidad.",
                  "7. Si cambia repentinamente su comportamiento y deja de jugar o interactuar."
                ]
              },
              {
                "titulo": "EMERGENCIAS VETERINARIAS",
                "items": [
                  "1. Dificultad para respirar: Si respira con mucho esfuerzo, se desploma o presenta encías azuladas, necesita atención inmediata.",
                  "2. Intoxicación: Si ingiere chocolate, medicamentos, productos químicos u otra sustancia potencialmente tóxica, contacta inmediatamente con un veterinario.",
                  "3. Vómitos o diarrea intensos: Especialmente si hay sangre, debilidad o incapacidad para retener agua.",
                  "4. Convulsiones o desmayo: Requieren atención urgente.",
                  "5. Traumatismos graves: Las caídas importantes, los atropellos y las heridas profundas deben evaluarse inmediatamente, aunque al principio parezca encontrarse bien.",
                  "6. Abdomen hinchado con arcadas: Si intenta vomitar sin conseguirlo y presenta inquietud o debilidad, acude a urgencias.",
                  "7. Hemorragia abundante: Aplica presión con una gasa limpia mientras consigues atención veterinaria.",
                  "8. Debilidad extrema en un cachorro pequeño: Si no puede levantarse, no responde normalmente o está muy frío, necesita atención inmediata."
                ]
              }
            ]
          }
        }
      }
    ,
      "adulto": {
      "tituloOriginal": "CHAPI ADULTO (DE 1 A 9 AÑOS)",
      "temas": {
            "alimentacion": {
                  "titulo": "1. ALIMENTACIÓN",
                  "secciones": [
                        {
                              "titulo": "ALIMENTACIÓN SALUDABLE",
                              "items": [
                                    "1. Alimento completo para adultos: ofrecer un alimento equilibrado para perros adultos, adecuado a su tamaño, peso y actividad.",
                                    "2. Proteínas de calidad: ayudan a conservar la musculatura y reparar tejidos; elegir un alimento que aporte proteínas suficientes.",
                                    "3. Porciones medidas: ajustar la ración según su peso, actividad y condición corporal para evitar el sobrepeso o la pérdida de peso.",
                                    "4. Horarios regulares: dividir la ración diaria en dos comidas suele facilitar la digestión y permite mantener una rutina.",
                                    "5. Agua fresca: mantener agua limpia y accesible durante todo el día.",
                                    "6. Premios moderados: utilizar premios adecuados para perros y descontarlos de la cantidad diaria de alimento.",
                                    "7. Cambios graduales: realizar la transición a un nuevo alimento progresivamente durante varios días.",
                                    "8. Alimentación según su actividad: los perros activos pueden necesitar más energía que los que realizan poca actividad.",
                                    "9. Control del peso: revisar periódicamente su peso y condición corporal y ajustar la ración cuando sea necesario.",
                                    "10. Dietas especiales: si presenta alergias o enfermedades, consultar al veterinario antes de elegir una dieta terapéutica."
                              ]
                        },
                        {
                              "titulo": "ALIMENTACIÓN NO SALUDABLE",
                              "items": [
                                    "1. Chocolate, café y productos con cafeína: pueden resultar tóxicos para los perros.",
                                    "2. Uvas y pasas: pueden provocar daño renal.",
                                    "3. Cebolla, ajo y puerro: pueden afectar los glóbulos rojos.",
                                    "4. Productos con xilitol: este edulcorante puede causar una intoxicación grave.",
                                    "5. Huesos cocidos: pueden astillarse y provocar lesiones u obstrucciones.",
                                    "6. Alimentos muy grasos: pueden causar molestias digestivas y favorecer problemas pancreáticos.",
                                    "7. Comidas muy saladas o condimentadas: no son apropiadas para su organismo.",
                                    "8. Sobras en mal estado: pueden provocar vómitos y diarrea.",
                                    "9. Exceso de premios: favorece el aumento de peso y desequilibra la dieta.",
                                    "10. Suplementos sin indicación: no administrar vitaminas, minerales u otros complementos sin orientación veterinaria."
                              ]
                        }
                  ]
            },
            "salud": {
                  "titulo": "2. SALUD",
                  "secciones": [
                        {
                              "titulo": "SEÑALES DE BUENA SALUD",
                              "items": [
                                    "1. Apetito habitual: come con normalidad y mantiene interés por su alimento.",
                                    "2. Peso estable: conserva una condición corporal adecuada y buena musculatura.",
                                    "3. Energía y actividad: se muestra atento y participa en actividades acordes con su edad.",
                                    "4. Respiración normal: respira sin esfuerzo cuando está en reposo.",
                                    "5. Ojos limpios: no presenta secreciones abundantes, enrojecimiento ni molestias.",
                                    "6. Piel y pelaje cuidados: no tiene heridas persistentes, pérdida excesiva de pelo ni picazón intensa.",
                                    "7. Boca saludable: puede comer y masticar sin dolor ni mal aliento intenso.",
                                    "8. Digestión regular: sus heces mantienen una consistencia habitual y no presenta vómitos repetidos.",
                                    "9. Movimiento cómodo: camina, corre y se levanta sin dolor ni cojera.",
                                    "10. Conducta habitual: responde a su entorno y mantiene sus hábitos normales."
                              ]
                        },
                        {
                              "titulo": "SEÑALES DE MALA SALUD",
                              "items": [
                                    "1. Pérdida o aumento de peso sin explicación.",
                                    "2. Falta persistente de apetito o sed excesiva.",
                                    "3. Vómitos o diarrea repetidos.",
                                    "4. Tos frecuente, estornudos persistentes o dificultad para respirar.",
                                    "5. Picazón intensa, heridas, bultos nuevos o caída anormal del pelo.",
                                    "6. Ojos rojos, secreciones abundantes o cambios en la visión.",
                                    "7. Mal aliento intenso, encías inflamadas o dificultad para masticar.",
                                    "8. Cojera, rigidez, dolor o dificultad para levantarse.",
                                    "9. Decaimiento, aislamiento o cambios repentinos de comportamiento.",
                                    "10. Dificultad o cambios importantes al orinar o defecar."
                              ]
                        }
                  ]
            },
            "primeros": {
                  "titulo": "3. PRIMEROS AUXILIOS",
                  "secciones": [
                        {
                              "titulo": "QUÉ HACER ANTE UNA EMERGENCIA",
                              "items": [
                                    "1. Mantener la calma y alejar al perro de aquello que pueda causarle más daño.",
                                    "2. Contactar a un veterinario: explicar qué ocurrió, cuándo comenzó y qué síntomas presenta.",
                                    "3. Heridas con sangrado: cubrir con una gasa o paño limpio y aplicar presión suave mientras se busca atención veterinaria.",
                                    "4. Golpes o caídas: limitar sus movimientos y no intentar acomodar huesos ni articulaciones.",
                                    "5. Quemaduras: evitar aplicar cremas o remedios caseros y solicitar orientación veterinaria.",
                                    "6. Sospecha de intoxicación: retirar el producto y conservar su envase para informar al veterinario; no provocar el vómito por cuenta propia.",
                                    "7. Convulsiones: retirar objetos cercanos, no sujetarlo con fuerza y no introducir nada en su boca.",
                                    "8. Dificultad respiratoria: mantenerlo tranquilo y acudir inmediatamente a urgencias.",
                                    "9. Golpe de calor: trasladarlo a un lugar fresco, comenzar un enfriamiento moderado con agua fresca y buscar atención veterinaria urgente.",
                                    "10. No administrar medicamentos humanos: algunos pueden ser tóxicos para los perros.",
                                    "11. Traslado seguro: moverlo con cuidado, evitando presionar zonas doloridas.",
                                    "12. Después del incidente: aunque parezca recuperado, solicitar evaluación si hubo golpe fuerte, intoxicación o síntomas importantes."
                              ]
                        }
                  ]
            },
            "cuidados": {
                  "titulo": "4. CUIDADOS",
                  "secciones": [
                        {
                              "titulo": "BUENOS CUIDADOS",
                              "items": [
                                    "1. Higiene regular: mantener limpio su cuerpo y utilizar productos adecuados para perros.",
                                    "2. Cepillado: adaptar la frecuencia al tipo de pelo para retirar suciedad y pelo muerto.",
                                    "3. Baño cuando lo necesite: evitar baños excesivos que puedan irritar la piel.",
                                    "4. Cuidado dental: cepillar sus dientes con productos veterinarios y revisar su boca.",
                                    "5. Uñas: controlar su longitud y acudir a un profesional si no se pueden cortar con seguridad.",
                                    "6. Oídos: revisar y limpiar únicamente cuando sea necesario, sin introducir objetos en el canal auditivo.",
                                    "7. Ejercicio diario: ofrecer paseos y actividad adecuados a su condición física.",
                                    "8. Descanso: proporcionarle un lugar limpio, seco, cómodo y protegido del clima.",
                                    "9. Protección climática: evitar exposición prolongada al calor o al frío intenso.",
                                    "10. Identificación: mantener actualizados sus datos de identificación y contacto.",
                                    "11. Supervisión: evitar que deambule sin control y mantenerlo en un espacio seguro.",
                                    "12. Revisiones preventivas: realizar controles veterinarios, vacunas y prevención de parásitos según sus necesidades."
                              ]
                        },
                        {
                              "titulo": "MALOS CUIDADOS QUE DEBEN EVITARSE",
                              "items": [
                                    "1. Dejarlo sin agua limpia o alimento adecuado.",
                                    "2. Mantenerlo permanentemente atado o encerrado sin espacio para moverse.",
                                    "3. No proporcionarle ejercicio ni estimulación.",
                                    "4. Descuidar heridas, problemas de piel o molestias persistentes.",
                                    "5. No atender su higiene dental, uñas y oídos.",
                                    "6. Bañarlo demasiado o utilizar champús para personas.",
                                    "7. Exponerlo al sol o al calor intenso sin sombra ni agua.",
                                    "8. Permitir que ingiera basura, sustancias químicas o alimentos peligrosos.",
                                    "9. Castigarlo físicamente o tratarlo con violencia.",
                                    "10. Dejarlo solo durante periodos prolongados sin cuidados.",
                                    "11. Omitir vacunas y prevención antiparasitaria recomendadas.",
                                    "12. Ignorar cambios de apetito, peso, movilidad o comportamiento."
                              ]
                        }
                  ]
            },
            "comportamiento": {
                  "titulo": "5. COMPORTAMIENTO",
                  "secciones": [
                        {
                              "titulo": "EDUCACIÓN Y ADIESTRAMIENTO POSITIVO",
                              "items": [
                                    "1. Reforzamiento positivo: premiar las conductas deseadas con alimento apropiado, juego o elogios.",
                                    "2. Órdenes sencillas: practicar indicaciones como venir, sentarse, esperar y caminar junto a la persona.",
                                    "3. Sesiones breves: realizar prácticas cortas y constantes para mantener su atención.",
                                    "4. Rutinas: establecer horarios para paseos, alimentación, descanso y juego.",
                                    "5. Socialización: permitir encuentros tranquilos y seguros con personas y perros compatibles.",
                                    "6. Paseos con correa: enseñarle a caminar sin tirar mediante paciencia y recompensas.",
                                    "7. Juego y estimulación: ofrecer juguetes seguros y actividades de olfato.",
                                    "8. Manejo de miedos: acercarlo gradualmente a estímulos que le preocupan, sin forzarlo.",
                                    "9. Límites consistentes: todas las personas de la casa deben utilizar las mismas reglas.",
                                    "10. Paciencia: repetir los ejercicios sin gritos ni castigos físicos."
                              ]
                        },
                        {
                              "titulo": "CONDUCTAS QUE DEBEN MEJORARSE",
                              "items": [
                                    "1. Ladridos excesivos: identificar si se relacionan con miedo, aburrimiento, alerta o frustración.",
                                    "2. Tirones de correa: practicar caminatas tranquilas y premiar cuando camina sin tensión.",
                                    "3. Saltar sobre las personas: reforzar saludos tranquilos con las cuatro patas en el suelo.",
                                    "4. Morder objetos: ofrecer juguetes apropiados y retirar objetos peligrosos.",
                                    "5. Ansiedad al quedarse solo: acostumbrarlo gradualmente a periodos de ausencia.",
                                    "6. Miedo a ruidos: trabajar con exposición gradual y experiencias positivas.",
                                    "7. Protección de comida u objetos: evitar confrontaciones y solicitar ayuda profesional si hay riesgo de mordida.",
                                    "8. Falta de obediencia: practicar señales sencillas en ambientes con pocas distracciones.",
                                    "9. Destrucción por aburrimiento: aumentar la estimulación física y mental adecuada.",
                                    "10. Agresividad o cambios repentinos: descartar primero dolor o enfermedad y buscar orientación profesional."
                              ]
                        }
                  ]
            },
            "vacunacion": {
                  "titulo": "6. VACUNACIÓN Y DESPARASITACIÓN",
                  "secciones": [
                        {
                              "titulo": "VACUNAS QUE DEBE MANTENER DURANTE SU VIDA",
                              "items": [
                                    "1. Vacuna múltiple esencial: protege frente a enfermedades importantes como moquillo, parvovirus y adenovirus canino.",
                                    "2. Vacuna contra la rabia: debe mantenerse de acuerdo con la normativa sanitaria vigente en Bolivia y la indicación veterinaria.",
                                    "3. Refuerzos: la frecuencia depende de los componentes de la vacuna, el producto utilizado y el historial del perro.",
                                    "4. Leptospirosis: puede recomendarse según la exposición a roedores, agua contaminada y riesgos de la región.",
                                    "5. Bordetella: puede considerarse si convive con muchos perros o asiste a guarderías y residencias.",
                                    "6. Parainfluenza e influenza canina: se valoran según el riesgo de exposición y la disponibilidad de vacunas.",
                                    "7. Otras vacunas: el veterinario determinará si son apropiadas para su entorno y estilo de vida.",
                                    "8. Cartilla de vacunación: conservar las fechas, nombres de vacunas y próximos refuerzos.",
                                    "9. Historial desconocido: solicitar al veterinario un calendario de recuperación sin repetir dosis por cuenta propia."
                              ]
                        },
                        {
                              "titulo": "DESPARASITACIÓN INTERNA Y EXTERNA",
                              "items": [
                                    "1. Parásitos intestinales: los perros pueden presentar lombrices, tenias y otros parásitos que afectan su salud.",
                                    "2. Análisis de heces: pueden ayudar a identificar parásitos y orientar el tratamiento.",
                                    "3. Frecuencia interna: debe establecerse según edad, estilo de vida, exposición y criterio veterinario.",
                                    "4. Pulgas: pueden causar picazón, dermatitis y transmitir otros parásitos.",
                                    "5. Garrapatas: pueden transmitir enfermedades y deben prevenirse con productos adecuados.",
                                    "6. Ácaros: pueden ocasionar problemas de piel y oídos.",
                                    "7. Productos preventivos: elegirlos según peso, edad y estado de salud.",
                                    "8. Higiene ambiental: lavar su cama y recoger las heces para reducir la exposición a parásitos.",
                                    "9. No combinar productos: evitar administrar antiparasitarios diferentes sin consultar al veterinario.",
                                    "10. Mantener un registro: anotar fechas y productos utilizados para evitar duplicaciones."
                              ]
                        }
                  ]
            },
            "veterinario": {
                  "titulo": "7. CUÁNDO LLEVAR AL VETERINARIO",
                  "secciones": [
                        {
                              "titulo": "REVISIONES RUTINARIAS",
                              "items": [
                                    "1. Realizar controles preventivos periódicos, aunque aparentemente se encuentre sano.",
                                    "2. Revisar peso y condición corporal para detectar cambios.",
                                    "3. Controlar dientes, encías y salud oral.",
                                    "4. Revisar piel, pelo, oídos y ojos.",
                                    "5. Evaluar movilidad, articulaciones y posibles molestias.",
                                    "6. Actualizar vacunas y prevención antiparasitaria.",
                                    "7. Consultar ante cambios persistentes de apetito, sed o eliminación.",
                                    "8. Informar sobre medicamentos, suplementos y antecedentes de salud."
                              ]
                        },
                        {
                              "titulo": "SEÑALES DE ALERTA QUE NECESITAN CONSULTA",
                              "items": [
                                    "1. Falta de apetito persistente o pérdida de peso sin explicación.",
                                    "2. Vómitos o diarrea que se repiten.",
                                    "3. Picazón intensa, heridas o bultos nuevos.",
                                    "4. Cojera, rigidez o dificultad para levantarse.",
                                    "5. Tos, secreciones o molestias respiratorias persistentes.",
                                    "6. Cambios importantes al beber u orinar.",
                                    "7. Dolor, aislamiento o cambios repentinos de conducta.",
                                    "8. Problemas dentales, mal aliento intenso o dificultad para masticar."
                              ]
                        },
                        {
                              "titulo": "SITUACIONES DE EMERGENCIA",
                              "items": [
                                    "1. Dificultad para respirar o encías azuladas.",
                                    "2. Convulsiones, desmayo o pérdida de respuesta.",
                                    "3. Hemorragia importante o herida profunda.",
                                    "4. Abdomen muy hinchado y doloroso.",
                                    "5. Sospecha de ingestión de veneno, medicamentos o sustancias tóxicas.",
                                    "6. Vómitos repetidos con debilidad o sangre.",
                                    "7. Incapacidad para orinar.",
                                    "8. Golpe fuerte, caída importante o posible fractura.",
                                    "9. Golpe de calor, colapso o debilidad extrema.",
                                    "10. Reacción alérgica intensa con hinchazón de la cara o dificultad respiratoria."
                              ]
                        }
                  ]
            }
      }
},
      "senior": {
      "tituloOriginal": "CHAPI SENIOR O GERIÁTRICO (A PARTIR DE LOS 10 AÑOS)",
      "temas": {
            "alimentacion": {
                  "titulo": "1. ALIMENTACIÓN",
                  "secciones": [
                        {
                              "titulo": "ALIMENTACIÓN SALUDABLE",
                              "items": [
                                    "1. Alimento para perros mayores: elegir una dieta completa que se adapte a su condición corporal, actividad y estado de salud.",
                                    "2. Proteínas suficientes: ayudan a conservar la masa muscular; no reducirlas automáticamente por la edad.",
                                    "3. Raciones individualizadas: ajustar la cantidad según peso, actividad y condición corporal, evitando tanto el sobrepeso como la pérdida muscular.",
                                    "4. Agua accesible: mantener agua fresca y colocar recipientes donde pueda alcanzarlos con facilidad.",
                                    "5. Textura adecuada: si tiene molestias dentales, consultar si conviene alimento húmedo o croquetas humedecidas.",
                                    "6. Comidas repartidas: ofrecer dos o más porciones pequeñas si le resulta más cómodo.",
                                    "7. Fibra y digestión: mantener una dieta equilibrada y consultar si presenta estreñimiento o diarrea persistentes.",
                                    "8. Nutrientes específicos: las dietas para enfermedades renales, cardíacas o digestivas deben ser indicadas por el veterinario.",
                                    "9. Premios pequeños: ofrecer premios apropiados en cantidades moderadas.",
                                    "10. Control de peso y músculos: vigilar cambios de peso y pérdida de musculatura.",
                                    "11. Cambios graduales: introducir nuevos alimentos progresivamente, salvo indicación clínica diferente.",
                                    "12. Horarios estables: mantener una rutina que facilite observar cambios en el apetito.",
                                    "13. Alimento de buena calidad: seleccionar productos completos y adecuados a sus necesidades.",
                                    "14. Evaluación nutricional: revisar su alimentación con el veterinario en los controles de salud."
                              ]
                        },
                        {
                              "titulo": "ALIMENTACIÓN NO SALUDABLE",
                              "items": [
                                    "1. Chocolate, café, cafeína y productos con xilitol.",
                                    "2. Uvas y pasas, cebolla, ajo y puerro.",
                                    "3. Huesos cocidos y objetos excesivamente duros.",
                                    "4. Alimentos muy grasos, salados o condimentados.",
                                    "5. Sobras en mal estado o alimentos vencidos.",
                                    "6. Exceso de premios y comida fuera de su ración.",
                                    "7. Dietas caseras sin formulación nutricional profesional.",
                                    "8. Suplementos de calcio, vitaminas u otros productos sin indicación.",
                                    "9. Reducir demasiado la comida y provocar pérdida de peso o músculo.",
                                    "10. Cambiar bruscamente su dieta sin necesidad médica.",
                                    "11. Dar alimentos difíciles de masticar cuando presenta problemas dentales.",
                                    "12. Restringir el agua sin indicación veterinaria.",
                                    "13. Ofrecer alimentos incompatibles con una dieta terapéutica prescrita.",
                                    "14. Ignorar pérdida de apetito o dificultad para tragar.",
                                    "15. Dar medicamentos humanos para estimular el apetito o aliviar molestias."
                              ]
                        }
                  ]
            },
            "salud": {
                  "titulo": "2. SALUD",
                  "secciones": [
                        {
                              "titulo": "SEÑALES DE BUENA SALUD",
                              "items": [
                                    "1. Mantiene interés por su entorno y disfruta actividades adaptadas a su capacidad.",
                                    "2. Conserva un peso adecuado y suficiente masa muscular.",
                                    "3. Come y bebe con normalidad.",
                                    "4. Descansa cómodamente y puede levantarse sin dolor importante.",
                                    "5. Camina con estabilidad dentro de sus posibilidades.",
                                    "6. Respira sin esfuerzo cuando está en reposo.",
                                    "7. Mantiene ojos limpios y responde a estímulos visuales y auditivos.",
                                    "8. Tiene piel y pelaje sin lesiones persistentes.",
                                    "9. Puede masticar y tragar sin dificultad.",
                                    "10. Orina y defeca con una frecuencia habitual.",
                                    "11. Se relaciona con su familia y conserva hábitos reconocibles.",
                                    "12. No presenta dolor persistente ni cambios repentinos de conducta.",
                                    "13. Sus enfermedades crónicas, si existen, están controladas.",
                                    "14. Acude a controles preventivos y recibe los cuidados indicados."
                              ]
                        },
                        {
                              "titulo": "SEÑALES DE MALA SALUD",
                              "items": [
                                    "1. Pérdida de peso o masa muscular sin explicación.",
                                    "2. Sed excesiva o aumento/disminución marcada de la orina.",
                                    "3. Pérdida persistente del apetito o dificultad para comer.",
                                    "4. Vómitos, diarrea o estreñimiento recurrentes.",
                                    "5. Tos, respiración rápida o dificultad respiratoria.",
                                    "6. Cojera, rigidez o problemas para levantarse.",
                                    "7. Desorientación, cambios del sueño o confusión.",
                                    "8. Pérdida de visión o audición que aparece o empeora.",
                                    "9. Bultos nuevos, heridas que no cicatrizan o sangrado.",
                                    "10. Mal aliento intenso, dolor dental o encías inflamadas.",
                                    "11. Incontinencia o dificultad para orinar.",
                                    "12. Aislamiento, irritabilidad o cambios de comportamiento.",
                                    "13. Debilidad, cansancio excesivo o desmayos.",
                                    "14. Picazón, lesiones cutáneas o infecciones recurrentes.",
                                    "15. Dolor persistente o sensibilidad al tocarlo.",
                                    "16. Cualquier deterioro rápido de su estado general."
                              ]
                        }
                  ]
            },
            "primeros": {
                  "titulo": "3. PRIMEROS AUXILIOS",
                  "secciones": [
                        {
                              "titulo": "QUÉ HACER ANTE UNA EMERGENCIA",
                              "items": [
                                    "1. Mantenerlo tranquilo y evitar que camine si presenta dolor o debilidad.",
                                    "2. Contactar inmediatamente con un veterinario y describir los síntomas.",
                                    "3. Ante sangrado, cubrir la zona con una gasa limpia y aplicar presión suave.",
                                    "4. Ante una caída o golpe, limitar sus movimientos y no manipular posibles fracturas.",
                                    "5. Si respira con dificultad, trasladarlo a urgencias sin retrasar la atención.",
                                    "6. Si convulsiona, retirar objetos cercanos y no introducir nada en su boca.",
                                    "7. Ante sospecha de intoxicación, conservar el envase y no provocar el vómito por cuenta propia.",
                                    "8. Si presenta golpe de calor, llevarlo a un lugar fresco, iniciar enfriamiento moderado y acudir urgentemente al veterinario.",
                                    "9. No administrar analgésicos ni medicamentos humanos.",
                                    "10. Para transportarlo, utilizar una superficie firme o manta, evitando movimientos bruscos.",
                                    "11. Vigilar su respiración y respuesta mientras se organiza el traslado.",
                                    "12. No esperar a que los síntomas desaparezcan cuando son repentinos o intensos."
                              ]
                        }
                  ]
            },
            "cuidados": {
                  "titulo": "4. CUIDADOS",
                  "secciones": [
                        {
                              "titulo": "BUENOS CUIDADOS",
                              "items": [
                                    "1. Controles veterinarios más frecuentes según su estado y recomendación profesional.",
                                    "2. Alimentación adaptada a su peso, musculatura y posibles enfermedades.",
                                    "3. Agua fresca en recipientes accesibles.",
                                    "4. Cama cómoda, seca y fácil de alcanzar.",
                                    "5. Paseos suaves y actividad adaptada a su movilidad.",
                                    "6. Evitar saltos y superficies resbaladizas.",
                                    "7. Mantener uñas cuidadas para facilitar la marcha.",
                                    "8. Cepillar su pelo y revisar la piel con regularidad.",
                                    "9. Mantener higiene dental y controles de la boca.",
                                    "10. Revisar ojos y oídos y consultar ante cambios.",
                                    "11. Protegerlo del frío, calor intenso y humedad.",
                                    "12. Facilitar rampas o escalones seguros si tiene dificultad para subir.",
                                    "13. Mantener horarios previsibles para comida, paseos y descanso.",
                                    "14. Proporcionar compañía y estimulación mental tranquila.",
                                    "15. Adaptar el hogar para reducir obstáculos.",
                                    "16. Administrar medicamentos únicamente según la receta veterinaria.",
                                    "17. Vigilar peso, apetito, sed, movilidad y eliminación.",
                                    "18. Tratarlo con paciencia y respetar sus periodos de descanso."
                              ]
                        },
                        {
                              "titulo": "MALOS CUIDADOS QUE DEBEN EVITARSE",
                              "items": [
                                    "1. Forzarlo a realizar ejercicio intenso o prolongado.",
                                    "2. Permitir que suba y baje escaleras si le causa dolor o inseguridad.",
                                    "3. Dejarlo en superficies resbaladizas o con obstáculos.",
                                    "4. No facilitar agua o alimento por dificultad para desplazarse.",
                                    "5. Ignorar dolor, rigidez o pérdida de movilidad.",
                                    "6. No realizar revisiones veterinarias preventivas.",
                                    "7. Cambiar su dieta o medicación sin orientación profesional.",
                                    "8. Administrar medicamentos humanos o suplementos por cuenta propia.",
                                    "9. Exponerlo a temperaturas extremas.",
                                    "10. Descuidar dientes, uñas, piel y oídos.",
                                    "11. Dejarlo aislado o sin compañía durante periodos prolongados.",
                                    "12. Castigarlo por accidentes de eliminación relacionados con la edad o enfermedad.",
                                    "13. Ignorar cambios de visión, audición o comportamiento.",
                                    "14. Permitir que pierda peso o músculo sin investigar la causa.",
                                    "15. Mantener su cama húmeda, sucia o incómoda.",
                                    "16. No adaptar el hogar a sus dificultades de movilidad.",
                                    "17. Omitir vacunas o prevención antiparasitaria sin valoración veterinaria."
                              ]
                        }
                  ]
            },
            "comportamiento": {
                  "titulo": "5. COMPORTAMIENTO",
                  "secciones": [
                        {
                              "titulo": "EDUCACIÓN Y ESTIMULACIÓN ADECUADA",
                              "items": [
                                    "1. Mantener rutinas estables para darle seguridad.",
                                    "2. Utilizar refuerzo positivo con premios pequeños y elogios.",
                                    "3. Realizar sesiones cortas de aprendizaje, respetando su energía.",
                                    "4. Reforzar órdenes sencillas que todavía pueda realizar cómodamente.",
                                    "5. Ofrecer juegos de olfato y búsqueda de baja exigencia física.",
                                    "6. Permitir paseos tranquilos para explorar su entorno.",
                                    "7. Mantener contacto social positivo con personas conocidas.",
                                    "8. Presentar cambios de ambiente gradualmente.",
                                    "9. Proporcionar un lugar tranquilo donde pueda descansar sin interrupciones.",
                                    "10. Adaptar juguetes y actividades a su visión, audición y movilidad.",
                                    "11. Tener paciencia si tarda más en responder o aprender.",
                                    "12. Consultar si aparecen cambios repentinos de conducta."
                              ]
                        },
                        {
                              "titulo": "CAMBIOS DE COMPORTAMIENTO QUE DEBEN ATENDERSE",
                              "items": [
                                    "1. Desorientación en lugares conocidos: consultar para evaluar posibles causas.",
                                    "2. Cambios en el sueño: registrar horarios y comentarlos con el veterinario.",
                                    "3. Ladridos o vocalizaciones nuevas: descartar dolor, miedo o alteraciones sensoriales.",
                                    "4. Irritabilidad al tocarlo: puede indicar dolor y necesita revisión.",
                                    "5. Aislamiento: observar si existe malestar físico o cambios del entorno.",
                                    "6. Pérdida de hábitos de higiene: descartar problemas urinarios, digestivos o cognitivos.",
                                    "7. Ansiedad ante separaciones: mantener rutinas y buscar orientación profesional.",
                                    "8. Menor interés por el juego: adaptar actividades y revisar su estado de salud.",
                                    "9. Reacciones de miedo: evitar forzarlo y ofrecer un entorno seguro.",
                                    "10. Dificultad para reconocer señales: considerar cambios de visión o audición.",
                                    "11. Conductas repetitivas nuevas: registrar su frecuencia y consultar.",
                                    "12. Agresividad repentina: descartar dolor o enfermedad antes de intentar corregirla.",
                                    "13. Pérdida de aprendizaje: practicar con paciencia y señales sencillas.",
                                    "14. Cambios persistentes: solicitar evaluación veterinaria y, si corresponde, apoyo de comportamiento."
                              ]
                        }
                  ]
            },
            "vacunacion": {
                  "titulo": "6. VACUNACIÓN Y DESPARASITACIÓN",
                  "secciones": [
                        {
                              "titulo": "VACUNAS QUE DEBE MANTENER DURANTE SU VIDA",
                              "items": [
                                    "1. La edad avanzada no significa que deban suspenderse automáticamente las vacunas.",
                                    "2. Vacuna múltiple esencial: protege frente a enfermedades como moquillo, parvovirus y adenovirus canino.",
                                    "3. Rabia: mantenerla conforme a la normativa sanitaria vigente y la duración de inmunidad autorizada.",
                                    "4. Leptospirosis: valorar según exposición a roedores, agua contaminada y riesgo local.",
                                    "5. Bordetella: considerar si tiene contacto frecuente con otros perros.",
                                    "6. Parainfluenza y otras vacunas respiratorias: valorar según su estilo de vida y riesgo.",
                                    "7. Refuerzos: la frecuencia depende del producto, historial y recomendación veterinaria.",
                                    "8. Enfermedades crónicas: el veterinario debe valorar el momento y conveniencia de cada vacuna.",
                                    "9. Cartilla: conservar el registro de vacunas y fechas de refuerzo.",
                                    "10. Historial incompleto: solicitar un calendario individualizado y no repetir dosis por cuenta propia."
                              ]
                        },
                        {
                              "titulo": "DESPARASITACIÓN INTERNA Y EXTERNA",
                              "items": [
                                    "1. Los perros senior siguen expuestos a parásitos y necesitan prevención individualizada.",
                                    "2. Lombrices intestinales: pueden causar molestias digestivas y pérdida de peso.",
                                    "3. Anquilostomas: pueden provocar pérdida de sangre y anemia.",
                                    "4. Tricocéfalos y tenias: pueden afectar el intestino y producir signos digestivos.",
                                    "5. Giardia y coccidios: requieren diagnóstico y tratamientos específicos.",
                                    "6. Análisis de heces: ayudan a orientar la necesidad de tratamiento.",
                                    "7. Frecuencia interna: determinar según exposición, estilo de vida y criterio veterinario.",
                                    "8. Pulgas: pueden causar picazón y dermatitis.",
                                    "9. Garrapatas: pueden transmitir enfermedades infecciosas.",
                                    "10. Ácaros: pueden producir problemas de piel y oídos.",
                                    "11. Elegir productos según peso, edad, enfermedades y medicamentos que utiliza."
                              ]
                        }
                  ]
            },
            "veterinario": {
                  "titulo": "7. CUÁNDO LLEVAR AL VETERINARIO",
                  "secciones": [
                        {
                              "titulo": "REVISIONES RUTINARIAS",
                              "items": [
                                    "1. Realizar revisiones preventivas con la frecuencia que indique el veterinario; muchos perros senior se benefician de controles semestrales.",
                                    "2. Controlar peso y masa muscular para detectar pérdidas o aumentos importantes.",
                                    "3. Evaluar articulaciones, movilidad y posibles signos de dolor.",
                                    "4. Revisar dientes, encías y piezas dentales.",
                                    "5. Controlar ojos, oídos, piel y pelaje.",
                                    "6. Revisar bultos nuevos o cambios en masas existentes.",
                                    "7. Evaluar apetito, sed, orina y deposiciones.",
                                    "8. Revisar vacunas y desparasitación según antecedentes y estilo de vida.",
                                    "9. Realizar análisis complementarios cuando el profesional los considere necesarios.",
                                    "10. Revisar enfermedades crónicas y respuesta a los tratamientos.",
                                    "11. Comentar cambios de sueño, orientación, conducta y movilidad.",
                                    "12. Revisar medicamentos y posibles efectos adversos.",
                                    "13. Solicitar orientación sobre alimentación y actividad física adaptadas.",
                                    "14. Mantener un registro de síntomas, cambios y consultas."
                              ]
                        },
                        {
                              "titulo": "SEÑALES DE ALERTA QUE NECESITAN CONSULTA",
                              "items": [
                                    "1. Pérdida de apetito, peso o masa muscular.",
                                    "2. Aumento marcado de sed u orina.",
                                    "3. Tos persistente o respiración diferente a la habitual.",
                                    "4. Vómitos, diarrea o estreñimiento recurrentes.",
                                    "5. Dificultad para caminar, levantarse o subir pequeños desniveles.",
                                    "6. Dolor, rigidez o sensibilidad al tocarlo.",
                                    "7. Cambios de visión, audición, sueño u orientación.",
                                    "8. Bultos nuevos, heridas que no cicatrizan o sangrado.",
                                    "9. Dificultad para masticar, mal aliento intenso o pérdida de piezas dentales.",
                                    "10. Incontinencia o cambios al orinar.",
                                    "11. Aislamiento, irritabilidad o cambios repentinos de conducta.",
                                    "12. Debilidad o cansancio que empeora.",
                                    "13. Picazón, infecciones de piel u oídos recurrentes.",
                                    "14. Cualquier síntoma persistente que no sea habitual en él.",
                                    "15. Pérdida repentina de coordinación o equilibrio.",
                                    "16. Deterioro rápido del estado general."
                              ]
                        },
                        {
                              "titulo": "SITUACIONES DE EMERGENCIA",
                              "items": [
                                    "1. Dificultad para respirar o respiración muy trabajosa.",
                                    "2. Convulsiones, desmayo o pérdida del conocimiento.",
                                    "3. Hemorragia importante o herida profunda.",
                                    "4. Abdomen hinchado con arcadas o dolor intenso.",
                                    "5. Incapacidad para orinar o intentos repetidos sin conseguirlo.",
                                    "6. Sospecha de ingestión de tóxicos o medicamentos.",
                                    "7. Vómitos repetidos acompañados de debilidad o sangre.",
                                    "8. Golpe fuerte, caída o posible fractura.",
                                    "9. Golpe de calor, colapso o debilidad extrema.",
                                    "10. Encías muy pálidas o amarillas acompañadas de debilidad.",
                                    "11. Reacción alérgica intensa con hinchazón facial o dificultad respiratoria.",
                                    "12. Dolor intenso o incapacidad para caminar.",
                                    "13. Sangrado abundante por cualquier zona.",
                                    "14. Cualquier deterioro repentino que comprometa su estado general."
                              ]
                        }
                  ]
            }
      }
}
    }
  },
  "K’ala": {
    "nombre": "K’ala / perro sin pelo boliviano",
    "etapas": {
      "cachorro": {
        "tituloOriginal": "PERRO K’ALA — CACHORRO (0–12 MESES)",
        "temas": {
          "alimentacion": {
            "titulo": "ALIMENTACIÓN",
            "secciones": [
              {
                "titulo": "ALIMENTACIÓN SALUDABLE",
                "items": [
                  "Alimento completo para cachorros: debe recibir un alimento formulado para el crecimiento, porque durante esta etapa necesita proteínas, grasas, vitaminas y minerales en proporciones adecuadas para desarrollar músculos, huesos, órganos y defensas.",
                  "Comidas distribuidas durante el día: entre las 6 y 12 semanas suele necesitar cuatro comidas pequeñas al día; desde los 3–6 meses puede pasar a tres y, posteriormente, a dos o tres, según su desarrollo y las indicaciones veterinarias.",
                  "Agua limpia y fresca: debe tener agua disponible durante todo el día. Es importante lavar su recipiente diariamente y cambiar el agua cuando esté sucia o caliente.",
                  "Proteínas de buena calidad: el alimento debe aportar proteínas suficientes para el crecimiento. No es necesario añadir carne por separado si ya consume una dieta completa, y agregarla en exceso puede desequilibrar sus nutrientes.",
                  "Grasas saludables: las grasas proporcionan energía y ayudan al desarrollo del cerebro, el sistema nervioso y la piel. Deben provenir de una dieta equilibrada para cachorros, sin agregar aceites por cuenta propia.",
                  "Minerales para los huesos: el calcio y el fósforo deben estar equilibrados. No se deben administrar suplementos de calcio sin indicación veterinaria, ya que un exceso también puede causar problemas de desarrollo.",
                  "Cambio gradual de alimento: si necesita cambiar de marca o tipo de comida, realizar la transición durante aproximadamente 5–7 días, mezclando progresivamente el alimento nuevo con el anterior, salvo que el veterinario indique otra cosa.",
                  "Premios apropiados: pueden utilizarse pequeñas porciones de premios formulados para cachorros durante el entrenamiento. Deben representar una parte pequeña de la alimentación diaria para no desplazar los nutrientes esenciales.",
                  "Control del crecimiento: observar su peso, energía, apetito y consistencia de las heces permite detectar problemas. La cantidad de alimento debe ajustarse según su desarrollo, no solamente según cuánto pide.",
                  "Dieta casera correctamente formulada: si la familia desea ofrecerle comida preparada en casa, debe contar con una receta equilibrada elaborada por un veterinario especializado en nutrición. La carne, el arroz y las verduras por sí solos no forman necesariamente una dieta completa."
                ]
              },
              {
                "titulo": "ALIMENTACIÓN NO SALUDABLE",
                "items": [
                  "Chocolate y cafeína: el chocolate, el café, el té con cafeína y algunas bebidas energéticas pueden provocar intoxicación. El riesgo depende del producto, la cantidad y el tamaño del cachorro.",
                  "Cebolla y ajo: pueden dañar los glóbulos rojos y causar anemia. Deben evitarse crudos, cocidos, en polvo o incorporados a comidas preparadas.",
                  "Uvas y pasas: pueden provocar daño renal grave en algunos perros. No existe una cantidad que pueda considerarse segura para ofrecerlas voluntariamente.",
                  "Productos con xilitol: algunos chicles, dulces, productos dentales y alimentos sin azúcar contienen este edulcorante, que puede causar una bajada peligrosa de glucosa y daño hepático.",
                  "Huesos cocidos: pueden astillarse, provocar atragantamiento, perforaciones u obstrucciones intestinales. Tampoco deben darse huesos duros que puedan fracturar los dientes.",
                  "Sobras condimentadas: las comidas con mucha sal, grasa, salsas, cebolla, ajo o condimentos no son adecuadas para el cachorro y pueden causarle trastornos digestivos o intoxicaciones.",
                  "Leche de vaca en exceso: muchos perros no digieren bien la lactosa después del destete. Puede provocar gases, dolor abdominal y diarrea; no sustituye el agua ni una alimentación completa.",
                  "Alimentos crudos de riesgo: la carne, los huevos y otros alimentos crudos pueden contener microorganismos perjudiciales. Una dieta cruda también puede presentar desequilibrios nutricionales, especialmente peligrosos durante el crecimiento.",
                  "Comida podrida o mohosa: puede contener bacterias, toxinas u hongos que causen vómitos, diarrea y otros problemas graves. Los alimentos deben almacenarse correctamente y desecharse cuando estén deteriorados."
                ]
              }
            ]
          },
          "salud": {
            "titulo": "SALUD",
            "secciones": [
              {
                "titulo": "TIENE BUENA SALUD",
                "items": [
                  "Buen nivel de energía: juega, explora y responde a los estímulos de acuerdo con su edad. Después de jugar descansa y vuelve a sus actividades con normalidad.",
                  "Apetito adecuado: come sus raciones habituales sin presentar dolor al masticar, dificultad para tragar ni rechazo persistente del alimento.",
                  "Ojos limpios: sus ojos se ven claros y no presenta secreciones abundantes, enrojecimiento intenso, hinchazón ni dolor.",
                  "Respiración normal: respira tranquilamente en reposo, sin esfuerzo abdominal, ruidos inusuales persistentes ni episodios de ahogo.",
                  "Encías y boca saludables: las encías suelen ser rosadas, aunque puede existir pigmentación natural. No presenta sangrado, mal olor intenso ni dificultad para comer.",
                  "Digestión regular: sus heces son generalmente formadas y no presenta vómitos repetidos, diarrea persistente ni sangre en las deposiciones.",
                  "Piel y pelaje cuidados: no tiene heridas sin tratar, parásitos visibles ni picazón intensa. La cantidad de pelo y su textura dependen de sus características individuales.",
                  "Crecimiento progresivo: gana peso de manera adecuada, camina sin cojear y recibe controles veterinarios, desparasitación y vacunas conforme a su calendario."
                ]
              },
              {
                "titulo": "TIENE MALA SALUD",
                "items": [
                  "Pérdida de apetito: deja de comer, rechaza repetidamente sus raciones o parece sentir dolor al masticar. En un cachorro, la falta de alimentación puede agravarse rápidamente.",
                  "Vómitos o diarrea: los episodios repetidos, la presencia de sangre o la diarrea intensa requieren atención veterinaria. Los cachorros pueden deshidratarse en poco tiempo.",
                  "Decaimiento anormal: duerme mucho más de lo habitual, no responde como de costumbre o pierde el interés por jugar. Si la debilidad es intensa, necesita atención urgente.",
                  "Problemas respiratorios: presenta respiración trabajosa, tos persistente, encías azuladas o dificultad para respirar. Los problemas respiratorios graves son emergencias.",
                  "Alteraciones en la piel: tiene heridas, costras extensas, pérdida de pelo en zonas, picazón intensa o inflamación que podría deberse a parásitos, alergias o infecciones.",
                  "Dificultad para caminar: cojea, llora al moverse, evita apoyar una pata o no puede levantarse. Puede existir una lesión, dolor articular o fractura.",
                  "Abdomen hinchado o doloroso: se muestra inquieto, adopta posturas extrañas o se queja al tocarle el vientre. La hinchazón repentina acompañada de dolor requiere atención inmediata.",
                  "Cambios en la orina: hace esfuerzos para orinar, produce cantidades anormales o presenta sangre. Si no consigue orinar, es una emergencia.",
                  "Signos de deshidratación o enfermedad grave: presenta debilidad, encías muy pálidas, colapso, ojos hundidos o dificultad para mantenerse en pie. Debe recibir valoración veterinaria urgente."
                ]
              }
            ]
          },
          "primeros": {
            "titulo": "PRIMEROS AUXILIOS",
            "secciones": [
              {
                "titulo": "QUÉ HACER CUANDO LE SUCEDEN ACCIDENTES COMO:",
                "items": []
              },
              {
                "titulo": "CAÍDA",
                "items": [
                  "Mantener al cachorro tranquilo y evitar que corra o salte después de la caída.",
                  "Observar si está consciente y respira normalmente, sin moverle bruscamente el cuello o la espalda.",
                  "Si no puede levantarse, presenta dolor intenso, sangrado, convulsiones o dificultad respiratoria, acudir inmediatamente a urgencias veterinarias.",
                  "Si se sospecha una lesión de columna, evitar doblar el cuerpo y trasladarlo sobre una superficie firme, con ayuda de un adulto.",
                  "No administrar analgésicos humanos ni intentar acomodar una posible fractura.",
                  "Aunque parezca recuperado, una caída importante puede causar lesiones internas que no se observan a simple vista."
                ]
              },
              {
                "titulo": "HERIDAS O HEMORRAGIAS",
                "items": [
                  "Mantener al cachorro quieto y pedir ayuda a un adulto.",
                  "Presionar la herida con una gasa limpia durante varios minutos, sin levantarla repetidamente para comprobar si sigue sangrando.",
                  "Si la gasa se empapa, colocar otra encima y mantener la presión.",
                  "No retirar objetos clavados profundamente ni apretar directamente sobre ellos.",
                  "No aplicar alcohol, agua oxigenada, polvos ni remedios caseros dentro de la herida.",
                  "Si el sangrado es abundante, la herida es profunda o no se detiene, acudir inmediatamente al veterinario."
                ]
              },
              {
                "titulo": "ATRAGANTAMIENTO",
                "items": [
                  "Si puede toser y respirar, mantenerlo calmado y buscar orientación veterinaria.",
                  "Si no puede respirar, emitir sonidos o toser eficazmente, pedir ayuda inmediata y acudir a urgencias.",
                  "No introducir los dedos a ciegas en la garganta ni empujar el objeto hacia el interior.",
                  "Si el objeto se ve claramente y puede retirarse sin empujarlo ni arriesgar una mordedura, actuar con extrema precaución.",
                  "Aunque el objeto salga y el cachorro parezca recuperarse, necesita evaluación si tuvo dificultad respiratoria, tos persistente o pérdida de conocimiento."
                ]
              },
              {
                "titulo": "INTOXICACIÓN",
                "items": [
                  "Alejar al cachorro del producto y evitar que vuelva a ingerirlo.",
                  "Guardar el envase o tomar nota del nombre del producto, la cantidad aproximada y la hora de exposición.",
                  "Contactar inmediatamente con un veterinario, aunque todavía no presente síntomas.",
                  "No provocar el vómito ni darle leche, aceite, sal, medicamentos o carbón activado sin indicación profesional.",
                  "Si presenta convulsiones, dificultad respiratoria o pérdida de conocimiento, trasladarlo a urgencias de inmediato y evitar manipularle la boca."
                ]
              },
              {
                "titulo": "QUEMADURAS",
                "items": [
                  "Alejarlo de la fuente de calor o del producto que provocó la quemadura.",
                  "Enfriar la zona con agua corriente fresca durante unos 20 minutos si es posible, sin retrasar la atención veterinaria.",
                  "No utilizar hielo, mantequilla, pasta dental ni cremas caseras.",
                  "No arrancar piel ni reventar ampollas.",
                  "Cubrir suavemente la zona con una tela limpia que no se adhiera y acudir al veterinario si la quemadura es importante, extensa o afecta la cara, las patas o los genitales."
                ]
              }
            ]
          },
          "cuidados": {
            "titulo": "CUIDADOS",
            "secciones": [
              {
                "titulo": "CÓMO MANTENERLO BIEN CUIDADO",
                "items": [
                  "Higiene del pelaje: cepillarlo de acuerdo con su tipo de pelo para retirar suciedad y observar la presencia de pulgas, garrapatas, heridas o irritaciones.",
                  "Baño adecuado: bañarlo cuando lo necesite con champú específico para perros. Enjuagar bien y secarlo para evitar que permanezca húmedo durante mucho tiempo.",
                  "Cuidado de los oídos: revisar que estén limpios y sin mal olor, secreción o enrojecimiento. No introducir hisopos profundamente en el conducto auditivo.",
                  "Higiene dental: acostumbrarlo poco a poco al cepillado con pasta dental veterinaria. Nunca utilizar pasta dental humana.",
                  "Uñas: comprobar su longitud y recortarlas con herramientas apropiadas si hace falta, evitando la parte sensible que contiene vasos sanguíneos.",
                  "Ejercicio seguro: permitirle jugar y explorar durante periodos adecuados a su edad, evitando el ejercicio excesivo y los saltos desde lugares altos.",
                  "Descanso: ofrecerle una cama limpia, seca y protegida del frío, la lluvia, el calor intenso y las corrientes de aire.",
                  "Prevención de parásitos: seguir las indicaciones veterinarias para prevenir pulgas, garrapatas y parásitos intestinales.",
                  "Vacunación y controles: llevar un registro de vacunas y revisiones, especialmente durante los primeros meses.",
                  "Seguridad: mantener sustancias tóxicas, cables, medicamentos, objetos pequeños y alimentos peligrosos fuera de su alcance."
                ]
              },
              {
                "titulo": "CÓMO SABER SI NO TIENE UN BUEN CUIDADO",
                "items": [
                  "✦ HIGIENE Y APARIENCIA",
                  "Tiene el pelaje constantemente sucio, enredado o con parásitos que no reciben tratamiento.",
                  "Presenta uñas excesivamente largas, heridas sin atender o suciedad acumulada en los oídos.",
                  "Tiene mal olor persistente, picazón intensa o lesiones cutáneas ignoradas.",
                  "✦ ALIMENTACIÓN Y AGUA",
                  "Está demasiado delgado, tiene un aumento excesivo de peso o no crece adecuadamente.",
                  "No dispone de agua limpia o recibe una alimentación insuficiente y desequilibrada.",
                  "Come desperdicios o alimentos deteriorados porque no se conserva correctamente su comida.",
                  "✦ SALUD Y PREVENCIÓN",
                  "No recibe vacunas, desparasitación ni controles veterinarios.",
                  "Tiene diarrea frecuente, tos persistente, parásitos o heridas que no se atienden.",
                  "Presenta dolor o cojera sin que se busque la causa.",
                  "✦ ATENCIÓN Y AMBIENTE",
                  "Permanece aislado durante largos periodos sin compañía, juego ni estímulos.",
                  "Vive expuesto al calor extremo, frío, lluvia o suciedad, sin refugio adecuado.",
                  "No tiene un lugar tranquilo y seguro para dormir."
                ]
              }
            ]
          },
          "comportamiento": {
            "titulo": "COMPORTAMIENTO",
            "secciones": [
              {
                "titulo": "ADIESTRAMIENTO DESDE CACHORRO",
                "items": [
                  "Reconocimiento del nombre: decir su nombre con voz amable y premiarlo cuando mire hacia la persona que lo llama.",
                  "Órdenes básicas: enseñarle «ven», «siéntate», «quieto» y «suelta» mediante sesiones cortas y recompensas.",
                  "Educación para hacer sus necesidades: llevarlo al lugar adecuado al despertar, después de comer, tras jugar y antes de dormir. Premiarlo inmediatamente cuando lo haga bien.",
                  "Uso de la correa: acostumbrarlo gradualmente al collar o arnés apropiado y a caminar sin tirones.",
                  "Socialización: presentarle de forma progresiva personas, sonidos, superficies y perros sanos y vacunados, sin obligarlo a acercarse cuando tiene miedo.",
                  "Control de mordidas: redirigir las mordidas hacia juguetes seguros y hacer una pausa breve en el juego si muerde demasiado fuerte.",
                  "Prevención de conductas peligrosas: enseñarle a no recoger comida desconocida de la calle y a soltar objetos de manera voluntaria.",
                  "Acostumbramiento al manejo: tocar suavemente sus patas, revisar sus orejas y cepillarlo poco a poco para facilitar los cuidados futuros.",
                  "Aprendizaje con refuerzo positivo: premiar las conductas deseadas en lugar de utilizar golpes, gritos o castigos que provoquen miedo.",
                  "Rutina estable: combinar alimentación, paseos apropiados, juego, entrenamiento y descanso para favorecer su aprendizaje."
                ]
              },
              {
                "titulo": "CÓMO MEJORAR EL COMPORTAMIENTO DE TU MASCOTA SI NO FUE ADIESTRADO",
                "items": [
                  "Empezar por una orden sencilla y practicarla en un lugar tranquilo, sin demasiadas distracciones.",
                  "Utilizar premios pequeños, juguetes o elogios para reforzar las respuestas correctas.",
                  "Establecer horarios regulares para comer, jugar, salir a hacer sus necesidades y dormir.",
                  "Si muerde muebles o zapatos, retirar el acceso a esos objetos y ofrecerle juguetes seguros.",
                  "Si tira de la correa, premiarlo cuando camine cerca de la persona y detenerse si la tensión continúa.",
                  "Si ladra demasiado, identificar si lo desencadenan el miedo, el aburrimiento, los ruidos o la necesidad de atención.",
                  "Si teme a personas o animales, aumentar la distancia y permitirle acercarse a su propio ritmo.",
                  "Evitar gritos, golpes y castigos físicos, porque pueden aumentar el miedo y las respuestas defensivas.",
                  "Practicar durante pocos minutos varias veces al día, ajustando la dificultad al progreso del cachorro.",
                  "Si aparecen agresividad intensa, ansiedad persistente o cambios repentinos de conducta, solicitar ayuda veterinaria y profesional."
                ]
              }
            ]
          },
          "vacunacion": {
            "titulo": "VACUNACIÓN",
            "secciones": [
              {
                "titulo": "TODAS LAS VACUNAS CON LAS QUE DEBERÍA CONTAR LA MASCOTA HASTA EL DÍA DE SU MUERTE",
                "items": [
                  "El calendario debe ajustarse a las normas sanitarias de Bolivia, las vacunas disponibles, el riesgo de exposición y el historial individual. El veterinario debe registrar cada dosis y establecer los refuerzos.",
                  "Moquillo canino: vacuna esencial para prevenir una enfermedad viral grave. La serie inicial suele comenzar entre las 6 y 8 semanas de edad.",
                  "Parvovirus canino: vacuna esencial, especialmente importante en cachorros porque la enfermedad puede causar vómitos, diarrea intensa y deshidratación.",
                  "Adenovirus canino: protege frente al adenovirus implicado en la hepatitis infecciosa canina y suele formar parte de las vacunas combinadas.",
                  "Parainfluenza canina: puede estar incluida en algunas vacunas combinadas. Su indicación depende del riesgo de exposición a otros perros.",
                  "Leptospirosis: se recomienda según la zona, la exposición a roedores o agua contaminada y la valoración veterinaria. Habitualmente requiere una serie inicial y refuerzos.",
                  "Rabia: es fundamental por su importancia para la salud pública y debe aplicarse conforme al calendario y las disposiciones oficiales de Bolivia.",
                  "Bordetella: puede recomendarse si el cachorro estará en guarderías, residencias, exposiciones o lugares donde convive estrechamente con muchos perros.",
                  "Influenza canina u otras vacunas específicas: solo se consideran si están disponibles y el riesgo epidemiológico justifica su uso.",
                  "Calendario orientativo:",
                  "6–8 semanas: inicio de la vacunación esencial, según la evaluación veterinaria.",
                  "Cada 2–4 semanas hasta al menos las 16 semanas: continuación de las dosis esenciales para cubrir el periodo en que los anticuerpos maternos pueden interferir con la respuesta a la vacuna.",
                  "Alrededor de las 12 semanas o según la normativa local: vacuna contra la rabia, conforme a la edad autorizada y las disposiciones oficiales.",
                  "Durante el primer año: refuerzos según el producto utilizado, el historial y las recomendaciones veterinarias.",
                  "Después del primer año: refuerzos posteriores según la vacuna, la normativa y el riesgo de exposición.",
                  "No todas las vacunas se administran anualmente. La frecuencia de los refuerzos depende del producto, de la legislación y de la valoración profesional."
                ]
              }
            ]
          },
          "veterinario": {
            "titulo": "CUÁNDO IR AL VETERINARIO",
            "secciones": [
              {
                "titulo": "EN QUÉ SITUACIONES DE EMERGENCIA DEBES DE ACUDIR A UN VETERINARIO",
                "items": [
                  "Hemorragia: una pérdida importante de sangre puede provocar debilidad y shock. Presionar suavemente con una gasa limpia mientras se busca atención.",
                  "Fractura: una caída o golpe puede romper un hueso y dañar tejidos cercanos. No intentar acomodar la extremidad.",
                  "Vómitos constantes: pueden provocar deshidratación y ser señal de infección, intoxicación u obstrucción.",
                  "Dificultad para respirar: puede indicar una obstrucción o una enfermedad grave y requiere atención inmediata.",
                  "Convulsiones: si son prolongadas, se repiten o es la primera vez que ocurren, el cachorro necesita valoración urgente. No introducir objetos en su boca.",
                  "Abdomen hinchado y doloroso: puede indicar una afección grave, especialmente si también intenta vomitar sin conseguirlo.",
                  "Intoxicación: medicamentos, productos de limpieza, venenos y alimentos tóxicos pueden causar daños graves. No provocar el vómito sin instrucciones veterinarias.",
                  "Diarrea intensa o con sangre: puede causar deshidratación rápidamente y estar relacionada con enfermedades infecciosas.",
                  "Golpe en la cabeza: puede ocasionar lesiones internas aunque no se observen heridas externas.",
                  "Incapacidad para orinar: puede indicar una obstrucción urinaria que necesita tratamiento inmediato.",
                  "Desmayo o debilidad extrema: pueden estar relacionados con problemas circulatorios, intoxicación u otras enfermedades graves.",
                  "Quemaduras importantes: pueden causar dolor intenso, infección y pérdida de líquidos, por lo que requieren atención profesional."
                ]
              }
            ]
          }
        }
      },
      "adulto": {
        "tituloOriginal": "PERRO K’ALA — ADULTO (1–9 AÑOS, APROXIMADAMENTE)",
        "temas": {
          "alimentacion": {
            "titulo": "ALIMENTACIÓN",
            "secciones": [
              {
                "titulo": "ALIMENTACIÓN SALUDABLE",
                "items": [
                  "Alimento completo para adultos: ofrecer una dieta formulada para perros adultos, con proteínas, grasas, carbohidratos, vitaminas y minerales en proporciones equilibradas para mantener sus músculos y órganos.",
                  "Raciones adecuadas al tamaño y actividad: calcular la cantidad diaria según el peso, la actividad física, la condición corporal y las indicaciones del fabricante. Un perro muy activo puede necesitar más energía que uno sedentario.",
                  "Agua limpia y permanente: debe disponer de agua fresca durante todo el día, especialmente después de jugar, pasear o permanecer en un ambiente cálido.",
                  "Proteínas de calidad: contribuyen al mantenimiento muscular, la reparación de tejidos y el funcionamiento del sistema inmunitario. Una dieta completa normalmente aporta las cantidades necesarias.",
                  "Grasas equilibradas: proporcionan energía y favorecen la piel y el pelaje. No añadir aceites o suplementos sin comprobar si realmente los necesita.",
                  "Fibra y digestión: la fibra presente en un alimento equilibrado favorece el tránsito intestinal. Cualquier cambio en las heces debe evaluarse si persiste o se acompaña de otros síntomas.",
                  "Horarios regulares: muchos perros adultos se alimentan adecuadamente con dos comidas diarias, aunque la frecuencia puede variar según sus necesidades individuales.",
                  "Premios moderados: los premios deben ser apropiados para perros y no representar una proporción excesiva de las calorías diarias. Si recibe muchos, hay que ajustar la ración principal.",
                  "Control de peso: revisar periódicamente su condición corporal permite detectar aumentos o pérdidas de peso. Las costillas deben poder palparse con facilidad razonable sin sobresalir excesivamente.",
                  "Comida casera equilibrada: si se desea alimentarlo con una dieta preparada en casa, debe ser formulada por un veterinario especializado en nutrición para evitar deficiencias o excesos."
                ]
              },
              {
                "titulo": "ALIMENTACIÓN NO SALUDABLE",
                "items": [
                  "Chocolate y cafeína: pueden causar vómitos, inquietud, alteraciones del ritmo cardiaco y otros problemas según la cantidad ingerida.",
                  "Cebolla y ajo: pueden dañar los glóbulos rojos y provocar anemia, incluso cuando forman parte de comidas preparadas.",
                  "Uvas y pasas: pueden causar daño renal. Si las ingiere, hay que contactar con el veterinario de inmediato.",
                  "Productos con xilitol: este edulcorante puede provocar una caída peligrosa de la glucosa y lesión hepática.",
                  "Huesos cocidos y objetos duros: pueden causar atragantamiento, obstrucciones, perforaciones intestinales o fracturas dentales.",
                  "Sobras grasas y condimentadas: pueden provocar trastornos digestivos y, en algunos casos, pancreatitis. También pueden contener ingredientes tóxicos como cebolla y ajo.",
                  "Exceso de sal y azúcar: no aporta beneficios y puede contribuir a problemas de salud, especialmente si se consume de forma frecuente.",
                  "Alimentos crudos o deteriorados: pueden contener bacterias, parásitos o toxinas. La comida debe conservarse correctamente y ofrecerse en condiciones higiénicas.",
                  "Exceso de comida y premios: una ración demasiado grande puede causar sobrepeso y dificultar la movilidad, por lo que las cantidades deben ajustarse a sus necesidades."
                ]
              }
            ]
          },
          "salud": {
            "titulo": "SALUD",
            "secciones": [
              {
                "titulo": "TIENE BUENA SALUD",
                "items": [
                  "Energía estable: realiza sus actividades habituales, disfruta de los paseos y descansa después del ejercicio sin agotamiento desproporcionado.",
                  "Apetito normal: consume sus raciones de manera habitual y no presenta dificultades para masticar o tragar.",
                  "Ojos claros: no presenta enrojecimiento persistente, secreción abundante, hinchazón ni signos de dolor.",
                  "Respiración tranquila: respira sin esfuerzo en reposo y no presenta tos persistente ni episodios de ahogo.",
                  "Boca y encías cuidadas: las encías suelen ser rosadas, salvo pigmentación natural. No presenta dolor al masticar, sangrado ni mal aliento intenso.",
                  "Peso estable: mantiene una condición corporal adecuada y no gana ni pierde peso sin explicación.",
                  "Piel y pelaje en buen estado: no presenta heridas sin atender, picazón intensa ni parásitos visibles.",
                  "Movilidad normal: camina, corre y se levanta sin cojera ni rigidez persistente, y recibe atención preventiva según sus necesidades."
                ]
              },
              {
                "titulo": "TIENE MALA SALUD",
                "items": [
                  "Pérdida de apetito o sed anormal: deja de comer, bebe mucho más o mucho menos de lo habitual, o presenta cambios persistentes en sus hábitos.",
                  "Vómitos o diarrea repetidos: pueden deberse a trastornos digestivos, parásitos, infecciones o intoxicaciones.",
                  "Pérdida o aumento de peso inexplicable: puede relacionarse con problemas nutricionales, hormonales o enfermedades internas.",
                  "Dificultad respiratoria o tos persistente: requiere evaluación, especialmente si se acompaña de debilidad o encías azuladas.",
                  "Problemas de piel: la picazón intensa, las heridas, las costras o la caída anormal del pelo pueden indicar alergias, parásitos o infecciones.",
                  "Cojera o rigidez: puede ser señal de una lesión, dolor articular u otro problema musculoesquelético.",
                  "Cambios en la orina: orina con sangre, presenta dolor al orinar o comienza a hacerlo con mucha más frecuencia.",
                  "Cambios de conducta: se vuelve repentinamente irritable, se esconde, evita el contacto o muestra agresividad que no era habitual.",
                  "Decaimiento importante: presenta debilidad extrema, desmayo, encías muy pálidas o dificultad para mantenerse de pie. Estos signos requieren atención urgente."
                ]
              }
            ]
          },
          "primeros": {
            "titulo": "PRIMEROS AUXILIOS",
            "secciones": [
              {
                "titulo": "QUÉ HACER CUANDO LE SUCEDEN ACCIDENTES COMO:",
                "items": []
              },
              {
                "titulo": "CAÍDA",
                "items": [
                  "Mantenerlo quieto y evitar que camine si presenta dolor o cojera.",
                  "Comprobar si respira con normalidad y si responde a la voz.",
                  "Si no puede levantarse, se golpeó la cabeza o muestra dolor intenso, evitar moverlo innecesariamente.",
                  "Si se sospecha una lesión de columna, transportarlo con el cuerpo alineado sobre una superficie firme.",
                  "No intentar enderezar extremidades ni administrar analgésicos humanos.",
                  "Buscar atención veterinaria si la caída fue importante o si aparecen cambios en su comportamiento, respiración o movilidad."
                ]
              },
              {
                "titulo": "HERIDAS O HEMORRAGIAS",
                "items": [
                  "Mantenerlo tranquilo y utilizar una barrera segura si el dolor hace que pueda morder involuntariamente.",
                  "Presionar la herida con una gasa limpia sin levantarla repetidamente.",
                  "Si el sangrado es abundante o no se detiene, acudir a urgencias.",
                  "No extraer objetos profundamente clavados ni colocar torniquetes improvisados.",
                  "Evitar alcohol, agua oxigenada y polvos sobre la herida.",
                  "El veterinario debe evaluar heridas profundas, mordeduras y lesiones cercanas a los ojos, articulaciones o tórax."
                ]
              },
              {
                "titulo": "ATRAGANTAMIENTO",
                "items": [
                  "Si puede respirar y toser, evitar introducir objetos en su boca y contactar con un veterinario si los síntomas persisten.",
                  "Si no puede respirar o pierde el conocimiento, pedir ayuda inmediata y trasladarlo a urgencias.",
                  "No introducir los dedos a ciegas ni empujar el objeto más profundamente.",
                  "Si el objeto está claramente visible y puede retirarse sin riesgo, hacerlo con mucha precaución.",
                  "Después de un episodio grave, necesita valoración aunque parezca recuperado, porque pueden existir lesiones en la garganta o los pulmones."
                ]
              },
              {
                "titulo": "INTOXICACIÓN",
                "items": [
                  "Retirar el producto y evitar nuevas exposiciones.",
                  "Identificar la sustancia y la cantidad aproximada ingerida.",
                  "Llamar inmediatamente al veterinario, sin esperar a que aparezcan síntomas.",
                  "No inducir el vómito ni administrar leche, aceite, medicamentos o remedios caseros.",
                  "Llevar el envase o una fotografía de la etiqueta para ayudar a identificar el tóxico."
                ]
              },
              {
                "titulo": "QUEMADURAS",
                "items": [
                  "Alejarlo de la fuente de calor o de la sustancia irritante.",
                  "Enfriar la zona con agua corriente fresca durante unos 20 minutos, si es posible sin retrasar la atención.",
                  "No aplicar hielo, mantequilla, pasta dental ni cremas no indicadas.",
                  "No romper ampollas ni arrancar la piel.",
                  "Cubrir suavemente la zona con una tela limpia y acudir al veterinario si la quemadura es extensa, profunda o afecta zonas sensibles."
                ]
              }
            ]
          },
          "cuidados": {
            "titulo": "CUIDADOS",
            "secciones": [
              {
                "titulo": "CÓMO MANTENERLO BIEN CUIDADO",
                "items": [
                  "Alimentación controlada: medir las raciones y ajustar la cantidad si cambia su actividad, peso o condición corporal.",
                  "Ejercicio diario: ofrecer paseos y juegos apropiados a su energía, aumentando o reduciendo la actividad según su capacidad física.",
                  "Cepillado: adaptar la frecuencia al tipo de pelaje para retirar pelo suelto y detectar parásitos o lesiones.",
                  "Baño: utilizar champú para perros y secarlo adecuadamente después del baño.",
                  "Higiene dental: cepillar sus dientes con productos veterinarios y consultar si presenta sarro, dolor o mal aliento persistente.",
                  "Cuidado de uñas: mantenerlas a una longitud adecuada para que no dificulten el apoyo de las patas.",
                  "Control de parásitos: seguir un plan veterinario de prevención de pulgas, garrapatas y parásitos intestinales.",
                  "Ambiente seguro: proporcionar agua, sombra, refugio y una cama limpia, sin mantenerlo expuesto al calor extremo.",
                  "Estimulación mental: ofrecer juguetes seguros, juegos de olfato y oportunidades para explorar.",
                  "Revisiones veterinarias: realizar controles periódicos y mantener al día las vacunas que correspondan según su edad y riesgo."
                ]
              },
              {
                "titulo": "CÓMO SABER SI NO TIENE UN BUEN CUIDADO",
                "items": [
                  "✦ HIGIENE Y PELAJE",
                  "Presenta pelo enredado, suciedad persistente, parásitos o lesiones cutáneas sin tratar.",
                  "Tiene uñas demasiado largas o molestias en las patas por falta de mantenimiento.",
                  "✦ ALIMENTACIÓN",
                  "Está excesivamente delgado o tiene sobrepeso por recibir raciones inadecuadas.",
                  "No tiene agua limpia disponible o come principalmente sobras desequilibradas.",
                  "✦ SALUD",
                  "No recibe atención preventiva y tiene problemas de salud que se ignoran.",
                  "Presenta dolor dental, cojera, picazón o cambios de peso sin evaluación.",
                  "✦ ATENCIÓN Y AMBIENTE",
                  "Permanece atado o aislado durante periodos prolongados sin ejercicio ni interacción.",
                  "No tiene refugio adecuado ni un lugar limpio para descansar.",
                  "Carece de oportunidades de juego, paseo y estimulación mental."
                ]
              }
            ]
          },
          "comportamiento": {
            "titulo": "COMPORTAMIENTO",
            "secciones": [
              {
                "titulo": "ADIESTRAMIENTO DESDE CACHORRO",
                "items": [
                  "Enseñar su nombre y órdenes básicas con recompensas y constancia.",
                  "Practicar el llamado para que acuda cuando se le necesite.",
                  "Acostumbrarlo a caminar con correa sin tirar ni perseguir personas o animales.",
                  "Enseñarle a esperar antes de cruzar una puerta o acercarse a la comida.",
                  "Reforzar las conductas tranquilas cuando llegan visitas o aparecen ruidos nuevos.",
                  "Ofrecer juguetes y juegos de olfato para reducir el aburrimiento.",
                  "Enseñarle a soltar objetos mediante intercambios por juguetes o premios apropiados.",
                  "Acostumbrarlo al cepillado, la revisión de patas y los controles veterinarios.",
                  "Mantener rutinas previsibles de paseo, comida, descanso y juego.",
                  "Evitar golpes y castigos físicos, utilizando refuerzo positivo para desarrollar confianza y cooperación."
                ]
              },
              {
                "titulo": "CÓMO MEJORAR EL COMPORTAMIENTO DE TU MASCOTA SI NO FUE ADIESTRADO",
                "items": [
                  "Empezar por identificar el comportamiento que se desea mejorar y qué situaciones lo provocan.",
                  "Practicar órdenes básicas en lugares tranquilos y aumentar gradualmente las distracciones.",
                  "Recompensar la conducta adecuada inmediatamente para que pueda asociarla con el resultado positivo.",
                  "Si tira de la correa, practicar caminatas cortas y premiar cuando camine sin tensión.",
                  "Si ladra ante visitas o ruidos, trabajar desde una distancia en la que pueda permanecer tranquilo.",
                  "Si destruye objetos, aumentar la estimulación y ofrecer juguetes adecuados, sin dejar a su alcance objetos peligrosos.",
                  "Si teme a otros perros, evitar los encuentros forzados y solicitar orientación profesional si el miedo persiste.",
                  "Si muestra agresividad, mantener distancia y seguridad, sin castigar ni intentar dominarlo físicamente.",
                  "Establecer horarios de actividad y descanso para reducir el aburrimiento y la frustración.",
                  "Si la conducta cambia repentinamente, consultar con el veterinario para descartar dolor o enfermedad."
                ]
              }
            ]
          },
          "vacunacion": {
            "titulo": "VACUNACIÓN",
            "secciones": [
              {
                "titulo": "TODAS LAS VACUNAS CON LAS QUE DEBERÍA CONTAR LA MASCOTA HASTA EL DÍA DE SU MUERTE",
                "items": [
                  "Moquillo canino: vacuna esencial que ayuda a prevenir una enfermedad viral grave. Los refuerzos posteriores dependen del historial y de las recomendaciones vigentes.",
                  "Parvovirus canino: vacuna esencial para prevenir una enfermedad que puede causar vómitos, diarrea y deshidratación.",
                  "Adenovirus canino: suele estar incluido en la vacuna combinada y protege contra la hepatitis infecciosa canina.",
                  "Parainfluenza canina: puede indicarse de acuerdo con la exposición a otros perros y suele formar parte de algunas vacunas combinadas.",
                  "Leptospirosis: se recomienda según el riesgo local, el contacto con roedores, agua contaminada y las indicaciones veterinarias.",
                  "Rabia: debe mantenerse de acuerdo con las disposiciones oficiales bolivianas y la pauta correspondiente a la vacuna aplicada.",
                  "Bordetella: puede ser recomendable para perros que acuden a guarderías, residencias o lugares con contacto estrecho y frecuente con otros perros.",
                  "Influenza canina u otras vacunas específicas: se consideran únicamente cuando existen indicaciones epidemiológicas y disponibilidad.",
                  "Si el perro adulto no tiene historial de vacunación: el veterinario establecerá un calendario de recuperación. No debe suponerse que necesita repetir todas las dosis de cachorro sin revisar su historial.",
                  "Las vacunas esenciales suelen requerir refuerzos a lo largo de la vida, pero no todas tienen la misma frecuencia. La vacunación contra la rabia debe seguir las normas sanitarias locales."
                ]
              }
            ]
          },
          "veterinario": {
            "titulo": "CUÁNDO IR AL VETERINARIO",
            "secciones": [
              {
                "titulo": "EN QUÉ SITUACIONES DE EMERGENCIA DEBES DE ACUDIR A UN VETERINARIO",
                "items": [
                  "Hemorragia: una pérdida importante de sangre puede provocar shock y necesita atención inmediata.",
                  "Fractura: un hueso roto puede dañar nervios y tejidos; no se debe intentar acomodarlo.",
                  "Vómitos constantes: pueden provocar deshidratación y señalar una intoxicación, obstrucción o enfermedad importante.",
                  "Dificultad para respirar: puede indicar una emergencia respiratoria o cardiaca.",
                  "Convulsiones: requieren atención urgente si son prolongadas, repetidas o aparecen por primera vez.",
                  "Abdomen hinchado y doloroso: puede ser señal de una afección potencialmente mortal.",
                  "Ingestión de tóxicos: requiere orientación veterinaria inmediata, incluso si aún no hay síntomas.",
                  "Diarrea con sangre: puede estar relacionada con enfermedades digestivas graves o pérdida importante de líquidos.",
                  "Golpe fuerte: una caída o accidente puede provocar lesiones internas que no son evidentes.",
                  "Incapacidad para orinar: puede indicar una obstrucción que necesita tratamiento urgente.",
                  "Desmayo o debilidad extrema: pueden ser señales de un problema circulatorio, intoxicación o enfermedad grave.",
                  "Quemaduras importantes: necesitan evaluación para controlar el dolor y prevenir complicaciones."
                ]
              }
            ]
          }
        }
      },
      "senior": {
        "tituloOriginal": "PERRO K’ALA — SENIOR O GERIÁTRICO (10 AÑOS EN ADELANTE, COMO REFERENCIA)",
        "temas": {
          "alimentacion": {
            "titulo": "ALIMENTACIÓN",
            "secciones": [
              {
                "titulo": "ALIMENTACIÓN SALUDABLE",
                "items": [
                  "Alimento adecuado para perros mayores: elegir una dieta completa que se adapte a su condición física, nivel de actividad y estado de salud. No todos los perros mayores necesitan la misma fórmula.",
                  "Raciones ajustadas a su actividad: muchos perros mayores se mueven menos y necesitan menos energía, aunque otros pueden mantener una actividad elevada. Ajustar las cantidades para evitar el sobrepeso o la pérdida muscular.",
                  "Agua fresca siempre disponible: mantener recipientes accesibles y observar si bebe mucho más o mucho menos de lo habitual, porque los cambios pueden ser señales de enfermedad.",
                  "Proteínas de calidad: los perros mayores necesitan conservar su masa muscular. No debe reducirse la proteína automáticamente por la edad; si existe enfermedad renal u otra condición, la dieta debe ajustarse con el veterinario.",
                  "Textura fácil de masticar: si tiene dientes ausentes o molestias dentales, puede necesitar alimento húmedo o croquetas adaptadas. La dificultad para comer requiere una revisión dental.",
                  "Fibra equilibrada: una dieta apropiada puede ayudar a mantener la regularidad intestinal. El estreñimiento persistente necesita evaluación para descartar deshidratación, dolor u otras enfermedades.",
                  "Comidas regulares: dividir la ración en dos o más comidas puede facilitar la alimentación de algunos perros mayores, especialmente si tienen menor apetito o molestias digestivas.",
                  "Premios moderados: utilizar premios pequeños y apropiados, teniendo en cuenta su aporte calórico. Si tiene enfermedades crónicas, los premios también deben ser compatibles con su dieta terapéutica.",
                  "Control del peso y los músculos: pesarlo periódicamente y observar si pierde músculo, se le marcan demasiado los huesos o acumula grasa permite detectar cambios tempranos.",
                  "Dieta especial bajo supervisión: si padece enfermedad renal, cardiaca, diabetes u otra condición, el veterinario puede recomendar una dieta terapéutica específica. No cambiar su alimentación por cuenta propia."
                ]
              },
              {
                "titulo": "ALIMENTACIÓN NO SALUDABLE",
                "items": [
                  "Chocolate y cafeína: pueden provocar intoxicación y problemas cardiacos o neurológicos; el riesgo no desaparece por tratarse de un perro de edad avanzada.",
                  "Cebolla y ajo: pueden dañar los glóbulos rojos y causar anemia, incluso si se encuentran en alimentos cocinados.",
                  "Uvas y pasas: pueden ocasionar daño renal grave y deben mantenerse fuera de su alcance.",
                  "Productos con xilitol: pueden causar una bajada peligrosa de glucosa y lesión hepática.",
                  "Huesos duros o cocidos: pueden provocar fracturas dentales, atragantamiento, lesiones digestivas u obstrucciones.",
                  "Sobras con mucha grasa: pueden ocasionar molestias digestivas y aumentar el riesgo de pancreatitis. No son adecuadas como alimento habitual.",
                  "Alimentos muy salados: las comidas procesadas y los embutidos no son apropiados como parte regular de su dieta, especialmente si tiene enfermedades cardiacas o renales.",
                  "Comida deteriorada o cruda de riesgo: puede contener bacterias, parásitos o toxinas capaces de provocar enfermedades graves.",
                  "Cambios bruscos y dietas improvisadas: sustituir de golpe su alimento o administrar suplementos sin orientación puede agravar trastornos digestivos o interferir con el manejo de enfermedades."
                ]
              }
            ]
          },
          "salud": {
            "titulo": "SALUD",
            "secciones": [
              {
                "titulo": "TIENE BUENA SALUD",
                "items": [
                  "Mantiene interés por su entorno: aunque descanse más, responde a su familia, disfruta de actividades apropiadas y conserva hábitos habituales.",
                  "Come de forma regular: mantiene su apetito y puede masticar y tragar sin dolor ni dificultad.",
                  "Peso relativamente estable: no pierde ni gana peso de manera inexplicable y conserva una masa muscular razonable.",
                  "Respira sin esfuerzo: no presenta dificultad respiratoria, tos persistente ni desmayos.",
                  "Ojos y boca cuidados: no presenta dolor ocular, secreción abundante ni dificultades importantes para masticar. Los cambios de visión deben revisarse.",
                  "Digestión regular: sus heces y hábitos intestinales se mantienen relativamente estables, sin vómitos o diarrea persistentes.",
                  "Movilidad adaptada a su edad: puede levantarse, caminar y cambiar de postura, aunque necesite más tiempo o paseos más suaves.",
                  "Controles preventivos regulares: recibe evaluaciones veterinarias, revisión dental y vacunas o medidas preventivas según su salud, historial y riesgo."
                ]
              },
              {
                "titulo": "TIENE MALA SALUD",
                "items": [
                  "Pérdida de peso o musculatura: puede relacionarse con enfermedades crónicas, problemas dentales, alteraciones hormonales o alimentación insuficiente.",
                  "Disminución persistente del apetito: puede indicar dolor, enfermedad digestiva, problemas renales o dificultad para masticar.",
                  "Aumento excesivo de sed u orina: puede ser señal de enfermedad renal, diabetes u otros problemas y necesita evaluación veterinaria.",
                  "Tos o dificultad respiratoria: pueden relacionarse con enfermedades cardiacas, pulmonares u otras afecciones importantes.",
                  "Problemas dentales: el mal aliento intenso, sangrado de encías, dolor o rechazo del alimento pueden indicar enfermedad periodontal.",
                  "Rigidez y dolor al moverse: puede presentar dificultad para levantarse, cojera o menor disposición a caminar por problemas articulares u otras causas.",
                  "Cambios en la visión o audición: puede chocar con objetos, sobresaltarse al acercarse alguien o responder menos a los sonidos. Estos cambios deben evaluarse para descartar causas tratables.",
                  "Desorientación o alteraciones del sueño: puede confundirse en lugares conocidos, caminar sin rumbo o cambiar sus horarios. Estos signos no deben atribuirse automáticamente a la edad.",
                  "Debilidad grave o colapso: si no puede levantarse, se desmaya, tiene encías muy pálidas o respira con dificultad, necesita atención urgente."
                ]
              }
            ]
          },
          "primeros": {
            "titulo": "PRIMEROS AUXILIOS",
            "secciones": [
              {
                "titulo": "QUÉ HACER CUANDO LE SUCEDEN ACCIDENTES COMO:",
                "items": []
              },
              {
                "titulo": "CAÍDA",
                "items": [
                  "Acercarse con calma y observar si responde y respira normalmente.",
                  "No obligarlo a levantarse ni caminar si muestra dolor, debilidad o pérdida de equilibrio.",
                  "Si se sospecha una lesión de columna, trasladarlo sobre una superficie firme manteniendo el cuerpo alineado.",
                  "Evitar mover bruscamente las articulaciones o intentar enderezar extremidades.",
                  "Buscar atención veterinaria inmediata si no puede levantarse, presenta dolor intenso, golpe en la cabeza o dificultad respiratoria.",
                  "Aunque la caída parezca leve, consultar si posteriormente aparece cojera, desorientación o pérdida del apetito."
                ]
              },
              {
                "titulo": "HERIDAS O HEMORRAGIAS",
                "items": [
                  "Mantenerlo tranquilo y manipularlo con suavidad, porque el dolor puede provocar una reacción defensiva.",
                  "Presionar la herida con una gasa limpia y mantener la presión.",
                  "Si el sangrado es abundante, no se detiene o el perro presenta debilidad, acudir de inmediato a urgencias.",
                  "No retirar objetos profundamente clavados ni aplicar alcohol o agua oxigenada.",
                  "Evitar vendas demasiado apretadas, especialmente en las extremidades.",
                  "Las heridas profundas, mordeduras y lesiones que afectan articulaciones requieren revisión veterinaria."
                ]
              },
              {
                "titulo": "ATRAGANTAMIENTO",
                "items": [
                  "Si todavía respira y tose, mantenerlo tranquilo y buscar asistencia veterinaria si los síntomas continúan.",
                  "Si no puede respirar, pierde el conocimiento o se pone muy débil, acudir a urgencias inmediatamente.",
                  "No introducir los dedos a ciegas en la boca ni empujar objetos hacia el interior.",
                  "Evitar maniobras improvisadas que puedan causar lesiones; seguir las instrucciones de un profesional veterinario.",
                  "Después del episodio, necesita valoración si persisten la tos, la respiración ruidosa o la dificultad para tragar."
                ]
              },
              {
                "titulo": "INTOXICACIÓN",
                "items": [
                  "Alejarlo de la sustancia tóxica y evitar una nueva exposición.",
                  "Identificar el producto, conservar el envase y anotar la cantidad aproximada y la hora.",
                  "Contactar inmediatamente con un veterinario, incluso si todavía no presenta síntomas.",
                  "No inducir el vómito ni ofrecer leche, aceite, carbón activado o medicamentos sin indicación profesional.",
                  "Si presenta convulsiones, dificultad respiratoria o pérdida de conocimiento, trasladarlo a urgencias sin demora."
                ]
              },
              {
                "titulo": "QUEMADURAS",
                "items": [
                  "Retirarlo de la fuente de calor o del producto irritante.",
                  "Enfriar la zona con agua corriente fresca durante unos 20 minutos, siempre que esto no retrase la atención.",
                  "No aplicar hielo, mantequilla, pasta dental ni cremas caseras.",
                  "No arrancar la piel dañada ni romper ampollas.",
                  "Cubrir suavemente la zona con una tela limpia y acudir al veterinario, especialmente si la quemadura es extensa o afecta zonas sensibles."
                ]
              }
            ]
          },
          "cuidados": {
            "titulo": "CUIDADOS",
            "secciones": [
              {
                "titulo": "CÓMO MANTENERLO BIEN CUIDADO",
                "items": [
                  "Alimentación adaptada: elegir un alimento apropiado para su condición corporal y sus enfermedades, si las tiene. Los cambios de dieta deben realizarse con orientación veterinaria.",
                  "Ejercicio moderado: ofrecer paseos más cortos y frecuentes si se cansa fácilmente, sin forzarlo a correr o saltar.",
                  "Superficie antideslizante: colocar alfombras o superficies con buen agarre en las zonas donde camina para reducir el riesgo de caídas.",
                  "Cama cómoda: proporcionarle una cama acolchada, seca y fácil de alcanzar, protegida del frío y del calor excesivo.",
                  "Acceso a comida y agua: ubicar los recipientes donde pueda llegar sin subir escaleras ni caminar sobre superficies resbaladizas.",
                  "Higiene cuidadosa: cepillarlo, bañarlo cuando sea necesario y secarlo bien. La piel de algunos perros mayores puede ser más delicada.",
                  "Cuidado dental: revisar periódicamente sus dientes y encías y consultar si tiene dolor, mal aliento o dificultad para comer.",
                  "Control de uñas: evitar que las uñas demasiado largas dificulten el apoyo y la estabilidad al caminar.",
                  "Estimulación mental: ofrecer juegos de olfato sencillos, interacción tranquila y actividades que pueda realizar sin dolor.",
                  "Controles veterinarios más frecuentes: realizar revisiones periódicas, a menudo cada seis meses o según indique el veterinario, para detectar enfermedades antes de que avancen."
                ]
              },
              {
                "titulo": "CÓMO SABER SI NO TIENE UN BUEN CUIDADO",
                "items": [
                  "✦ HIGIENE Y COMODIDAD",
                  "Tiene el pelo sucio, las uñas excesivamente largas o la piel irritada por falta de mantenimiento.",
                  "No dispone de una cama cómoda y seca que le permita descansar sin dolor.",
                  "✦ ALIMENTACIÓN Y AGUA",
                  "Pierde peso o masa muscular sin que se investigue la causa.",
                  "Tiene dificultad para alcanzar el agua o comer porque sus recipientes están mal ubicados.",
                  "Recibe suplementos o dietas restrictivas sin supervisión veterinaria.",
                  "✦ SALUD Y PREVENCIÓN",
                  "Se ignoran el dolor, la cojera, los problemas dentales o los cambios de comportamiento.",
                  "No recibe controles veterinarios a pesar de presentar enfermedades o signos persistentes.",
                  "✦ ATENCIÓN Y MOVILIDAD",
                  "Se le obliga a realizar ejercicio excesivo pese a mostrar dolor o agotamiento.",
                  "Vive en un lugar donde resbala constantemente o debe subir escaleras que ya no puede utilizar con seguridad.",
                  "Permanece aislado, sin interacción, compañía ni actividades adecuadas a su capacidad."
                ]
              }
            ]
          },
          "comportamiento": {
            "titulo": "COMPORTAMIENTO",
            "secciones": [
              {
                "titulo": "ADIESTRAMIENTO DESDE CACHORRO",
                "items": [
                  "Enseñar órdenes básicas con refuerzo positivo, sesiones breves y recompensas.",
                  "Acostumbrarlo a caminar con correa y regresar cuando se le llama.",
                  "Enseñarle a esperar antes de salir por una puerta y a mantener distancia segura de la calle.",
                  "Premiar las conductas tranquilas y las interacciones respetuosas con las personas.",
                  "Introducir progresivamente el cepillado, la revisión de patas y la manipulación suave.",
                  "Enseñarle a aceptar visitas veterinarias mediante experiencias graduales y recompensas.",
                  "Mantener una rutina que combine ejercicio, descanso, comida y estimulación mental.",
                  "Evitar castigos físicos que puedan generar miedo, dolor o desconfianza.",
                  "Proporcionar experiencias positivas con otros perros cuando sea seguro y apropiado.",
                  "Adaptar las sesiones de aprendizaje a su capacidad de atención y a su nivel de energía."
                ]
              },
              {
                "titulo": "CÓMO MEJORAR EL COMPORTAMIENTO DE TU MASCOTA SI NO FUE ADIESTRADO",
                "items": [
                  "Comenzar con órdenes sencillas y recompensar las respuestas correctas.",
                  "Practicar en un ambiente tranquilo, aumentando las distracciones poco a poco.",
                  "Si tiene dificultades para escuchar o ver, utilizar señales visuales, gestos o indicaciones que pueda percibir.",
                  "Si se muestra irritable al tocarlo, evitar forzarlo y consultar con el veterinario para descartar dolor.",
                  "Si ladra por ansiedad, identificar los desencadenantes y trabajar de forma gradual para reducir el estrés.",
                  "Si se desorienta, mantener una rutina estable y evitar cambios innecesarios en los muebles y el entorno.",
                  "Si tiene miedo de otros perros, mantener distancia y no forzar los encuentros.",
                  "Evitar los castigos, gritos y movimientos bruscos, especialmente si tiene problemas sensoriales.",
                  "Ajustar el entrenamiento a sesiones breves, con descansos y recompensas apropiadas.",
                  "Consultar con un veterinario si aparecen confusión, irritabilidad, ansiedad o cambios de conducta repentinos."
                ]
              }
            ]
          },
          "vacunacion": {
            "titulo": "VACUNACIÓN",
            "secciones": [
              {
                "titulo": "TODAS LAS VACUNAS CON LAS QUE DEBERÍA CONTAR LA MASCOTA HASTA EL DÍA DE SU MUERTE",
                "items": [
                  "Moquillo canino: debe contar con la serie inicial y los refuerzos que correspondan según el historial y la pauta veterinaria.",
                  "Parvovirus canino: la protección se mantiene mediante las dosis iniciales y los refuerzos indicados para la vacuna utilizada.",
                  "Adenovirus canino: generalmente se administra como parte de la vacuna combinada y se refuerza según las recomendaciones aplicables.",
                  "Parainfluenza canina: puede recomendarse si existe riesgo de exposición frecuente a otros perros.",
                  "Leptospirosis: la necesidad de refuerzos depende de la exposición local y de las indicaciones veterinarias.",
                  "Rabia: debe mantenerse conforme a la normativa sanitaria boliviana y las instrucciones correspondientes a la vacuna.",
                  "Bordetella: puede indicarse si el perro tiene contacto frecuente con muchos perros o acude a guarderías y residencias.",
                  "Influenza canina u otras vacunas específicas: se consideran cuando existe un riesgo relevante y el veterinario determina que son apropiadas.",
                  "En perros senior: la edad por sí sola no significa que deba dejar de vacunarse. El veterinario revisará su historial, estado de salud, exposición y normas locales para determinar qué vacunas necesita y con qué frecuencia. No todas las vacunas requieren refuerzos anuales."
                ]
              }
            ]
          },
          "veterinario": {
            "titulo": "CUÁNDO IR AL VETERINARIO",
            "secciones": [
              {
                "titulo": "EN QUÉ SITUACIONES DE EMERGENCIA DEBES DE ACUDIR A UN VETERINARIO",
                "items": [
                  "Hemorragia: puede provocar pérdida importante de sangre y shock. Mantener presión con una gasa limpia mientras se busca atención urgente.",
                  "Fractura: puede causar dolor intenso y daño a los tejidos. Evitar mover la extremidad o intentar acomodar el hueso.",
                  "Vómitos constantes: pueden provocar deshidratación y señalar una enfermedad digestiva grave, intoxicación u obstrucción.",
                  "Dificultad para respirar: puede ser señal de enfermedad cardiaca o pulmonar y requiere atención inmediata.",
                  "Convulsiones: si son prolongadas, repetidas o aparecen por primera vez, debe recibir evaluación urgente.",
                  "Abdomen hinchado y doloroso: puede indicar una afección grave que necesita tratamiento inmediato.",
                  "Intoxicación: algunos productos pueden causar daño a los órganos incluso antes de que aparezcan síntomas.",
                  "Diarrea con sangre: puede ocasionar pérdida de líquidos y ser señal de una enfermedad importante.",
                  "Golpe fuerte o caída: puede provocar lesiones internas, fracturas o traumatismos que no se ven a simple vista.",
                  "Incapacidad para orinar: puede indicar una obstrucción urinaria que necesita tratamiento urgente.",
                  "Desmayo o debilidad extrema: puede ser consecuencia de un problema circulatorio, cardiaco o metabólico.",
                  "Dolor intenso o incapacidad para levantarse: requiere atención inmediata, especialmente si aparece de repente.",
                  "En los perros mayores, también conviene consultar pronto ante pérdida de peso, aumento de sed, tos persistente, desorientación o dificultad progresiva para caminar, aunque estos signos no parezcan una emergencia inmediata."
                ]
              }
            ]
          }
        }
      }
    }
  },
  "mestizo": {
    "nombre": "Mestizo",
    "etapas": {
      "cachorro": {
        "tituloOriginal": "PERRO MESTIZO — CACHORRO (0–12 MESES)",
        "temas": {
          "alimentacion": {
            "titulo": "ALIMENTACIÓN",
            "secciones": [
              {
                "titulo": "ALIMENTACIÓN SALUDABLE",
                "items": [
                  "Alimento completo para cachorros: debe recibir un alimento formulado para el crecimiento, con proteínas, grasas, vitaminas y minerales equilibrados. Estos nutrientes favorecen el desarrollo de los músculos, los huesos, los órganos y el sistema inmunitario.",
                  "Cantidad de comida según su tamaño: la ración debe adaptarse a su peso actual, crecimiento y actividad. Como los mestizos pueden alcanzar tamaños muy diferentes, no todos necesitan la misma cantidad de alimento.",
                  "Comidas distribuidas durante el día: entre las 6 y 12 semanas suelen necesitar cuatro comidas pequeñas; entre los 3 y 6 meses pueden pasar a tres, y posteriormente a dos o tres, según su desarrollo y las recomendaciones veterinarias.",
                  "Agua limpia y fresca: debe tener agua disponible durante todo el día. Es importante lavar el recipiente diariamente y cambiar el agua cuando esté sucia o caliente.",
                  "Proteínas de buena calidad: son necesarias para desarrollar músculos, reparar tejidos y mantener las defensas. Un alimento completo para cachorros suele aportar la cantidad apropiada, por lo que no es necesario añadir grandes cantidades de carne.",
                  "Calcio y fósforo equilibrados: son fundamentales para el desarrollo óseo. No se deben administrar suplementos de calcio por cuenta propia, porque los excesos también pueden causar alteraciones del crecimiento.",
                  "Cambio gradual de alimento: si se necesita cambiar de marca o fórmula, hacerlo progresivamente durante unos 5–7 días, mezclando el alimento nuevo con el anterior. Si existe una indicación médica, seguir las instrucciones del veterinario.",
                  "Premios saludables: utilizar premios apropiados para perros y en cantidades pequeñas durante el entrenamiento. Los premios no deben reemplazar una parte importante de la alimentación completa.",
                  "Control del peso y crecimiento: pesarlo periódicamente ayuda a comprobar que crece adecuadamente. La cantidad de comida debe ajustarse si está demasiado delgado, aumenta excesivamente de peso o cambia su actividad.",
                  "Alimentación casera equilibrada: si se desea darle comida preparada en casa, la receta debe ser formulada por un veterinario especializado en nutrición. Carne, arroz y verduras por sí solos no garantizan que reciba todos los nutrientes que necesita."
                ]
              },
              {
                "titulo": "ALIMENTACIÓN NO SALUDABLE",
                "items": [
                  "Chocolate y cafeína: el chocolate, el café, el té con cafeína y algunas bebidas energéticas pueden causar intoxicación. El riesgo depende del producto, la cantidad ingerida y el peso del cachorro.",
                  "Cebolla y ajo: pueden dañar los glóbulos rojos y causar anemia. Deben evitarse crudos, cocidos, en polvo o como ingredientes de comidas preparadas.",
                  "Uvas y pasas: pueden provocar daño renal grave en algunos perros. Si las ingiere, se debe contactar inmediatamente con un veterinario.",
                  "Productos con xilitol: algunos chicles, dulces y productos sin azúcar contienen este edulcorante, que puede provocar una bajada peligrosa de glucosa y daño hepático.",
                  "Huesos cocidos: pueden astillarse y provocar atragantamiento, obstrucciones, lesiones intestinales o perforaciones. Los huesos muy duros también pueden fracturar los dientes.",
                  "Sobras condimentadas: las comidas con mucha sal, grasa, salsas, cebolla o ajo pueden ocasionar problemas digestivos o intoxicaciones. No deben ser su alimentación habitual.",
                  "Leche de vaca en exceso: muchos perros no digieren bien la lactosa después del destete. Puede causar gases, dolor abdominal y diarrea, y no sustituye el agua ni el alimento completo.",
                  "Alimentos crudos de riesgo: la carne y los huevos crudos pueden contener bacterias o parásitos. Además, una dieta cruda mal formulada puede provocar deficiencias nutricionales.",
                  "Comida podrida o mohosa: puede contener bacterias y toxinas que causan vómitos, diarrea y otros problemas graves. Deben desecharse los alimentos deteriorados."
                ]
              }
            ]
          },
          "salud": {
            "titulo": "SALUD",
            "secciones": [
              {
                "titulo": "TIENE BUENA SALUD",
                "items": [
                  "Energía adecuada: juega, explora y responde a los estímulos de acuerdo con su edad. Después de jugar descansa y posteriormente retoma sus actividades con normalidad.",
                  "Apetito regular: consume sus raciones habituales sin mostrar dolor al masticar, dificultad para tragar ni rechazo persistente de la comida.",
                  "Ojos limpios: los ojos se ven claros y no presentan secreciones abundantes, hinchazón, enrojecimiento intenso ni señales de dolor.",
                  "Respiración normal: respira tranquilamente cuando está en reposo, sin esfuerzo abdominal, ruidos inusuales persistentes ni episodios de ahogo.",
                  "Boca saludable: las encías suelen ser rosadas, aunque pueden tener pigmentación natural. No presenta sangrado, dolor al comer ni mal aliento intenso.",
                  "Digestión regular: sus heces son generalmente formadas y no presenta vómitos repetidos, diarrea persistente ni sangre en las deposiciones.",
                  "Piel y pelaje en buen estado: no tiene heridas sin atender, parásitos visibles ni picazón intensa. El tipo y la cantidad de pelo dependen de sus características individuales.",
                  "Crecimiento progresivo: gana peso adecuadamente, camina sin cojear y recibe revisiones veterinarias, desparasitación y vacunas según su calendario."
                ]
              },
              {
                "titulo": "TIENE MALA SALUD",
                "items": [
                  "Pérdida de apetito: deja de comer, rechaza varias comidas o parece sentir dolor al masticar. En los cachorros, la falta de alimentación puede agravarse rápidamente.",
                  "Vómitos o diarrea: los episodios repetidos, la presencia de sangre o la diarrea intensa requieren atención veterinaria. Los cachorros pueden deshidratarse en poco tiempo.",
                  "Decaimiento anormal: pierde el interés por jugar, permanece débil o responde menos de lo habitual. Si está muy débil o no puede mantenerse en pie, necesita atención urgente.",
                  "Problemas respiratorios: presenta tos persistente, secreción nasal importante, respiración trabajosa o encías azuladas. La dificultad para respirar es una emergencia.",
                  "Alteraciones en la piel: tiene heridas, costras, pérdida anormal de pelo, picazón intensa o inflamación que podría estar relacionada con parásitos, alergias o infecciones.",
                  "Dificultad para caminar: cojea, llora al moverse, evita apoyar una pata o no puede levantarse. Puede existir una lesión o un problema musculoesquelético.",
                  "Abdomen hinchado o doloroso: se muestra inquieto, se queja al tocarle el vientre o adopta posturas inusuales. La hinchazón repentina acompañada de dolor requiere atención inmediata.",
                  "Cambios en la orina: hace esfuerzos para orinar, presenta sangre o deja de orinar. La incapacidad para orinar es una emergencia.",
                  "Signos de deshidratación o enfermedad grave: presenta debilidad marcada, encías muy pálidas, ojos hundidos, colapso o dificultad para mantenerse en pie. Necesita atención veterinaria urgente."
                ]
              }
            ]
          },
          "primeros": {
            "titulo": "PRIMEROS AUXILIOS",
            "secciones": [
              {
                "titulo": "QUÉ HACER CUANDO LE SUCEDEN ACCIDENTES COMO:",
                "items": []
              },
              {
                "titulo": "CAÍDA",
                "items": [
                  "Mantener al cachorro tranquilo y evitar que corra o salte después de la caída.",
                  "Comprobar si está consciente y respira normalmente, sin moverle bruscamente el cuello o la espalda.",
                  "Si no puede levantarse, tiene dolor intenso, sufrió un golpe en la cabeza o presenta dificultad respiratoria, acudir inmediatamente a urgencias veterinarias.",
                  "Si se sospecha una lesión de columna, evitar doblar el cuerpo y trasladarlo sobre una superficie firme, con ayuda de un adulto.",
                  "No intentar acomodar una extremidad ni administrar analgésicos humanos.",
                  "Aunque parezca recuperado, una caída importante puede provocar lesiones internas que no se observan a simple vista."
                ]
              },
              {
                "titulo": "HERIDAS O HEMORRAGIAS",
                "items": [
                  "Mantenerlo tranquilo y pedir ayuda a un adulto.",
                  "Presionar la herida con una gasa limpia durante varios minutos, sin levantarla repetidamente para comprobar si sigue sangrando.",
                  "Si la gasa se empapa, colocar otra encima y mantener la presión.",
                  "No retirar objetos profundamente clavados ni apretar directamente sobre ellos.",
                  "No aplicar alcohol, agua oxigenada, polvos ni remedios caseros dentro de la herida.",
                  "Si el sangrado es abundante, la herida es profunda o el sangrado no se detiene, acudir inmediatamente al veterinario."
                ]
              },
              {
                "titulo": "ATRAGANTAMIENTO",
                "items": [
                  "Si puede toser y respirar, mantenerlo tranquilo y buscar orientación veterinaria si los síntomas persisten.",
                  "Si no puede respirar, toser eficazmente o emitir sonidos, pedir ayuda inmediata y acudir a urgencias.",
                  "No introducir los dedos a ciegas en la garganta ni empujar el objeto hacia el interior.",
                  "Si el objeto está claramente visible y puede retirarse sin riesgo, actuar con extrema precaución.",
                  "Aunque el objeto salga, necesita valoración si presenta tos persistente, respiración anormal o debilidad."
                ]
              },
              {
                "titulo": "INTOXICACIÓN",
                "items": [
                  "Alejarlo del producto y evitar que vuelva a ingerirlo.",
                  "Guardar el envase y anotar el nombre del producto, la cantidad aproximada y la hora de exposición.",
                  "Contactar inmediatamente con un veterinario, aunque todavía no presente síntomas.",
                  "No provocar el vómito ni darle leche, aceite, sal, medicamentos o carbón activado sin indicación profesional.",
                  "Si presenta convulsiones, dificultad respiratoria o pérdida de conocimiento, trasladarlo a urgencias sin demora."
                ]
              },
              {
                "titulo": "QUEMADURAS",
                "items": [
                  "Alejarlo de la fuente de calor o del producto que provocó la quemadura.",
                  "Enfriar la zona con agua corriente fresca durante unos 20 minutos, si es posible sin retrasar la atención.",
                  "No utilizar hielo, mantequilla, pasta dental ni cremas caseras.",
                  "No arrancar piel ni reventar ampollas.",
                  "Cubrir suavemente la zona con una tela limpia que no se adhiera y acudir al veterinario si la quemadura es extensa, profunda o afecta zonas sensibles."
                ]
              }
            ]
          },
          "cuidados": {
            "titulo": "CUIDADOS",
            "secciones": [
              {
                "titulo": "CÓMO MANTENERLO BIEN CUIDADO",
                "items": [
                  "Higiene del pelaje: cepillarlo según su tipo de pelo para retirar suciedad y detectar pulgas, garrapatas, heridas o irritaciones.",
                  "Baño adecuado: bañarlo cuando lo necesite con champú específico para perros. Enjuagar bien y secarlo para evitar que permanezca húmedo durante mucho tiempo.",
                  "Cuidado de los oídos: revisar que estén limpios y sin mal olor, secreción o enrojecimiento. No introducir hisopos profundamente en el conducto auditivo.",
                  "Higiene dental: acostumbrarlo al cepillado con pasta dental veterinaria. Nunca utilizar pasta dental humana.",
                  "Cuidado de las uñas: comprobar su longitud y recortarlas con herramientas apropiadas si hace falta, evitando la parte sensible que contiene vasos sanguíneos.",
                  "Ejercicio seguro: permitirle jugar y explorar durante periodos apropiados para su edad. Evitar ejercicios excesivos y saltos desde lugares altos.",
                  "Descanso: proporcionarle una cama limpia, seca y protegida del frío, la lluvia y el calor intenso.",
                  "Prevención de parásitos: seguir las indicaciones veterinarias para prevenir pulgas, garrapatas y parásitos intestinales.",
                  "Vacunación y controles: mantener un registro de vacunas y revisiones, especialmente durante los primeros meses.",
                  "Seguridad en el hogar: mantener medicamentos, productos de limpieza, cables, objetos pequeños y alimentos peligrosos fuera de su alcance."
                ]
              },
              {
                "titulo": "CÓMO SABER SI NO TIENE UN BUEN CUIDADO",
                "items": [
                  "✦ HIGIENE Y APARIENCIA",
                  "Tiene el pelaje constantemente sucio, enredado o con parásitos que no reciben tratamiento.",
                  "Presenta uñas demasiado largas, heridas sin atender o suciedad acumulada en los oídos.",
                  "Tiene mal olor persistente, picazón intensa o lesiones cutáneas ignoradas.",
                  "✦ ALIMENTACIÓN Y AGUA",
                  "Está demasiado delgado, aumenta excesivamente de peso o no crece adecuadamente.",
                  "No dispone de agua limpia o recibe una alimentación insuficiente y desequilibrada.",
                  "Come desperdicios o alimentos deteriorados por falta de higiene y conservación.",
                  "✦ SALUD Y PREVENCIÓN",
                  "No recibe vacunas, desparasitación ni controles veterinarios.",
                  "Tiene diarrea frecuente, tos persistente, parásitos o heridas que no se atienden.",
                  "Presenta dolor o cojera sin que se investigue la causa.",
                  "✦ ATENCIÓN Y AMBIENTE",
                  "Permanece aislado durante largos periodos sin compañía, juego ni estímulos.",
                  "Vive expuesto al calor intenso, frío o lluvia sin refugio adecuado.",
                  "No tiene un lugar tranquilo y seguro para dormir."
                ]
              }
            ]
          },
          "comportamiento": {
            "titulo": "COMPORTAMIENTO",
            "secciones": [
              {
                "titulo": "ADIESTRAMIENTO DESDE CACHORRO",
                "items": [
                  "Reconocimiento del nombre: decir su nombre con voz amable y premiarlo cuando mire hacia la persona que lo llama.",
                  "Órdenes básicas: enseñarle «ven», «siéntate», «quieto» y «suelta» mediante sesiones cortas y recompensas.",
                  "Educación para hacer sus necesidades: llevarlo al lugar adecuado al despertar, después de comer, tras jugar y antes de dormir. Premiarlo inmediatamente cuando lo haga bien.",
                  "Uso de la correa: acostumbrarlo gradualmente al collar o arnés apropiado y a caminar sin tirones.",
                  "Socialización: presentarle progresivamente personas, sonidos, superficies y perros sanos y vacunados, sin obligarlo a acercarse cuando tiene miedo.",
                  "Control de mordidas: redirigir las mordidas hacia juguetes seguros y hacer una pausa breve en el juego si muerde demasiado fuerte.",
                  "Prevención de conductas peligrosas: enseñarle a no recoger comida desconocida de la calle y a soltar objetos voluntariamente.",
                  "Acostumbramiento al manejo: tocar suavemente sus patas, revisar sus orejas y cepillarlo poco a poco para facilitar los cuidados futuros.",
                  "Aprendizaje positivo: premiar las conductas deseadas en lugar de utilizar golpes, gritos o castigos que provoquen miedo.",
                  "Rutina estable: combinar alimentación, paseos apropiados, juego, entrenamiento y descanso para favorecer su aprendizaje."
                ]
              },
              {
                "titulo": "CÓMO MEJORAR EL COMPORTAMIENTO DE TU MASCOTA SI NO FUE ADIESTRADO",
                "items": [
                  "Comenzar con una orden sencilla y practicarla en un lugar tranquilo, sin demasiadas distracciones.",
                  "Utilizar premios pequeños, juguetes o elogios para reforzar las respuestas correctas.",
                  "Establecer horarios regulares para comer, jugar, salir a hacer sus necesidades y dormir.",
                  "Si muerde muebles o zapatos, retirar el acceso a esos objetos y ofrecerle juguetes seguros.",
                  "Si tira de la correa, practicar caminatas cortas y premiar cuando camine sin tensión.",
                  "Si ladra demasiado, identificar si lo desencadenan el miedo, el aburrimiento, los ruidos o la necesidad de atención.",
                  "Si teme a personas o animales, aumentar la distancia y permitirle acercarse a su propio ritmo.",
                  "Evitar gritos, golpes y castigos físicos, porque pueden aumentar el miedo y las respuestas defensivas.",
                  "Practicar durante pocos minutos varias veces al día, ajustando la dificultad a su progreso.",
                  "Si aparecen agresividad intensa, ansiedad persistente o cambios repentinos de conducta, solicitar ayuda veterinaria y profesional."
                ]
              }
            ]
          },
          "vacunacion": {
            "titulo": "VACUNACIÓN",
            "secciones": [
              {
                "titulo": "TODAS LAS VACUNAS CON LAS QUE DEBERÍA CONTAR LA MASCOTA HASTA EL DÍA DE SU MUERTE",
                "items": [
                  "El calendario debe adaptarse a las normas sanitarias de Bolivia, las vacunas disponibles, el riesgo de exposición y el historial individual del perro.",
                  "Moquillo canino: vacuna esencial para prevenir una enfermedad viral grave. La serie inicial suele comenzar entre las 6 y 8 semanas de edad.",
                  "Parvovirus canino: vacuna esencial, especialmente importante en cachorros porque la enfermedad puede provocar vómitos, diarrea intensa y deshidratación.",
                  "Adenovirus canino: protege frente al adenovirus relacionado con la hepatitis infecciosa canina y suele formar parte de las vacunas combinadas.",
                  "Parainfluenza canina: puede estar incluida en algunas vacunas combinadas. Su indicación depende del riesgo de exposición.",
                  "Leptospirosis: se recomienda según la zona, el contacto con roedores o agua contaminada y la valoración veterinaria. Habitualmente requiere una serie inicial y refuerzos.",
                  "Rabia: es fundamental por su importancia para la salud pública y debe aplicarse conforme al calendario y las disposiciones oficiales de Bolivia.",
                  "Bordetella: puede recomendarse si el cachorro estará en guarderías, residencias, exposiciones o lugares donde convive estrechamente con muchos perros.",
                  "Influenza canina u otras vacunas específicas: solo se consideran si están disponibles y el veterinario determina que son apropiadas para el riesgo local.",
                  "Calendario orientativo:",
                  "6–8 semanas: inicio de las vacunas esenciales, según la evaluación veterinaria.",
                  "Cada 2–4 semanas hasta al menos las 16 semanas: continuación de las dosis esenciales para cubrir el periodo en que los anticuerpos maternos pueden interferir con la respuesta a la vacuna.",
                  "Alrededor de las 12 semanas o según la normativa local: vacuna contra la rabia, respetando la edad autorizada y las disposiciones oficiales.",
                  "Durante el primer año: refuerzos según el producto utilizado, el historial y las recomendaciones veterinarias.",
                  "Después del primer año: refuerzos posteriores según la vacuna, la normativa y el riesgo de exposición.",
                  "No todas estas vacunas son obligatorias para todos los perros ni se administran anualmente. El veterinario debe establecer los intervalos de refuerzo y mantener el registro actualizado."
                ]
              }
            ]
          },
          "veterinario": {
            "titulo": "CUÁNDO IR AL VETERINARIO",
            "secciones": [
              {
                "titulo": "EN QUÉ SITUACIONES DE EMERGENCIA DEBES DE ACUDIR A UN VETERINARIO",
                "items": [
                  "Hemorragia: una pérdida importante de sangre puede provocar debilidad y shock. Presionar suavemente con una gasa limpia mientras se busca atención.",
                  "Fractura: una caída o golpe puede romper un hueso y dañar tejidos cercanos. No intentar acomodar la extremidad.",
                  "Vómitos constantes: pueden provocar deshidratación y ser señal de infección, intoxicación u obstrucción.",
                  "Dificultad para respirar: puede indicar una obstrucción o una enfermedad grave y requiere atención inmediata.",
                  "Convulsiones: si son prolongadas, se repiten o aparecen por primera vez, necesita evaluación urgente. No introducir objetos en su boca.",
                  "Abdomen hinchado y doloroso: puede indicar una afección grave, especialmente si intenta vomitar sin conseguirlo.",
                  "Ingestión de tóxicos: medicamentos, productos de limpieza, venenos y alimentos tóxicos pueden causar daños graves. No provocar el vómito sin instrucciones veterinarias.",
                  "Diarrea intensa o con sangre: puede causar deshidratación y estar relacionada con enfermedades infecciosas o digestivas.",
                  "Golpe en la cabeza: puede ocasionar lesiones internas aunque no haya heridas externas.",
                  "Incapacidad para orinar: puede indicar una obstrucción urinaria que necesita tratamiento inmediato.",
                  "Desmayo o debilidad extrema: pueden deberse a problemas circulatorios, intoxicaciones u otras enfermedades graves.",
                  "Quemaduras importantes: pueden causar dolor intenso, infección y pérdida de líquidos, por lo que requieren atención profesional."
                ]
              }
            ]
          }
        }
      },
      "adulto": {
        "tituloOriginal": "PERRO MESTIZO — ADULTO (1–9 AÑOS, APROXIMADAMENTE)",
        "temas": {
          "alimentacion": {
            "titulo": "ALIMENTACIÓN",
            "secciones": [
              {
                "titulo": "ALIMENTACIÓN SALUDABLE",
                "items": [
                  "Alimento completo para adultos: debe consumir una dieta formulada para perros adultos que aporte proteínas, grasas, vitaminas y minerales equilibrados para mantener sus músculos, órganos y defensas.",
                  "Raciones según su tamaño: calcular la cantidad diaria de acuerdo con su peso, actividad y condición corporal. Un mestizo pequeño puede necesitar menos comida que uno grande, aunque su gasto energético también depende de cuánto se mueve.",
                  "Agua fresca disponible: debe tener agua limpia durante todo el día. Es importante revisar el recipiente después de paseos y actividades físicas.",
                  "Proteínas de calidad: contribuyen al mantenimiento muscular y a la reparación de tejidos. Una dieta completa normalmente proporciona lo necesario sin añadir carne en exceso.",
                  "Grasas equilibradas: aportan energía y ayudan a mantener la piel y el pelaje. Los aceites y suplementos solo deben añadirse si existe una razón nutricional y orientación profesional.",
                  "Fibra adecuada: contribuye a la regularidad intestinal. Si presenta estreñimiento o diarrea persistente, es necesario investigar la causa en lugar de modificar la dieta repetidamente.",
                  "Horarios regulares: muchos perros adultos se alimentan adecuadamente con dos comidas al día, aunque la frecuencia puede adaptarse a sus necesidades individuales.",
                  "Premios moderados: los premios deben ser apropiados para perros y representar una proporción pequeña de las calorías diarias. Si recibe muchos, se debe ajustar la ración principal.",
                  "Control del peso: revisar su condición corporal permite detectar sobrepeso o pérdida de musculatura. Las costillas deberían poder palparse con facilidad razonable, sin sobresalir excesivamente.",
                  "Dieta casera equilibrada: si se desea alimentarlo con comida preparada en casa, debe utilizarse una receta formulada por un veterinario especializado en nutrición para evitar deficiencias o excesos."
                ]
              },
              {
                "titulo": "ALIMENTACIÓN NO SALUDABLE",
                "items": [
                  "Chocolate y cafeína: pueden provocar vómitos, inquietud, alteraciones cardiacas y otros problemas según la cantidad ingerida.",
                  "Cebolla y ajo: pueden dañar los glóbulos rojos y causar anemia, incluso si forman parte de comidas cocinadas.",
                  "Uvas y pasas: pueden ocasionar daño renal grave y requieren contacto veterinario inmediato si las ingiere.",
                  "Productos con xilitol: pueden provocar una bajada peligrosa de glucosa y daño hepático.",
                  "Huesos cocidos y objetos duros: pueden causar atragantamiento, obstrucciones, perforaciones intestinales o fracturas dentales.",
                  "Sobras grasas y condimentadas: pueden provocar problemas digestivos y, en algunos casos, pancreatitis. No son apropiadas como alimentación habitual.",
                  "Exceso de sal y azúcar: no aporta beneficios y puede contribuir a problemas de salud si se consume de forma frecuente.",
                  "Alimentos crudos o deteriorados: pueden contener bacterias, parásitos o toxinas. La comida debe conservarse correctamente y ofrecerse en condiciones higiénicas.",
                  "Exceso de comida y premios: las raciones demasiado grandes pueden causar sobrepeso y dificultar la movilidad, por lo que deben ajustarse a sus necesidades reales."
                ]
              }
            ]
          },
          "salud": {
            "titulo": "SALUD",
            "secciones": [
              {
                "titulo": "TIENE BUENA SALUD",
                "items": [
                  "Energía estable: realiza sus actividades habituales, disfruta de los paseos y descansa después del ejercicio sin agotamiento desproporcionado.",
                  "Apetito normal: consume sus raciones de manera habitual y no presenta dificultad para masticar o tragar.",
                  "Ojos claros: no presenta enrojecimiento persistente, secreción abundante, hinchazón ni signos de dolor.",
                  "Respiración tranquila: respira sin esfuerzo en reposo y no presenta tos persistente ni episodios de ahogo.",
                  "Boca y encías cuidadas: las encías suelen ser rosadas, salvo pigmentación natural. No presenta dolor al masticar, sangrado ni mal aliento intenso.",
                  "Peso estable: mantiene una condición corporal adecuada y no gana ni pierde peso sin explicación.",
                  "Piel y pelaje en buen estado: no presenta heridas sin atender, picazón intensa ni parásitos visibles.",
                  "Movilidad normal: camina, corre y se levanta sin cojera ni rigidez persistente, y recibe atención preventiva según sus necesidades."
                ]
              },
              {
                "titulo": "TIENE MALA SALUD",
                "items": [
                  "Pérdida de apetito o sed anormal: deja de comer, bebe mucho más o mucho menos de lo habitual, o presenta cambios persistentes en sus hábitos.",
                  "Vómitos o diarrea repetidos: pueden deberse a trastornos digestivos, parásitos, infecciones o intoxicaciones.",
                  "Pérdida o aumento de peso inexplicable: puede relacionarse con problemas nutricionales, hormonales o enfermedades internas.",
                  "Dificultad respiratoria o tos persistente: requiere evaluación, especialmente si se acompaña de debilidad o encías azuladas.",
                  "Problemas de piel: la picazón intensa, las heridas, las costras o la caída anormal del pelo pueden indicar alergias, parásitos o infecciones.",
                  "Cojera o rigidez: puede ser señal de una lesión, dolor articular u otro problema musculoesquelético.",
                  "Cambios en la orina: orina con sangre, presenta dolor al orinar o comienza a hacerlo con mucha más frecuencia.",
                  "Cambios de conducta: se vuelve repentinamente irritable, se esconde, evita el contacto o muestra agresividad que no era habitual.",
                  "Decaimiento importante: presenta debilidad extrema, desmayo, encías muy pálidas o dificultad para mantenerse en pie. Estos signos requieren atención urgente."
                ]
              }
            ]
          },
          "primeros": {
            "titulo": "PRIMEROS AUXILIOS",
            "secciones": [
              {
                "titulo": "QUÉ HACER CUANDO LE SUCEDEN ACCIDENTES COMO:",
                "items": []
              },
              {
                "titulo": "CAÍDA",
                "items": [
                  "Mantenerlo quieto y evitar que camine si presenta dolor o cojera.",
                  "Comprobar si respira normalmente y si responde a la voz.",
                  "Si no puede levantarse, se golpeó la cabeza o muestra dolor intenso, evitar moverlo innecesariamente.",
                  "Si se sospecha una lesión de columna, transportarlo sobre una superficie firme con el cuerpo alineado.",
                  "No intentar enderezar extremidades ni administrar analgésicos humanos.",
                  "Buscar atención veterinaria si la caída fue importante o aparecen cambios en su respiración, conducta o movilidad."
                ]
              },
              {
                "titulo": "HERIDAS O HEMORRAGIAS",
                "items": [
                  "Mantenerlo tranquilo y utilizar una barrera segura si el dolor hace que pueda morder involuntariamente.",
                  "Presionar la herida con una gasa limpia sin levantarla repetidamente.",
                  "Si el sangrado es abundante o no se detiene, acudir a urgencias.",
                  "No extraer objetos profundamente clavados ni colocar torniquetes improvisados.",
                  "Evitar alcohol, agua oxigenada y polvos sobre la herida.",
                  "El veterinario debe evaluar heridas profundas, mordeduras y lesiones cercanas a los ojos, articulaciones o tórax."
                ]
              },
              {
                "titulo": "ATRAGANTAMIENTO",
                "items": [
                  "Si puede respirar y toser, evitar introducir objetos en su boca y contactar con un veterinario si los síntomas persisten.",
                  "Si no puede respirar o pierde el conocimiento, pedir ayuda inmediata y trasladarlo a urgencias.",
                  "No introducir los dedos a ciegas ni empujar el objeto más profundamente.",
                  "Si el objeto está claramente visible y puede retirarse sin riesgo, hacerlo con mucha precaución.",
                  "Después de un episodio grave, necesita valoración aunque parezca recuperado, porque pueden existir lesiones en la garganta o los pulmones."
                ]
              },
              {
                "titulo": "INTOXICACIÓN",
                "items": [
                  "Retirar el producto y evitar nuevas exposiciones.",
                  "Identificar la sustancia y la cantidad aproximada ingerida.",
                  "Llamar inmediatamente al veterinario, sin esperar a que aparezcan síntomas.",
                  "No inducir el vómito ni administrar leche, aceite, medicamentos o remedios caseros.",
                  "Llevar el envase o una fotografía de la etiqueta para ayudar a identificar el tóxico."
                ]
              },
              {
                "titulo": "QUEMADURAS",
                "items": [
                  "Alejarlo de la fuente de calor o de la sustancia irritante.",
                  "Enfriar la zona con agua corriente fresca durante unos 20 minutos, si es posible sin retrasar la atención.",
                  "No aplicar hielo, mantequilla, pasta dental ni cremas no indicadas.",
                  "No romper ampollas ni arrancar la piel.",
                  "Cubrir suavemente la zona con una tela limpia y acudir al veterinario si la quemadura es extensa, profunda o afecta zonas sensibles."
                ]
              }
            ]
          },
          "cuidados": {
            "titulo": "CUIDADOS",
            "secciones": [
              {
                "titulo": "CÓMO MANTENERLO BIEN CUIDADO",
                "items": [
                  "Alimentación controlada: medir las raciones y ajustar la cantidad si cambia su actividad, peso o condición corporal.",
                  "Ejercicio diario: ofrecer paseos y juegos apropiados a su energía, aumentando o reduciendo la actividad según su capacidad física.",
                  "Cepillado: adaptar la frecuencia al tipo de pelaje para retirar pelo suelto y detectar parásitos o lesiones.",
                  "Baño: utilizar champú para perros y secarlo adecuadamente después del baño.",
                  "Higiene dental: cepillar sus dientes con productos veterinarios y consultar si presenta sarro, dolor o mal aliento persistente.",
                  "Cuidado de uñas: mantenerlas a una longitud adecuada para que no dificulten el apoyo de las patas.",
                  "Control de parásitos: seguir un plan veterinario de prevención de pulgas, garrapatas y parásitos intestinales.",
                  "Ambiente seguro: proporcionarle agua, sombra, refugio y una cama limpia, sin mantenerlo expuesto al calor extremo.",
                  "Estimulación mental: ofrecer juguetes seguros, juegos de olfato y oportunidades para explorar.",
                  "Revisiones veterinarias: realizar controles periódicos y mantener al día las vacunas que correspondan según su edad y riesgo."
                ]
              },
              {
                "titulo": "CÓMO SABER SI NO TIENE UN BUEN CUIDADO",
                "items": [
                  "✦ HIGIENE Y PELAJE",
                  "Presenta pelo enredado, suciedad persistente, parásitos o lesiones cutáneas sin tratar.",
                  "Tiene uñas demasiado largas o molestias en las patas por falta de mantenimiento.",
                  "✦ ALIMENTACIÓN",
                  "Está excesivamente delgado o tiene sobrepeso por recibir raciones inadecuadas.",
                  "No tiene agua limpia disponible o come principalmente sobras desequilibradas.",
                  "✦ SALUD",
                  "No recibe atención preventiva y tiene problemas de salud que se ignoran.",
                  "Presenta dolor dental, cojera, picazón o cambios de peso sin evaluación.",
                  "✦ ATENCIÓN Y AMBIENTE",
                  "Permanece atado o aislado durante periodos prolongados sin ejercicio ni interacción.",
                  "No tiene refugio adecuado ni un lugar limpio para descansar.",
                  "Carece de oportunidades de juego, paseo y estimulación mental."
                ]
              }
            ]
          },
          "comportamiento": {
            "titulo": "COMPORTAMIENTO",
            "secciones": [
              {
                "titulo": "ADIESTRAMIENTO DESDE CACHORRO",
                "items": [
                  "Enseñar su nombre y órdenes básicas con recompensas y constancia.",
                  "Practicar el llamado para que acuda cuando se le necesite.",
                  "Acostumbrarlo a caminar con correa sin tirar ni perseguir personas o animales.",
                  "Enseñarle a esperar antes de cruzar una puerta o acercarse a la comida.",
                  "Reforzar las conductas tranquilas cuando llegan visitas o aparecen ruidos nuevos.",
                  "Ofrecer juguetes y juegos de olfato para reducir el aburrimiento.",
                  "Enseñarle a soltar objetos mediante intercambios por juguetes o premios apropiados.",
                  "Acostumbrarlo al cepillado, la revisión de patas y los controles veterinarios.",
                  "Mantener rutinas previsibles de paseo, comida, descanso y juego.",
                  "Evitar castigos físicos y utilizar refuerzo positivo para desarrollar confianza y cooperación."
                ]
              },
              {
                "titulo": "CÓMO MEJORAR EL COMPORTAMIENTO DE TU MASCOTA SI NO FUE ADIESTRADO",
                "items": [
                  "Empezar por identificar el comportamiento que se desea mejorar y qué situaciones lo provocan.",
                  "Practicar órdenes básicas en lugares tranquilos y aumentar gradualmente las distracciones.",
                  "Recompensar la conducta adecuada inmediatamente para que pueda asociarla con el resultado positivo.",
                  "Si tira de la correa, practicar caminatas cortas y premiar cuando camine sin tensión.",
                  "Si ladra ante visitas o ruidos, trabajar desde una distancia en la que pueda permanecer tranquilo.",
                  "Si destruye objetos, aumentar la estimulación y ofrecer juguetes adecuados, sin dejar a su alcance objetos peligrosos.",
                  "Si teme a otros perros, evitar los encuentros forzados y solicitar orientación profesional si el miedo persiste.",
                  "Si muestra agresividad, mantener distancia y seguridad, sin castigar ni intentar dominarlo físicamente.",
                  "Establecer horarios de actividad y descanso para reducir el aburrimiento y la frustración.",
                  "Consultar con un veterinario si aparecen confusión, irritabilidad, ansiedad o cambios de conducta repentinos."
                ]
              }
            ]
          },
          "vacunacion": {
            "titulo": "VACUNACIÓN",
            "secciones": [
              {
                "titulo": "TODAS LAS VACUNAS CON LAS QUE DEBERÍA CONTAR LA MASCOTA HASTA EL DÍA DE SU MUERTE",
                "items": [
                  "Moquillo canino: vacuna esencial que ayuda a prevenir una enfermedad viral grave. Los refuerzos posteriores dependen del historial y de las recomendaciones vigentes.",
                  "Parvovirus canino: vacuna esencial para prevenir una enfermedad que puede causar vómitos, diarrea y deshidratación.",
                  "Adenovirus canino: generalmente se administra como parte de la vacuna combinada y protege contra la hepatitis infecciosa canina.",
                  "Parainfluenza canina: puede recomendarse de acuerdo con la exposición a otros perros y suele formar parte de algunas vacunas combinadas.",
                  "Leptospirosis: se recomienda según el riesgo local, el contacto con roedores, el agua contaminada y las indicaciones veterinarias.",
                  "Rabia: debe mantenerse conforme a las disposiciones oficiales bolivianas y la pauta correspondiente a la vacuna aplicada.",
                  "Bordetella: puede ser recomendable para perros que acuden a guarderías, residencias o lugares con contacto frecuente con otros perros.",
                  "Influenza canina u otras vacunas específicas: se consideran cuando existe un riesgo relevante y el veterinario determina que son apropiadas.",
                  "Si el perro adulto no tiene historial de vacunación, el veterinario establecerá un calendario de recuperación. No debe suponerse que necesita repetir todas las dosis de cachorro sin revisar su historial.",
                  "Las vacunas esenciales requieren refuerzos a lo largo de la vida, pero no todas tienen la misma frecuencia. La vacunación contra la rabia debe seguir las normas sanitarias locales."
                ]
              }
            ]
          },
          "veterinario": {
            "titulo": "CUÁNDO IR AL VETERINARIO",
            "secciones": [
              {
                "titulo": "EN QUÉ SITUACIONES DE EMERGENCIA DEBES DE ACUDIR A UN VETERINARIO",
                "items": [
                  "Hemorragia: una pérdida importante de sangre puede provocar shock y necesita atención inmediata.",
                  "Fractura: un hueso roto puede dañar nervios y tejidos; no se debe intentar acomodarlo.",
                  "Vómitos constantes: pueden provocar deshidratación y señalar una intoxicación, obstrucción o enfermedad importante.",
                  "Dificultad para respirar: puede indicar una emergencia respiratoria o cardiaca.",
                  "Convulsiones: requieren atención urgente si son prolongadas, repetidas o aparecen por primera vez.",
                  "Abdomen hinchado y doloroso: puede ser señal de una afección potencialmente mortal.",
                  "Ingestión de tóxicos: requiere orientación veterinaria inmediata, incluso si aún no hay síntomas.",
                  "Diarrea con sangre: puede ocasionar pérdida de líquidos y ser señal de una enfermedad importante.",
                  "Golpe fuerte o caída: puede provocar lesiones internas que no son evidentes.",
                  "Incapacidad para orinar: puede indicar una obstrucción que necesita tratamiento urgente.",
                  "Desmayo o debilidad extrema: puede ser consecuencia de un problema circulatorio, intoxicación o enfermedad grave.",
                  "Quemaduras importantes: necesitan evaluación para controlar el dolor y prevenir complicaciones."
                ]
              }
            ]
          }
        }
      },
      "senior": {
        "tituloOriginal": "PERRO MESTIZO — SENIOR O GERIÁTRICO (10 AÑOS EN ADELANTE, COMO REFERENCIA)",
        "temas": {
          "alimentacion": {
            "titulo": "ALIMENTACIÓN",
            "secciones": [
              {
                "titulo": "ALIMENTACIÓN SALUDABLE",
                "items": [
                  "Alimento adecuado para perros mayores: elegir una dieta completa que se adapte a su condición corporal, actividad y estado de salud. No todos los perros mayores necesitan la misma fórmula.",
                  "Raciones ajustadas a su actividad: muchos perros mayores se mueven menos y necesitan menos energía, aunque otros pueden mantenerse activos. Ajustar las cantidades para evitar el sobrepeso o la pérdida muscular.",
                  "Agua fresca siempre disponible: mantener recipientes accesibles y observar si bebe mucho más o mucho menos de lo habitual, porque estos cambios pueden indicar enfermedad.",
                  "Proteínas de calidad: los perros mayores necesitan conservar su masa muscular. No se debe reducir la proteína automáticamente por la edad; si existe enfermedad renal u otra condición, la dieta debe ajustarse con el veterinario.",
                  "Textura fácil de masticar: si tiene dientes ausentes o molestias dentales, puede necesitar alimento húmedo o croquetas adaptadas. La dificultad para comer requiere una revisión dental.",
                  "Fibra equilibrada: una dieta apropiada puede ayudar a mantener la regularidad intestinal. El estreñimiento persistente requiere evaluación para descartar deshidratación, dolor u otras enfermedades.",
                  "Comidas regulares: dividir la ración en dos o más comidas puede facilitar la alimentación de algunos perros mayores, especialmente si tienen menor apetito o molestias digestivas.",
                  "Premios moderados: utilizar premios pequeños y apropiados, teniendo en cuenta su aporte calórico. Si tiene enfermedades crónicas, los premios también deben ser compatibles con su dieta terapéutica.",
                  "Control del peso y los músculos: pesarlo periódicamente y observar si pierde músculo, se le marcan demasiado los huesos o acumula grasa permite detectar cambios tempranos.",
                  "Dieta especial bajo supervisión: si padece enfermedad renal, cardiaca, diabetes u otra condición, el veterinario puede recomendar una dieta terapéutica específica. No cambiar su alimentación por cuenta propia."
                ]
              },
              {
                "titulo": "ALIMENTACIÓN NO SALUDABLE",
                "items": [
                  "Chocolate y cafeína: pueden provocar intoxicación y problemas cardiacos o neurológicos; el riesgo no desaparece por tratarse de un perro de edad avanzada.",
                  "Cebolla y ajo: pueden dañar los glóbulos rojos y causar anemia, incluso si se encuentran en alimentos cocinados.",
                  "Uvas y pasas: pueden ocasionar daño renal grave y deben mantenerse fuera de su alcance.",
                  "Productos con xilitol: pueden causar una bajada peligrosa de glucosa y lesión hepática.",
                  "Huesos duros o cocidos: pueden provocar fracturas dentales, atragantamiento, lesiones digestivas u obstrucciones.",
                  "Sobras con mucha grasa: pueden ocasionar molestias digestivas y aumentar el riesgo de pancreatitis. No son adecuadas como alimento habitual.",
                  "Alimentos muy salados: las comidas procesadas y los embutidos no son apropiados como parte regular de su dieta, especialmente si tiene enfermedades cardiacas o renales.",
                  "Comida deteriorada o cruda de riesgo: puede contener bacterias, parásitos o toxinas capaces de provocar enfermedades graves.",
                  "Cambios bruscos y dietas improvisadas: sustituir de golpe su alimento o administrar suplementos sin orientación puede agravar trastornos digestivos o interferir con el manejo de enfermedades."
                ]
              }
            ]
          },
          "salud": {
            "titulo": "SALUD",
            "secciones": [
              {
                "titulo": "TIENE BUENA SALUD",
                "items": [
                  "Mantiene interés por su entorno: aunque descanse más, responde a su familia, disfruta de actividades apropiadas y conserva sus hábitos habituales.",
                  "Come de forma regular: mantiene su apetito y puede masticar y tragar sin dolor ni dificultad.",
                  "Peso relativamente estable: no pierde ni gana peso de manera inexplicable y conserva una masa muscular razonable.",
                  "Respira sin esfuerzo: no presenta dificultad respiratoria, tos persistente ni desmayos.",
                  "Ojos y boca cuidados: no presenta dolor ocular, secreción abundante ni dificultades importantes para masticar. Los cambios de visión deben revisarse.",
                  "Digestión regular: sus heces y hábitos intestinales se mantienen relativamente estables, sin vómitos o diarrea persistentes.",
                  "Movilidad adaptada a su edad: puede levantarse, caminar y cambiar de postura, aunque necesite más tiempo o paseos más suaves.",
                  "Controles preventivos regulares: recibe evaluaciones veterinarias, revisión dental y vacunas o medidas preventivas según su salud, historial y riesgo."
                ]
              },
              {
                "titulo": "TIENE MALA SALUD",
                "items": [
                  "Pérdida de peso o musculatura: puede relacionarse con enfermedades crónicas, problemas dentales, alteraciones hormonales o alimentación insuficiente.",
                  "Disminución persistente del apetito: puede indicar dolor, enfermedad digestiva, problemas renales o dificultad para masticar.",
                  "Aumento excesivo de sed u orina: puede ser señal de enfermedad renal, diabetes u otros problemas y necesita evaluación veterinaria.",
                  "Tos o dificultad respiratoria: pueden relacionarse con enfermedades cardiacas, pulmonares u otras afecciones importantes.",
                  "Problemas dentales: el mal aliento intenso, sangrado de encías, dolor o rechazo del alimento pueden indicar enfermedad periodontal.",
                  "Rigidez y dolor al moverse: puede presentar dificultad para levantarse, cojera o menor disposición a caminar por problemas articulares u otras causas.",
                  "Cambios en la visión o audición: puede chocar con objetos, sobresaltarse al acercarse alguien o responder menos a los sonidos. Estos cambios deben evaluarse para descartar causas tratables.",
                  "Desorientación o alteraciones del sueño: puede confundirse en lugares conocidos, caminar sin rumbo o cambiar sus horarios. Estos signos no deben atribuirse automáticamente a la edad.",
                  "Debilidad grave o colapso: si no puede levantarse, se desmaya, tiene encías muy pálidas o respira con dificultad, necesita atención urgente."
                ]
              }
            ]
          },
          "primeros": {
            "titulo": "PRIMEROS AUXILIOS",
            "secciones": [
              {
                "titulo": "QUÉ HACER CUANDO LE SUCEDEN ACCIDENTES COMO:",
                "items": []
              },
              {
                "titulo": "CAÍDA",
                "items": [
                  "Acercarse con calma y observar si responde y respira normalmente.",
                  "No obligarlo a levantarse ni caminar si muestra dolor, debilidad o pérdida de equilibrio.",
                  "Si se sospecha una lesión de columna, trasladarlo sobre una superficie firme manteniendo el cuerpo alineado.",
                  "Evitar mover bruscamente las articulaciones o intentar enderezar extremidades.",
                  "Buscar atención veterinaria inmediata si no puede levantarse, presenta dolor intenso, golpe en la cabeza o dificultad respiratoria.",
                  "Aunque la caída parezca leve, consultar si posteriormente aparece cojera, desorientación o pérdida del apetito."
                ]
              },
              {
                "titulo": "HERIDAS O HEMORRAGIAS",
                "items": [
                  "Mantenerlo tranquilo y manipularlo con suavidad, porque el dolor puede provocar una reacción defensiva.",
                  "Presionar la herida con una gasa limpia y mantener la presión.",
                  "Si el sangrado es abundante, no se detiene o el perro presenta debilidad, acudir de inmediato a urgencias.",
                  "No retirar objetos profundamente clavados ni aplicar alcohol o agua oxigenada.",
                  "Evitar vendas demasiado apretadas, especialmente en las extremidades.",
                  "Las heridas profundas, mordeduras y lesiones que afectan articulaciones requieren revisión veterinaria."
                ]
              },
              {
                "titulo": "ATRAGANTAMIENTO",
                "items": [
                  "Si todavía respira y tose, mantenerlo tranquilo y buscar asistencia veterinaria si los síntomas continúan.",
                  "Si no puede respirar, pierde el conocimiento o se debilita mucho, acudir a urgencias inmediatamente.",
                  "No introducir los dedos a ciegas en la boca ni empujar objetos hacia el interior.",
                  "Evitar maniobras improvisadas que puedan causar lesiones y seguir las instrucciones de un profesional veterinario.",
                  "Después del episodio, necesita valoración si persisten la tos, la respiración ruidosa o la dificultad para tragar."
                ]
              },
              {
                "titulo": "INTOXICACIÓN",
                "items": [
                  "Alejarlo de la sustancia tóxica y evitar una nueva exposición.",
                  "Identificar el producto, conservar el envase y anotar la cantidad aproximada y la hora.",
                  "Contactar inmediatamente con un veterinario, incluso si todavía no presenta síntomas.",
                  "No inducir el vómito ni ofrecer leche, aceite, carbón activado o medicamentos sin indicación profesional.",
                  "Si presenta convulsiones, dificultad respiratoria o pérdida de conocimiento, trasladarlo a urgencias sin demora."
                ]
              },
              {
                "titulo": "QUEMADURAS",
                "items": [
                  "Retirarlo de la fuente de calor o del producto irritante.",
                  "Enfriar la zona con agua corriente fresca durante unos 20 minutos, siempre que esto no retrase la atención.",
                  "No aplicar hielo, mantequilla, pasta dental ni cremas caseras.",
                  "No arrancar la piel dañada ni romper ampollas.",
                  "Cubrir suavemente la zona con una tela limpia y acudir al veterinario, especialmente si la quemadura es extensa o afecta zonas sensibles."
                ]
              }
            ]
          },
          "cuidados": {
            "titulo": "CUIDADOS",
            "secciones": [
              {
                "titulo": "CÓMO MANTENERLO BIEN CUIDADO",
                "items": [
                  "Alimentación adaptada: elegir un alimento apropiado para su condición corporal y sus enfermedades, si las tiene. Los cambios de dieta deben realizarse con orientación veterinaria.",
                  "Ejercicio moderado: ofrecer paseos más cortos y frecuentes si se cansa fácilmente, sin forzarlo a correr o saltar.",
                  "Superficie antideslizante: colocar alfombras o superficies con buen agarre en las zonas donde camina para reducir el riesgo de caídas.",
                  "Cama cómoda: proporcionarle una cama acolchada, seca y fácil de alcanzar, protegida del frío y del calor excesivo.",
                  "Acceso a comida y agua: ubicar los recipientes donde pueda llegar sin subir escaleras ni caminar sobre superficies resbaladizas.",
                  "Higiene cuidadosa: cepillarlo, bañarlo cuando sea necesario y secarlo bien. La piel de algunos perros mayores puede ser más delicada.",
                  "Cuidado dental: revisar periódicamente sus dientes y encías y consultar si tiene dolor, mal aliento o dificultad para comer.",
                  "Control de uñas: evitar que las uñas demasiado largas dificulten el apoyo y la estabilidad al caminar.",
                  "Estimulación mental: ofrecer juegos de olfato sencillos, interacción tranquila y actividades que pueda realizar sin dolor.",
                  "Controles veterinarios más frecuentes: realizar revisiones periódicas, a menudo cada seis meses o según indique el veterinario, para detectar enfermedades antes de que avancen."
                ]
              },
              {
                "titulo": "CÓMO SABER SI NO TIENE UN BUEN CUIDADO",
                "items": [
                  "✦ HIGIENE Y COMODIDAD",
                  "Tiene el pelo sucio, las uñas excesivamente largas o la piel irritada por falta de mantenimiento.",
                  "No dispone de una cama cómoda y seca que le permita descansar sin dolor.",
                  "✦ ALIMENTACIÓN Y AGUA",
                  "Pierde peso o masa muscular sin que se investigue la causa.",
                  "Tiene dificultad para alcanzar el agua o comer porque sus recipientes están mal ubicados.",
                  "Recibe suplementos o dietas restrictivas sin supervisión veterinaria.",
                  "✦ SALUD Y PREVENCIÓN",
                  "Se ignoran el dolor, la cojera, los problemas dentales o los cambios de comportamiento.",
                  "No recibe controles veterinarios a pesar de presentar enfermedades o signos persistentes.",
                  "✦ ATENCIÓN Y MOVILIDAD",
                  "Se le obliga a realizar ejercicio excesivo pese a mostrar dolor o agotamiento.",
                  "Vive en un lugar donde resbala constantemente o debe subir escaleras que ya no puede utilizar con seguridad.",
                  "Permanece aislado, sin interacción, compañía ni actividades adecuadas a su capacidad."
                ]
              }
            ]
          },
          "comportamiento": {
            "titulo": "COMPORTAMIENTO",
            "secciones": [
              {
                "titulo": "ADIESTRAMIENTO DESDE CACHORRO",
                "items": [
                  "Enseñar órdenes básicas con refuerzo positivo, sesiones breves y recompensas.",
                  "Acostumbrarlo a caminar con correa y regresar cuando se le llama.",
                  "Enseñarle a esperar antes de salir por una puerta y a mantener distancia segura de la calle.",
                  "Premiar las conductas tranquilas y las interacciones respetuosas con las personas.",
                  "Introducir progresivamente el cepillado, la revisión de patas y la manipulación suave.",
                  "Acostumbrarlo a las visitas veterinarias mediante experiencias graduales y recompensas.",
                  "Mantener una rutina que combine ejercicio, descanso, comida y estimulación mental.",
                  "Evitar castigos físicos que puedan generar miedo, dolor o desconfianza.",
                  "Proporcionar experiencias positivas con otros perros cuando sea seguro y apropiado.",
                  "Adaptar las sesiones de aprendizaje a su capacidad de atención y a su nivel de energía."
                ]
              },
              {
                "titulo": "CÓMO MEJORAR EL COMPORTAMIENTO DE TU MASCOTA SI NO FUE ADIESTRADO",
                "items": [
                  "Comenzar con órdenes sencillas y recompensar las respuestas correctas.",
                  "Practicar en un ambiente tranquilo, aumentando las distracciones poco a poco.",
                  "Si tiene dificultades para escuchar o ver, utilizar señales visuales, gestos o indicaciones que pueda percibir.",
                  "Si se muestra irritable al tocarlo, evitar forzarlo y consultar con el veterinario para descartar dolor.",
                  "Si ladra por ansiedad, identificar los desencadenantes y trabajar gradualmente para reducir el estrés.",
                  "Si se desorienta, mantener una rutina estable y evitar cambios innecesarios en los muebles y el entorno.",
                  "Si tiene miedo de otros perros, mantener distancia y no forzar los encuentros.",
                  "Evitar castigos, gritos y movimientos bruscos, especialmente si tiene problemas sensoriales.",
                  "Ajustar el entrenamiento a sesiones breves, con descansos y recompensas apropiadas.",
                  "Consultar con un veterinario si aparecen confusión, irritabilidad, ansiedad o cambios de conducta repentinos."
                ]
              }
            ]
          },
          "vacunacion": {
            "titulo": "VACUNACIÓN",
            "secciones": [
              {
                "titulo": "TODAS LAS VACUNAS CON LAS QUE DEBERÍA CONTAR LA MASCOTA HASTA EL DÍA DE SU MUERTE",
                "items": [
                  "Moquillo canino: debe contar con la serie inicial y los refuerzos que correspondan según su historial y la pauta veterinaria.",
                  "Parvovirus canino: la protección se mantiene mediante las dosis iniciales y los refuerzos indicados para la vacuna utilizada.",
                  "Adenovirus canino: generalmente se administra como parte de la vacuna combinada y se refuerza según las recomendaciones aplicables.",
                  "Parainfluenza canina: puede recomendarse si existe riesgo de exposición frecuente a otros perros.",
                  "Leptospirosis: la necesidad de refuerzos depende de la exposición local y de las indicaciones veterinarias.",
                  "Rabia: debe mantenerse conforme a la normativa sanitaria boliviana y las instrucciones correspondientes a la vacuna.",
                  "Bordetella: puede indicarse si el perro tiene contacto frecuente con muchos perros o acude a guarderías y residencias.",
                  "Influenza canina u otras vacunas específicas: se consideran cuando existe un riesgo relevante y están indicadas por el veterinario.",
                  "En perros senior, la edad por sí sola no significa que deba dejar de vacunarse. El veterinario revisará su historial, estado de salud, exposición y normas locales para determinar qué vacunas necesita y con qué frecuencia. No todas las vacunas requieren refuerzos anuales."
                ]
              }
            ]
          },
          "veterinario": {
            "titulo": "CUÁNDO IR AL VETERINARIO",
            "secciones": [
              {
                "titulo": "EN QUÉ SITUACIONES DE EMERGENCIA DEBES DE ACUDIR A UN VETERINARIO",
                "items": [
                  "Hemorragia: puede provocar pérdida importante de sangre y shock. Mantener presión con una gasa limpia mientras se busca atención urgente.",
                  "Fractura: puede causar dolor intenso y daño a los tejidos. Evitar mover la extremidad o intentar acomodar el hueso.",
                  "Vómitos constantes: pueden provocar deshidratación y señalar una enfermedad digestiva grave, intoxicación u obstrucción.",
                  "Dificultad para respirar: puede ser señal de enfermedad cardiaca o pulmonar y requiere atención inmediata.",
                  "Convulsiones: si son prolongadas, repetidas o aparecen por primera vez, debe recibir evaluación urgente.",
                  "Abdomen hinchado y doloroso: puede indicar una afección grave que necesita tratamiento inmediato.",
                  "Intoxicación: algunos productos pueden causar daño a los órganos incluso antes de que aparezcan síntomas.",
                  "Diarrea con sangre: puede ocasionar pérdida de líquidos y ser señal de una enfermedad importante.",
                  "Golpe fuerte o caída: puede provocar lesiones internas, fracturas o traumatismos que no se ven a simple vista.",
                  "Incapacidad para orinar: puede indicar una obstrucción urinaria que necesita tratamiento urgente.",
                  "Desmayo o debilidad extrema: puede ser consecuencia de un problema circulatorio, cardiaco o metabólico.",
                  "Dolor intenso o incapacidad para levantarse: requiere atención inmediata, especialmente si aparece de repente.",
                  "En los perros mayores, también conviene consultar pronto ante pérdida de peso, aumento de sed, tos persistente, desorientación o dificultad progresiva para caminar, aunque estos signos no parezcan una emergencia inmediata."
                ]
              }
            ]
          }
        }
      }
    }
  },
  "criollo": {
    "nombre": "Criollo",
    "etapas": {
      "cachorro": {
        "tituloOriginal": "PERRO CRIOLLO – CACHORRO (0 A 12 MESES)",
        "temas": {
          "alimentacion": {
            "titulo": "ALIMENTACIÓN",
            "secciones": [
              {
                "titulo": "ALIMENTACIÓN SALUDABLE",
                "items": [
                  "Alimento completo para cachorros: Debe recibir un alimento comercial completo y equilibrado formulado para cachorros. Este contiene proteínas, grasas, vitaminas, minerales y otros nutrientes necesarios para el crecimiento de los huesos, músculos, órganos y sistema nervioso. La cantidad debe ajustarse a su peso, tamaño esperado de adulto y nivel de actividad.",
                  "Proteínas de buena calidad: Las proteínas contribuyen al desarrollo muscular, la reparación de tejidos y el funcionamiento del organismo. Un alimento para cachorros debe proporcionar proteínas adecuadas provenientes de ingredientes animales y otras fuentes nutritivas. No es necesario agregar carne adicional si el alimento ya cubre sus necesidades.",
                  "Agua limpia y fresca: Debe tener agua potable disponible durante todo el día. El recipiente debe lavarse con frecuencia y colocarse en un lugar accesible, protegido del sol intenso y de la suciedad. Los cachorros pueden deshidratarse con mayor facilidad que los perros adultos, especialmente cuando presentan vómitos o diarrea.",
                  "Comidas repartidas durante el día: Los cachorros pequeños suelen necesitar entre tres y cuatro comidas diarias, según su edad, tamaño y recomendaciones veterinarias. A medida que crecen, las comidas pueden reducirse gradualmente. Repartir la ración ayuda a mantener una alimentación regular y facilita la digestión.",
                  "Alimentación durante el destete: Durante las primeras semanas, la leche materna es la principal fuente de alimento. Si la madre no puede amamantar, se debe utilizar un sustituto lácteo formulado específicamente para cachorros, indicado por un veterinario. El destete suele comenzar alrededor de las tres o cuatro semanas y se realiza gradualmente; no debe separarse prematuramente al cachorro de su madre cuando sea posible evitarlo.",
                  "Alimento adecuado para su tamaño: Un cachorro que crecerá hasta un tamaño pequeño puede necesitar croquetas más pequeñas, mientras que uno de tamaño grande puede requerir una fórmula de crecimiento específica. El tamaño del perro no se determina únicamente por sus patas cuando es pequeño; conviene consultar al veterinario para estimar sus necesidades.",
                  "Cambio gradual de alimento: Si es necesario cambiar de marca o fórmula, la transición debe realizarse progresivamente durante varios días, generalmente entre cinco y siete, siempre que el cachorro tolere el alimento. Los cambios repentinos pueden producir diarrea, gases o molestias digestivas.",
                  "Premios saludables y moderados: Para enseñarle órdenes básicas se pueden utilizar pequeñas porciones de su propio alimento o premios formulados para perros. Los premios deben ser pequeños y no reemplazar sus comidas. En general, no deberían superar aproximadamente el 10 % de las calorías diarias para evitar desequilibrios nutricionales.",
                  "Comida húmeda completa para cachorros: Puede utilizarse si está identificada como alimento completo para crecimiento. También puede ayudar a los cachorros que tienen dificultades para masticar croquetas. Una vez abierta, debe conservarse según las indicaciones del fabricante y no dejarse muchas horas a temperatura ambiente.",
                  "Seguimiento del crecimiento: Debe pesarse periódicamente y observarse si aumenta de peso de manera constante, tiene energía y produce heces normales. El veterinario puede ajustar la cantidad de comida según su desarrollo. No se debe alimentar en exceso pensando que crecerá más fuerte, porque el exceso de peso puede afectar sus articulaciones y su salud."
                ]
              },
              {
                "titulo": "ALIMENTACIÓN NO SALUDABLE",
                "items": [
                  "Chocolate y cacao: Contienen sustancias que pueden intoxicar a los perros. El riesgo depende del tipo de chocolate, la cantidad ingerida y el tamaño del cachorro. Si consume chocolate, se debe contactar de inmediato con un veterinario, sin esperar a que aparezcan síntomas.",
                  "Cebolla, ajo y alimentos de la misma familia: Pueden dañar los glóbulos rojos y provocar anemia. El riesgo existe con distintas preparaciones y formas de consumo. No se deben utilizar como remedios caseros ni agregarlos deliberadamente a su comida.",
                  "Uvas y pasas: Pueden causar lesiones renales graves en algunos perros y no existe una cantidad que pueda considerarse segura para todos. Si el cachorro las ingiere, necesita orientación veterinaria urgente, aunque inicialmente parezca estar bien.",
                  "Huesos cocidos: Pueden astillarse y ocasionar atragantamiento, lesiones en el aparato digestivo u obstrucciones. No deben darse como método para limpiar los dientes. Los huesos crudos tampoco están libres de riesgos, ya que pueden producir fracturas dentales, obstrucciones y contaminación bacteriana.",
                  "Comida excesivamente salada, grasosa o condimentada: Las frituras, embutidos, restos de comida con mucha sal y preparaciones muy aceitosas pueden causar problemas digestivos y aportar demasiadas calorías. Algunos platos también contienen cebolla, ajo u otros ingredientes tóxicos.",
                  "Leche de vaca como alimento habitual: Muchos cachorros no digieren bien la lactosa y pueden presentar gases o diarrea. La leche de vaca no reemplaza la leche materna ni un sustituto formulado para cachorros.",
                  "Dulces, caramelos y productos con xilitol: El xilitol, presente en algunos productos sin azúcar, puede provocar una bajada peligrosa de la glucosa y daño hepático. Nunca se deben ofrecer chicles, caramelos o productos que contengan este ingrediente.",
                  "Alimentos crudos o en mal estado: La carne, los huevos y otros productos crudos pueden contener microorganismos perjudiciales. Los alimentos podridos o contaminados también pueden causar intoxicaciones y enfermedades digestivas. No se debe alimentar al cachorro con sobras que hayan pasado mucho tiempo al calor.",
                  "Exceso de suplementos o comida casera desequilibrada: Agregar calcio, vitaminas o minerales sin indicación veterinaria puede perjudicar el desarrollo, especialmente en cachorros que crecerán mucho. Una dieta compuesta únicamente de arroz, carne, sopa o sobras no garantiza los nutrientes que necesita."
                ]
              }
            ]
          },
          "salud": {
            "titulo": "SALUD",
            "secciones": [
              {
                "titulo": "TIENE BUENA SALUD",
                "items": [
                  "Tiene energía apropiada para su edad: Juega, explora, corre durante períodos cortos y responde a las personas. Es normal que los cachorros alternen momentos de actividad con períodos largos de sueño, porque están creciendo y aprendiendo.",
                  "Tiene buen apetito: Come sus raciones con regularidad y bebe agua. Puede haber pequeñas variaciones en el apetito, pero una pérdida persistente del interés por la comida debe consultarse, especialmente en cachorros pequeños.",
                  "Sus ojos se ven limpios: Los ojos suelen estar brillantes, sin secreción abundante, enrojecimiento intenso ni hinchazón. Si entrecierra un ojo, se lo frota o parece sentir dolor, necesita revisión veterinaria.",
                  "Su nariz y respiración no presentan alteraciones evidentes: Respira cómodamente cuando está en reposo, sin esfuerzo marcado, tos persistente ni sonidos respiratorios anormales. La nariz puede estar húmeda o seca en diferentes momentos; por sí sola, su humedad no permite determinar si está enfermo.",
                  "Tiene piel y pelaje en buen estado: El pelaje se mantiene razonablemente limpio y no presenta calvas extensas, heridas, costras abundantes ni picazón constante. Algunos cachorros cambian de pelaje mientras crecen, pero la pérdida excesiva o la inflamación requieren atención.",
                  "Sus heces son formadas: Defeca sin esfuerzo excesivo y las heces no presentan sangre ni una cantidad importante de mucosidad. Los cambios de alimento y algunos parásitos pueden alterar las heces, por lo que es importante observar cualquier cambio persistente.",
                  "Se mueve con normalidad: Camina, se levanta y juega sin cojear de forma persistente. Si se cae continuamente, no apoya una pata o parece tener dolor al moverse, debe evaluarlo un veterinario.",
                  "Crece y aprende progresivamente: Aumenta de peso, explora su entorno y responde cada vez mejor a las rutinas. La velocidad de desarrollo depende de su genética, tamaño y salud; el veterinario puede comprobar si está creciendo de manera adecuada."
                ]
              },
              {
                "titulo": "TIENE MALA SALUD",
                "items": [
                  "Pierde el apetito o deja de beber: Si rechaza varias comidas, está débil o no quiere beber, debe consultarse pronto. En un cachorro muy pequeño, la falta de alimento puede volverse peligrosa en poco tiempo.",
                  "Presenta vómitos repetidos o diarrea intensa: Puede deshidratarse rápidamente. Si hay sangre, debilidad, dolor, fiebre aparente o no puede retener el agua, necesita atención veterinaria urgente. No debe suponerse que se trata únicamente de un cambio de comida.",
                  "Tiene abdomen hinchado o doloroso: Un vientre muy distendido, duro o doloroso, especialmente acompañado de arcadas, debilidad o inquietud, puede indicar una emergencia. No se debe presionar el abdomen ni administrar medicamentos por cuenta propia.",
                  "Está excesivamente decaído: Si deja de jugar, permanece acostado, no responde como de costumbre o parece desorientado, puede estar enfermo. El decaimiento acompañado de vómitos, diarrea o falta de apetito requiere una evaluación rápida.",
                  "Tiene secreción abundante en ojos o nariz: Las secreciones espesas, el enrojecimiento, los estornudos constantes y la tos pueden indicar una infección u otro problema. El riesgo es mayor cuando todavía no ha completado sus vacunas.",
                  "Se rasca continuamente o pierde pelo: Las pulgas, garrapatas, ácaros, hongos y alergias pueden causar picazón, lesiones y caída del pelo. Se necesita un diagnóstico adecuado antes de elegir un tratamiento, porque algunos productos no son seguros para cachorros pequeños.",
                  "Presenta encías pálidas o amarillentas: Las encías muy pálidas pueden relacionarse con anemia o pérdida de sangre, mientras que la coloración amarillenta puede indicar problemas importantes. Ambas situaciones requieren atención veterinaria urgente, especialmente si está débil.",
                  "Tiene dificultad para caminar o convulsiones: La pérdida del equilibrio, los temblores intensos, las convulsiones o la incapacidad para mantenerse en pie son señales de alarma. Se debe proteger al cachorro de golpes y trasladarlo a un centro veterinario; no se deben introducir objetos en su boca.",
                  "Tiene parásitos o no aumenta de peso: Un abdomen abultado, diarrea recurrente, gusanos visibles en las heces, encías pálidas o crecimiento insuficiente pueden estar relacionados con parásitos u otras enfermedades. El veterinario debe establecer el tratamiento y el calendario de desparasitación."
                ]
              }
            ]
          },
          "primeros": {
            "titulo": "PRIMEROS AUXILIOS",
            "secciones": [
              {
                "titulo": "QUÉ HACER CUANDO LE SUCEDEN ACCIDENTES COMO:",
                "items": [
                  "CAÍDAS, GOLPES O ATROPELLOS",
                  "Mantener la calma y alejar al cachorro del tránsito u otros peligros sin ponerse en riesgo.",
                  "Observar si está consciente, respira normalmente y puede moverse. No obligarlo a caminar para comprobar si está bien.",
                  "Si se sospecha una lesión en la columna, pelvis o patas, moverlo lo menos posible y transportarlo sobre una superficie firme, procurando mantener el cuerpo alineado.",
                  "Si hay sangrado externo, aplicar presión suave y continua con una gasa o tela limpia, siempre que sea posible hacerlo sin empeorar la lesión.",
                  "No intentar acomodar huesos, estirar patas ni masajear zonas dolorosas.",
                  "Acudir urgentemente al veterinario después de un atropello o golpe fuerte, aunque el cachorro parezca normal, porque algunas lesiones internas no se ven inmediatamente.",
                  "HERIDAS Y SANGRADO",
                  "Si la herida es superficial, evitar que el cachorro la lama y consultar cómo limpiarla de forma segura.",
                  "Para un sangrado externo, colocar una gasa limpia y ejercer presión constante. Si la gasa se empapa, añadir otra encima sin retirar la primera.",
                  "Si el sangrado es abundante, la herida es profunda, hay un objeto incrustado o se observa tejido expuesto, acudir inmediatamente al veterinario.",
                  "No extraer objetos grandes incrustados ni aplicar alcohol, agua oxigenada, polvos, ceniza, café o preparados caseros sobre la herida.",
                  "No utilizar antibióticos, cremas humanas ni analgésicos sin indicación veterinaria.",
                  "Aunque deje de sangrar, una mordedura o una herida profunda debe revisarse porque puede infectarse o esconder daños internos.",
                  "ATRAGANTAMIENTO O DIFICULTAD PARA RESPIRAR",
                  "Si el cachorro tose con fuerza y todavía puede respirar, permitirle toser mientras se busca ayuda veterinaria.",
                  "Si no puede respirar, no emite sonidos, se desploma o sus encías se tornan azuladas, se trata de una emergencia inmediata.",
                  "Mirar la boca solamente si es seguro hacerlo y el objeto se encuentra claramente visible y puede retirarse sin empujarlo hacia la garganta.",
                  "No introducir los dedos a ciegas en la boca, porque se puede empujar el objeto más profundamente o sufrir una mordedura involuntaria.",
                  "No darle agua, comida, aceite ni medicamentos para intentar que el objeto pase.",
                  "Llamar a un servicio veterinario de urgencia y seguir sus instrucciones mientras se organiza el traslado.",
                  "SOSPECHA DE INTOXICACIÓN",
                  "Retirar al cachorro de la fuente de exposición y evitar que otros animales tengan contacto con ella.",
                  "Identificar, si es posible, el producto, planta, alimento o sustancia ingerida y guardar su envase o una fotografía de la etiqueta.",
                  "Contactar inmediatamente con un veterinario, incluso si todavía no hay síntomas.",
                  "No provocar el vómito ni administrar leche, aceite, sal, carbón activado u otros remedios, salvo que un profesional indique específicamente qué hacer.",
                  "Si el producto está sobre el pelaje o la piel, evitar que lo lama y pedir instrucciones para descontaminarlo de manera segura.",
                  "Si presenta convulsiones, dificultad respiratoria, desmayo o debilidad intensa, trasladarlo a urgencias sin demora.",
                  
                ]
              },
              {
                "titulo": "QUÉ HACER CUANDO LE SUCEDEN ACCIDENTES COMO:",
                "items": [
                "QUEMADURAS POR AGUA CALIENTE, FUEGO O PRODUCTOS QUÍMICOS",
                  "Alejarlo de la fuente de calor o de la sustancia peligrosa.",
                  "En una quemadura térmica pequeña, enfriar suavemente la zona con agua corriente fresca, nunca helada, durante unos 20 minutos si se puede hacer sin retrasar la atención.",
                  "No colocar hielo, mantequilla, aceite, pasta dental, cremas humanas ni remedios caseros.",
                  "No arrancar piel ni reventar ampollas. Cubrir la zona de manera ligera con una tela limpia que no se adhiera y acudir al veterinario.",
                  "Si el producto es químico, evitar el contacto con la sustancia y solicitar instrucciones profesionales para retirarla; algunos productos reaccionan con el agua.",
                  "Las quemaduras en la cara, los ojos, las patas, los genitales o una superficie amplia necesitan atención urgente.",
                  "MORDEDURAS DE OTROS ANIMALES Y PICADURAs",
                  "Separar al cachorro del otro animal sin exponer las manos a una nueva mordedura.",
                  "Si hay una herida, controlar el sangrado con presión suave y acudir al veterinario, incluso si los orificios parecen pequeños.",
                  "Vigilar hinchazón rápida de la cara, vómitos, debilidad o dificultad respiratoria, ya que pueden indicar una reacción grave.",
                  "No administrar antihistamínicos ni medicamentos humanos sin indicación veterinaria.",
                  "Si la mordedura proviene de un animal desconocido o con comportamiento extraño, evitar tocar su saliva y solicitar orientación veterinaria y sanitaria sobre la rabia.",
                  "Si existe contacto con un murciélago o un animal sospechoso de rabia, se necesita orientación sanitaria urgente, además de la evaluación del cachorro.",
                  "VÓMITOS Y DIARREA",
                  "Mantenerlo en un lugar tranquilo y observar la frecuencia, el aspecto de las heces y cualquier síntoma adicional.",
                  "No administrar antidiarreicos ni antibióticos humanos.",
                  "No obligarlo a comer o beber. Si está alerta y no vomita repetidamente, se puede ofrecer una pequeña cantidad de agua mientras se contacta al veterinario.",
                  "No someter a un cachorro pequeño a ayunos prolongados sin indicación profesional.",
                  "Buscar atención urgente si hay sangre, vómitos repetidos, dolor abdominal, debilidad, encías pálidas o incapacidad para retener agua.",
                  "Si no ha completado su vacunación y presenta vómitos o diarrea, debe revisarse pronto para descartar enfermedades infecciosas, como el parvovirus. Mantenerlo separado de otros perros hasta recibir orientación.",
                  "GOLPE DE CALOR O SOBRECALENTAMIENTO",
                  "Trasladarlo inmediatamente a un lugar fresco, ventilado y protegido del sol.",
                  "Mojar suavemente el cuerpo con agua fresca, no helada, y utilizar ventilación mientras se organiza el traslado veterinario.",
                  "No envolverlo en toallas mojadas que acumulen calor ni utilizar hielo directamente sobre el cuerpo.",
                  "No forzarlo a beber si está desorientado, vomita o no puede tragar con normalidad.",
                  "Buscar atención veterinaria urgente si jadea intensamente, babea mucho, vomita, camina de manera inestable, se desploma o parece confundido.",
                  "En Bolivia, la exposición al sol y los ambientes muy calurosos pueden ser peligrosos incluso cuando el día no parece extremadamente caliente."
                
                ]
              }
            ]
          },
          "cuidados": {
            "titulo": "CUIDADOS",
            "secciones": [
              {
                "titulo": "CÓMO MANTENERLO BIEN CUIDADO",
                "items": [
                  "Proporcionar un lugar seguro para dormir: Debe contar con una cama seca, limpia, cómoda y protegida del frío, la lluvia y las corrientes de aire. Los cachorros pequeños tienen mayor dificultad para regular su temperatura, por lo que necesitan un ambiente adecuado sin fuentes de calor que puedan quemarlos.",
                  "Mantener su espacio limpio: Lavar periódicamente sus recipientes, retirar las heces y mantener limpio el lugar donde duerme. La acumulación de excrementos puede favorecer la transmisión de parásitos y microorganismos, especialmente cuando hay varios perros en la misma casa.",
                  "Realizar visitas veterinarias preventivas: Durante los primeros meses se deben revisar el crecimiento, los dientes, la piel, los oídos y el estado general. El veterinario también establecerá el calendario de vacunas, desparasitación y prevención de pulgas y garrapatas.",
                  "Cumplir la desparasitación indicada: Los cachorros pueden adquirir parásitos de la madre o del ambiente. El producto y la frecuencia deben elegirse según la edad, el peso, el riesgo de exposición y, cuando corresponda, un examen de heces. No se deben utilizar remedios caseros ni dosis calculadas al azar.",
                  "Protegerlo de las enfermedades infecciosas: Hasta que complete las vacunas y el veterinario confirme que puede ampliar sus contactos, evitar lugares muy concurridos por perros, heces de animales desconocidos y recipientes comunitarios sucios. Puede socializar de manera segura con personas y animales sanos, vacunados y conocidos, siguiendo las recomendaciones veterinarias.",
                  "Acostumbrarlo al cepillado: Cepillarlo suavemente con un instrumento apropiado para su tipo de pelaje ayuda a retirar pelo suelto, descubrir parásitos y acostumbrarlo a la manipulación. La frecuencia depende de si tiene pelo corto, medio o largo.",
                  "Cuidar sus dientes desde pequeño: Acostumbrarlo gradualmente a que le revisen la boca y utilizar un cepillo y pasta dental formulados para perros. La pasta dental humana no es adecuada para que la trague. El cuidado temprano facilita mantener una buena higiene oral durante su vida adulta.",
                  "Revisar las orejas y las patas: Observar si hay enrojecimiento, mal olor, secreción, heridas o espigas vegetales entre los dedos. Limpiar únicamente la parte externa de las orejas y utilizar productos específicos si el veterinario lo indica; no introducir hisopos profundamente en el canal auditivo.",
                  "Ofrecer ejercicio apropiado: Permitirle jugar y explorar en períodos cortos, con pausas para descansar. Evitar carreras forzadas, saltos desde alturas y ejercicio intenso prolongado, especialmente durante el crecimiento. Las necesidades dependen de su tamaño, edad y condición física.",
                  "Supervisar el juego y el entorno: Retirar cables, productos de limpieza, medicamentos, objetos pequeños y basura que pueda ingerir. Vigilarlo cuando esté cerca de escaleras, calles, piscinas u otros peligros. No dejarlo solo en lugares donde pueda escapar o lesionarse.",
                  "Mantener identificación y supervisión: Utilizar un collar o arnés adecuado y una identificación con datos de contacto. No permitir que camine libremente por calles o carreteras. En zonas rurales, también debe protegerse de vehículos, animales agresivos y posibles encuentros con fauna silvestre.",
                  "Acostumbrarlo al baño sin excesos: Bañarlo cuando realmente lo necesite, utilizando un champú para perros apropiado para cachorros. Evitar productos perfumados fuertes y secarlo bien, especialmente si hace frío. Los baños demasiado frecuentes pueden irritar la piel.",
                  "Enseñarle a hacer sus necesidades en el lugar correcto: Llevarlo al lugar elegido después de dormir, comer, beber y jugar, y premiarlo inmediatamente cuando lo haga allí. Limpiar los accidentes sin castigarlo; los gritos pueden generar miedo y dificultar el aprendizaje.",
                  "Garantizar descanso suficiente: Los cachorros necesitan muchas horas de sueño a lo largo del día. Deben tener un sitio tranquilo para descansar y no ser despertados constantemente para jugar. El descanso favorece su desarrollo y aprendizaje.",
                  "Proporcionar afecto y contacto positivo: Hablarle con calma, manipularlo suavemente y permitir que se acerque a nuevas experiencias sin forzarlo. El trato amable ayuda a construir confianza y reduce el riesgo de miedo a las personas."
                ]
              },
              {
                "titulo": "CÓMO SABER SI NO TIENE UN BUEN CUIDADO",
                "items": [
                  "1. Mala alimentación o falta de agua",
                  "Se observa muy delgado, no aumenta de peso o presenta un abdomen abultado acompañado de otros síntomas.",
                  "Tiene el pelo opaco, está débil o parece tener hambre constantemente.",
                  "El recipiente de agua está vacío, sucio o fuera de su alcance.",
                  "Recibe únicamente sobras, arroz, pan u otros alimentos que no cubren sus necesidades de crecimiento.",
                  "2. Higiene insuficiente",
                  "Tiene el cuerpo permanentemente sucio, el pelaje enredado o un olor desagradable persistente.",
                  "Su cama está húmeda, llena de heces o expuesta continuamente a la lluvia.",
                  "Presenta uñas excesivamente largas, suciedad acumulada o lesiones que no se atienden.",
                  "Tiene pulgas, garrapatas o heridas que se dejan sin tratamiento.",
                  "3. Falta de atención médica",
                  "No recibe las vacunas recomendadas ni la desparasitación indicada.",
                  "Pasa días con diarrea, vómitos, tos, heridas o picazón sin ser evaluado.",
                  "Se utilizan medicamentos humanos o remedios caseros sin consultar a un veterinario.",
                  "No se comprueba su crecimiento ni se busca ayuda cuando deja de comer o se muestra débil.",
                  "4. Falta de protección",
                  "Permanece atado durante períodos prolongados sin poder moverse cómodamente.",
                  "Se encuentra expuesto al sol intenso, al frío, a la lluvia o a temperaturas extremas.",
                  "Tiene acceso a la calle sin supervisión y puede ser atropellado, perderse o sufrir ataques.",
                  "Está en un ambiente con basura, productos tóxicos, cables o materiales que puede tragarse.",
                  "5. Falta de cariño y socialización",
                  "Se le grita, golpea o castiga físicamente cuando comete errores.",
                  "Se le impide tener experiencias positivas con personas y ambientes seguros.",
                  "Pasa la mayor parte del tiempo aislado y sin interacción.",
                  "Muestra miedo constante, se esconde o reacciona con angustia cuando alguien se acerca."
                ]
              }
            ]
          },
          "comportamiento": {
            "titulo": "COMPORTAMIENTO",
            "secciones": [
              {
                "titulo": "ADIESTRAMIENTO DESDE CACHORRO",
                "items": [
                  "Enseñarle su nombre: Pronunciar su nombre con voz amable y premiarlo cuando mire hacia la persona que lo llama. Practicar en un ambiente tranquilo y aumentar gradualmente las distracciones. No utilizar su nombre únicamente para regañarlo.",
                  "Enseñarle a responder a la llamada: Decir una palabra sencilla, como “ven”, desde una distancia corta. Cuando se acerque, recompensarlo con elogios, juego o un pequeño premio. Practicar en lugares seguros y utilizar una correa cuando exista riesgo de que salga corriendo.",
                  "Enseñarle a sentarse: Sostener un premio cerca de su nariz y moverlo lentamente hacia arriba y atrás para facilitar que se siente. En cuanto lo haga, decir “siéntate” y recompensarlo. No empujar su cuerpo hacia el suelo.",
                  "Enseñarle a esperar: Pedirle que permanezca quieto durante uno o dos segundos antes de darle la comida o abrir una puerta. Aumentar el tiempo gradualmente y recompensarlo por mantener la calma. No exigirle períodos prolongados al comienzo.",
                  "Enseñarle a caminar con correa: Presentarle el arnés y la correa de forma positiva dentro de casa. Recompensarlo por caminar cerca de la persona sin tirar. Practicar en espacios tranquilos antes de pasar a lugares con más estímulos.",
                  "Evitar que muerda las manos durante el juego: Los cachorros exploran con la boca y pueden morder suavemente mientras juegan. Cuando lo haga, detener brevemente el juego y ofrecerle un juguete apropiado para morder. Evitar juegos que lo estimulen a perseguir o morder manos y pies.",
                  "Enseñarle a hacer sus necesidades: Establecer horarios y llevarlo al lugar elegido al despertarse, después de comer y tras jugar. Premiarlo inmediatamente después de hacerlo correctamente. Limpiar los accidentes y mantener una rutina consistente.",
                  "Socializarlo de forma segura: Permitir que conozca gradualmente personas, sonidos, superficies y ambientes variados, sin obligarlo a acercarse si muestra miedo. La socialización debe ser positiva y compatible con su protección frente a enfermedades infecciosas.",
                  "Acostumbrarlo a la manipulación: Tocar suavemente sus patas, orejas y cuerpo durante unos segundos, ofreciendo premios para que asocie la experiencia con algo agradable. Esto facilita el cepillado, el corte de uñas y las revisiones veterinarias.",
                  "Enseñarle a quedarse solo poco a poco: Comenzar con ausencias muy breves y seguras, dejando juguetes apropiados y un lugar cómodo. Aumentar gradualmente el tiempo si permanece tranquilo. Si presenta angustia intensa, ladridos persistentes o intenta escapar, consultar a un profesional en comportamiento canino.",
                  "Usar refuerzo positivo: Premiar las conductas deseadas con comida, elogios o juegos. El aprendizaje mejora cuando todos los miembros de la familia utilizan las mismas señales y rutinas. El castigo físico puede generar miedo, estrés y respuestas defensivas.",
                  "Practicar sesiones cortas: Realizar varias sesiones breves durante el día en vez de una sesión muy larga. Terminar con una actividad que el cachorro pueda realizar correctamente y permitirle descansar. La paciencia y la constancia son esenciales."
                ]
              },
              {
                "titulo": "CÓMO MEJORAR EL COMPORTAMIENTO DE TU MASCOTA SI NO FUE ADIESTRADO",
                "items": [
                  "1. Si muerde objetos de la casa",
                  "Guardar zapatos, cables, ropa y objetos peligrosos fuera de su alcance.",
                  "Proporcionar juguetes seguros adecuados a su edad y tamaño.",
                  "Si empieza a morder un objeto prohibido, redirigirlo con calma hacia un juguete permitido.",
                  "No perseguirlo ni gritarle, porque puede interpretar la situación como parte de un juego.",
                  "Si ingiere un objeto, especialmente uno afilado, tóxico o que pueda obstruir el intestino, consultar inmediatamente al veterinario.",
                  "2. Si ladra excesivamente",
                  "Observar qué provoca los ladridos: ruidos, personas, otros perros, miedo, aburrimiento o necesidad de atención.",
                  "Premiar los momentos en que permanece tranquilo y enseñarle una señal para regresar a la calma.",
                  "Proporcionar ejercicio apropiado, juegos de olfato y actividades mentales.",
                  "Evitar gritarle desde lejos, ya que puede aumentar su excitación.",
                  "Si los ladridos aparecen de repente o se acompañan de dolor, desorientación o angustia intensa, buscar orientación veterinaria o profesional.",
                  "3. Si hace sus necesidades dentro de casa",
                  "Establecer horarios regulares para salir o acudir al lugar designado.",
                  "Llevarlo allí después de dormir, comer, beber y jugar.",
                  "Recompensarlo inmediatamente cuando lo haga correctamente.",
                  "Limpiar las zonas sucias con un producto apropiado para eliminar olores y evitar que vuelva al mismo sitio.",
                  "No restregarle el hocico ni castigarlo después del accidente, porque no comprenderá la relación y puede aprender a esconderse para hacerlo.",
                  "4. Si salta sobre las personas",
                  "Enseñarle a saludar con las cuatro patas en el suelo.",
                  "Premiarlo cuando se acerque con calma y pedir a las visitas que sigan la misma regla.",
                  "Evitar empujarlo o jugar con él cuando está saltando, porque puede interpretarlo como atención.",
                  "Si está muy excitado, darle unos momentos para calmarse antes de saludar.",
                  "5. Si tira de la correa",
                  "Utilizar un arnés bien ajustado y una correa apropiada.",
                  "Practicar primero en un lugar tranquilo, recompensando cuando camine cerca.",
                  "Detenerse brevemente si tira y reanudar la marcha cuando afloje la correa.",
                  "Evitar tirones fuertes, collares que causen dolor o técnicas que puedan lesionarlo.",
                  "Si reacciona con miedo o agresividad frente a otros perros, aumentar la distancia y buscar ayuda profesional.",
                  "6. Si tiene miedo de las personas o de los ruidos",
                  "No obligarlo a acercarse ni a soportar situaciones que lo asustan.",
                  "Mantener una distancia en la que pueda observar sin entrar en pánico.",
                  "Asociar los estímulos con premios y experiencias tranquilas, aumentando la dificultad poco a poco.",
                  "Proporcionarle un lugar seguro al que pueda retirarse.",
                  "Si el miedo es intenso o afecta su vida diaria, consultar a un veterinario o especialista en comportamiento.",
                  "7. Si protege la comida o sus juguetes",
                  "No quitarle los objetos por la fuerza ni castigarlo por gruñir.",
                  "Mantener a niños y otras mascotas alejados mientras come.",
                  "Practicar intercambios seguros con objetos de poco valor por premios mejores, sin acercarse de forma amenazante.",
                  "Solicitar orientación profesional si muestra rigidez corporal, gruñidos intensos o intentos de morder.",
                  "8. Si pelea con otros perros",
                  "Mantener distancia de los animales que desencadenan la reacción.",
                  "No forzar saludos ni permitir que se acerquen de frente cuando está tenso.",
                  "Utilizar una correa segura y evitar lugares concurridos hasta comprender el desencadenante.",
                  "Si ocurre una pelea, no introducir las manos entre las bocas de los animales; buscar una forma segura de separarlos y comprobar después si existen lesiones.",
                  "Consultar a un profesional que trabaje con métodos respetuosos y seguros."
                ]
              }
            ]
          },
          "vacunacion": {
            "titulo": "VACUNACIÓN",
            "secciones": [
              {
                "titulo": "TODAS LAS VACUNAS CON LAS QUE DEBERÍA CONTAR LA MASCOTA HASTA EL DÍA DE SU MUERTE",
                "items": [
                  "El calendario debe establecerlo un veterinario según la edad, el estado de salud, los antecedentes, el riesgo de exposición y las normas sanitarias vigentes en Bolivia. Un cachorro que no tiene registros fiables de vacunación debe evaluarse como un caso individual; no se debe asumir que ya está protegido.",
                  "Vacuna contra el parvovirus canino: Protege frente a una enfermedad muy contagiosa que puede causar vómitos, diarrea intensa, deshidratación y complicaciones graves, especialmente en cachorros. La vacunación comienza habitualmente entre las seis y ocho semanas, según el producto y la recomendación veterinaria, y se repite cada dos a cuatro semanas hasta que el cachorro tenga al menos 16 semanas. En situaciones de riesgo elevado, el veterinario puede recomendar completar la serie a una edad posterior.",
                  "Vacuna contra el moquillo canino o distemper: Protege frente a una infección viral que puede afectar el aparato respiratorio, digestivo y nervioso. Normalmente forma parte de una vacuna combinada. Se administra en una serie durante la etapa de cachorro, con dosis separadas por intervalos recomendados hasta al menos las 16 semanas de edad.",
                  "Vacuna contra el adenovirus canino: Contribuye a proteger frente a la hepatitis infecciosa canina y otras enfermedades relacionadas con adenovirus. Generalmente se incluye en la vacuna combinada para cachorros. Las dosis iniciales y los refuerzos se programan según el producto y la evaluación veterinaria.",
                  "Vacuna contra la parainfluenza canina: Puede formar parte de las vacunas combinadas y ayuda a reducir el riesgo de enfermedad respiratoria asociada con este agente. Su conveniencia y los refuerzos dependen de la exposición del perro, por ejemplo, si acude a guarderías, refugios o espacios donde conviven muchos perros.",
                  "Vacuna contra la leptospirosis: Protege frente a bacterias que pueden transmitirse mediante la orina de animales infectados y agua o suelo contaminados. Puede ser especialmente relevante en lugares donde hay roedores, inundaciones, agua estancada o contacto con fauna. Generalmente requiere una serie inicial de dos dosis y refuerzos periódicos, a menudo anuales, según el producto y el riesgo local. También es importante porque la leptospirosis puede afectar a las personas.",
                  "Vacuna contra la rabia: Es esencial para la salud pública y la protección del perro. La rabia es una enfermedad mortal una vez que aparecen los síntomas. La edad de la primera dosis y la frecuencia de los refuerzos deben ajustarse a las disposiciones sanitarias vigentes en Bolivia y a las indicaciones del veterinario. Debe conservarse el certificado de vacunación.",
                  "Vacuna contra la tos infecciosa canina o complejo respiratorio infeccioso: Puede recomendarse para perros que estarán en residencias, guarderías, exposiciones, refugios o lugares con contacto frecuente con muchos perros. Según el producto, puede dirigirse contra Bordetella bronchiseptica y otros agentes respiratorios. No es necesariamente indispensable para todos los perros y no elimina todos los riesgos de tos.",
                  "Vacuna contra la enfermedad de Lyme: No es una vacuna de uso rutinario para todos los perros. Solo se considera en determinadas regiones y situaciones de exposición a garrapatas y a la bacteria que causa esta enfermedad. Su necesidad debe evaluarse con el veterinario; no debe incluirse automáticamente en el calendario de un perro que vive en Bolivia.",
                  "Refuerzos durante la adultez: Las vacunas no se repiten todas con la misma frecuencia. Algunas requieren un refuerzo después de la serie inicial y otras pueden aplicarse a intervalos más largos según el producto y las normas. El veterinario debe indicar la fecha de cada refuerzo y anotarla en el carnet.",
                  "Vacunación durante la vejez: Un perro senior puede seguir necesitando protección contra enfermedades infecciosas. La edad avanzada por sí sola no significa que deban suspenderse todas las vacunas. Se debe evaluar su salud, su riesgo de exposición, su historial y las recomendaciones veterinarias para decidir cuáles corresponden y cuándo aplicarlas.",
                  "Si se desconoce su historial: No se deben aplicar varias vacunas al azar ni considerar que una dosis aislada siempre completa la protección. El veterinario puede establecer un esquema de recuperación adecuado según la edad, el estado de salud y los productos disponibles.",
                  "Medidas de protección mientras se completa el esquema: Evitar el contacto con heces de perros desconocidos, animales enfermos y espacios muy contaminados. La vacunación no sustituye la limpieza, la alimentación adecuada, el control de parásitos ni las revisiones médicas."
                ]
              }
            ]
          },
          "veterinario": {
            "titulo": "CUÁNDO IR AL VETERINARIO",
            "secciones": [
              {
                "titulo": "EN QUÉ SITUACIONES DE EMERGENCIA DEBES DE ACUDIR A UN VETERINARIO",
                "items": [
                  "Dificultad para respirar: Si respira con mucho esfuerzo, tiene las encías azuladas, se ahoga o no puede respirar normalmente, necesita atención inmediata. Los problemas respiratorios pueden empeorar rápidamente y no deben tratarse en casa.",
                  "Vómitos repetidos o diarrea intensa: En los cachorros, la pérdida de líquidos puede provocar deshidratación en poco tiempo. La presencia de sangre, debilidad, dolor o falta de apetito aumenta la urgencia. Si no ha completado las vacunas, se deben descartar enfermedades infecciosas graves.",
                  "Sospecha de intoxicación: Si ingiere veneno para roedores, productos de limpieza, medicamentos, chocolate, xilitol, uvas, pasas u otra sustancia peligrosa, se debe contactar inmediatamente con el veterinario. No se debe esperar a que aparezcan síntomas ni intentar provocar el vómito por cuenta propia.",
                  "Atropello o caída importante: Puede presentar fracturas, hemorragias o lesiones internas que no se observan desde fuera. Aunque siga caminando, necesita una evaluación urgente después de un traumatismo importante.",
                  "Sangrado abundante o herida profunda: Las mordeduras, las heridas abiertas y los cortes profundos pueden producir pérdida de sangre e infecciones. Si el sangrado no se controla con presión continua o el cachorro está débil, debe trasladarse inmediatamente.",
                  "Convulsiones, desmayo o pérdida del equilibrio: Pueden estar relacionados con intoxicaciones, enfermedades neurológicas u otros problemas graves. Se debe apartar cualquier objeto peligroso, no sujetarle la lengua ni introducir nada en la boca y acudir a urgencias.",
                  "Encías muy pálidas o amarillentas: Estos cambios pueden indicar anemia, pérdida de sangre o problemas internos importantes. Si aparecen junto con debilidad, respiración acelerada o desmayo, se requiere atención inmediata.",
                  "Abdomen muy hinchado y doloroso: Un vientre distendido, acompañado de arcadas, inquietud o debilidad, puede indicar una emergencia abdominal. No se debe presionar el abdomen ni ofrecer remedios caseros.",
                  "No puede orinar o intenta hacerlo sin conseguirlo: La incapacidad para orinar, el dolor intenso al intentarlo o la presencia de sangre en la orina requieren evaluación urgente.",
                  "Dolor intenso o incapacidad para caminar: Si llora al moverse, no apoya una pata, tiene una deformidad o no puede levantarse, no se debe forzarlo a caminar. Puede existir una lesión que necesita atención inmediata.",
                  "Reacción grave después de una picadura o vacunación: La hinchazón rápida de la cara, la dificultad respiratoria, el colapso o los vómitos repetidos pueden indicar una reacción alérgica grave. Debe acudir inmediatamente al veterinario. Una molestia leve y pasajera después de una vacuna no es lo mismo que una reacción grave, pero cualquier duda debe consultarse.",
                  "Fiebre aparente acompañada de decaimiento: Si está muy débil, no come, tiembla o presenta otros síntomas, necesita una evaluación pronta. La temperatura no se determina con seguridad tocándole la nariz; el veterinario puede medirla correctamente y buscar la causa.",
                  "Signos de deshidratación: La debilidad, la boca muy seca, los ojos hundidos o la incapacidad para retener agua pueden indicar deshidratación. En cachorros, especialmente cuando hay diarrea o vómitos, se necesita atención rápida.",
                  "Mordedura de un animal desconocido o posible exposición a la rabia: Se debe buscar atención veterinaria y orientación sanitaria sin demora. No se debe manipular saliva de un animal sospechoso con las manos desnudas y es importante informar si el cachorro tiene una vacuna antirrábica documentada.",
                  "Rechazo persistente de alimento o agua: Si un cachorro deja de comer, especialmente si es muy pequeño, está decaído o presenta vómitos o diarrea, debe evaluarse rápidamente. No conviene esperar varios días para comprobar si mejora solo.",
                  "Cualquier deterioro rápido: Si pasa de estar activo a permanecer inmóvil, se desorienta, empeora en pocas horas o presenta una combinación de síntomas, debe buscarse atención veterinaria. Es preferible consultar temprano que esperar a que el problema se vuelva grave."
                ]
              }
            ]
          }
        }
      },
      "adulto": {
        "tituloOriginal": "PERRO CRIOLLO – ADULTO (1 A 9 AÑOS APROXIMADAMENTE)",
        "temas": {
          "alimentacion": {
            "titulo": "ALIMENTACIÓN",
            "secciones": [
              {
                "titulo": "ALIMENTACIÓN SALUDABLE",
                "items": [
                  "Alimento completo para perros adultos: Debe consumir un alimento formulado para mantenimiento de perros adultos, con nutrientes equilibrados y una cantidad de energía adecuada. La fórmula ideal depende de su tamaño, actividad, estado corporal y posibles problemas de salud. No todos los perros criollos tienen las mismas necesidades.",
                  "Proteínas adecuadas: Las proteínas ayudan a conservar los músculos y mantener los tejidos. Un alimento completo de buena calidad debe aportar la cantidad necesaria para su etapa de vida. Si tiene una enfermedad renal, hepática u otra condición, el veterinario puede recomendar una fórmula específica.",
                  "Grasas en cantidades equilibradas: Las grasas proporcionan energía y ayudan a absorber determinadas vitaminas. Sin embargo, los alimentos muy grasos y las porciones excesivas pueden contribuir al aumento de peso y a problemas digestivos. La cantidad adecuada debe ajustarse a su actividad.",
                  "Agua potable disponible todo el día: Debe disponer de agua fresca incluso si pasa tiempo en un patio o jardín. En los días calurosos, durante las caminatas y después del ejercicio, es importante comprobar que tenga acceso a agua limpia y sombra.",
                  "Porciones medidas: Utilizar la guía de alimentación del producto como punto de partida y ajustar las cantidades según el peso, la condición corporal y la actividad. Si comienza a engordar o adelgazar sin explicación, se debe revisar su ración y consultar al veterinario.",
                  "Horarios regulares: Muchos perros adultos pueden alimentarse una o dos veces al día, según su rutina, estado de salud y recomendación profesional. Mantener horarios constantes ayuda a controlar la cantidad que consume y facilita observar cambios en su apetito.",
                  "Alimentos caseros correctamente formulados: Una dieta casera puede ser apropiada si está formulada por un veterinario especializado en nutrición para que sea completa y equilibrada. No basta con mezclar carne, arroz, verduras y caldo, porque pueden faltar minerales, vitaminas y otros nutrientes esenciales.",
                  "Premios en cantidades pequeñas: Los premios pueden servir para reforzar el buen comportamiento, pero deben contabilizarse dentro de su consumo diario. Elegir opciones seguras para perros y evitar que familiares o visitas le den comida constantemente.",
                  "Frutas y verduras aptas para perros: Algunos perros pueden consumir pequeñas porciones de zanahoria, pepino o manzana sin semillas ni corazón, siempre que las toleren y no exista una contraindicación médica. Deben lavarse y cortarse en trozos apropiados para evitar atragantamientos. No todas las frutas y verduras son seguras.",
                  "Cambios de dieta supervisados: Si se necesita cambiar de alimento, realizar una transición gradual durante varios días, siempre que el perro esté sano y tolere el cambio. Si presenta vómitos, diarrea persistente o pérdida de peso, no conviene seguir cambiando de comida sin averiguar la causa."
                ]
              },
              {
                "titulo": "ALIMENTACIÓN NO SALUDABLE",
                "items": [
                  "Sobras de comida con mucha grasa: La piel de pollo muy grasosa, las frituras, los embutidos y los restos aceitosos pueden causar molestias digestivas y favorecer el aumento de peso. Las comidas muy grasas también pueden desencadenar pancreatitis en algunos perros.",
                  "Chocolate y cacao: Son tóxicos para los perros y pueden afectar el sistema nervioso y el corazón. El riesgo depende del tipo y la cantidad consumida. Si lo ingiere, contactar inmediatamente con un veterinario y no esperar a que aparezcan síntomas.",
                  "Uvas y pasas: Pueden provocar daño renal grave. No deben utilizarse como premio ni mezclarse con alimentos caseros. Ante una ingestión, se debe buscar orientación veterinaria urgente.",
                  "Cebolla y ajo: Pueden dañar los glóbulos rojos y provocar anemia. No se deben ofrecer deliberadamente, ni siquiera como ingredientes habituales de una preparación casera.",
                  "Huesos cocidos y objetos duros: Los huesos cocidos pueden astillarse y causar lesiones u obstrucciones. Los objetos excesivamente duros también pueden fracturar dientes. Es mejor ofrecer juguetes y mordedores diseñados para perros y de tamaño adecuado.",
                  "Alimentos muy salados o condimentados: Los embutidos, las sopas muy saladas, los alimentos con salsas y ciertos platos preparados no son apropiados como dieta habitual. Pueden aportar demasiada sal, grasa y otros ingredientes perjudiciales.",
                  "Alcohol y bebidas con cafeína: El alcohol puede causar intoxicación y las bebidas con cafeína pueden alterar el sistema cardiovascular y nervioso. Nunca deben dejarse vasos o recipientes al alcance del perro.",
                  "Productos con xilitol: Algunos chicles, caramelos, productos sin azúcar y preparaciones comerciales contienen este edulcorante, que puede causar una caída peligrosa de la glucosa y daño hepático. Ante una posible ingestión, acudir de inmediato al veterinario.",
                  "Exceso de comida y dieta desequilibrada: Dar porciones demasiado grandes, muchos premios o una dieta compuesta solo por carne y arroz puede producir obesidad o deficiencias nutricionales. Mantener un peso saludable ayuda a proteger las articulaciones, el corazón y la movilidad."
                ]
              }
            ]
          },
          "salud": {
            "titulo": "SALUD",
            "secciones": [
              {
                "titulo": "TIENE BUENA SALUD",
                "items": [
                  "Mantiene una actividad normal: Camina, juega y explora de acuerdo con su edad y condición física. Puede descansar después de ejercitarse, pero no debería presentar debilidad persistente ni agotarse de manera inusual con actividades que antes toleraba.",
                  "Conserva un peso adecuado: Se puede palpar suavemente la zona de las costillas sin que estén cubiertas por una capa excesiva de grasa. Visto desde arriba, normalmente presenta una cintura perceptible, y de lado el abdomen puede elevarse ligeramente detrás de las costillas. El aspecto varía según su estructura corporal.",
                  "Tiene apetito y sed relativamente constantes: Come con regularidad y mantiene hábitos de consumo de agua similares a los habituales. Un cambio marcado o persistente puede indicar problemas dentales, digestivos, hormonales o de otro tipo.",
                  "Tiene ojos limpios y buena respuesta visual: Los ojos no presentan secreción abundante, dolor, hinchazón ni opacidad nueva. Responde a los movimientos y se orienta normalmente en su entorno.",
                  "Presenta una piel y un pelaje saludables: No tiene picazón constante, heridas que no cicatrizan, calvas extensas ni lesiones recurrentes. La cantidad de muda depende del tipo de pelaje, la época y el ambiente.",
                  "Tiene una boca en buenas condiciones: Las encías suelen ser rosadas, el aliento no presenta un olor extremadamente desagradable y puede masticar sin dolor. La ausencia de síntomas no descarta enfermedad dental, por lo que las revisiones siguen siendo importantes.",
                  "Orina y defeca con normalidad: No muestra esfuerzo excesivo, dolor ni cambios persistentes en la frecuencia. Las heces suelen mantener una consistencia relativamente estable, aunque pueden variar por la dieta.",
                  "Mantiene un comportamiento habitual: Se relaciona con las personas, descansa, juega y responde a su entorno de manera acorde con su personalidad. Los cambios repentinos de carácter pueden ser una señal temprana de dolor o enfermedad."
                ]
              },
              {
                "titulo": "TIENE MALA SALUD",
                "items": [
                  "Aumento o pérdida de peso inexplicable: Puede relacionarse con cambios de alimentación, parásitos, problemas hormonales u otras enfermedades. Si el cambio es rápido o persiste a pesar de mantener una rutina estable, necesita revisión veterinaria.",
                  "Tos, jadeo excesivo o dificultad respiratoria: La tos persistente, el jadeo excesivo en reposo o la respiración trabajosa pueden indicar problemas respiratorios, cardíacos, dolor o sobrecalentamiento. La dificultad respiratoria es una emergencia.",
                  "Problemas dentales: El mal aliento intenso, las encías inflamadas, el sarro abundante, el babeo o la dificultad para masticar pueden indicar enfermedad dental. No debe esperarse a que deje de comer para buscar atención.",
                  "Vómitos o diarrea persistentes: Pueden deberse a cambios de dieta, parásitos, infecciones, intoxicaciones u otras causas. Si se acompañan de sangre, dolor, debilidad o deshidratación, necesita atención urgente.",
                  "Picazón y lesiones en la piel: El rascado constante, el lamido de las patas, el enrojecimiento, las costras y la pérdida de pelo pueden relacionarse con pulgas, garrapatas, alergias, hongos u otras enfermedades. El tratamiento depende de la causa.",
                  "Cambios en la orina: La sangre, el esfuerzo al orinar, el aumento marcado de la sed o la producción de orina pueden señalar problemas urinarios, renales, metabólicos u otros. Si no puede orinar, necesita atención inmediata.",
                  "Dolor al caminar o rigidez: Cojera, dificultad para levantarse, rechazo a subir escalones o dolor al tocar una zona pueden indicar lesiones articulares, musculares o de otro tipo. No debe obligarse a hacer ejercicio para comprobar si mejora.",
                  "Decaimiento o cambios de comportamiento: Un perro que se aísla, deja de jugar, gruñe cuando lo tocan o duerme mucho más de lo habitual puede sentir dolor o estar enfermo. No se debe interpretar automáticamente como desobediencia o mal carácter.",
                  "Bultos o heridas que cambian: Cualquier bulto nuevo, herida que no cicatriza, crecimiento que aumenta de tamaño o lesión que sangra debe revisarse. No todos los bultos son cancerosos, pero no es posible determinar su naturaleza únicamente por la apariencia."
                ]
              }
            ]
          },
          "primeros": {
            "titulo": "PRIMEROS AUXILIOS",
            "secciones": [
              {
                "titulo": "QUÉ HACER CUANDO LE SUCEDEN ACCIDENTES COMO:",
                "items": [
                  "1. Caídas, atropellos y golpes fuertes",
                  "Alejarlo del peligro y evitar que corra o camine innecesariamente.",
                  "Comprobar desde una distancia segura si está consciente y respira normalmente.",
                  "Si hay sospecha de lesión en la columna o pelvis, moverlo lo mínimo posible y utilizar una superficie firme para transportarlo.",
                  "Aplicar presión con una gasa limpia sobre una hemorragia externa si se puede hacer de forma segura.",
                  "No intentar enderezar una pata, manipular articulaciones ni administrar analgésicos humanos.",
                  "Acudir a urgencias después de un atropello o traumatismo importante, incluso si no se observan heridas externas.",
                  "2. Heridas, cortes y sangrado",
                  "Evitar que lama la lesión y mantenerlo lo más tranquilo posible.",
                  "Aplicar presión continua con una gasa o tela limpia sobre el sangrado.",
                  "No retirar objetos incrustados ni utilizar alcohol, polvos, ceniza o sustancias irritantes.",
                  "Las heridas profundas, mordeduras, cortes extensos o hemorragias persistentes necesitan atención veterinaria inmediata.",
                  "No cerrar una herida con pegamento, cinta adhesiva ni productos domésticos.",
                  "Seguir las indicaciones del veterinario para la limpieza y los cuidados posteriores.",
                  "3. Atragantamiento",
                  "Si todavía puede toser y respirar, permitirle toser mientras se busca orientación veterinaria.",
                  "Si no puede respirar, se desploma o sus encías se vuelven azuladas, se trata de una emergencia.",
                  "Retirar un objeto de la boca únicamente si es claramente visible y puede alcanzarse sin empujarlo más profundamente.",
                  "No introducir los dedos a ciegas ni ofrecer pan, agua, aceite u otros alimentos para intentar desplazarlo.",
                  "Organizar el traslado urgente y seguir las instrucciones del servicio veterinario.",
                  "4. Intoxicación por alimentos, productos químicos o medicamentos",
                  "Retirar la sustancia y evitar una nueva exposición.",
                  "Guardar el envase o fotografiar la etiqueta para identificar el producto.",
                  "Contactar inmediatamente con el veterinario, indicando qué sustancia pudo ingerir, cuánto y cuándo, si se sabe.",
                  "No provocar el vómito ni administrar leche, aceite, sal, carbón activado o medicamentos por cuenta propia.",
                  "Si presenta convulsiones, desmayo o dificultad respiratoria, trasladarlo a urgencias sin demora.",
                  "5. Quemaduras",
                  "Alejarlo de la fuente de calor o del producto químico.",
                  "Para una quemadura térmica pequeña, enfriar la zona con agua corriente fresca durante unos 20 minutos, si es posible sin retrasar la atención.",
                  "No aplicar hielo, mantequilla, pasta dental ni cremas humanas.",
                  "Cubrir la lesión de forma ligera con un material limpio que no se adhiera y acudir al veterinario.",
                  "Las quemaduras extensas o las que afectan cara, ojos, patas o genitales requieren atención urgente.",
                  "6. Picaduras de insectos y mordeduras",
                  "Alejarlo del animal o insecto y observar si desarrolla hinchazón rápida, debilidad o dificultad respiratoria.",
                  "Si la respiración se altera o la cara se hincha rápidamente, acudir de inmediato a urgencias.",
                  "No administrar antihistamínicos ni otros medicamentos humanos sin orientación veterinaria.",
                  "Las mordeduras pueden causar infecciones profundas incluso cuando la herida exterior parece pequeña.",
                  "Si el animal agresor es desconocido o puede tener rabia, solicitar orientación veterinaria y sanitaria.",
                  "7. Vómitos y diarrea",
                  "Observar la frecuencia y si hay sangre, dolor, debilidad o cambios en el consumo de agua.",
                  "No dar antidiarreicos, antibióticos ni analgésicos humanos.",
                  "Si está alerta y no vomita repetidamente, se puede ofrecer agua en pequeñas cantidades mientras se busca orientación.",
                  "No mantenerlo en ayuno prolongado sin indicación veterinaria.",
                  "Buscar atención urgente ante sangre, dolor abdominal intenso, vómitos repetidos, deshidratación o incapacidad para retener agua.",
                  "8. Golpe de calor",
                  "Llevarlo inmediatamente a un lugar fresco y ventilado.",
                  "Mojar suavemente el cuerpo con agua fresca, no helada, y utilizar ventilación.",
                  "No cubrirlo con toallas mojadas que acumulen calor ni obligarlo a beber si está desorientado.",
                  "Acudir urgentemente al veterinario si jadea de manera extrema, vomita, camina tambaleándose o se desploma.",
                  "No esperar a que se recupere por sí solo, porque el golpe de calor puede afectar órganos internos incluso después de que parezca enfriarse."
                ]
              }
            ]
          },
          "cuidados": {
            "titulo": "CUIDADOS",
            "secciones": [
              {
                "titulo": "CÓMO MANTENERLO BIEN CUIDADO",
                "items": [
                  "Mantener una alimentación equilibrada: Elegir un alimento completo apropiado para perros adultos y ajustar la ración según su tamaño, actividad y condición corporal. Evitar que las sobras y los premios reemplacen una parte importante de su dieta.",
                  "Garantizar agua limpia y sombra: El agua debe estar disponible durante todo el día y el perro debe contar con un lugar fresco y ventilado para descansar. En climas cálidos, no dejarlo encerrado en un vehículo ni expuesto al sol sin protección.",
                  "Proporcionar ejercicio regular: La actividad puede incluir caminatas, juegos de búsqueda, exploración y actividades de olfato. La intensidad debe ajustarse a su edad, tamaño, condición física y salud. Un perro que vive en un patio también necesita interacción y actividades.",
                  "Mantener un peso saludable: Revisar periódicamente su silueta y palpar las costillas con suavidad. Si aumenta de peso, ajustar la ración y los premios con ayuda veterinaria. El exceso de peso puede agravar los problemas articulares y reducir su resistencia física.",
                  "Realizar revisiones veterinarias preventivas: Un perro adulto aparentemente sano también necesita controles periódicos. La frecuencia depende de sus antecedentes y factores de riesgo. Durante las revisiones se pueden evaluar dientes, piel, peso, articulaciones, vacunas y prevención de parásitos.",
                  "Mantener al día las vacunas: Conservar el carnet de vacunación y seguir las fechas de refuerzo indicadas. La vacuna antirrábica debe cumplir las disposiciones sanitarias vigentes en Bolivia. El calendario se individualiza según el producto, la salud y el riesgo de exposición.",
                  "Controlar pulgas, garrapatas y otros parásitos: Utilizar productos veterinarios adecuados para su peso, edad y condición de salud. No combinar productos sin orientación ni aplicar productos para ganado o insecticidas domésticos sobre el perro.",
                  "Cuidar su higiene dental: Cepillar los dientes con productos formulados para perros y revisar periódicamente las encías. Si tiene sarro abundante, dolor o mal aliento intenso, necesita una evaluación profesional. No intentar retirar el sarro con objetos cortantes.",
                  "Cepillar el pelaje: La frecuencia depende de la longitud y densidad del pelo. El cepillado permite retirar pelo muerto y detectar lesiones, parásitos o bultos. Si tiene pelo largo, revisar las zonas donde pueden formarse nudos.",
                  "Bañarlo cuando sea necesario: Utilizar champú para perros y enjuagar bien. Evitar baños excesivamente frecuentes si resecan o irritan su piel. Secarlo correctamente, sobre todo en épocas frías o si tiene un pelaje denso.",
                  "Revisar uñas, orejas y patas: Observar si hay uñas demasiado largas, heridas, cuerpos extraños, mal olor o secreciones en las orejas. Si no se sabe cortar las uñas con seguridad, pedir una demostración al veterinario o a un profesional de peluquería canina.",
                  "Protegerlo de accidentes: Mantenerlo bajo supervisión en espacios abiertos y utilizar una correa segura cerca de calles. Un perro criollo puede explorar o perseguir animales por instinto, por lo que no debe asumirse que conoce todos los peligros del entorno.",
                  "Ofrecer estimulación mental: Utilizar juegos de olfato, juguetes adecuados, búsqueda de premios y ejercicios de obediencia. Estas actividades ayudan a reducir el aburrimiento y pueden mejorar el vínculo con la familia.",
                  "Brindar compañía y descanso: Los perros necesitan interacción diaria y un lugar tranquilo para dormir. No deben permanecer atados permanentemente ni aislados de las personas durante largos períodos.",
                  "Observar cambios en su salud: Registrar variaciones de peso, apetito, sed, orina, heces, energía y comportamiento. Los cambios persistentes pueden ser señales tempranas de enfermedad y deben comentarse con el veterinario."
                ]
              },
              {
                "titulo": "CÓMO SABER SI NO TIENE UN BUEN CUIDADO",
                "items": [
                  "1. Alimentación insuficiente o inadecuada",
                  "Está demasiado delgado o presenta sobrepeso.",
                  "Recibe solamente sobras o alimentos que no cubren sus necesidades nutricionales.",
                  "No dispone de agua limpia de forma constante.",
                  "Su alimentación cambia continuamente sin una razón clara y presenta molestias digestivas repetidas.",
                  "2. Falta de higiene",
                  "El pelaje está enredado, sucio o presenta lesiones sin tratar.",
                  "Tiene mal olor persistente, problemas dentales visibles o secreción anormal en los oídos.",
                  "Las uñas están tan largas que dificultan la marcha.",
                  "Su espacio de descanso está lleno de suciedad, humedad o excrementos.",
                  "3. Falta de atención veterinaria",
                  "Tiene vacunas atrasadas o no existe ningún registro de ellas.",
                  "Presenta parásitos visibles o picazón persistente sin tratamiento.",
                  "Se dejan sin revisar bultos, heridas, cojeras o cambios de comportamiento.",
                  "Recibe medicamentos humanos sin indicación profesional.",
                  "4. Falta de protección y ejercicio",
                  "Permanece expuesto continuamente al sol, al frío o a la lluvia.",
                  "Está atado durante largos períodos sin posibilidad de moverse cómodamente.",
                  "No tiene actividad, paseos ni oportunidades para explorar de manera segura.",
                  "Puede escapar a la calle y exponerse a atropellos, peleas o intoxicaciones.",
                  "5. Maltrato o aislamiento",
                  "Se le golpea, intimida o castiga físicamente.",
                  "No recibe interacción positiva ni atención diaria.",
                  "Presenta miedo persistente hacia las personas que lo cuidan.",
                  "Tiene heridas, pérdida de pelo o cambios de conducta relacionados con estrés, dolor o negligencia."
                ]
              }
            ]
          },
          "comportamiento": {
            "titulo": "COMPORTAMIENTO",
            "secciones": [
              {
                "titulo": "ADIESTRAMIENTO Y MANTENIMIENTO DEL BUEN COMPORTAMIENTO EN LA EDAD ADULTA",
                "items": [
                  "Reforzar las órdenes básicas: Practicar “ven”, “siéntate”, “espera” y “quieto” en sesiones cortas. Recompensar las respuestas correctas y practicar en diferentes ambientes de manera gradual.",
                  "Mantener una rutina consistente: Establecer horarios razonablemente regulares para las comidas, los paseos, el juego y el descanso. La previsibilidad puede reducir la frustración y facilitar la convivencia.",
                  "Caminar con correa sin tirar: Premiar cuando camine cerca de la persona y detenerse brevemente cuando la correa se tense. Evitar los tirones violentos y elegir un equipo adecuado a su tamaño y fuerza.",
                  "Enseñarle a saludar tranquilamente: Pedirle que mantenga las patas en el suelo antes de recibir atención. Recompensar la calma y coordinar con las visitas para que no refuercen los saltos.",
                  "Prevenir la persecución peligrosa: Practicar la llamada en espacios seguros y utilizar correa en lugares donde pueda perseguir vehículos, ganado, aves u otros animales. No asumir que obedecerá en todas las situaciones sin entrenamiento.",
                  "Proporcionar actividades mentales: Incorporar búsquedas de premios, juguetes interactivos seguros y ejercicios de olfato. Las actividades deben ser adecuadas para su tamaño y no incluir objetos que pueda tragar.",
                  "Enseñarle a quedarse solo: Si necesita permanecer solo durante un tiempo, acostumbrarlo gradualmente y dejarlo en un ambiente seguro. Si presenta angustia intensa, destrucción persistente o intentos de escape, solicitar ayuda profesional.",
                  "Practicar el intercambio de objetos: Enseñarle a entregar un juguete a cambio de un premio, sin perseguirlo ni quitarle las cosas por la fuerza. Esto facilita recuperar objetos de forma segura.",
                  "Favorecer una convivencia segura con otros perros: Realizar encuentros graduales con perros compatibles y en ambientes controlados. No forzar la interacción y separar con seguridad a los animales si aparece tensión creciente.",
                  "Recompensar la tranquilidad: Premiar cuando descansa en su cama, espera sin ladrar o responde con calma ante un estímulo. El aprendizaje debe centrarse en enseñar lo que se espera de él, no solo en corregir errores.",
                  "No utilizar el castigo físico: Los golpes, gritos y collares que provocan dolor pueden aumentar el miedo y las respuestas defensivas. Las técnicas de refuerzo positivo favorecen el aprendizaje y la confianza.",
                  "Consultar cuando el comportamiento cambia: Si un perro que era tranquilo comienza a gruñir, evitar el contacto o reaccionar de manera inusual, se debe descartar dolor o enfermedad antes de atribuirlo a un problema de obediencia."
                ]
              },
              {
                "titulo": "CÓMO MEJORAR EL COMPORTAMIENTO DE TU MASCOTA SI NO FUE ADIESTRADO",
                "items": [
                  "1. Si destruye objetos",
                  "Guardar los objetos peligrosos y ofrecer juguetes resistentes apropiados para su tamaño.",
                  "Aumentar las oportunidades de ejercicio y actividades de olfato según su condición física.",
                  "Redirigirlo hacia un juguete permitido y premiarlo cuando lo utilice.",
                  "Evitar castigos después de encontrar un objeto destruido, porque no asociará correctamente el castigo con la conducta pasada.",
                  "Si la destrucción aparece principalmente cuando se queda solo, evaluar si existe angustia por separación.",
                  "2. Si ladra constantemente",
                  "Identificar si ladra por miedo, alerta, aburrimiento, frustración o búsqueda de atención.",
                  "Reducir la exposición a los estímulos que desencadenan los ladridos mientras se enseña una respuesta más tranquila.",
                  "Premiar los períodos de silencio y proporcionar actividad física y mental adecuada.",
                  "Evitar gritarle o recurrir a dispositivos que le causen dolor.",
                  "Consultar si los ladridos comienzan repentinamente o se acompañan de otros cambios de salud.",
                  "3. Si tira de la correa",
                  "Practicar primero en un lugar con pocas distracciones.",
                  "Premiar cada vez que camine con la correa floja.",
                  "Detenerse si tira y continuar cuando afloje la tensión.",
                  "Aumentar gradualmente la dificultad de los paseos.",
                  "Si intenta atacar a otros perros o personas, no acercarlo a los desencadenantes y solicitar ayuda profesional.",
                  "4. Si muestra miedo o agresividad",
                  "No castigarlo por gruñir ni intentar dominarlo físicamente.",
                  "Mantener una distancia segura y evitar las situaciones que lo ponen en riesgo de reaccionar.",
                  "Utilizar premios para crear asociaciones positivas de manera gradual, sin obligarlo a acercarse.",
                  "Consultar primero con un veterinario para descartar dolor o enfermedad.",
                  "Si ha intentado morder o representa un peligro, trabajar con un profesional cualificado en comportamiento canino.",
                  "5. Si protege comida, cama u objetos",
                  "Evitar quitarle objetos por la fuerza.",
                  "Alimentarlo en un espacio tranquilo, sin que niños u otros animales lo molesten.",
                  "Practicar intercambios con recompensas de mayor valor únicamente cuando sea seguro.",
                  "Solicitar orientación especializada si hay gruñidos intensos, embestidas o mordeduras.",
                  "6. Si no obedece cuando lo llaman",
                  "Practicar la llamada en casa y en un lugar cerrado con pocas distracciones.",
                  "Utilizar siempre una señal clara y premiar de forma generosa cuando se acerque.",
                  "No llamarlo únicamente para terminar actividades agradables o regañarlo.",
                  "Usar una correa larga de entrenamiento en espacios adecuados y seguros, bajo supervisión.",
                  "No dejarlo suelto cerca de carreteras mientras la llamada no sea fiable."
                ]
              }
            ]
          },
          "vacunacion": {
            "titulo": "VACUNACIÓN",
            "secciones": [
              {
                "titulo": "TODAS LAS VACUNAS CON LAS QUE DEBERÍA CONTAR LA MASCOTA HASTA EL DÍA DE SU MUERTE",
                "items": [
                  "Vacuna contra el moquillo canino: Si completó correctamente la serie de cachorro, necesita refuerzos según las recomendaciones del producto y del veterinario. La frecuencia no debe decidirse solamente por la edad; también se consideran su historial y su riesgo de exposición.",
                  "Vacuna contra el parvovirus canino: Es importante mantener la protección frente a esta enfermedad, que puede ser grave. Después de la serie inicial y del refuerzo recomendado tras la etapa de cachorro, los refuerzos posteriores se programan según las guías veterinarias y la vacuna utilizada.",
                  "Vacuna contra el adenovirus canino: Suele formar parte de la vacuna combinada que también protege frente a otras enfermedades. Los refuerzos pueden espaciarse de acuerdo con el producto y las recomendaciones veterinarias.",
                  "Vacuna contra la parainfluenza canina: Puede recomendarse si el perro frecuenta espacios con muchos animales o tiene una exposición respiratoria elevada. No todos los perros adultos necesitan exactamente el mismo esquema.",
                  "Vacuna contra la leptospirosis: Puede ser importante si vive en zonas con roedores, agua estancada, inundaciones o contacto con animales potencialmente infectados. A menudo requiere refuerzos anuales, pero el intervalo exacto depende del producto y del criterio veterinario.",
                  "Vacuna contra la rabia: Debe mantenerse al día conforme a las disposiciones sanitarias vigentes en Bolivia y al calendario indicado por el veterinario. Guardar el certificado de cada aplicación es importante para demostrar su estado de vacunación.",
                  "Vacuna contra la tos infecciosa canina: Puede considerarse para perros que acuden a guarderías, residencias, exposiciones o lugares donde se reúnen muchos perros. La necesidad y los refuerzos dependen del riesgo de exposición.",
                  "Vacunas adicionales según riesgo: Otras vacunas pueden tener utilidad en regiones o situaciones específicas, pero no deben aplicarse automáticamente a todos los perros criollos. El veterinario debe explicar el riesgo local y el beneficio esperado.",
                  "Si tiene vacunas atrasadas: Solicitar una revisión del carnet y establecer un plan para recuperar la protección. No se debe asumir que todas las vacunas requieren una dosis anual ni que una dosis aislada siempre basta para completar una serie.",
                  "Durante toda la vida adulta: Conservar el carnet, anotar las fechas y acudir a las revisiones preventivas. Las vacunas son una parte de la prevención y no sustituyen el control de parásitos, la higiene ni la atención médica."
                ]
              }
            ]
          },
          "veterinario": {
            "titulo": "CUÁNDO IR AL VETERINARIO",
            "secciones": [
              {
                "titulo": "EN QUÉ SITUACIONES DE EMERGENCIA DEBES DE ACUDIR A UN VETERINARIO",
                "items": [
                  "Dificultad para respirar: La respiración trabajosa, las encías azuladas, el ahogo o el colapso requieren atención inmediata.",
                  "Vómitos repetidos o diarrea con sangre: Pueden provocar deshidratación o indicar una infección, intoxicación u otra enfermedad importante. Si hay debilidad o dolor, no se debe esperar.",
                  "Sospecha de intoxicación: Ante la ingestión de venenos, medicamentos, chocolate, uvas, pasas, xilitol o productos químicos, contactar inmediatamente con un veterinario. No provocar el vómito sin indicación profesional.",
                  "Accidente de tránsito o golpe fuerte: Puede haber lesiones internas aunque el perro no presente una herida visible. Debe evaluarse urgentemente.",
                  "Hemorragia o herida profunda: Aplicar presión suave con una gasa limpia mientras se busca atención. Las heridas profundas y mordeduras necesitan revisión por el riesgo de lesiones e infección.",
                  "Convulsiones o pérdida del conocimiento: Protegerlo de los objetos cercanos, no introducir nada en su boca y trasladarlo a urgencias.",
                  "Abdomen hinchado con arcadas: Puede indicar una emergencia abdominal, incluida una dilatación gástrica potencialmente mortal. No esperar a que el abdomen disminuya por sí solo.",
                  "Incapacidad para orinar: Si intenta orinar repetidamente sin conseguirlo, necesita atención inmediata, ya que una obstrucción urinaria puede ser mortal.",
                  "Dolor intenso o incapacidad para caminar: Una cojera súbita, una pata deformada, un dolor intenso o la imposibilidad de levantarse requieren evaluación rápida.",
                  "Golpe de calor: Jadeo extremo, desorientación, vómitos, debilidad o colapso después de exponerse al calor requieren enfriamiento inicial seguro y traslado veterinario urgente.",
                  "Encías pálidas o amarillas: Pueden indicar anemia, pérdida de sangre o enfermedad interna. Si se acompañan de debilidad o respiración rápida, es una emergencia.",
                  "Reacción alérgica grave: La hinchazón rápida de la cara, la dificultad respiratoria o el colapso después de una picadura, alimento o medicamento requieren atención inmediata.",
                  "Cambios repentinos de conducta acompañados de dolor: Un perro que se vuelve muy irritable, se esconde, llora o no permite que lo toquen puede estar lesionado o enfermo. Debe evaluarse antes de intentar corregir su conducta.",
                  "Bultos que crecen rápidamente o heridas que no cicatrizan: No todos los bultos son peligrosos, pero los cambios rápidos, el sangrado y las lesiones persistentes requieren una consulta veterinaria.",
                  "Pérdida persistente del apetito o cambios marcados de sed: Si deja de comer, bebe mucho más de lo habitual o pierde peso sin explicación, necesita una revisión. Si además está débil, vomita o no puede beber, la atención es más urgente.",
                  "Exposición posible a la rabia: Una mordedura o contacto con saliva de un animal sospechoso requiere atención veterinaria y orientación sanitaria inmediata, aunque el perro parezca estar sano."
                ]
              }
            ]
          }
        }
      },
      "senior": {
        "tituloOriginal": "PERRO CRIOLLO – SENIOR O GERIÁTRICO (10 AÑOS EN ADELANTE, APROXIMADAMENTE)",
        "temas": {
          "alimentacion": {
            "titulo": "ALIMENTACIÓN",
            "secciones": [
              {
                "titulo": "ALIMENTACIÓN SALUDABLE",
                "items": [
                  "Alimento completo adecuado para perros mayores: Puede beneficiarse de una fórmula para perros senior si se adapta a su estado de salud y condición corporal. Algunos perros mayores necesitan menos energía, mientras que otros requieren una dieta distinta por enfermedades o pérdida de masa muscular. La etiqueta “senior” no garantiza que el alimento sea apropiado para todos.",
                  "Proteínas de buena calidad: Los perros mayores necesitan proteínas suficientes para conservar sus músculos. No se debe reducir drásticamente la proteína solo porque ha envejecido; si tiene una enfermedad renal u otra condición, el veterinario debe recomendar la cantidad y el tipo de alimento adecuados.",
                  "Control de las calorías: Si hace menos ejercicio, puede necesitar una ración más pequeña para evitar el sobrepeso. Sin embargo, si pierde peso o músculo, reducir aún más la comida puede empeorar su estado. Los ajustes deben basarse en su peso, condición corporal y evaluación clínica.",
                  "Agua limpia y accesible: Debe disponer de agua fresca durante todo el día. Si tiene dificultad para levantarse o caminar, colocar recipientes en varios lugares de fácil acceso. Un aumento marcado de la sed puede ser señal de enfermedad y no debe atribuirse automáticamente a la edad.",
                  "Comidas en porciones manejables: Dividir la ración diaria en dos o más comidas puede ayudar a los perros con menor apetito o que se cansan al comer. Si presenta náuseas, vómitos o dificultad para tragar, se debe buscar atención veterinaria.",
                  "Alimento de textura adecuada: Si le faltan dientes o tiene sensibilidad oral, una comida húmeda completa o croquetas humedecidas pueden facilitar la alimentación. Antes de asumir que necesita comida blanda, conviene revisar si hay dolor dental u otro problema tratable.",
                  "Nutrientes adaptados a sus enfermedades: Algunos perros mayores necesitan dietas específicas para enfermedades renales, cardíacas, digestivas o metabólicas. No se deben elegir dietas terapéuticas ni suplementos sin una evaluación veterinaria.",
                  "Premios pequeños y seguros: Puede seguir recibiendo premios, pero en cantidades moderadas. Los premios muy duros pueden dañar dientes sensibles y los alimentos muy grasos pueden causar molestias digestivas. Se pueden utilizar pequeñas porciones de su alimento habitual como recompensa.",
                  "Cambio de dieta gradual: Introducir los cambios progresivamente, observando el apetito, las heces y la tolerancia. Si pierde peso, vomita o deja de comer, se debe investigar la causa en vez de probar diferentes alimentos continuamente.",
                  "Seguimiento del peso y el apetito: Registrar el peso con regularidad y observar si pierde músculo, deja comida o bebe más agua. En los perros mayores, los cambios sutiles pueden ser una señal temprana de enfermedad y merecen atención."
                ]
              },
              {
                "titulo": "ALIMENTACIÓN NO SALUDABLE",
                "items": [
                  "Exceso de calorías: Las porciones grandes, las sobras frecuentes y los premios constantes pueden provocar sobrepeso. El exceso de peso aumenta la carga sobre las articulaciones y puede dificultar la movilidad.",
                  "Alimentos muy grasos: Las frituras, la piel de pollo muy grasosa y los restos aceitosos pueden causar problemas digestivos y contribuir al aumento de peso. Algunos perros pueden desarrollar pancreatitis después de ingerir comidas muy grasas.",
                  "Chocolate y cacao: Pueden provocar intoxicación y afectar el sistema nervioso y el corazón. Si lo ingiere, contactar de inmediato con el veterinario.",
                  "Uvas y pasas: Pueden ocasionar daño renal grave. No deben ofrecerse como premios y cualquier ingestión debe consultarse urgentemente.",
                  "Cebolla, ajo y productos con xilitol: La cebolla y el ajo pueden dañar los glóbulos rojos, mientras que el xilitol puede causar una bajada peligrosa de la glucosa y daño hepático. No deben utilizarse en la dieta del perro.",
                  "Huesos cocidos y alimentos duros: Pueden causar fracturas dentales, atragantamiento u obstrucciones. Si el perro tiene enfermedad dental, puede necesitar opciones de textura más suave, pero estas deben ser nutricionalmente adecuadas.",
                  "Alimentos en mal estado: La comida podrida, contaminada o conservada incorrectamente puede causar intoxicaciones. No ofrecer sobras que hayan pasado mucho tiempo expuestas al calor.",
                  "Dietas caseras incompletas: Una alimentación basada únicamente en carne, arroz, pan, sopa o verduras no garantiza los nutrientes necesarios. Si se desea ofrecer una dieta casera, debe formularla un profesional de nutrición veterinaria.",
                  "Suplementos y medicamentos por cuenta propia: El calcio, las vitaminas, los productos para articulaciones y los medicamentos humanos no son automáticamente seguros para un perro mayor. Algunos pueden interactuar con sus tratamientos o agravar enfermedades existentes."
                ]
              }
            ]
          },
          "salud": {
            "titulo": "SALUD",
            "secciones": [
              {
                "titulo": "TIENE BUENA SALUD",
                "items": [
                  "Mantiene interés por su entorno: Aunque pueda dormir más y jugar durante menos tiempo que antes, sigue respondiendo a la familia, disfruta de actividades suaves y muestra curiosidad por su ambiente.",
                  "Conserva un peso relativamente estable: No presenta pérdida rápida de peso ni aumento excesivo. Es importante observar también la musculatura, porque algunos perros pueden perder músculo aunque su peso total cambie poco.",
                  "Come y bebe de manera habitual: Mantiene un apetito razonable y no presenta dificultades para masticar o tragar. Los cambios persistentes en la sed o el apetito deben investigarse.",
                  "Puede levantarse y desplazarse con comodidad razonable: Puede necesitar más tiempo para incorporarse, pero no debería mostrar dolor intenso, caídas frecuentes ni una pérdida repentina de movilidad.",
                  "Tiene respiración cómoda en reposo: No presenta dificultad respiratoria, tos persistente ni desmayos. El jadeo excesivo sin ejercicio o en un ambiente fresco merece atención.",
                  "Mantiene piel y pelaje en condiciones aceptables: El pelaje puede cambiar con la edad, pero no debería presentar heridas persistentes, picazón intensa ni pérdida de pelo inexplicable.",
                  "Orina y defeca sin dolor: No presenta sangre, esfuerzo marcado ni accidentes repentinos que antes no ocurrían. Si empieza a orinar más, beber mucho o perder el control de esfínteres, conviene realizar una revisión.",
                  "Conserva una conducta reconocible: Puede volverse más tranquilo, pero sigue reconociendo sus rutinas y mostrando respuestas habituales. Los cambios marcados de memoria, orientación o interacción no deben considerarse normales sin evaluación."
                ]
              },
              {
                "titulo": "TIENE MALA SALUD",
                "items": [
                  "Pierde peso o masa muscular: Puede relacionarse con problemas dentales, enfermedades crónicas, alteraciones metabólicas o una alimentación insuficiente. La pérdida involuntaria de peso necesita una evaluación veterinaria.",
                  "Tiene dificultad para levantarse o caminar: La rigidez, la cojera, el rechazo a subir escalones o el dolor al tocar las articulaciones pueden indicar artritis u otros problemas. Existen medidas para mejorar la comodidad, pero requieren un plan apropiado.",
                  "Presenta tos o dificultad respiratoria: La tos persistente, la respiración acelerada en reposo o el esfuerzo para respirar pueden estar relacionados con enfermedades cardíacas, respiratorias u otras. La dificultad respiratoria es una emergencia.",
                  "Tiene problemas dentales: El mal aliento intenso, la pérdida de dientes, el babeo, las encías inflamadas o el rechazo de alimentos duros pueden indicar dolor. Una evaluación dental puede mejorar su comodidad y alimentación.",
                  "Bebe u orina mucho más: Estos cambios pueden asociarse con problemas renales, diabetes u otras enfermedades. No se debe restringir el agua para evitar que orine; se necesita una evaluación para determinar la causa.",
                  "Presenta cambios de visión u oído: Puede empezar a chocar con objetos, no responder a sonidos o asustarse cuando alguien se acerca por detrás. Se deben adaptar el entorno y las señales de comunicación, y consultar para distinguir cambios normales de problemas tratables.",
                  "Tiene confusión o cambios de conducta: Puede perderse en lugares conocidos, quedarse mirando fijamente, alterar sus horarios de sueño o parecer desorientado. Estos signos pueden relacionarse con deterioro cognitivo, dolor u otras enfermedades y deben evaluarse.",
                  "Presenta bultos o heridas persistentes: Los bultos nuevos, las lesiones que crecen, las heridas que sangran o las zonas que no cicatrizan requieren revisión. No es posible determinar por su apariencia si un bulto es benigno o maligno.",
                  "Se muestra muy decaído o deja de comer: La falta de apetito, el aislamiento y la debilidad pueden indicar dolor o enfermedad. En un perro senior, no conviene atribuir estos cambios únicamente a la edad."
                ]
              }
            ]
          },
          "primeros": {
            "titulo": "PRIMEROS AUXILIOS",
            "secciones": [
              {
                "titulo": "QUÉ HACER CUANDO LE SUCEDEN ACCIDENTES COMO:",
                "items": [
                  "1. Caídas y golpes",
                  "Evitar que siga caminando si parece tener dolor o dificultad para levantarse.",
                  "Comprobar si respira normalmente y si está consciente.",
                  "Si se sospecha una lesión en la columna, pelvis o patas, moverlo lo mínimo posible y utilizar una superficie firme para transportarlo.",
                  "No intentar acomodar articulaciones ni forzarlo a ponerse de pie.",
                  "Si hay sangrado, aplicar presión suave con una gasa limpia.",
                  "Acudir urgentemente al veterinario después de un golpe fuerte, especialmente si se desmaya, respira con dificultad o presenta dolor intenso.",
                  "2. Heridas y sangrado",
                  "Mantenerlo tranquilo y evitar que lama la herida.",
                  "Presionar suavemente con una gasa limpia para controlar el sangrado externo.",
                  "No retirar objetos incrustados ni aplicar alcohol, polvos o remedios caseros.",
                  "Las heridas profundas, mordeduras y hemorragias persistentes necesitan atención inmediata.",
                  "Si toma medicamentos o tiene una enfermedad crónica, informar al veterinario antes de administrar cualquier tratamiento.",
                  "No darle analgésicos humanos, ya que algunos son tóxicos para los perros.",
                  "3. Atragantamiento",
                  "Si puede toser y respirar, permitirle toser mientras se solicita ayuda veterinaria.",
                  "Si no puede respirar, se desploma o sus encías se tornan azuladas, acudir a urgencias inmediatamente.",
                  "Retirar un objeto de la boca solo si está claramente visible y se puede alcanzar sin empujarlo hacia la garganta.",
                  "No introducir los dedos a ciegas ni darle agua o comida para intentar que el objeto pase.",
                  "Tras el episodio, necesita evaluación si persisten tos, arcadas, respiración anormal o molestias.",
                  "4. Intoxicación",
                  "Alejarlo de la sustancia y evitar nuevas exposiciones.",
                  "Guardar el envase o fotografiar la etiqueta.",
                  "Llamar inmediatamente al veterinario y explicar qué pudo ingerir, cuándo y en qué cantidad, si se sabe.",
                  "No provocar el vómito ni administrar leche, aceite, sal, carbón activado o medicamentos por cuenta propia.",
                  "Si presenta convulsiones, dificultad respiratoria, desmayo o debilidad intensa, trasladarlo a urgencias.",
                  "5. Quemaduras",
                  "Alejarlo de la fuente de calor o del producto químico.",
                  "En una quemadura térmica pequeña, enfriar la zona con agua corriente fresca durante unos 20 minutos si es posible sin retrasar la atención.",
                  "No aplicar hielo, mantequilla, pasta dental ni cremas humanas.",
                  "Cubrir la lesión de forma ligera con material limpio que no se adhiera y acudir al veterinario.",
                  "Las quemaduras extensas o las que afectan cara, ojos, patas o genitales necesitan atención urgente.",
                  "6. Picaduras y mordeduras",
                  "Mantenerlo alejado del animal o insecto y observar su respiración y estado general.",
                  "Si aparece hinchazón rápida de la cara, debilidad o dificultad respiratoria, acudir de inmediato a urgencias.",
                  "No administrar medicamentos humanos sin indicación veterinaria.",
                  "Las mordeduras pueden producir lesiones profundas e infecciones, incluso si la piel presenta solo pequeñas perforaciones.",
                  "Si existe sospecha de rabia, contactar con el veterinario y las autoridades sanitarias pertinentes.",
                  "7. Vómitos y diarrea",
                  "Observar la frecuencia, la presencia de sangre, el dolor y los cambios en el consumo de agua.",
                  "No dar antidiarreicos ni antibióticos humanos.",
                  "Si está alerta y no vomita repetidamente, se puede ofrecer agua en pequeñas cantidades mientras se consulta.",
                  "No someterlo a ayunos prolongados sin indicación veterinaria, especialmente si tiene enfermedades crónicas.",
                  "Buscar atención urgente ante vómitos repetidos, sangre, dolor abdominal, debilidad o incapacidad para retener agua.",
                  "8. Golpe de calor",
                  "Llevarlo inmediatamente a un lugar fresco y ventilado.",
                  "Mojar suavemente el cuerpo con agua fresca, no helada, y utilizar ventilación.",
                  "No envolverlo en toallas mojadas que acumulen calor ni obligarlo a beber si está desorientado.",
                  "Trasladarlo urgentemente al veterinario si jadea intensamente, vomita, se tambalea o se desploma.",
                  "Los perros mayores pueden tener menor tolerancia al calor, especialmente si padecen enfermedades cardíacas o respiratorias."
                ]
              }
            ]
          },
          "cuidados": {
            "titulo": "CUIDADOS",
            "secciones": [
              {
                "titulo": "CÓMO MANTENERLO BIEN CUIDADO",
                "items": [
                  "Ofrecer un lugar cómodo para descansar: Su cama debe ser limpia, seca, cálida cuando haga frío y estar protegida de la lluvia y el sol intenso. Una superficie acolchada puede ayudar a aliviar la presión sobre las articulaciones.",
                  "Facilitar el acceso a comida y agua: Colocar los recipientes en lugares accesibles y evitar que deba subir escalones o caminar distancias largas para beber. Si tiene dificultad para agacharse, consultar si conviene modificar la altura de los recipientes.",
                  "Mantener una alimentación adaptada: Elegir la dieta según su condición corporal, salud dental y enfermedades. No reducir la comida automáticamente por su edad; la pérdida de peso y de músculo puede ser tan preocupante como el sobrepeso.",
                  "Realizar ejercicio suave y regular: Los paseos cortos, los juegos tranquilos y las actividades de olfato ayudan a mantener la movilidad y el bienestar mental. Ajustar la duración a su resistencia y detener la actividad si aparece dolor, jadeo excesivo o debilidad.",
                  "Proteger las articulaciones: Utilizar superficies antideslizantes, evitar saltos desde muebles altos y facilitar rampas o escalones seguros cuando sean apropiados. No obligarlo a subir escaleras si le causan dolor.",
                  "Mantener controles veterinarios frecuentes: Los perros mayores pueden beneficiarse de revisiones al menos cada seis meses, o con mayor frecuencia si tienen enfermedades crónicas. El veterinario decidirá si necesita análisis de sangre, orina, controles dentales u otros estudios.",
                  "Controlar enfermedades crónicas: Si tiene una condición diagnosticada, seguir el plan de tratamiento y acudir a los controles indicados. No suspender medicamentos ni cambiar las dosis porque parezca estar mejor.",
                  "Cuidar los dientes: Cepillar con productos formulados para perros y consultar si presenta mal aliento intenso, dolor o dificultad para comer. El tratamiento dental puede mejorar significativamente su bienestar.",
                  "Cepillar con delicadeza: Utilizar un cepillo apropiado para su pelaje y evitar tirar de los nudos. Revisar la piel durante el cepillado para detectar bultos, heridas o irritaciones.",
                  "Mantener uñas y patas en buen estado: Las uñas demasiado largas pueden alterar la postura y dificultar la marcha. Revisar también las almohadillas para detectar heridas, grietas o cuerpos extraños.",
                  "Adaptar el ambiente si ve u oye menos: Mantener los muebles en lugares constantes, bloquear escaleras peligrosas y acercarse de manera que pueda percibir a la persona sin asustarse. Utilizar señales visuales o táctiles suaves cuando sea necesario.",
                  "Ayudarlo a mantener la higiene: Si le cuesta levantarse para hacer sus necesidades, facilitarle salidas más frecuentes y un trayecto seguro. Limpiar y secar la piel si se moja o ensucia para prevenir irritaciones.",
                  "Proporcionar compañía y estimulación mental: Ofrecer contacto afectuoso, juegos sencillos, oportunidades para olfatear y rutinas conocidas. Aunque sea mayor, necesita participar en la vida familiar de una manera que respete su energía.",
                  "Protegerlo del frío y del calor: Evitar que duerma en el suelo húmedo o permanezca al sol sin sombra. Los perros mayores pueden tolerar peor los extremos de temperatura, sobre todo si tienen problemas cardíacos, respiratorios o articulares.",
                  "Vigilar su peso, apetito y movilidad: Anotar cambios y comentarlos en las consultas. Las pequeñas variaciones pueden ser las primeras señales de dolor, enfermedad dental o una condición interna.",
                  "Mantener su vacunación y prevención de parásitos: La edad no elimina la necesidad de protección. El veterinario debe adaptar las vacunas y los productos preventivos a su historial, salud y riesgo de exposición."
                ]
              },
              {
                "titulo": "CÓMO SABER SI NO TIENE UN BUEN CUIDADO",
                "items": [
                  "1. Falta de comodidad",
                  "Su cama es dura, húmeda o está en un lugar expuesto a temperaturas extremas.",
                  "Debe subir escaleras o saltar para llegar a su agua y comida, a pesar de tener dificultades de movilidad.",
                  "Se resbala constantemente sobre pisos lisos y no cuenta con un entorno adaptado.",
                  "Permanece acostado en una misma posición durante largos períodos sin que se compruebe si necesita ayuda para cambiar de postura.",
                  "2. Alimentación inadecuada",
                  "Pierde peso o músculo sin que se investigue la causa.",
                  "Tiene sobrepeso que dificulta caminar o respirar cómodamente.",
                  "No dispone de agua limpia o recibe únicamente sobras.",
                  "Se le niega comida por ser viejo o se le administran suplementos sin evaluación profesional.",
                  "3. Falta de atención médica",
                  "Se ignoran el dolor, la cojera, la tos o los cambios de sed.",
                  "No recibe controles veterinarios ni se revisan sus enfermedades crónicas.",
                  "Tiene dientes dolorosos, heridas, bultos o lesiones que no se evalúan.",
                  "Se le dan medicamentos humanos o se suspenden sus tratamientos sin consultar.",
                  "4. Falta de higiene",
                  "Su pelaje está muy enredado o permanece sucio y húmedo.",
                  "Tiene uñas demasiado largas que dificultan caminar.",
                  "Presenta mal olor intenso, heridas o irritación en la piel sin atención.",
                  "No se le ayuda a mantener limpia su zona de descanso cuando tiene problemas de movilidad.",
                  "5. Aislamiento o falta de respeto por sus límites",
                  "Se le obliga a correr, saltar o realizar actividades que le provocan dolor.",
                  "Se le deja solo durante períodos prolongados sin atender sus necesidades.",
                  "Se le castiga por tener accidentes dentro de casa relacionados con una enfermedad o dificultad física.",
                  "Se ignoran los signos de miedo, dolor o cansancio cuando necesita descansar."
                ]
              }
            ]
          },
          "comportamiento": {
            "titulo": "COMPORTAMIENTO",
            "secciones": [
              {
                "titulo": "ADIESTRAMIENTO Y ESTIMULACIÓN EN LA ETAPA SENIOR",
                "items": [
                  "Mantener las órdenes que ya conoce: Practicar señales sencillas como “ven”, “espera” y “siéntate” en sesiones breves. Adaptar los ejercicios si tiene dolor articular, pérdida de audición o dificultades de visión.",
                  "Reforzar la conducta tranquila: Premiar cuando descansa, espera o se acerca sin empujar. Las recompensas pueden ser elogios, caricias si las disfruta o pequeñas porciones de alimento apropiado.",
                  "Utilizar juegos de olfato: Esconder pequeñas porciones de su alimento en lugares fáciles y seguros para que las encuentre. Estos juegos estimulan la mente sin exigir carreras ni saltos.",
                  "Mantener una rutina predecible: Procurar horarios regulares para las comidas, los paseos, el descanso y los medicamentos. Las rutinas conocidas pueden ayudar a reducir la confusión y la inquietud.",
                  "Adaptar los paseos: Elegir trayectos cortos, superficies seguras y horarios con temperaturas moderadas. Permitirle olfatear y detenerse cuando lo necesite, sin obligarlo a seguir si está cansado.",
                  "Evitar castigos por accidentes: Si comienza a hacer sus necesidades dentro de casa, revisar primero si hay problemas urinarios, digestivos, dolor o dificultades para desplazarse. Aumentar las oportunidades de salir y premiar cuando lo haga en el lugar adecuado.",
                  "Mantener el contacto social: Permitir que interactúe con personas conocidas y animales tranquilos, siempre respetando sus límites. Si ve u oye menos, acercarse con suavidad para evitar que se sobresalte.",
                  "Practicar la manipulación de forma amable: Si necesita cepillado o revisión de las patas, realizarlo en sesiones cortas y detenerse si muestra dolor. Puede necesitar ayuda profesional para cuidados que le resulten difíciles.",
                  "Evitar cambios bruscos: Si se modifica el lugar de descanso, la distribución de los muebles o los horarios, hacerlo de manera gradual cuando sea posible. Los cambios repentinos pueden generar inseguridad en perros con dificultades sensoriales o cognitivas.",
                  "Reconocer los signos de dolor: Si empieza a gruñir cuando lo tocan, se aparta o evita ciertas actividades, no castigarlo. El dolor puede modificar la conducta y necesita una evaluación veterinaria.",
                  "Ofrecer actividades apropiadas para su capacidad: Los juegos deben ser sencillos y adaptados a su movilidad. Evitar lanzamientos que lo obliguen a girar bruscamente, saltar o correr detrás de objetos en superficies resbaladizas.",
                  "Buscar ayuda ante cambios cognitivos: Si se desorienta, se queda atrapado en esquinas, altera su horario de sueño o parece olvidar rutinas conocidas, consultar al veterinario. Algunos problemas pueden tratarse o manejarse mejor cuando se identifican temprano."
                ]
              },
              {
                "titulo": "CÓMO MEJORAR EL COMPORTAMIENTO DE TU MASCOTA SI NO FUE ADIESTRADO",
                "items": [
                  "1. Si está inquieto o camina de un lado a otro",
                  "Comprobar si necesita salir, beber, descansar o recibir atención.",
                  "Observar si muestra signos de dolor, dificultad respiratoria o molestias al acostarse.",
                  "Mantener un ambiente tranquilo y una rutina predecible.",
                  "Ofrecer una actividad suave de olfato si su estado físico lo permite.",
                  "Si la inquietud aparece repentinamente, especialmente durante la noche, consultar al veterinario para descartar dolor, enfermedad o cambios cognitivos.",
                  "2. Si empieza a hacer sus necesidades dentro de casa",
                  "No castigarlo ni asumir que lo hace por desobediencia.",
                  "Facilitar salidas más frecuentes y reducir los obstáculos para llegar al exterior.",
                  "Limpiar las zonas sucias con productos adecuados.",
                  "Registrar si bebe más, orina en pequeñas cantidades o parece tener dolor.",
                  "Solicitar una evaluación veterinaria, especialmente si el cambio es reciente o persistente.",
                  "3. Si se vuelve irritable o gruñe",
                  "Respetar su espacio y no obligarlo a recibir caricias.",
                  "Evitar tocar las zonas que parecen dolorosas.",
                  "Mantener a los niños alejados cuando esté descansando o comiendo.",
                  "No castigar el gruñido, porque es una señal de advertencia que puede ayudar a prevenir una mordedura.",
                  "Consultar al veterinario para descartar dolor, problemas dentales, pérdida sensorial u otras enfermedades.",
                  "4. Si parece desorientado",
                  "Mantener los muebles y las rutas de acceso lo más estables posible.",
                  "Bloquear escaleras y otros lugares donde pueda quedar atrapado o lesionarse.",
                  "Utilizar luces suaves durante la noche y facilitar el acceso a su cama y al agua.",
                  "Mantener horarios conocidos y hablarle antes de tocarlo.",
                  "Solicitar una evaluación veterinaria si la desorientación es nueva, frecuente o va empeorando.",
                  "5. Si ladra durante la noche",
                  "Comprobar si necesita salir, tiene frío, siente dolor o está desorientado.",
                  "Asegurar que su cama sea cómoda y que pueda llegar al agua.",
                  "Mantener una rutina nocturna tranquila y evitar estímulos innecesarios.",
                  "No castigarlo por ladrar si puede estar expresando una necesidad.",
                  "Si el comportamiento es nuevo o persistente, consultar al veterinario para identificar la causa.",
                  "6. Si tiene miedo de las personas o los ruidos",
                  "Acercarse de frente y con suavidad, permitiendo que note la presencia de la persona.",
                  "Evitar movimientos bruscos y no despertarlo tocándolo de repente.",
                  "Proporcionar un lugar tranquilo donde pueda retirarse.",
                  "Recompensar la calma y permitirle acercarse a su propio ritmo.",
                  "Adaptar las señales si ha perdido visión o audición.",
                  "7. Si ya no responde a las órdenes",
                  "Comprobar si oye y ve adecuadamente antes de pensar que está desobedeciendo.",
                  "Utilizar señales visuales o táctiles suaves que pueda reconocer.",
                  "Practicar ejercicios sencillos en lugares sin distracciones.",
                  "Recompensar cada respuesta correcta y evitar sesiones largas.",
                  "Consultar si la pérdida de respuesta es repentina, ya que puede relacionarse con un problema de salud.",
                  "8. Si tiene dificultades para quedarse solo",
                  "Mantener horarios previsibles y un espacio cómodo.",
                  "Dejarle agua, cama y acceso seguro a sus necesidades.",
                  "Evitar ausencias prolongadas si muestra angustia intensa, cuando sea posible.",
                  "Pedir ayuda profesional si presenta vocalizaciones persistentes, destrucción o signos claros de ansiedad.",
                  "No utilizar castigos ni métodos que aumenten el miedo."
                ]
              }
            ]
          },
          "vacunacion": {
            "titulo": "VACUNACIÓN",
            "secciones": [
              {
                "titulo": "TODAS LAS VACUNAS CON LAS QUE DEBERÍA CONTAR LA MASCOTA HASTA EL DÍA DE SU MUERTE",
                "items": [
                  "Vacuna contra el moquillo canino: Los perros mayores que recibieron la serie inicial y sus refuerzos pueden necesitar nuevas dosis según las recomendaciones veterinarias y el producto. La edad avanzada no significa automáticamente que la vacuna deba suspenderse.",
                  "Vacuna contra el parvovirus canino: La protección frente al parvovirus sigue siendo importante, especialmente si el perro tiene contacto con otros animales o ambientes donde puede haber contaminación. Los intervalos de refuerzo deben establecerse de acuerdo con su historial y las guías veterinarias.",
                  "Vacuna contra el adenovirus canino: Generalmente forma parte de las vacunas combinadas. El veterinario revisará cuándo corresponde el refuerzo y si existen circunstancias médicas que deban considerarse antes de la aplicación.",
                  "Vacuna contra la parainfluenza canina: Puede recomendarse en perros que tienen exposición frecuente a otros perros. La necesidad depende de su estilo de vida y de los productos disponibles.",
                  "Vacuna contra la leptospirosis: Puede ser importante cuando existe exposición a roedores, agua contaminada, inundaciones u otros factores de riesgo. Si se recomienda, los refuerzos suelen programarse de manera periódica, con frecuencia anual según el producto y la evaluación veterinaria.",
                  "Vacuna contra la rabia: Debe mantenerse según las normas sanitarias vigentes en Bolivia y el calendario establecido por el veterinario. La protección contra la rabia sigue siendo relevante durante toda la vida del perro.",
                  "Vacuna contra la tos infecciosa canina: Puede considerarse si frecuenta residencias, guarderías, refugios u otros lugares con muchos perros. No todos los perros mayores la necesitan, por lo que se debe valorar su exposición.",
                  "Evaluación antes de vacunar: Si tiene una enfermedad crónica, está recibiendo tratamientos o presenta síntomas, el veterinario debe evaluar su estado antes de decidir el momento adecuado para vacunar. No se debe suspender toda vacunación únicamente por la edad ni aplicarla sin revisar su condición.",
                  "Revisión de los registros: Si el carnet se perdió o el historial es desconocido, solicitar un plan individual para recuperar la protección. No repetir ni omitir vacunas al azar.",
                  "Prevención durante la vejez: Además de las vacunas, mantener control de parásitos, higiene, alimentación adecuada y revisiones médicas. La combinación de estas medidas contribuye a proteger su salud y su calidad de vida."
                ]
              }
            ]
          },
          "veterinario": {
            "titulo": "CUÁNDO IR AL VETERINARIO",
            "secciones": [
              {
                "titulo": "EN QUÉ SITUACIONES DE EMERGENCIA DEBES DE ACUDIR A UN VETERINARIO",
                "items": [
                  "Dificultad respiratoria: Respiración trabajosa, encías azuladas, ahogo o colapso requieren atención inmediata. No esperar a ver si mejora solo.",
                  "Vómitos repetidos o diarrea con sangre: Pueden provocar deshidratación y señalar una enfermedad grave. La urgencia aumenta si está débil, tiene dolor o no puede retener agua.",
                  "Sospecha de intoxicación: Si ingiere medicamentos, venenos, chocolate, uvas, pasas, xilitol o productos químicos, contactar inmediatamente con un veterinario. No provocar el vómito ni administrar remedios caseros.",
                  "Atropello o golpe fuerte: Aunque no se observen heridas, puede tener lesiones internas. Debe ser evaluado urgentemente.",
                  "Sangrado abundante: Aplicar presión suave con una gasa limpia y trasladarlo a urgencias. No retirar objetos incrustados ni aplicar sustancias irritantes.",
                  "Convulsiones o desmayo: Apartar los objetos que puedan lastimarlo, no introducir nada en la boca y buscar atención inmediata.",
                  "Abdomen hinchado con arcadas: Puede indicar una emergencia abdominal potencialmente mortal. No esperar a que disminuya la hinchazón.",
                  "Incapacidad para orinar: Si intenta hacerlo repetidamente sin conseguirlo, necesita atención inmediata. No se debe restringir el agua ni administrar medicamentos por cuenta propia.",
                  "Dolor intenso o incapacidad para levantarse: Puede indicar una lesión, un problema neurológico o una enfermedad grave. No forzarlo a caminar.",
                  "Golpe de calor: Jadeo extremo, desorientación, vómitos, debilidad o colapso después de exponerse al calor requieren enfriamiento inicial seguro y traslado veterinario urgente.",
                  "Encías muy pálidas o amarillentas: Pueden indicar anemia, hemorragia o enfermedad interna. Si se acompañan de debilidad, desmayo o respiración acelerada, se trata de una emergencia.",
                  "Reacción alérgica grave: La hinchazón rápida de la cara, la dificultad respiratoria o el colapso después de una picadura o medicamento requieren atención inmediata.",
                  "Dolor repentino o pérdida de movilidad: Si deja de apoyar una pata, no puede levantarse o llora al moverse, necesita una evaluación rápida. No administrar analgésicos humanos.",
                  "Desorientación repentina: Si no reconoce el entorno, camina de forma inestable, parece confundido de repente o presenta debilidad, debe evaluarse urgentemente para descartar problemas neurológicos u otras enfermedades.",
                  "Pérdida marcada de apetito o debilidad: Si deja de comer, está muy decaído o pierde peso sin explicación, necesita una consulta pronta. Si no puede beber, vomita repetidamente o se desploma, acudir a urgencias.",
                  "Cambios importantes en la sed y la orina: Beber mucho más, orinar en exceso o presentar sangre en la orina requiere evaluación. La incapacidad para orinar es una emergencia inmediata.",
                  "Bultos que crecen o heridas que no cicatrizan: No todos los bultos son malignos, pero el crecimiento rápido, el sangrado y las lesiones persistentes deben revisarse sin demora.",
                  "Exposición posible a la rabia: Si lo muerde un animal sospechoso o tiene contacto con saliva potencialmente infectada, buscar atención veterinaria y orientación sanitaria inmediatamente, aunque no tenga síntomas.",
                  "Deterioro rápido del estado general: Si en pocas horas deja de responder normalmente, pierde el equilibrio, respira de manera anormal o presenta varios síntomas a la vez, necesita atención inmediata.",
                  "Dolor persistente que afecta su vida diaria: Aunque no siempre sea una emergencia de minutos, el dolor crónico, la dificultad para dormir, el rechazo a caminar o la pérdida de interés por la familia requieren una consulta para mejorar su comodidad y calidad de vida."
                ]
              }
            ]
          }
        }
      }
    }
  },
  "pinscher": {
    "nombre": "Pinscher",
    "etapas": {
      "cachorro": {
        "tituloOriginal": "PINSCHER – CACHORRO (0 A 12 MESES)",
        "temas": {
          "alimentacion": {
            "titulo": "ALIMENTACIÓN",
            "secciones": [
              {
                "titulo": "ALIMENTACIÓN SALUDABLE",
                "items": [
                  "Alimento completo para cachorros de raza pequeña: Debe recibir un alimento formulado para cachorros, preferentemente apropiado para perros de tamaño pequeño. Estos alimentos aportan proteínas, grasas, vitaminas y minerales en proporciones adecuadas para el crecimiento. Las croquetas deben tener un tamaño que pueda masticar cómodamente y la ración debe ajustarse a su peso, edad y condición corporal.",
                  "Proteínas de buena calidad: Las proteínas contribuyen al desarrollo de los músculos, la piel, el pelo y los órganos. Un alimento completo para cachorros debe proporcionar proteínas suficientes para su crecimiento. No es necesario agregar carne a todas las comidas si el alimento ya cubre sus necesidades, ya que los añadidos pueden desequilibrar la dieta.",
                  "Grasas saludables en cantidades adecuadas: Las grasas aportan energía para sus actividades y contribuyen a la absorción de algunas vitaminas. Como el pinscher es activo, necesita una cantidad adecuada de energía, pero no debe recibir alimentos muy grasos ni premios en exceso, porque puede aumentar de peso rápidamente.",
                  "Agua limpia y fresca durante todo el día: Debe disponer de agua potable en un recipiente estable, limpio y fácil de alcanzar. Aunque sea pequeño, puede deshidratarse cuando presenta vómitos, diarrea o permanece en un ambiente caluroso. Se debe comprobar regularmente que el recipiente tenga agua y no esté contaminado.",
                  "Varias comidas pequeñas al día: Los cachorros de razas pequeñas pueden necesitar tres o cuatro comidas diarias, dependiendo de su edad, peso y recomendación veterinaria. Los ejemplares muy pequeños pueden tener mayor riesgo de sufrir una bajada peligrosa de glucosa si pasan demasiado tiempo sin comer. Si presenta debilidad, temblores o desorientación, necesita atención veterinaria inmediata.",
                  "Alimentación apropiada durante el destete: Durante las primeras semanas, la leche materna es su principal alimento. Si la madre no puede amamantar, se debe utilizar un sustituto lácteo formulado para cachorros bajo orientación veterinaria. El destete suele comenzar gradualmente alrededor de las tres o cuatro semanas, y no debe reemplazarse la leche materna por leche de vaca.",
                  "Porciones adaptadas a su tamaño: Un pinscher miniatura necesita cantidades mucho menores que un perro grande, pero eso no significa que deba recibir una alimentación insuficiente. La ración debe medirse y ajustarse según su crecimiento. Las indicaciones del envase son un punto de partida; el veterinario puede modificarlas según su condición corporal.",
                  "Cambio gradual de alimento: Cuando sea necesario cambiar de marca o fórmula, realizar una transición progresiva durante varios días, generalmente entre cinco y siete, siempre que el cachorro esté sano y tolere el cambio. Cambiar bruscamente puede ocasionar diarrea, gases o pérdida temporal del apetito.",
                  "Premios pequeños para el entrenamiento: Para enseñarle a acudir cuando lo llaman, sentarse o caminar con correa, pueden utilizarse pequeñas porciones de su alimento o premios específicos para perros. Deben ser fáciles de masticar y no sustituir sus comidas. Los premios deberían representar, en general, no más del 10 % de las calorías diarias.",
                  "Seguimiento del crecimiento y del peso: Se debe controlar periódicamente su peso y observar si aumenta de manera constante, mantiene energía y tiene heces normales. Un cachorro muy delgado, excesivamente débil o que deja de ganar peso necesita revisión veterinaria. No se debe intentar que crezca más rápido dándole raciones excesivas o suplementos sin indicación profesional."
                ]
              },
              {
                "titulo": "ALIMENTACIÓN NO SALUDABLE",
                "items": [
                  "Chocolate y cacao: Contienen sustancias que pueden intoxicar al pinscher y afectar su corazón y sistema nervioso. Como es un perro pequeño, incluso una cantidad que parezca insignificante puede ser preocupante dependiendo del tipo de chocolate. Si lo ingiere, se debe contactar inmediatamente con un veterinario.",
                  "Uvas y pasas: Pueden provocar daño renal grave en algunos perros y no existe una cantidad que pueda considerarse segura para todos. Nunca deben darse como premio ni mezclarse con sus alimentos. Ante una ingestión accidental, necesita orientación veterinaria urgente aunque todavía parezca estar bien.",
                  "Cebolla y ajo: Pueden dañar los glóbulos rojos y causar anemia. El riesgo puede existir tanto en alimentos crudos como cocidos o deshidratados. No se deben agregar a sus comidas ni utilizar como supuestos remedios naturales.",
                  "Huesos cocidos: Pueden astillarse, causar atragantamiento, dañar los dientes o provocar lesiones y obstrucciones intestinales. Los perros pequeños tienen una boca delicada, por lo que no deben recibir huesos como método para limpiar sus dientes. Es preferible utilizar productos dentales apropiados para su tamaño.",
                  "Comida frita y muy grasosa: Las frituras, los embutidos, la piel de pollo muy grasosa y los restos aceitosos pueden causar problemas digestivos y favorecer el sobrepeso. Una comida muy grasa también puede desencadenar pancreatitis en algunos perros.",
                  "Leche de vaca y productos lácteos en exceso: Muchos perros no digieren bien la lactosa y pueden presentar diarrea, gases o dolor abdominal. La leche de vaca no sustituye la leche materna ni un sustituto lácteo formulado para cachorros.",
                  "Dulces y productos con xilitol: Algunos chicles, caramelos, productos sin azúcar y otros alimentos pueden contener xilitol, que puede causar una bajada peligrosa de glucosa y daño hepático. Nunca deben dejarse estos productos al alcance del pinscher.",
                  "Alimentos excesivamente salados o condimentados: Las sopas muy saladas, las salsas, los embutidos y las sobras condimentadas no son adecuados para su alimentación habitual. Pueden aportar demasiada sal, grasa y otros ingredientes perjudiciales.",
                  "Suplementos y dietas caseras desequilibradas: No se debe añadir calcio, vitaminas, minerales o suplementos para el crecimiento sin indicación veterinaria. Una dieta basada únicamente en arroz, carne, pollo o sobras puede carecer de nutrientes esenciales y afectar su desarrollo."
                ]
              }
            ]
          },
          "salud": {
            "titulo": "SALUD",
            "secciones": [
              {
                "titulo": "TIENE BUENA SALUD",
                "items": [
                  "Se muestra activo y curioso: El cachorro pinscher suele interesarse por los sonidos, los juguetes y las personas de su entorno. Alterna momentos de juego con períodos de descanso. Su nivel de actividad debe ser adecuado a su edad, sin obligarlo a realizar ejercicios prolongados.",
                  "Tiene buen apetito: Come sus raciones con regularidad y bebe agua. Como es pequeño, una pérdida persistente del apetito debe tomarse en serio, especialmente si se acompaña de temblores, debilidad o somnolencia inusual.",
                  "Tiene ojos limpios y sin dolor: Sus ojos deben estar libres de secreciones abundantes, enrojecimiento intenso e hinchazón. Si mantiene un ojo cerrado, se lo frota o parece no ver bien, necesita revisión veterinaria.",
                  "Tiene una piel y un pelaje en buen estado: Su pelo corto debe estar relativamente limpio, sin calvas extensas, heridas, costras ni picazón constante. El pelo corto puede hacer que algunas lesiones de la piel sean más fáciles de detectar.",
                  "Camina y juega con normalidad: Se mueve sin cojear persistentemente y utiliza sus cuatro patas. Por su tamaño, las caídas desde camas, sofás o brazos pueden provocar lesiones, por lo que debe evitarse que salte desde alturas.",
                  "Tiene heces formadas: Defeca sin esfuerzo excesivo y no presenta sangre ni diarrea persistente. Los cambios de alimento, los parásitos y las infecciones pueden alterar sus heces, por lo que cualquier cambio importante debe observarse y consultarse.",
                  "Mantiene una respiración cómoda: Respira sin esfuerzo marcado cuando está en reposo y no presenta tos persistente ni jadeo excesivo en un ambiente fresco. Si la respiración cambia de repente, se debe evaluar con rapidez.",
                  "Crece de manera progresiva: Aumenta de peso, desarrolla su musculatura y aprende gradualmente a moverse y relacionarse. El veterinario puede revisar su crecimiento y confirmar que su desarrollo corresponde a su edad."
                ]
              },
              {
                "titulo": "TIENE MALA SALUD",
                "items": [
                  "Presenta debilidad o temblores inusuales: En cachorros de razas pequeñas, la debilidad, los temblores, la desorientación o el colapso pueden indicar una bajada peligrosa de glucosa u otro problema. Se necesita atención veterinaria inmediata; no se debe intentar tratar un cuadro grave únicamente con remedios caseros.",
                  "Deja de comer o beber: Si rechaza las comidas, está decaído o no quiere beber, debe consultarse pronto. En un cachorro pequeño, la falta de alimento puede convertirse en un problema serio en poco tiempo.",
                  "Tiene vómitos o diarrea repetidos: Puede deshidratarse rápidamente. Si presenta sangre, debilidad, dolor abdominal o no puede retener agua, necesita atención urgente. En cachorros sin vacunación completa también deben considerarse enfermedades infecciosas.",
                  "Tiene encías pálidas o amarillentas: Las encías muy pálidas pueden indicar anemia o pérdida de sangre, mientras que la coloración amarillenta puede señalar problemas internos importantes. Si está débil o respira rápido, debe ser atendido inmediatamente.",
                  "Se rasca constantemente: La picazón, las costras, la pérdida de pelo o el enrojecimiento pueden deberse a pulgas, garrapatas, ácaros, hongos o alergias. No se deben aplicar insecticidas domésticos ni productos antiparasitarios que no estén aprobados para su edad y peso.",
                  "Tiene tos o secreción abundante: La tos persistente, los estornudos continuos, las secreciones espesas o la dificultad respiratoria pueden indicar una enfermedad. Si todavía no completó sus vacunas, debe mantenerse separado de perros desconocidos y ser evaluado.",
                  "Cojea o parece sentir dolor: Puede haberse lesionado durante un salto, una caída o un juego. Si no apoya una pata, llora al moverse o presenta hinchazón, necesita revisión veterinaria. No se deben manipular las articulaciones ni administrar analgésicos humanos.",
                  "Tiene abdomen hinchado o doloroso: Un vientre muy distendido, especialmente con vómitos, arcadas, debilidad o dolor, puede indicar una emergencia. No se debe presionar el abdomen ni intentar tratarlo con aceites o infusiones.",
                  "Presenta problemas en la boca: Dificultad para masticar, sangrado de encías, dientes dañados o mal aliento intenso pueden indicar un problema dental. Debe recibir una evaluación profesional y no se deben extraer dientes por cuenta propia."
                ]
              }
            ]
          },
          "primeros": {
            "titulo": "PRIMEROS AUXILIOS",
            "secciones": [
              {
                "titulo": "QUÉ HACER CUANDO LE SUCEDEN ACCIDENTES COMO:",
                "items": [
                  "1. Caídas, golpes o atropellos",
                  "Alejarlo del peligro y mantenerlo tranquilo.",
                  "Observar si está consciente, respira normalmente y puede mantenerse estable. No obligarlo a caminar.",
                  "Si se sospecha una lesión en la columna, pelvis o patas, moverlo lo menos posible y utilizar una superficie firme para transportarlo.",
                  "Si hay sangrado externo, aplicar presión suave y constante con una gasa o tela limpia.",
                  "No intentar acomodar huesos, estirar las patas ni masajear las zonas dolorosas.",
                  "Acudir urgentemente al veterinario después de un atropello o golpe fuerte, aunque no se observen heridas externas.",
                  "Prevenir nuevas caídas utilizando rampas seguras, bloqueando escaleras peligrosas y evitando que salte desde muebles altos.",
                  "2. Heridas y sangrado",
                  "Mantenerlo tranquilo y evitar que lama la herida.",
                  "Aplicar presión constante con una gasa limpia sobre el sangrado externo.",
                  "Si la gasa se empapa, colocar otra encima sin retirar la primera.",
                  "No aplicar alcohol, agua oxigenada, ceniza, café, polvos ni preparados caseros sobre la herida.",
                  "No extraer objetos grandes incrustados ni intentar cerrar una herida profunda.",
                  "Acudir al veterinario si la herida es profunda, hay mordeduras, el sangrado no se detiene o el cachorro está débil.",
                  "3. Atragantamiento o dificultad para respirar",
                  "Si tose con fuerza y todavía puede respirar, permitirle toser mientras se busca ayuda veterinaria.",
                  "Si no puede respirar, se desploma, no consigue emitir sonidos o sus encías se tornan azuladas, se trata de una emergencia inmediata.",
                  "Revisar la boca solamente si es seguro y el objeto está claramente visible y puede retirarse sin empujarlo más profundamente.",
                  "No introducir los dedos a ciegas ni darle agua, pan, aceite o comida para intentar que el objeto pase.",
                  "Contactar con un servicio veterinario de urgencia y trasladarlo siguiendo las instrucciones recibidas.",
                  "4. Intoxicación por alimentos, medicamentos o productos químicos",
                  "Alejarlo de la sustancia y evitar que vuelva a entrar en contacto con ella.",
                  "Identificar el producto y guardar su envase o tomar una fotografía de la etiqueta.",
                  "Contactar inmediatamente con el veterinario, indicando qué pudo ingerir y cuándo.",
                  "No provocar el vómito ni administrar leche, aceite, sal, carbón activado u otros remedios salvo indicación profesional.",
                  "Si presenta convulsiones, desmayo, dificultad respiratoria o debilidad intensa, trasladarlo a urgencias sin demora.",
                  "Recordar que, por su pequeño tamaño, la cantidad ingerida en relación con su peso puede ser importante.",
                  
                  ]
                },
                {
                "titulo": "QUÉ HACER CUANDO LE SUCEDEN ACCIDENTES COMO:",
                "items": [
                 "5. Quemaduras por calor o productos químicos",
                  "Alejarlo de la fuente de calor o del producto peligroso.",
                  "Para una quemadura térmica pequeña, enfriar suavemente la zona con agua corriente fresca, nunca helada, durante unos 20 minutos si es posible sin retrasar la atención.",
                  "No aplicar hielo, mantequilla, pasta dental, cremas humanas ni remedios caseros.",
                  "Cubrir la lesión ligeramente con un material limpio que no se adhiera y acudir al veterinario.",
                  "Si la quemadura es extensa o afecta la cara, los ojos, las patas o los genitales, necesita atención urgente.",
                  "Si se trata de un producto químico, solicitar instrucciones profesionales para retirarlo con seguridad.",
                  "6. Picaduras de insectos y mordeduras",
                  "Alejarlo del animal o insecto y observar su respiración y estado general.",
                  "Si aparece hinchazón rápida de la cara, vómitos, debilidad o dificultad respiratoria, acudir inmediatamente a urgencias.",
                  "No administrar antihistamínicos ni medicamentos humanos sin indicación veterinaria.",
                  "Las mordeduras pueden causar lesiones profundas e infecciones aunque la herida exterior parezca pequeña.",
                  "Si lo muerde un animal desconocido o sospechoso de rabia, contactar con el veterinario y solicitar orientación sanitaria.",
                  "7. Vómitos y diarrea",
                  "Observar la frecuencia, la presencia de sangre y cualquier signo de dolor o debilidad.",
                  "No administrar antidiarreicos ni antibióticos humanos.",
                  "Si está alerta y no vomita repetidamente, se puede ofrecer una pequeña cantidad de agua mientras se contacta al veterinario.",
                  "No someter a un cachorro pequeño a ayunos prolongados sin indicación profesional.",
                  "Acudir urgentemente si hay sangre, vómitos repetidos, dolor abdominal, debilidad, temblores o incapacidad para retener agua.",
                  "Si no ha completado su vacunación, mantenerlo separado de otros perros hasta descartar enfermedades contagiosas.",
                  "8. Golpe de calor o sobrecalentamiento",
                  "Llevarlo inmediatamente a un lugar fresco, ventilado y protegido del sol.",
                  "Mojar suavemente el cuerpo con agua fresca, no helada, y utilizar ventilación mientras se organiza el traslado veterinario.",
                  "No cubrirlo con toallas mojadas que acumulen calor ni forzarlo a beber si está desorientado.",
                  "Acudir urgentemente si jadea de manera extrema, vomita, se tambalea o se desploma.",
                  "No dejarlo dentro de un automóvil estacionado ni en patios sin sombra y agua."
                ]
              }
            ]
          },
          "cuidados": {
            "titulo": "CUIDADOS",
            "secciones": [
              {
                "titulo": "CÓMO MANTENERLO BIEN CUIDADO",
                "items": [
                  "Proporcionar una cama cálida y cómoda: El pinscher tiene pelo corto y puede sentir frío con mayor facilidad que algunos perros de pelaje denso. Debe dormir en un lugar seco, protegido de las corrientes de aire y de la humedad. Una cama adecuada ayuda a que descanse y evita que permanezca sobre superficies frías.",
                  "Protegerlo de las bajas temperaturas: En zonas de Bolivia donde las noches son frías, debe contar con un espacio interior protegido. Puede utilizar una prenda cómoda para perros cuando sea necesario, siempre que no limite el movimiento ni le cause irritación. No debe permanecer mojado ni expuesto al frío durante períodos prolongados.",
                  "Evitar el sobrecalentamiento: Aunque el pinscher sea pequeño, también puede sufrir por el calor. Debe tener agua fresca, sombra y ventilación. Los paseos se deben realizar en horarios apropiados y no se debe dejar al perro encerrado en vehículos.",
                  "Alimentarlo de forma equilibrada: Elegir un alimento completo adecuado para su edad y tamaño. Medir las porciones y evitar que reciba demasiados premios, porque las calorías adicionales pueden acumularse rápidamente en un perro pequeño.",
                  "Mantener su peso saludable: Revisar periódicamente su silueta y palpar suavemente las costillas. No debería tener una capa excesiva de grasa ni estar demasiado delgado. El veterinario puede ayudar a establecer un peso adecuado para su estructura corporal.",
                  "Realizar ejercicio diario moderado: Necesita paseos, juegos y oportunidades para explorar. Su energía no significa que deba correr durante horas. Las actividades deben ajustarse a su edad, condición física y temperatura ambiental.",
                  "Evitar saltos desde grandes alturas: No permitir que salte repetidamente desde sofás, camas o brazos. Utilizar rampas o ayudarlo a bajar de manera segura. Las caídas pueden causar fracturas o lesiones, especialmente en cachorros y perros pequeños.",
                  "Cumplir las revisiones veterinarias: Durante la etapa de cachorro necesita controles para revisar su crecimiento, dientes, piel y desarrollo. Las visitas también permiten programar las vacunas y la prevención de parásitos según su edad y riesgo.",
                  "Mantener al día las vacunas: Conservar su carnet y seguir el calendario indicado por el veterinario. La vacuna contra la rabia debe ajustarse a las disposiciones sanitarias vigentes en Bolivia. No se deben aplicar vacunas al azar ni asumir que todas necesitan refuerzos anuales.",
                  "Prevenir pulgas y garrapatas: Utilizar productos aprobados para perros y adecuados a su edad y peso. Los productos destinados a perros grandes, ganado o ambientes domésticos pueden ser peligrosos si se utilizan de manera incorrecta. Nunca usar insecticidas domésticos directamente sobre su cuerpo.",
                  "Cepillar su pelaje corto: El cepillado suave ayuda a retirar pelo suelto y permite observar la piel. Aunque tiene pelo corto, puede presentar irritación, parásitos o lesiones que necesitan atención. No requiere cepillados agresivos ni baños excesivamente frecuentes.",
                  "Bañarlo cuando lo necesite: Utilizar un champú apropiado para perros y secarlo bien después del baño. Evitar que permanezca húmedo en ambientes fríos. Si presenta picazón, enrojecimiento o lesiones recurrentes, consultar antes de utilizar productos medicados.",
                  "Cuidar los dientes desde cachorro: Acostumbrarlo progresivamente al cepillado con un cepillo y pasta dental formulados para perros. Las razas pequeñas pueden desarrollar problemas dentales, por lo que la higiene oral es importante desde temprana edad.",
                  "Revisar las orejas, uñas y patas: Observar si hay enrojecimiento, mal olor, secreciones, uñas largas o heridas. Limpiar únicamente la parte externa de las orejas y no introducir objetos profundamente en el canal auditivo.",
                  "Proporcionar socialización positiva: Presentarle gradualmente personas, sonidos, superficies y animales sanos y compatibles. No forzarlo a acercarse si tiene miedo. La socialización debe ser segura y respetar las recomendaciones veterinarias mientras completa su vacunación.",
                  "Mantenerlo identificado y supervisado: Utilizar una identificación con datos de contacto y una correa segura durante los paseos. No dejarlo caminar solo por calles o carreteras, porque su pequeño tamaño lo hace vulnerable a vehículos y ataques de animales más grandes.",
                  "Ofrecer juguetes apropiados: Elegir juguetes resistentes, sin piezas pequeñas que pueda tragar y de un tamaño adecuado para su boca. Supervisar los juegos con objetos nuevos y retirar los que se rompan.",
                  "Brindar compañía y descanso: Aunque sea independiente en algunos momentos, necesita interacción diaria con su familia. Debe disponer de un lugar tranquilo para dormir y no ser despertado constantemente para jugar."
                ]
              },
              {
                "titulo": "CÓMO SABER SI NO TIENE UN BUEN CUIDADO",
                "items": [
                  "1. Falta de protección frente al frío y al calor",
                  "Duerme en un suelo húmedo o en un lugar expuesto a corrientes de aire.",
                  "Tiembla repetidamente durante el frío y no cuenta con un refugio cálido.",
                  "Permanece bajo el sol intenso sin sombra ni agua.",
                  "Se deja dentro de un vehículo cerrado o en un ambiente con ventilación insuficiente.",
                  "2. Mala alimentación",
                  "Está demasiado delgado o presenta sobrepeso.",
                  "Recibe únicamente sobras o alimentos que no cubren sus necesidades nutricionales.",
                  "No dispone de agua limpia durante todo el día.",
                  "Recibe muchos premios o suplementos sin una indicación veterinaria.",
                  "3. Falta de higiene",
                  "Tiene la piel sucia, inflamada o con heridas que no se atienden.",
                  "Presenta pulgas, garrapatas o picazón persistente sin tratamiento.",
                  "Tiene mal aliento intenso, encías inflamadas o dificultad para comer.",
                  "Sus uñas están tan largas que dificultan el apoyo de las patas.",
                  "4. Falta de seguridad",
                  "Se le permite saltar desde alturas sin supervisión.",
                  "Puede salir a la calle sin correa ni identificación.",
                  "Tiene acceso a medicamentos, productos de limpieza, cables o alimentos tóxicos.",
                  "Convive sin supervisión con animales mucho más grandes que podrían lastimarlo durante el juego.",
                  "5. Falta de educación y compañía",
                  "Se le grita o golpea cuando comete errores.",
                  "Pasa largos períodos aislado y sin actividades.",
                  "No se le enseña a convivir con personas y animales de manera segura.",
                  "Se ignoran sus señales de miedo, cansancio o dolor."
                ]
              }
            ]
          },
          "comportamiento": {
            "titulo": "COMPORTAMIENTO",
            "secciones": [
              {
                "titulo": "ADIESTRAMIENTO DESDE CACHORRO",
                "items": [
                  "Enseñarle a reconocer su nombre: Decir su nombre con voz tranquila y premiarlo cuando mire hacia la persona que lo llama. Practicar en un ambiente sin demasiadas distracciones y aumentar la dificultad gradualmente.",
                  "Enseñarle a acudir cuando lo llaman: Utilizar una señal sencilla como “ven” y recompensarlo cuando se acerque. Empezar dentro de casa o en un espacio cerrado. No dejarlo suelto cerca de calles hasta que la respuesta sea fiable.",
                  "Enseñarle a sentarse: Sostener un premio cerca de su nariz y moverlo suavemente hacia arriba y atrás para facilitar que se siente. En cuanto lo haga, decir “siéntate” y recompensarlo. No empujar su espalda ni sus caderas.",
                  "Enseñarle a esperar: Pedirle que espere uno o dos segundos antes de recibir la comida o salir por una puerta. Recompensarlo por mantenerse tranquilo y aumentar gradualmente el tiempo. No exigirle períodos prolongados al principio.",
                  "Acostumbrarlo a la correa y al arnés: Presentarle el arnés dentro de casa y permitirle olfatearlo. Colocárselo durante períodos cortos y recompensarlo por estar tranquilo. Después, practicar caminatas breves en lugares seguros.",
                  "Enseñarle a hacer sus necesidades en un lugar determinado: Llevarlo al lugar elegido después de dormir, comer, beber y jugar. Premiarlo inmediatamente cuando lo haga correctamente. Limpiar los accidentes sin castigarlo.",
                  "Evitar que muerda las manos: Los cachorros exploran con la boca y pueden morder suavemente durante el juego. Si lo hace, detener brevemente el juego y ofrecerle un juguete apropiado. Evitar jugar de forma que lo anime a perseguir manos y pies.",
                  "Socializarlo gradualmente: Presentarle personas, sonidos y ambientes variados de forma positiva. Como puede ser cauteloso o reactivo ante estímulos nuevos, debe poder observar desde una distancia cómoda y retirarse si siente miedo.",
                  "Acostumbrarlo a la manipulación: Tocar suavemente sus patas, orejas y cuerpo durante unos segundos y ofrecer premios. Esto facilita el cepillado, el cuidado de las uñas y las revisiones veterinarias.",
                  "Enseñarle a caminar sin tirar: Recompensarlo cuando camine cerca de la persona con la correa floja. Si tira, detenerse brevemente y reanudar la marcha cuando afloje la tensión. No dar tirones fuertes, porque su cuello es delicado.",
                  "Enseñarle a quedarse solo progresivamente: Comenzar con ausencias breves y aumentar el tiempo gradualmente si permanece tranquilo. Dejarlo en un lugar seguro con agua y juguetes adecuados. Si muestra angustia intensa, consultar a un profesional.",
                  "Utilizar refuerzo positivo: Premiar las conductas deseadas con elogios, comida o juegos. El pinscher puede aprender rápidamente, pero necesita reglas consistentes. Los castigos físicos pueden aumentar el miedo y las respuestas defensivas."
                ]
              },
              {
                "titulo": "CÓMO MEJORAR EL COMPORTAMIENTO DE TU MASCOTA SI NO FUE ADIESTRADO",
                "items": [
                  "1. Si ladra demasiado",
                  "Identificar qué provoca los ladridos: ruidos, personas que pasan, otros perros, miedo o aburrimiento.",
                  "Reducir los estímulos que lo alteran mientras se trabaja en enseñar una respuesta tranquila.",
                  "Premiar los momentos en que permanece calmado y responde a una señal.",
                  "Proporcionar juegos de olfato, paseos y actividades apropiadas.",
                  "Evitar gritarle, porque puede interpretar los gritos como parte de la excitación o sentirse más amenazado.",
                  "2. Si muerde objetos de la casa",
                  "Guardar cables, zapatos, medicamentos y objetos pequeños fuera de su alcance.",
                  "Ofrecer juguetes seguros adecuados para su tamaño.",
                  "Redirigirlo hacia un juguete permitido y premiarlo cuando lo utilice.",
                  "Evitar perseguirlo para quitarle el objeto, ya que puede convertirlo en un juego.",
                  "Si ingiere un objeto peligroso, consultar inmediatamente al veterinario.",
                  "3. Si salta sobre las personas",
                  "Enseñarle a saludar con las cuatro patas en el suelo.",
                  "Premiarlo cuando se acerque con calma.",
                  "Pedir a las visitas que sigan las mismas reglas y no lo animen a saltar.",
                  "Evitar empujarlo o gritarle, porque puede interpretarlo como atención.",
                  "Si está demasiado excitado, esperar unos momentos antes de permitir el saludo.",
                  "4. Si tiene miedo de personas, ruidos u otros perros",
                  "No obligarlo a acercarse al estímulo que lo asusta.",
                  "Mantener una distancia en la que pueda observar sin entrar en pánico.",
                  "Asociar gradualmente la presencia del estímulo con premios y experiencias positivas.",
                  "Proporcionarle un lugar seguro al que pueda retirarse.",
                  "Si el miedo es intenso o empeora, solicitar ayuda profesional.",
                  "5. Si gruñe o intenta morder",
                  "No castigarlo por gruñir ni intentar dominarlo físicamente.",
                  "Aumentar la distancia respecto de aquello que provoca la reacción.",
                  "Evitar que niños u otras personas lo molesten mientras come o descansa.",
                  "Consultar al veterinario para descartar dolor o enfermedad.",
                  "Si ha intentado morder, trabajar con un profesional en comportamiento canino que utilice métodos respetuosos y seguros.",
                  "6. Si tira de la correa",
                  "Utilizar un arnés bien ajustado que no comprima su cuello.",
                  "Practicar en lugares tranquilos y premiarlo cuando camine cerca.",
                  "Detenerse cuando tire y continuar cuando afloje la correa.",
                  "Aumentar poco a poco las distracciones.",
                  "No dejarlo suelto en lugares abiertos mientras no responda de manera fiable a la llamada.",
                  "7. Si hace sus necesidades dentro de casa",
                  "Establecer horarios regulares para llevarlo al lugar elegido.",
                  "Acompañarlo después de dormir, comer y jugar.",
                  "Recompensarlo inmediatamente cuando lo haga correctamente.",
                  "Limpiar los accidentes con productos apropiados para eliminar el olor.",
                  "No castigarlo después del accidente; si el problema aparece de repente, consultar al veterinario para descartar una causa médica.",
                  "8. Si no obedece las órdenes",
                  "Volver a practicar una orden sencilla en un lugar sin distracciones.",
                  "Utilizar siempre la misma palabra y recompensar la respuesta correcta.",
                  "Mantener las sesiones cortas y terminar con una experiencia positiva.",
                  "Evitar repetir la orden muchas veces sin ayudarlo a comprenderla.",
                  "Ser consistente con las reglas de toda la familia."
                ]
              }
            ]
          },
          "vacunacion": {
            "titulo": "VACUNACIÓN",
            "secciones": [
              {
                "titulo": "TODAS LAS VACUNAS CON LAS QUE DEBERÍA CONTAR LA MASCOTA HASTA EL DÍA DE SU MUERTE",
                "items": [
                  "El calendario de vacunación debe ser establecido por un veterinario según la edad, el historial, el estado de salud, la exposición a otros animales y las normas sanitarias vigentes en Bolivia. El pinscher no necesita un calendario completamente distinto por ser pequeño, pero la dosis y el producto deben ser los adecuados para perros. Nunca se debe reducir una dosis de vacuna por cuenta propia solo porque el perro pesa poco.",
                  "Vacuna contra el parvovirus canino: Protege frente a una enfermedad contagiosa que puede causar vómitos, diarrea intensa y deshidratación. La serie inicial suele comenzar entre las seis y ocho semanas, según el producto y la recomendación veterinaria, y se repite cada dos a cuatro semanas hasta que el cachorro tenga al menos 16 semanas. En situaciones de riesgo elevado, el veterinario puede recomendar dosis adicionales.",
                  "Vacuna contra el moquillo canino o distemper: Protege frente a una enfermedad viral que puede afectar los sistemas respiratorio, digestivo y nervioso. Normalmente forma parte de una vacuna combinada. Se administra en una serie durante la etapa de cachorro y requiere refuerzos posteriores según las recomendaciones veterinarias.",
                  "Vacuna contra el adenovirus canino: Ayuda a proteger frente a la hepatitis infecciosa canina y enfermedades relacionadas con adenovirus. Generalmente se incluye en la vacuna combinada para cachorros. Los refuerzos se programan de acuerdo con el producto utilizado y las recomendaciones profesionales.",
                  "Vacuna contra la parainfluenza canina: Puede formar parte de algunas vacunas combinadas y ayuda a reducir el riesgo de enfermedad respiratoria asociada con este agente. Su conveniencia depende del contacto que tenga con otros perros y de su exposición a lugares donde conviven muchos animales.",
                  "Vacuna contra la leptospirosis: Protege frente a bacterias que pueden transmitirse por la orina de animales infectados y por agua o suelo contaminados. Puede ser importante en zonas con roedores, inundaciones o agua estancada. Habitualmente requiere dos dosis iniciales y refuerzos periódicos, a menudo anuales, según el producto y el riesgo local.",
                  "Vacuna contra la rabia: Es fundamental para la protección del perro y la salud pública. La rabia es mortal una vez que aparecen los síntomas. La primera dosis y los refuerzos deben cumplir las disposiciones sanitarias vigentes en Bolivia y las indicaciones del veterinario. Se debe conservar el carnet o certificado de vacunación.",
                  "Vacuna contra la tos infecciosa canina: Puede recomendarse si el pinscher acude a guarderías, residencias, refugios o lugares con contacto frecuente con muchos perros. La indicación depende de la exposición y del producto disponible; no todos los perros necesitan exactamente el mismo esquema.",
                  "Vacunas adicionales según el riesgo: Algunas vacunas se utilizan solo en determinadas regiones o circunstancias. No deben aplicarse automáticamente a todos los pinscher. El veterinario debe explicar qué enfermedades son relevantes en la zona y qué beneficio se espera de cada vacuna.",
                  "Refuerzos durante la adultez: Después de completar la serie inicial y el refuerzo recomendado tras la etapa de cachorro, algunas vacunas se aplican a intervalos más largos y otras pueden requerir refuerzos más frecuentes. No todas las vacunas necesitan una dosis anual; se debe respetar el intervalo establecido para cada producto.",
                  "Vacunación durante la vejez: El pinscher senior puede seguir necesitando protección frente a enfermedades infecciosas. La edad avanzada por sí sola no significa que deban suspenderse todas las vacunas. El veterinario debe considerar su historial, sus enfermedades y su riesgo de exposición.",
                  "Si no tiene carnet o se desconoce su historial: Solicitar una evaluación veterinaria para establecer un calendario de recuperación. No se debe asumir que está protegido ni aplicar dosis al azar.",
                  "Medidas preventivas adicionales: Mientras completa su serie de cachorro, evitar el contacto con heces de perros desconocidos, animales enfermos y lugares muy contaminados. La vacunación debe complementarse con higiene, control de parásitos y revisiones veterinarias."
                ]
              }
            ]
          },
          "veterinario": {
            "titulo": "CUÁNDO IR AL VETERINARIO",
            "secciones": [
              {
                "titulo": "EN QUÉ SITUACIONES DE EMERGENCIA DEBES DE ACUDIR A UN VETERINARIO",
                "items": [
                  "Dificultad para respirar: Si respira con mucho esfuerzo, se ahoga, presenta encías azuladas o se desploma, necesita atención inmediata. No se debe esperar a comprobar si mejora por sí solo.",
                  "Debilidad intensa, temblores o desmayo: En un cachorro de raza pequeña, estos signos pueden indicar una bajada peligrosa de glucosa u otro problema grave. Es necesario acudir urgentemente al veterinario, especialmente si no puede mantenerse en pie o no responde normalmente.",
                  "Vómitos repetidos o diarrea con sangre: Puede deshidratarse rápidamente y presentar complicaciones graves. Si no puede retener agua, está muy decaído o tiene dolor abdominal, necesita atención inmediata.",
                  "Sospecha de intoxicación: Si ingiere chocolate, uvas, pasas, xilitol, veneno para roedores, medicamentos o productos químicos, contactar inmediatamente con un veterinario. No provocar el vómito ni administrar remedios caseros.",
                  "Caída desde una altura o atropello: Aunque no haya una herida visible, puede sufrir fracturas o lesiones internas. Debe ser evaluado urgentemente y no se le debe obligar a caminar.",
                  "Sangrado abundante o herida profunda: Aplicar presión suave con una gasa limpia y trasladarlo a un centro veterinario. Las mordeduras y heridas profundas también necesitan revisión por el riesgo de infección.",
                  "Convulsiones o pérdida del conocimiento: Apartar los objetos que puedan lastimarlo, no introducir nada en su boca y buscar atención veterinaria inmediata.",
                  "Abdomen muy hinchado y doloroso: Si el vientre se distiende rápidamente, tiene arcadas, dolor o debilidad, debe ser atendido urgentemente. No se debe presionar el abdomen ni administrar aceites.",
                  "Incapacidad para orinar: Si intenta orinar repetidamente sin conseguirlo, necesita atención inmediata. No se debe restringir el agua ni darle medicamentos por cuenta propia.",
                  "Cojera intensa o incapacidad para apoyar una pata: Puede tener una fractura, lesión articular o traumatismo. No intentar acomodar la pata ni obligarlo a caminar.",
                  "Encías muy pálidas o amarillentas: Pueden indicar anemia, hemorragia o enfermedad interna. Si se acompañan de debilidad, respiración acelerada o desmayo, se trata de una emergencia.",
                  "Reacción alérgica grave: La hinchazón rápida de la cara, los vómitos repetidos, la dificultad respiratoria o el colapso después de una picadura o medicamento requieren atención inmediata.",
                  "Golpe de calor: Jadeo extremo, desorientación, vómitos, debilidad o colapso después de exponerse al calor necesitan enfriamiento inicial seguro y traslado urgente al veterinario.",
                  "Dolor intenso o cambios repentinos de conducta: Si llora, se esconde, gruñe cuando lo tocan o deja de moverse de repente, puede estar sufriendo dolor o una enfermedad. No se debe castigar su comportamiento ni darle analgésicos humanos.",
                  "Pérdida persistente del apetito: Si deja de comer, especialmente si es cachorro, está débil o presenta temblores, debe ser evaluado rápidamente. En los perros pequeños no conviene esperar varios días para consultar.",
                  "Aumento marcado de la sed o cambios en la orina: Si comienza a beber mucho más, orina excesivamente o presenta sangre en la orina, necesita una revisión veterinaria. Si no puede orinar, la atención es inmediata.",
                  "Problemas oculares repentinos: Un ojo que se mantiene cerrado, dolor intenso, lesión, hinchazón o pérdida repentina de visión necesita evaluación rápida para evitar complicaciones.",
                  "Mordedura de un animal desconocido o posible exposición a la rabia: Se debe acudir al veterinario y solicitar orientación sanitaria inmediata, aunque el pinscher parezca encontrarse bien.",
                  "Deterioro rápido del estado general: Si pasa de estar activo a permanecer inmóvil, pierde el equilibrio, respira anormalmente o presenta varios síntomas a la vez, necesita atención urgente.",
                  "Cambios persistentes de peso, piel o movilidad: Aunque no siempre constituyen una emergencia inmediata, la pérdida de peso, la picazón constante, los bultos nuevos, el dolor al caminar o la tos persistente necesitan una consulta para identificar la causa y evitar que el problema empeore."
                ]
              }
            ]
          }
        }
      },
      "adulto": {
        "tituloOriginal": "PERRO PINSCHER – ADULTO (1 A 9 AÑOS APROXIMADAMENTE)",
        "temas": {
          "alimentacion": {
            "titulo": "ALIMENTACIÓN",
            "secciones": [
              {
                "titulo": "ALIMENTACIÓN SALUDABLE",
                "items": [
                  "Alimento completo para perros adultos pequeños: Debe recibir una fórmula para perros adultos que cubra sus necesidades nutricionales. Las croquetas apropiadas para razas pequeñas suelen facilitar la masticación, pero lo más importante es que el alimento sea completo y se adapte a su condición corporal y actividad.",
                  "Proteínas suficientes para conservar los músculos: Las proteínas contribuyen al mantenimiento de los tejidos y la musculatura. Un alimento completo debe proporcionar la cantidad adecuada para un perro adulto. Si presenta una enfermedad renal, hepática u otra condición, el veterinario puede recomendar una dieta específica.",
                  "Grasas en cantidades equilibradas: Las grasas aportan energía y ayudan a absorber vitaminas. El pinscher suele ser activo, pero no necesita recibir comidas grasosas ni grandes cantidades de premios. La ración debe ajustarse para mantener un peso saludable.",
                  "Agua limpia disponible constantemente: Debe tener agua potable durante todo el día, incluso cuando está en el interior de la casa. Durante los paseos y los días calurosos, se debe comprobar que pueda beber y descansar en la sombra.",
                  "Porciones medidas: Utilizar las indicaciones del alimento como referencia y ajustarlas según el peso, la actividad y la condición corporal. Las pequeñas cantidades adicionales pueden representar una parte importante de sus calorías diarias debido a su tamaño.",
                  "Horarios regulares de comida: Muchos perros adultos pueden alimentarse una o dos veces al día, según su rutina y las indicaciones veterinarias. Si tiene antecedentes de problemas de glucosa o alguna enfermedad, puede necesitar un plan diferente.",
                  "Premios pequeños y controlados: Los premios son útiles para reforzar el adiestramiento, pero deben ser pequeños y contarse dentro de la ración diaria. Evitar que familiares y visitas le den comida constantemente, porque puede aumentar de peso sin que se note de inmediato.",
                  "Alimentos caseros correctamente formulados: Si se desea darle una dieta casera como alimentación principal, debe formularla un profesional en nutrición veterinaria. Una mezcla de carne, arroz y verduras no garantiza el equilibrio de minerales, vitaminas y otros nutrientes esenciales.",
                  "Cambio gradual de alimento: Si se necesita cambiar de marca o fórmula, hacerlo progresivamente durante varios días. Si aparecen vómitos, diarrea persistente, pérdida de peso o rechazo de la comida, se debe consultar en vez de continuar probando alimentos sin una causa clara.",
                  "Control regular de la condición corporal: Observar su cintura, palpar suavemente las costillas y controlar su peso. Si aumenta de peso, ajustar las raciones y los premios. Si adelgaza sin explicación, buscar atención veterinaria."
                ]
              },
              {
                "titulo": "ALIMENTACIÓN NO SALUDABLE",
                "items": [
                  "Chocolate y cacao: Son tóxicos para los perros y pueden provocar alteraciones cardíacas y neurológicas. Como el pinscher es pequeño, la cantidad ingerida en relación con su peso puede ser importante. Ante una ingestión, contactar con el veterinario inmediatamente.",
                  "Uvas y pasas: Pueden causar daño renal grave. No deben ofrecerse como premio ni mezclarse con otros alimentos. Cualquier ingestión requiere orientación veterinaria urgente.",
                  "Cebolla y ajo: Pueden dañar los glóbulos rojos y provocar anemia. No se deben agregar deliberadamente a su comida, incluso si forman parte de preparaciones cocidas.",
                  "Comidas fritas y muy grasosas: Los embutidos, las frituras y las sobras aceitosas pueden producir problemas digestivos y favorecer la obesidad. Una comida muy grasa también puede desencadenar pancreatitis.",
                  "Huesos cocidos y mordedores excesivamente duros: Pueden astillarse, causar obstrucciones o fracturar los dientes. Es preferible utilizar juguetes y productos dentales diseñados para perros pequeños.",
                  "Productos con xilitol: Algunos chicles, caramelos y productos sin azúcar contienen este ingrediente, que puede provocar una bajada peligrosa de glucosa y daño hepático. Deben mantenerse fuera de su alcance.",
                  "Alcohol y bebidas con cafeína: Pueden causar intoxicaciones y alteraciones del sistema nervioso y cardiovascular. No se deben dejar vasos ni recipientes al alcance del perro.",
                  "Exceso de premios y sobras: Las porciones pequeñas también suman calorías. Dar comida constantemente puede causar sobrepeso y dificultar que mantenga una alimentación equilibrada.",
                  "Suplementos y dietas desequilibradas: No añadir vitaminas, minerales, calcio ni suplementos para las articulaciones sin indicación veterinaria. Una dieta basada únicamente en carne, arroz o sobras puede ser deficiente."
                ]
              }
            ]
          },
          "salud": {
            "titulo": "SALUD",
            "secciones": [
              {
                "titulo": "TIENE BUENA SALUD",
                "items": [
                  "Mantiene su energía habitual: Juega, camina y explora de acuerdo con su personalidad y condición física. Puede descansar después de ejercitarse, pero no debería mostrar debilidad persistente ni cansarse de manera inusual.",
                  "Conserva un peso adecuado: Tiene una cintura perceptible y las costillas pueden palparse suavemente sin una capa excesiva de grasa. No debe estar demasiado delgado ni presentar un abdomen abultado acompañado de otros síntomas.",
                  "Tiene apetito estable: Come sus raciones de manera habitual y mantiene un consumo de agua relativamente constante. Los cambios marcados en el apetito o la sed deben observarse y consultarse.",
                  "Tiene ojos limpios: No presenta secreción abundante, enrojecimiento intenso ni dolor. Puede orientarse por su entorno y no choca repentinamente con los objetos.",
                  "Mantiene una piel sana: No presenta picazón persistente, heridas, calvas extensas ni irritaciones recurrentes. Su pelo corto permite observar con relativa facilidad algunos cambios en la piel.",
                  "Tiene una boca en buen estado: Puede masticar sin dolor y no presenta encías muy inflamadas ni mal aliento intenso. La higiene dental sigue siendo importante durante toda la adultez.",
                  "Orina y defeca con normalidad: No muestra dolor, esfuerzo excesivo ni sangre en la orina o las heces. Los cambios persistentes pueden indicar una enfermedad y deben evaluarse.",
                  "Conserva su comportamiento habitual: Responde a su familia, muestra interés por el entorno y descansa con normalidad. Un cambio repentino de carácter puede ser una señal de dolor o malestar."
                ]
              },
              {
                "titulo": "TIENE MALA SALUD",
                "items": [
                  "Aumento o pérdida de peso inexplicable: Puede relacionarse con una dieta inadecuada, parásitos, problemas hormonales u otras enfermedades. Si el cambio persiste, necesita una revisión veterinaria.",
                  "Tos o respiración anormal: La tos persistente, el jadeo excesivo en reposo o la respiración trabajosa pueden indicar un problema respiratorio, cardíaco, dolor o sobrecalentamiento. La dificultad respiratoria es una emergencia.",
                  "Problemas dentales: El mal aliento intenso, las encías inflamadas, el sarro abundante o la dificultad para masticar pueden indicar enfermedad dental. La evaluación temprana ayuda a prevenir dolor y pérdida de dientes.",
                  "Vómitos o diarrea persistentes: Pueden deberse a problemas digestivos, parásitos, infecciones o intoxicaciones. Si hay sangre, debilidad, dolor o deshidratación, necesita atención urgente.",
                  "Picazón o lesiones en la piel: El rascado constante, el lamido de las patas, las costras y la pérdida de pelo pueden deberse a parásitos, alergias u otras enfermedades. El tratamiento debe elegirse según la causa.",
                  "Cambios en la orina o la sed: Beber mucho más, orinar con mayor frecuencia, presentar sangre o esforzarse para orinar puede indicar un problema urinario, renal o metabólico. Si no puede orinar, es una emergencia.",
                  "Cojera o dolor al caminar: Puede presentar lesiones musculares, articulares o fracturas. No se debe obligar a caminar para comprobar si mejora ni administrar analgésicos humanos.",
                  "Cambios repentinos de conducta: Si empieza a esconderse, gruñir cuando lo tocan o rechazar actividades que antes disfrutaba, puede estar sintiendo dolor o malestar. Primero debe descartarse una causa médica.",
                  "Bultos o heridas persistentes: Cualquier bulto nuevo, lesión que crece o herida que no cicatriza debe revisarse. No se puede determinar por la apariencia si un bulto es benigno o maligno."
                ]
              }
            ]
          },
          "primeros": {
            "titulo": "PRIMEROS AUXILIOS",
            "secciones": [
              {
                "titulo": "QUÉ HACER CUANDO LE SUCEDEN ACCIDENTES COMO:",
                "items": [
                  "1. Caídas, golpes o atropellos",
                  "Alejarlo del peligro y evitar que corra o camine innecesariamente.",
                  "Comprobar si está consciente y respira normalmente.",
                  "Si se sospecha una lesión de columna, pelvis o patas, moverlo lo mínimo posible y transportarlo sobre una superficie firme.",
                  "Aplicar presión suave con una gasa limpia si existe sangrado externo.",
                  "No intentar enderezar una pata ni manipular las articulaciones.",
                  "Acudir urgentemente al veterinario después de un golpe fuerte, aunque parezca estar bien.",
                  "2. Heridas y sangrado",
                  "Mantenerlo tranquilo y evitar que lama la herida.",
                  "Aplicar presión continua con una gasa limpia.",
                  "No retirar objetos incrustados ni aplicar alcohol, polvos o remedios caseros.",
                  "Las mordeduras y heridas profundas necesitan revisión por el riesgo de lesiones internas e infección.",
                  "Si el sangrado no se detiene o el perro está débil, trasladarlo inmediatamente a urgencias.",
                  "3. Atragantamiento",
                  "Si puede toser y respirar, permitirle toser mientras se solicita orientación veterinaria.",
                  "Si no puede respirar, se desploma o sus encías se tornan azuladas, acudir inmediatamente a urgencias.",
                  "Retirar un objeto solo si está claramente visible y puede alcanzarse sin empujarlo más profundamente.",
                  "No introducir los dedos a ciegas ni darle agua, comida o aceite para intentar desplazar el objeto.",
                  "Trasladarlo a un centro veterinario y seguir las instrucciones del profesional.",
                  "4. Intoxicación",
                  "Retirarlo de la sustancia y evitar una nueva exposición.",
                  "Identificar el producto y guardar su envase o fotografiar la etiqueta.",
                  "Contactar inmediatamente con el veterinario.",
                  "No provocar el vómito ni administrar leche, aceite, sal, carbón activado o medicamentos sin indicación.",
                  "Si presenta convulsiones, dificultad respiratoria o desmayo, trasladarlo urgentemente.",
                  "5. Quemaduras",
                  "Alejarlo de la fuente de calor o del producto químico.",
                  "En una quemadura térmica pequeña, enfriar la zona con agua corriente fresca durante unos 20 minutos si puede hacerse sin retrasar la atención.",
                  "No aplicar hielo, mantequilla, pasta dental ni cremas humanas.",
                  "Cubrir la zona ligeramente con un material limpio que no se adhiera.",
                  "Acudir al veterinario, especialmente si la quemadura es extensa o afecta cara, ojos, patas o genitales.",
                  "6. Picaduras y mordeduras",
                  "Alejarlo del animal o insecto y observar si aparece hinchazón rápida o dificultad respiratoria.",
                  "Si la cara se hincha, vomita repetidamente, se debilita o respira mal, acudir inmediatamente a urgencias.",
                  "No administrar medicamentos humanos sin indicación veterinaria.",
                  "Las mordeduras necesitan revisión, aunque las heridas exteriores parezcan pequeñas.",
                  "Si existe sospecha de rabia, solicitar orientación veterinaria y sanitaria.",
                  "7. Vómitos y diarrea",
                  "Observar la frecuencia, la presencia de sangre y los cambios de energía.",
                  "No administrar medicamentos humanos ni antibióticos por cuenta propia.",
                  "Si está alerta y no vomita repetidamente, se puede ofrecer una pequeña cantidad de agua mientras se consulta.",
                  "No someterlo a ayunos prolongados sin indicación veterinaria.",
                  "Buscar atención urgente si hay sangre, dolor intenso, debilidad, vómitos repetidos o incapacidad para retener agua.",
                  "8. Golpe de calor",
                  "Trasladarlo a un lugar fresco y ventilado.",
                  "Mojar suavemente el cuerpo con agua fresca, no helada, y utilizar ventilación.",
                  "No cubrirlo con toallas mojadas que acumulen calor ni forzarlo a beber si está desorientado.",
                  "Acudir urgentemente al veterinario si jadea intensamente, vomita, se tambalea o se desploma."
                ]
              }
            ]
          },
          "cuidados": {
            "titulo": "CUIDADOS",
            "secciones": [
              {
                "titulo": "CÓMO MANTENERLO BIEN CUIDADO",
                "items": [
                  "Alimentación y peso: Darle una dieta completa para perros adultos pequeños y medir las raciones. Ajustar la cantidad si aumenta de peso o pierde musculatura. Evitar que las sobras y los premios se conviertan en una parte importante de su alimentación.",
                  "Protección climática: Proporcionarle una cama seca y cálida, especialmente durante las noches frías. En días calurosos, asegurar agua, sombra y ventilación. No dejarlo encerrado en un automóvil ni expuesto a temperaturas extremas.",
                  "Ejercicio diario: Ofrecer paseos, juegos y actividades de olfato que mantengan su cuerpo y mente activos. Ajustar la intensidad a su condición física y evitar los ejercicios forzados o los saltos desde grandes alturas.",
                  "Controles veterinarios preventivos: Realizar revisiones periódicas para evaluar su peso, dientes, piel, articulaciones y estado general. La frecuencia depende de sus antecedentes y de las recomendaciones del veterinario.",
                  "Vacunación y desparasitación: Mantener el carnet al día y utilizar productos antiparasitarios adecuados para su peso. No combinar medicamentos ni utilizar productos para ganado o perros grandes sin indicación profesional.",
                  "Higiene dental: Cepillar los dientes con productos específicos para perros y revisar las encías. Si tiene sarro abundante, dolor o mal aliento intenso, necesita una evaluación dental.",
                  "Cuidado del pelaje: Cepillarlo suavemente para retirar pelo suelto y revisar la piel. Bañarlo cuando sea necesario con champú para perros y secarlo bien, sobre todo si el ambiente es frío.",
                  "Cuidado de uñas, orejas y patas: Revisar regularmente las uñas y las almohadillas. Observar si hay heridas, enrojecimiento o secreciones en los oídos y consultar si aparecen molestias persistentes.",
                  "Identificación y seguridad: Utilizar collar o arnés adecuado, identificación y correa durante los paseos. No permitir que camine libremente por calles o carreteras.",
                  "Estimulación mental: Proporcionar juegos de búsqueda, juguetes seguros y ejercicios de obediencia. El pinscher necesita oportunidades para utilizar su inteligencia y curiosidad.",
                  "Compañía y descanso: Dedicarle tiempo cada día y permitirle descansar en un lugar tranquilo. No debe permanecer atado permanentemente ni aislado durante largos períodos.",
                  "Observación diaria: Prestar atención a cambios en el apetito, la sed, las heces, la orina, la movilidad y el comportamiento. Los cambios persistentes deben consultarse."
                ]
              },
              {
                "titulo": "CÓMO SABER SI NO TIENE UN BUEN CUIDADO",
                "items": [
                  "1. Alimentación inadecuada",
                  "Tiene sobrepeso o está demasiado delgado.",
                  "Recibe únicamente sobras o alimentos que no cubren sus necesidades.",
                  "No dispone de agua limpia.",
                  "Se le administran suplementos o medicamentos sin orientación veterinaria.",
                  "2. Falta de protección",
                  "Duerme en un lugar húmedo o demasiado frío.",
                  "Permanece expuesto al sol sin sombra ni agua.",
                  "Se le permite saltar desde alturas sin supervisión.",
                  "Puede escapar a la calle y exponerse a vehículos o animales agresivos.",
                  "3. Mala higiene",
                  "Presenta uñas demasiado largas, piel irritada o heridas sin tratar.",
                  "Tiene pulgas, garrapatas o picazón constante.",
                  "Presenta mal aliento intenso o dolor al masticar.",
                  "Su cama y sus recipientes están sucios de forma persistente.",
                  "4. Falta de atención médica",
                  "No recibe las vacunas recomendadas.",
                  "Tiene tos, diarrea, cojera o pérdida de peso sin evaluación.",
                  "Se utilizan productos antiparasitarios sin comprobar si son adecuados para su tamaño.",
                  "Se ignoran cambios importantes de comportamiento o de salud.",
                  "5. Falta de compañía y educación",
                  "Se le grita o golpea por cometer errores.",
                  "Pasa largos períodos aislado y sin actividad.",
                  "No se respetan sus señales de miedo o cansancio.",
                  "Se le obliga a interactuar con personas o animales que lo asustan."
                ]
              }
            ]
          },
          "comportamiento": {
            "titulo": "COMPORTAMIENTO",
            "secciones": [
              {
                "titulo": "ADIESTRAMIENTO Y MANTENIMIENTO DEL BUEN COMPORTAMIENTO EN LA EDAD ADULTA",
                "items": [
                  "Reforzar las órdenes básicas: Practicar “ven”, “siéntate”, “espera” y “quieto” con sesiones breves y recompensas. Practicar en distintos ambientes y aumentar gradualmente las distracciones.",
                  "Mantener una rutina estable: Establecer horarios regulares para comer, pasear, jugar y descansar. La consistencia facilita el aprendizaje y ayuda a prevenir el aburrimiento.",
                  "Caminar con correa sin tirar: Utilizar un arnés adecuado para su tamaño. Premiarlo cuando camine cerca y detenerse brevemente cuando tire. Evitar tirones fuertes sobre el cuello.",
                  "Controlar los ladridos: Identificar qué los provoca y premiar los momentos de calma. Ofrecer actividad física y mental adecuada, sin utilizar castigos que aumenten el miedo.",
                  "Prevenir la persecución de animales: Practicar la llamada en espacios seguros y utilizar correa en exteriores. No dejarlo suelto cerca de carreteras, ganado o animales que pueda perseguir.",
                  "Favorecer una convivencia segura: Permitir encuentros graduales con personas y perros compatibles. No obligarlo a saludar ni asumir que todos los perros se sentirán cómodos con su energía.",
                  "Practicar intercambios de objetos: Enseñarle a entregar juguetes a cambio de premios. Evitar quitarle los objetos por la fuerza, porque puede desarrollar conductas de protección.",
                  "Proporcionar estimulación mental: Incluir juegos de olfato, búsqueda de premios y ejercicios de obediencia. Las actividades deben ser seguras y adecuadas a su tamaño.",
                  "Enseñarle a quedarse solo: Acostumbrarlo progresivamente a ausencias cortas. Si presenta angustia intensa, vocalización persistente o intentos de escapar, consultar a un profesional.",
                  "Utilizar refuerzo positivo: Recompensar las conductas deseadas en lugar de recurrir a golpes, intimidación o herramientas que causen dolor. Las reglas deben ser consistentes entre todos los miembros de la familia.",
                  "Respetar su necesidad de descanso: Evitar interrumpirlo constantemente cuando duerme y no permitir que niños lo persigan o lo manipulen bruscamente.",
                  "Consultar ante cambios de conducta: Si comienza a gruñir, esconderse, evitar el contacto o reaccionar de forma inusual, descartar primero dolor o enfermedad antes de tratarlo como un problema de obediencia."
                ]
              },
              {
                "titulo": "CÓMO MEJORAR EL COMPORTAMIENTO DE TU MASCOTA SI NO FUE ADIESTRADO",
                "items": [
                  "1. Si ladra constantemente",
                  "Observar si reacciona a personas, sonidos, otros perros, miedo o aburrimiento.",
                  "Reducir temporalmente los estímulos que lo alteran y premiar los momentos de calma.",
                  "Enseñarle una señal sencilla para regresar junto a la persona.",
                  "Proporcionar paseos y juegos de olfato adecuados.",
                  "No gritarle ni utilizar dispositivos que le causen dolor.",
                  "2. Si muerde objetos",
                  "Retirar cables, zapatos y objetos peligrosos de su alcance.",
                  "Ofrecer juguetes seguros y apropiados para su tamaño.",
                  "Redirigirlo hacia el juguete permitido y premiarlo cuando lo utilice.",
                  "Evitar perseguirlo para quitarle el objeto.",
                  "Si ingiere un objeto peligroso, acudir al veterinario.",
                  "3. Si salta sobre las personas",
                  "Enseñarle a saludar con las cuatro patas en el suelo.",
                  "Premiar la calma y pedir a las visitas que sigan la misma regla.",
                  "Evitar empujarlo o gritarle, porque puede interpretar la reacción como atención.",
                  "Permitir el saludo cuando se haya calmado.",
                  "4. Si muestra miedo o agresividad",
                  "No obligarlo a acercarse a aquello que lo asusta.",
                  "Mantener una distancia segura y reducir las situaciones que desencadenan la reacción.",
                  "Recompensar gradualmente las respuestas tranquilas.",
                  "Consultar al veterinario para descartar dolor o enfermedad.",
                  "Si ha intentado morder, buscar ayuda profesional para trabajar de forma segura.",
                  "5. Si tira de la correa",
                  "Practicar en un lugar tranquilo con un arnés bien ajustado.",
                  "Premiar cuando camine con la correa floja.",
                  "Detenerse cuando tire y continuar cuando afloje la tensión.",
                  "Aumentar poco a poco la dificultad de los paseos.",
                  "Evitar soltarlo en espacios abiertos si no responde a la llamada.",
                  "6. Si hace sus necesidades dentro de casa",
                  "Establecer horarios regulares para salir o acudir al lugar designado.",
                  "Llevarlo después de dormir, comer y jugar.",
                  "Premiarlo inmediatamente cuando lo haga correctamente.",
                  "Limpiar los accidentes y evitar castigos.",
                  "Si el cambio es repentino, consultar al veterinario para descartar una causa médica.",
                  "7. Si protege la comida o sus juguetes",
                  "No quitarle objetos por la fuerza.",
                  "Alimentarlo en un lugar tranquilo y mantener alejados a los niños mientras come.",
                  "Practicar intercambios seguros con premios cuando sea apropiado.",
                  "No castigarlo por gruñir.",
                  "Buscar ayuda profesional si muestra amenazas intensas o intenta morder.",
                  "8. Si no obedece cuando lo llaman",
                  "Practicar primero en casa o en un espacio cerrado.",
                  "Utilizar una señal clara y recompensar generosamente cuando acuda.",
                  "No llamarlo únicamente para terminar actividades agradables o regañarlo.",
                  "Utilizar una correa larga de entrenamiento en lugares apropiados.",
                  "No dejarlo suelto cerca de calles hasta que su respuesta sea fiable."
                ]
              }
            ]
          },
          "vacunacion": {
            "titulo": "VACUNACIÓN",
            "secciones": [
              {
                "titulo": "TODAS LAS VACUNAS CON LAS QUE DEBERÍA CONTAR LA MASCOTA HASTA EL DÍA DE SU MUERTE",
                "items": [
                  "Vacuna contra el moquillo canino: Los perros adultos que completaron la serie de cachorro necesitan refuerzos según el producto y las recomendaciones veterinarias. No todas las vacunas requieren una dosis anual.",
                  "Vacuna contra el parvovirus canino: Mantener la protección frente a esta enfermedad es importante, especialmente si tiene contacto con otros perros o ambientes contaminados. Los refuerzos se programan según su historial y las guías veterinarias.",
                  "Vacuna contra el adenovirus canino: Suele formar parte de la vacuna combinada para perros. El veterinario revisará cuándo corresponde el refuerzo de acuerdo con el producto utilizado.",
                  "Vacuna contra la parainfluenza canina: Puede recomendarse para perros con contacto frecuente con otros animales. Su necesidad depende del estilo de vida y del riesgo de exposición.",
                  "Vacuna contra la leptospirosis: Puede ser importante en zonas con roedores, agua estancada, inundaciones o contacto con animales potencialmente infectados. Los refuerzos se programan según el producto y el riesgo local, a menudo de forma anual.",
                  "Vacuna contra la rabia: Debe mantenerse al día conforme a las disposiciones sanitarias vigentes en Bolivia y las indicaciones veterinarias. Es importante conservar el certificado de vacunación.",
                  "Vacuna contra la tos infecciosa canina: Puede considerarse si acude a guarderías, residencias, refugios o lugares donde se reúnen muchos perros. No todos los perros adultos la necesitan.",
                  "Vacunas adicionales según exposición: Algunas vacunas solo son útiles en determinadas regiones o circunstancias. El veterinario debe evaluar el riesgo y explicar por qué recomienda cada una.",
                  "Si tiene vacunas atrasadas: Revisar el carnet y establecer un plan de recuperación. No se debe asumir que está protegido ni aplicar vacunas al azar.",
                  "Durante toda la vida adulta: Mantener las fechas registradas y acudir a revisiones preventivas. La vacunación debe acompañarse de higiene, control de parásitos y atención veterinaria."
                ]
              }
            ]
          },
          "veterinario": {
            "titulo": "CUÁNDO IR AL VETERINARIO",
            "secciones": [
              {
                "titulo": "EN QUÉ SITUACIONES DE EMERGENCIA DEBES DE ACUDIR A UN VETERINARIO",
                "items": [
                  "Dificultad para respirar: La respiración trabajosa, el ahogo, las encías azuladas o el colapso requieren atención inmediata.",
                  "Vómitos repetidos o diarrea con sangre: Pueden causar deshidratación y señalar una enfermedad grave. La debilidad, el dolor y la incapacidad para retener agua aumentan la urgencia.",
                  "Sospecha de intoxicación: Ante la ingestión de chocolate, uvas, pasas, xilitol, medicamentos, venenos o productos químicos, contactar inmediatamente con un veterinario.",
                  "Atropello o golpe fuerte: Puede sufrir lesiones internas aunque no tenga heridas visibles. Debe evaluarse urgentemente.",
                  "Hemorragia o herida profunda: Aplicar presión suave con una gasa limpia mientras se organiza el traslado. No retirar objetos incrustados ni aplicar sustancias irritantes.",
                  "Convulsiones o pérdida del conocimiento: Apartar objetos peligrosos, no introducir nada en la boca y acudir inmediatamente a urgencias.",
                  "Abdomen hinchado con arcadas: Puede indicar una emergencia abdominal. No esperar a que la hinchazón desaparezca por sí sola.",
                  "Incapacidad para orinar: Si intenta hacerlo repetidamente sin conseguirlo, necesita atención inmediata.",
                  "Dolor intenso o incapacidad para caminar: Puede existir una lesión articular, fractura o problema neurológico. No obligarlo a caminar ni administrar analgésicos humanos.",
                  "Golpe de calor: Jadeo extremo, desorientación, vómitos, debilidad o colapso después de exponerse al calor requieren enfriamiento inicial seguro y traslado urgente.",
                  "Encías pálidas o amarillentas: Pueden indicar anemia, pérdida de sangre o enfermedad interna. Si se acompañan de debilidad o respiración acelerada, se trata de una emergencia.",
                  "Reacción alérgica grave: La hinchazón rápida de la cara, la dificultad respiratoria o el colapso después de una picadura o medicamento requieren atención inmediata.",
                  "Pérdida repentina del apetito con debilidad: Si deja de comer y además presenta temblores, vómitos, desorientación o decaimiento intenso, debe ser evaluado rápidamente.",
                  "Cambios repentinos de conducta: Si comienza a esconderse, gruñir al tocarlo o evitar movimientos habituales, puede sentir dolor o estar enfermo. Se debe investigar la causa.",
                  "Cambios marcados en la sed o la orina: Beber mucho más, orinar con sangre o esforzarse para hacerlo requiere evaluación veterinaria. La incapacidad para orinar es una emergencia.",
                  "Problemas oculares repentinos: Dolor, lesión, hinchazón o pérdida súbita de visión necesitan atención rápida.",
                  "Mordedura de un animal desconocido o posible exposición a la rabia: Buscar atención veterinaria y orientación sanitaria sin demora.",
                  "Deterioro rápido del estado general: Si se debilita en pocas horas, pierde el equilibrio, respira anormalmente o presenta varios síntomas a la vez, necesita atención inmediata."
                ]
              }
            ]
          },
        }
      },
      "senior": {
        "tituloOriginal": "PERRO PINSCHER – SENIOR O GERIÁTRICO (10 AÑOS EN ADELANTE, APROXIMADAMENTE)",
        "temas": {
          "alimentacion": {
            "titulo": "ALIMENTACIÓN",
            "secciones": [
              {
                "titulo": "ALIMENTACIÓN SALUDABLE",
                "items": [
                  "Alimento completo adecuado para perros mayores pequeños: Puede beneficiarse de una fórmula senior si se adapta a su salud y condición corporal. Algunos perros mayores necesitan menos calorías, mientras que otros requieren una dieta distinta por pérdida de peso, enfermedades o pérdida de musculatura. La elección debe hacerse de acuerdo con sus necesidades individuales.",
                  "Proteínas suficientes para conservar la musculatura: Los perros mayores pueden perder masa muscular con la edad. Por eso, no se debe reducir drásticamente la proteína sin una razón médica. Si tiene una enfermedad renal u otra condición, el veterinario debe determinar qué dieta resulta más adecuada.",
                  "Control de las calorías: Si se mueve menos, puede necesitar una ración más pequeña para evitar el sobrepeso. Sin embargo, si pierde peso o músculo, reducir la comida puede empeorar el problema. El veterinario puede ayudar a ajustar las cantidades.",
                  "Agua fresca y fácil de alcanzar: Debe disponer de agua potable durante todo el día. Si le cuesta levantarse, colocar el recipiente en un lugar accesible. Un aumento marcado de la sed no debe atribuirse simplemente a la vejez, porque puede indicar una enfermedad.",
                  "Comidas pequeñas y regulares: Dividir su ración en dos o más comidas puede facilitar la alimentación si tiene menor apetito o se cansa al comer. Si presenta náuseas, vómitos, dolor al masticar o dificultad para tragar, necesita una revisión veterinaria.",
                  "Textura adecuada a su salud dental: Si le faltan dientes o tiene sensibilidad en la boca, puede beneficiarse de alimento húmedo completo o croquetas humedecidas. Antes de asumir que necesita comida blanda, conviene comprobar si hay dolor dental tratable.",
                  "Dieta adaptada a sus enfermedades: Algunos perros mayores necesitan alimentos terapéuticos por problemas renales, cardíacos, digestivos o metabólicos. Estas dietas deben elegirse con el veterinario y no sustituirse por mezclas caseras sin una formulación profesional.",
                  "Premios pequeños y fáciles de masticar: Puede seguir recibiendo premios adecuados para perros, pero en cantidades moderadas. Evitar productos muy duros que puedan fracturar dientes y alimentos muy grasos que provoquen molestias digestivas.",
                  "Cambio gradual de alimentación: Introducir cualquier cambio de forma progresiva durante varios días si el perro está estable. Si deja de comer, vomita o pierde peso, no conviene seguir probando diferentes alimentos sin averiguar la causa.",
                  "Seguimiento del peso y la musculatura: Controlar su peso periódicamente y observar si las patas o la espalda parecen perder musculatura. Registrar estos cambios facilita que el veterinario detecte problemas antes de que se vuelvan graves."
                ]
              },
              {
                "titulo": "ALIMENTACIÓN NO SALUDABLE",
                "items": [
                  "Exceso de calorías: Los premios frecuentes, las sobras y las porciones demasiado grandes pueden producir sobrepeso. El peso excesivo aumenta la carga sobre las articulaciones y puede dificultar la respiración y la movilidad.",
                  "Comidas muy grasosas: Las frituras, los embutidos y los restos aceitosos pueden causar problemas digestivos y contribuir a la obesidad. En algunos perros, una comida muy grasa puede desencadenar pancreatitis.",
                  "Chocolate y cacao: Son tóxicos y pueden provocar alteraciones cardíacas y neurológicas. Si los consume, contactar inmediatamente con el veterinario.",
                  "Uvas y pasas: Pueden causar daño renal grave. Nunca deben utilizarse como premio y cualquier ingestión requiere orientación veterinaria urgente.",
                  "Cebolla y ajo: Pueden dañar los glóbulos rojos y causar anemia. No se deben agregar deliberadamente a su alimentación.",
                  "Productos con xilitol: Algunos productos sin azúcar contienen este ingrediente, que puede provocar una bajada peligrosa de glucosa y daño hepático. Mantenerlos fuera de su alcance.",
                  "Huesos cocidos y objetos muy duros: Pueden causar atragantamiento, obstrucciones o fracturas dentales. Si tiene problemas en la boca, elegir texturas apropiadas y consultar al veterinario.",
                  "Dietas caseras incompletas: Una alimentación basada únicamente en carne, arroz, pollo o sopa puede carecer de nutrientes esenciales. Si se desea una dieta casera, debe formularse de manera profesional.",
                  "Suplementos y medicamentos sin indicación: Las vitaminas, el calcio, los suplementos articulares y los medicamentos humanos no son automáticamente seguros para un perro senior. Pueden interactuar con sus tratamientos o empeorar enfermedades existentes."
                ]
              }
            ]
          },
          "salud": {
            "titulo": "SALUD",
            "secciones": [
              {
                "titulo": "TIENE BUENA SALUD",
                "items": [
                  "Mantiene interés por su entorno: Puede jugar durante períodos más cortos y descansar más, pero sigue mostrando interés por su familia, los olores y las actividades que disfruta.",
                  "Conserva un peso relativamente estable: No pierde peso rápidamente ni desarrolla sobrepeso importante. También debe observarse la musculatura, porque puede perder músculo aunque el peso total no cambie demasiado.",
                  "Come y bebe de manera habitual: Mantiene un apetito razonable y no presenta dificultades para masticar o tragar. Los cambios persistentes en el apetito o la sed necesitan revisión.",
                  "Puede levantarse y caminar con comodidad razonable: Puede necesitar más tiempo para incorporarse, pero no debería sufrir dolor intenso, caídas frecuentes ni pérdida repentina de movilidad.",
                  "Respira cómodamente en reposo: No presenta dificultad respiratoria, tos persistente ni desmayos. El jadeo excesivo en reposo o la respiración trabajosa necesitan evaluación.",
                  "Mantiene la piel en condiciones aceptables: No presenta heridas persistentes, picazón intensa ni bultos que crecen rápidamente sin revisión. Los cambios del pelaje pueden ocurrir con la edad, pero no deben ignorarse las lesiones.",
                  "Orina y defeca sin dolor: No presenta sangre, esfuerzo excesivo ni cambios persistentes en la frecuencia. Si comienza a beber mucho más o tiene accidentes dentro de casa, conviene consultar.",
                  "Conserva una conducta reconocible: Puede estar más tranquilo, pero sigue respondiendo a sus rutinas y mostrando interés por la familia. Los cambios marcados de memoria, orientación o interacción deben evaluarse."
                ]
              },
              {
                "titulo": "TIENE MALA SALUD",
                "items": [
                  "Pierde peso o musculatura: Puede estar relacionado con problemas dentales, enfermedades crónicas, alteraciones metabólicas u otras causas. La pérdida involuntaria de peso necesita una revisión veterinaria.",
                  "Tiene dificultad para levantarse o caminar: La rigidez, la cojera, el rechazo a subir escalones o el dolor al tocar las articulaciones pueden indicar artritis u otros problemas. Existen tratamientos y adaptaciones que pueden mejorar su comodidad.",
                  "Presenta tos o dificultad respiratoria: La tos persistente, la respiración acelerada en reposo o el esfuerzo para respirar pueden indicar problemas cardíacos, respiratorios u otras enfermedades. La dificultad respiratoria es una emergencia.",
                  "Tiene problemas dentales: El mal aliento intenso, las encías inflamadas, el babeo o el rechazo de alimentos duros pueden indicar dolor. Una evaluación dental puede mejorar su alimentación y calidad de vida.",
                  "Bebe u orina mucho más: Puede estar relacionado con problemas renales, diabetes u otras enfermedades. No se debe restringir el agua; se necesita una evaluación para determinar la causa.",
                  "Presenta cambios de visión u oído: Puede empezar a chocar con objetos, no responder a sonidos o asustarse cuando alguien se acerca por detrás. Conviene adaptar el entorno y consultar para distinguir cambios sensoriales de problemas tratables.",
                  "Tiene confusión o cambios de conducta: Si se desorienta en lugares conocidos, altera su horario de sueño o parece olvidar rutinas, puede existir deterioro cognitivo u otra enfermedad. El veterinario puede evaluar las causas y las opciones de manejo.",
                  "Tiene bultos o heridas que no cicatrizan: Los bultos nuevos, las lesiones que crecen o las heridas que sangran deben revisarse. No todos los bultos son malignos, pero no se puede determinar su naturaleza solo por la apariencia.",
                  "Se muestra muy decaído o deja de comer: La falta de apetito, el aislamiento y la debilidad pueden indicar dolor o enfermedad. No se debe atribuir automáticamente todo cambio a la edad."
                ]
              }
            ]
          },
          "primeros": {
            "titulo": "PRIMEROS AUXILIOS",
            "secciones": [
              {
                "titulo": "QUÉ HACER CUANDO LE SUCEDEN ACCIDENTES COMO:",
                "items": [
                  "1. Caídas y golpes",
                  "Evitar que siga caminando si presenta dolor o dificultad para levantarse.",
                  "Comprobar si está consciente y respira normalmente.",
                  "Si se sospecha una lesión de columna, pelvis o patas, moverlo lo mínimo posible.",
                  "Aplicar presión suave con una gasa limpia si existe sangrado externo.",
                  "No intentar enderezar articulaciones ni forzarlo a ponerse de pie.",
                  "Acudir urgentemente al veterinario después de un golpe importante, especialmente si hay dolor intenso, debilidad o dificultad respiratoria.",
                  "2. Heridas y sangrado",
                  "Mantenerlo tranquilo y evitar que lama la lesión.",
                  "Aplicar presión continua con una gasa limpia.",
                  "No retirar objetos incrustados ni aplicar alcohol, polvos o remedios caseros.",
                  "Las heridas profundas, las mordeduras y las hemorragias persistentes requieren atención inmediata.",
                  "Informar al veterinario sobre sus enfermedades y medicamentos habituales.",
                  "3. Atragantamiento",
                  "Si puede toser y respirar, permitirle toser mientras se busca orientación veterinaria.",
                  "Si no puede respirar, se desploma o sus encías se vuelven azuladas, acudir inmediatamente a urgencias.",
                  "Retirar un objeto solo si está claramente visible y se puede alcanzar sin empujarlo más profundamente.",
                  "No introducir los dedos a ciegas ni darle comida o agua para intentar desplazar el objeto.",
                  "Si persisten la tos, las arcadas o la respiración anormal, necesita una evaluación.",
                  "4. Intoxicación",
                  "Alejarlo de la sustancia y evitar nuevas exposiciones.",
                  "Identificar el producto y guardar el envase o fotografiar la etiqueta.",
                  "Contactar inmediatamente con el veterinario.",
                  "No provocar el vómito ni administrar leche, aceite, sal, carbón activado o medicamentos por cuenta propia.",
                  "Si presenta convulsiones, dificultad respiratoria, desmayo o debilidad intensa, trasladarlo a urgencias.",
                  "5. Quemaduras",
                  "Alejarlo de la fuente de calor o del producto químico.",
                  "En una quemadura térmica pequeña, enfriar la zona con agua corriente fresca durante unos 20 minutos si puede hacerse sin retrasar la atención.",
                  "No aplicar hielo, mantequilla, pasta dental ni cremas humanas.",
                  "Cubrir ligeramente la lesión con un material limpio que no se adhiera y acudir al veterinario.",
                  "Las quemaduras extensas o las que afectan la cara, los ojos, las patas o los genitales requieren atención urgente.",
                  "6. Picaduras y mordeduras",
                  "Alejarlo del animal o insecto y observar su respiración y estado general.",
                  "Si presenta hinchazón rápida de la cara, dificultad respiratoria, debilidad o colapso, acudir inmediatamente a urgencias.",
                  "No administrar antihistamínicos ni medicamentos humanos sin indicación veterinaria.",
                  "Las mordeduras necesitan revisión aunque las heridas exteriores sean pequeñas.",
                  "Si hay sospecha de rabia, contactar con el veterinario y solicitar orientación sanitaria.",
                  "7. Vómitos y diarrea",
                  "Observar la frecuencia, la presencia de sangre y los signos de dolor o debilidad.",
                  "No administrar antidiarreicos ni antibióticos humanos.",
                  "Si está alerta y no vomita repetidamente, se puede ofrecer una pequeña cantidad de agua mientras se consulta.",
                  "No someterlo a ayunos prolongados sin indicación veterinaria, especialmente si tiene enfermedades crónicas.",
                  "Acudir urgentemente si hay sangre, vómitos repetidos, dolor abdominal, debilidad o incapacidad para retener agua.",
                  "8. Golpe de calor",
                  "Trasladarlo a un lugar fresco y ventilado.",
                  "Mojar suavemente el cuerpo con agua fresca, no helada, y utilizar ventilación.",
                  "No cubrirlo con toallas mojadas que acumulen calor ni obligarlo a beber si está desorientado.",
                  "Acudir urgentemente al veterinario si jadea intensamente, vomita, se tambalea o se desploma.",
                  "Los perros mayores pueden tolerar peor las temperaturas extremas, especialmente si padecen enfermedades cardíacas o respiratorias."
                ]
              }
            ]
          },
          "cuidados": {
            "titulo": "CUIDADOS",
            "secciones": [
              {
                "titulo": "CÓMO MANTENERLO BIEN CUIDADO",
                "items": [
                  "Proporcionar una cama cómoda y cálida: Debe tener una cama limpia, seca y protegida del frío. El pinscher tiene pelo corto y puede necesitar una manta ligera o una prenda apropiada cuando hace frío, siempre que no le limite el movimiento ni le irrite la piel.",
                  "Facilitar el acceso a comida y agua: Colocar los recipientes en lugares fáciles de alcanzar. Si le cuesta agacharse o levantarse, consultar si conviene modificar la altura de los recipientes.",
                  "Mantener una alimentación adaptada: Elegir la dieta según su peso, salud dental y enfermedades. No reducir automáticamente la comida por su edad; la pérdida de músculo también puede perjudicarlo.",
                  "Realizar ejercicio suave: Ofrecer paseos cortos, juegos tranquilos y actividades de olfato. Ajustar la duración a su resistencia y detener la actividad si aparece dolor, jadeo excesivo o debilidad.",
                  "Proteger las articulaciones: Utilizar superficies antideslizantes y evitar saltos desde muebles altos. Facilitar rampas seguras si necesita subir a lugares que utiliza habitualmente, siempre que pueda hacerlo sin riesgo.",
                  "Realizar controles veterinarios frecuentes: Los perros mayores pueden beneficiarse de revisiones al menos cada seis meses, o con mayor frecuencia si tienen enfermedades crónicas. El veterinario decidirá si necesita análisis de sangre, orina, evaluación dental u otros estudios.",
                  "Mantener sus tratamientos: Si tiene una enfermedad crónica, seguir las indicaciones veterinarias y no cambiar las dosis por cuenta propia. Informar sobre cualquier suplemento o medicamento que esté recibiendo.",
                  "Cuidar los dientes: Cepillarlos con productos formulados para perros y consultar si hay mal aliento intenso, dolor o dificultad para comer. No intentar retirar el sarro con objetos cortantes.",
                  "Cepillar su pelaje con delicadeza: El cepillado suave ayuda a retirar pelo suelto y permite revisar la piel. Observar si hay bultos, heridas, irritación o cambios que requieran una consulta.",
                  "Mantener uñas y patas en buen estado: Las uñas demasiado largas pueden dificultar la marcha. Revisar también las almohadillas y acudir a un profesional si no se sabe cortar las uñas con seguridad.",
                  "Adaptar el ambiente si ve u oye menos: Mantener los muebles en lugares estables, bloquear escaleras peligrosas y acercarse de manera que pueda notar a la persona sin sobresaltarse. Utilizar señales visuales o táctiles suaves cuando sea necesario.",
                  "Ayudarlo con la higiene: Si le cuesta levantarse, facilitar salidas más frecuentes para hacer sus necesidades. Limpiar y secar la piel si se moja o ensucia para evitar irritaciones.",
                  "Proporcionar compañía y estimulación mental: Ofrecer contacto afectuoso, juegos sencillos y actividades de olfato. Aunque sea mayor, necesita interacción familiar y oportunidades de explorar de forma segura.",
                  "Protegerlo del frío y del calor: Evitar que duerma en el suelo húmedo o permanezca al sol sin sombra. Su pelo corto puede hacerlo más sensible al frío y su edad puede reducir su tolerancia a temperaturas extremas.",
                  "Vigilar cambios de salud: Registrar variaciones de peso, apetito, sed, orina, heces, movilidad y comportamiento. Los cambios persistentes deben comentarse con el veterinario.",
                  "Mantener vacunas y prevención de parásitos: La edad no elimina la necesidad de protección. El veterinario debe adaptar el calendario y los productos a su historial y condición de salud."
                ]
              },
              {
                "titulo": "CÓMO SABER SI NO TIENE UN BUEN CUIDADO",
                "items": [
                  "1. Falta de comodidad",
                  "Su cama es dura, húmeda o está expuesta a temperaturas extremas.",
                  "Debe saltar o subir escaleras para llegar al agua, aunque le cueste moverse.",
                  "Se resbala constantemente y no cuenta con un ambiente adaptado.",
                  "Se ignoran sus dificultades para levantarse, caminar o mantener la higiene.",
                  "2. Alimentación inadecuada",
                  "Pierde peso o musculatura sin que se investigue la causa.",
                  "Tiene sobrepeso que dificulta caminar.",
                  "No dispone de agua limpia y accesible.",
                  "Recibe suplementos o medicamentos sin evaluación veterinaria.",
                  "3. Falta de atención médica",
                  "Se ignoran la tos, el dolor, la cojera o los cambios de sed.",
                  "No recibe revisiones preventivas.",
                  "Tiene dientes dolorosos, heridas o bultos que no se evalúan.",
                  "Se suspenden tratamientos sin consultar al veterinario.",
                  "4. Mala higiene",
                  "Su pelaje está sucio o presenta lesiones sin tratar.",
                  "Tiene uñas demasiado largas que dificultan caminar.",
                  "Presenta mal olor intenso o irritación persistente.",
                  "No se mantiene limpia su cama cuando tiene problemas de movilidad.",
                  "5. Aislamiento o falta de respeto por sus límites",
                  "Se le obliga a correr o saltar a pesar del dolor.",
                  "Se le castiga por accidentes relacionados con una enfermedad.",
                  "Pasa largos períodos sin compañía ni atención.",
                  "Se ignoran sus señales de miedo, dolor o cansancio."
                ]
              }
            ]
          },
          "comportamiento": {
            "titulo": "COMPORTAMIENTO",
            "secciones": [
              {
                "titulo": "ADIESTRAMIENTO Y ESTIMULACIÓN EN LA ETAPA SENIOR",
                "items": [
                  "Mantener las órdenes que ya conoce: Practicar señales sencillas como “ven”, “espera” y “siéntate” en sesiones breves. Adaptar los ejercicios si tiene dolor articular, pérdida de audición o dificultades de visión.",
                  "Reforzar la conducta tranquila: Premiar cuando descansa, espera o se acerca sin saltar. Las recompensas pueden ser elogios, caricias si las disfruta o pequeñas porciones de alimento apropiado.",
                  "Utilizar juegos de olfato: Esconder pequeñas porciones de su alimento en lugares fáciles y seguros para que las encuentre. Estas actividades estimulan la mente sin exigir carreras ni saltos.",
                  "Mantener una rutina predecible: Procurar horarios regulares para las comidas, los paseos, el descanso y los medicamentos. Las rutinas conocidas pueden reducir la confusión y la inquietud.",
                  "Adaptar los paseos: Elegir trayectos cortos, superficies seguras y horarios con temperaturas moderadas. Permitirle olfatear y descansar cuando lo necesite, sin obligarlo a continuar si está cansado.",
                  "Evitar castigos por accidentes: Si comienza a hacer sus necesidades dentro de casa, revisar primero si tiene problemas urinarios, dolor o dificultad para desplazarse. Facilitarle salidas más frecuentes y premiarlo cuando lo haga en el lugar correcto.",
                  "Mantener el contacto social: Permitir que interactúe con personas conocidas y animales tranquilos, respetando sus límites. Si ve u oye menos, acercarse con suavidad para evitar que se sobresalte.",
                  "Practicar la manipulación con calma: Si necesita cepillado o revisión de las patas, realizarlo en sesiones cortas y detenerse si muestra dolor. Puede necesitar ayuda profesional para los cuidados que le resulten difíciles.",
                  "Evitar cambios bruscos en su ambiente: Mantener los muebles y las rutas de acceso lo más estables posible. Si se necesita cambiar algo, hacerlo gradualmente cuando sea posible.",
                  "Reconocer los signos de dolor: Si empieza a gruñir cuando lo tocan, evita ciertas actividades o se aparta, no castigarlo. El dolor puede modificar su comportamiento y necesita evaluación veterinaria.",
                  "Ofrecer actividades adecuadas a su capacidad: Los juegos deben ser sencillos y seguros. Evitar lanzamientos que lo obliguen a girar bruscamente, saltar o correr sobre superficies resbaladizas.",
                  "Buscar ayuda ante cambios cognitivos: Si se desorienta, se queda atrapado en esquinas, altera su horario de sueño o parece olvidar rutinas, consultar al veterinario. Algunos problemas pueden manejarse mejor cuando se identifican temprano."
                ]
              },
              {
                "titulo": "CÓMO MEJORAR EL COMPORTAMIENTO DE TU MASCOTA SI NO FUE ADIESTRADO",
                "items": [
                  "1. Si está inquieto o camina de un lado a otro",
                  "Comprobar si necesita salir, beber, descansar o recibir atención.",
                  "Observar si presenta dolor, dificultad para respirar o molestias al acostarse.",
                  "Mantener un ambiente tranquilo y una rutina predecible.",
                  "Ofrecer una actividad suave de olfato si su estado físico lo permite.",
                  "Si la inquietud aparece de repente o empeora por la noche, consultar al veterinario.",
                  "2. Si comienza a hacer sus necesidades dentro de casa",
                  "No castigarlo ni asumir que lo hace por desobediencia.",
                  "Facilitar salidas más frecuentes y un trayecto seguro hacia el exterior.",
                  "Limpiar las zonas sucias con productos adecuados.",
                  "Registrar si bebe más, orina en pequeñas cantidades o parece tener dolor.",
                  "Solicitar una evaluación veterinaria, especialmente si el cambio es reciente.",
                  "3. Si se vuelve irritable o gruñe",
                  "Respetar su espacio y no obligarlo a recibir caricias.",
                  "Evitar tocar las zonas que parecen dolorosas.",
                  "Mantener a los niños alejados mientras come o descansa.",
                  "No castigar el gruñido, porque es una señal de advertencia.",
                  "Consultar al veterinario para descartar dolor, problemas dentales o pérdida sensorial.",
                  "4. Si parece desorientado",
                  "Mantener los muebles y las rutas de acceso estables.",
                  "Bloquear escaleras y lugares donde pueda quedar atrapado o lesionarse.",
                  "Utilizar luces suaves durante la noche y facilitar el acceso a su cama y al agua.",
                  "Acercarse con calma y hablarle antes de tocarlo.",
                  "Consultar si la desorientación es nueva, frecuente o va empeorando.",
                  "5. Si ladra durante la noche",
                  "Comprobar si necesita salir, tiene frío, siente dolor o está desorientado.",
                  "Asegurar que su cama sea cómoda y que pueda llegar al agua.",
                  "Mantener una rutina nocturna tranquila.",
                  "No castigarlo si puede estar expresando una necesidad.",
                  "Si el comportamiento es nuevo o persistente, consultar al veterinario.",
                  "6. Si tiene miedo de las personas o los ruidos",
                  "Acercarse con suavidad y permitirle notar la presencia de la persona.",
                  "Evitar movimientos bruscos y no despertarlo tocándolo de repente.",
                  "Proporcionarle un lugar tranquilo donde pueda retirarse.",
                  "Recompensar la calma y permitirle acercarse a su propio ritmo.",
                  "Adaptar las señales si ha perdido visión o audición.",
                  "7. Si ya no responde a las órdenes",
                  "Comprobar si oye y ve adecuadamente antes de pensar que está desobedeciendo.",
                  "Utilizar señales visuales o táctiles suaves que pueda reconocer.",
                  "Practicar ejercicios sencillos en lugares sin distracciones.",
                  "Recompensar cada respuesta correcta y evitar sesiones largas.",
                  "Consultar si la pérdida de respuesta es repentina.",
                  "8. Si tiene dificultades para quedarse solo",
                  "Mantener horarios previsibles y un espacio cómodo.",
                  "Dejarle agua, cama y acceso seguro a sus necesidades.",
                  "Evitar ausencias prolongadas si muestra angustia intensa, cuando sea posible.",
                  "Solicitar ayuda profesional si presenta vocalizaciones persistentes, destrucción o signos claros de ansiedad.",
                  "No utilizar castigos ni métodos que aumenten el miedo."
                ]
              }
            ]
          },
          "vacunacion": {
            "titulo": "VACUNACIÓN",
            "secciones": [
              {
                "titulo": "TODAS LAS VACUNAS CON LAS QUE DEBERÍA CONTAR LA MASCOTA HASTA EL DÍA DE SU MUERTE",
                "items": [
                  "Vacuna contra el moquillo canino: Los perros senior que completaron correctamente la serie inicial pueden necesitar refuerzos según el producto y las recomendaciones veterinarias. La edad avanzada no significa automáticamente que deba suspenderse.",
                  "Vacuna contra el parvovirus canino: Mantener la protección frente al parvovirus sigue siendo importante. Los refuerzos deben programarse según su historial, la vacuna utilizada y las recomendaciones veterinarias.",
                  "Vacuna contra el adenovirus canino: Generalmente forma parte de la vacuna combinada. El veterinario revisará el historial y decidirá cuándo corresponde el refuerzo.",
                  "Vacuna contra la parainfluenza canina: Puede considerarse si tiene contacto frecuente con otros perros. La necesidad depende de su estilo de vida y exposición.",
                  "Vacuna contra la leptospirosis: Puede ser importante si existe exposición a roedores, agua estancada, inundaciones o animales potencialmente infectados. La frecuencia de los refuerzos depende del producto y del riesgo local.",
                  "Vacuna contra la rabia: Debe mantenerse según las disposiciones sanitarias vigentes en Bolivia y las indicaciones veterinarias. Es importante conservar el certificado de vacunación.",
                  "Vacuna contra la tos infecciosa canina: Puede recomendarse si frecuenta lugares donde se reúnen muchos perros. No todos los perros mayores la necesitan.",
                  "Evaluación antes de vacunar: Si tiene una enfermedad crónica, recibe tratamientos o presenta síntomas, el veterinario debe evaluar su estado y decidir el momento apropiado para vacunar.",
                  "Revisión de los registros: Si se perdió el carnet o se desconoce su historial, solicitar un plan individual. No se deben aplicar vacunas al azar ni asumir que está protegido.",
                  "Prevención durante la vejez: Mantener el control de parásitos, la higiene, la alimentación adecuada y las revisiones médicas. Las vacunas son una parte importante de la prevención, pero no sustituyen los demás cuidados."
                ]
              }
            ]
          },
          "veterinario": {
            "titulo": "CUÁNDO IR AL VETERINARIO",
            "secciones": [
              {
                "titulo": "EN QUÉ SITUACIONES DE EMERGENCIA DEBES DE ACUDIR A UN VETERINARIO",
                "items": [
                  "Dificultad para respirar: La respiración trabajosa, el ahogo, las encías azuladas o el colapso requieren atención inmediata.",
                  "Vómitos repetidos o diarrea con sangre: Pueden causar deshidratación y señalar una enfermedad grave. Si está débil o no puede retener agua, acudir urgentemente.",
                  "Sospecha de intoxicación: Ante la ingestión de medicamentos, chocolate, uvas, pasas, xilitol, venenos o productos químicos, contactar inmediatamente con un veterinario.",
                  "Atropello o golpe fuerte: Puede sufrir lesiones internas aunque no haya heridas visibles. Debe ser evaluado urgentemente.",
                  "Sangrado abundante: Aplicar presión suave con una gasa limpia y trasladarlo a urgencias. No retirar objetos incrustados ni aplicar sustancias irritantes.",
                  "Convulsiones o pérdida del conocimiento: Apartar los objetos peligrosos, no introducir nada en la boca y buscar atención inmediata.",
                  "Abdomen hinchado con arcadas: Puede indicar una emergencia abdominal potencialmente mortal. No esperar a que disminuya la hinchazón.",
                  "Incapacidad para orinar: Si intenta hacerlo repetidamente sin conseguirlo, necesita atención inmediata.",
                  "Dolor intenso o incapacidad para levantarse: Puede indicar una lesión o una enfermedad grave. No forzarlo a caminar ni administrar analgésicos humanos.",
                  "Golpe de calor: Jadeo extremo, desorientación, vómitos, debilidad o colapso después de exponerse al calor requieren enfriamiento inicial seguro y traslado urgente.",
                  "Encías muy pálidas o amarillentas: Pueden indicar anemia, pérdida de sangre o enfermedad interna. Si se acompañan de debilidad o respiración acelerada, es una emergencia.",
                  "Reacción alérgica grave: La hinchazón rápida de la cara, la dificultad respiratoria o el colapso después de una picadura o medicamento requieren atención inmediata.",
                  "Desorientación repentina: Si deja de reconocer el entorno, camina de forma inestable o parece confundido de repente, debe evaluarse urgentemente.",
                  "Pérdida marcada de apetito o debilidad: Si deja de comer, está muy decaído o pierde peso sin explicación, necesita una consulta pronta. Si no puede beber, vomita repetidamente o se desploma, acudir a urgencias.",
                  "Cambios importantes en la sed y la orina: Beber mucho más, orinar en exceso o presentar sangre en la orina requiere evaluación. La incapacidad para orinar es una emergencia inmediata.",
                  "Bultos que crecen o heridas que no cicatrizan: Los bultos nuevos, el crecimiento rápido, el sangrado y las lesiones persistentes deben revisarse sin demora.",
                  "Exposición posible a la rabia: Si lo muerde un animal sospechoso o tiene contacto con saliva potencialmente infectada, buscar atención veterinaria y orientación sanitaria inmediatamente.",
                  "Deterioro rápido del estado general: Si en pocas horas pierde la movilidad, respira anormalmente, se desorienta o presenta varios síntomas a la vez, necesita atención inmediata.",
                  "Dolor persistente que afecta su vida diaria: Si evita caminar, no puede dormir cómodamente o pierde interés por las actividades habituales, necesita una consulta para mejorar su comodidad y calidad de vida.",
                  "Cambios repentinos en su comportamiento: Si se vuelve muy irritable, se esconde constantemente o rechaza que lo toquen, no debe atribuirse automáticamente a la edad. El dolor y otras enfermedades pueden modificar la conducta y requieren evaluación."
                ]
              }
            ]
          }
        },
      }
    }
  },
  "goldenretriever": {
  "nombre": "Golden Retriever",
  "descripcion": "El Golden Retriever es una raza de perro conocida por su pelaje dorado, su inteligencia y su carácter amigable. Es de tamaño mediano a grande, juguetón y cariñoso. En Bolivia, muchas familias lo eligen como mascota por ser sociable, leal y fácil de entrenar.",
  "etapas": {
    "cachorro": {
      "tituloOriginal": "Golden Retriever – Etapa CACHORRO (hasta los 12–18 meses)",
      "temas": {
        "alimentacion": {
          "titulo": "Alimentación",
          "secciones": [
            {
              "titulo": "ALIMENTACIÓN SALUDABLE",
              "items": [
                "Usa un alimento completo y equilibrado para cachorros de razas grandes, adecuado para su crecimiento. No es obligatorio que la carne sea el primer ingrediente: lo importante es que el alimento cumpla los estándares nutricionales y sea apropiado para su etapa de vida.",
                "Sigue la ración orientativa del envase y ajústala según su peso, condición corporal y crecimiento, con ayuda del veterinario. Pesa la comida para controlar mejor las cantidades.",
                "Como pauta práctica, ofrece 3–4 comidas al día cuando es muy pequeño; después puedes pasar a 3 y, más adelante, a 2 comidas, según su edad y tolerancia.",
                "Usa como premios pequeños trozos de pollo o pavo bien cocidos, sin huesos ni condimentos, o zanahoria. Los premios no deben superar aproximadamente el 10 % de sus calorías diarias.",
                "Puedes ofrecer un poco de calabaza cocida y sin condimentos si la tolera, pero no es necesaria para una dieta equilibrada.",
                "No añadas aceite de pescado, calcio ni otros suplementos sin consultar al veterinario. Un alimento completo para cachorros de razas grandes ya está formulado para cubrir sus necesidades.",
                "Si cambias de alimento, hazlo gradualmente durante unos 7–10 días, siempre que el veterinario no indique otra cosa.",
                "Mantén agua limpia y fresca disponible en todo momento.",
                "Comprueba periódicamente su condición corporal: las costillas deben poder palparse sin quedar excesivamente marcadas y debe observarse una cintura desde arriba.",
                "Evita que crezca con exceso de peso, ya que una carga corporal elevada puede aumentar el esfuerzo sobre sus articulaciones durante el desarrollo.",
                "No le ofrezcas comida mientras está jugando intensamente o haciendo ejercicio. Procura que coma en un ambiente tranquilo y pueda descansar después."
              ]
            },
            {
              "titulo": "ALIMENTACIÓN NO SALUDABLE",
              "items": [
                "Uvas y pasas: pueden causar daño renal grave.",
                "Chocolate, café y otros productos con cafeína: pueden ser tóxicos.",
                "Cebolla, ajo y puerro: pueden dañar los glóbulos rojos.",
                "Xilitol, presente en algunos productos sin azúcar: puede provocar una intoxicación grave.",
                "Huesos cocidos: pueden astillarse y causar obstrucciones o lesiones.",
                "Comida muy grasa, frita o condimentada: puede causar trastornos digestivos y pancreatitis.",
                "Demasiados premios o sobras: favorecen el sobrepeso.",
                "Leche de vaca en cantidad: puede causar diarrea.",
                "Suplementos de calcio sin indicación veterinaria: pueden alterar el equilibrio mineral durante el crecimiento.",
                "Alimentos en mal estado o con moho: pueden provocar intoxicaciones y problemas digestivos.",
                "Dietas caseras improvisadas basadas solamente en carne, arroz o verduras: pueden no aportar todos los nutrientes que necesita para desarrollarse.",
                "Cambios repentinos de alimento: pueden provocar molestias digestivas, como diarrea, gases o vómitos."
              ]
            }
          ]
        },
        "salud": {
          "titulo": "Salud",
          "secciones": [
            {
              "titulo": "SEÑALES DE BUENA SALUD",
              "items": [
                "Tiene energía, curiosidad y ganas de jugar, con periodos de descanso adecuados.",
                "Come y bebe con normalidad.",
                "Crece de forma constante sin ganar peso excesivamente rápido.",
                "Tiene ojos claros, piel sana y oídos sin mal olor.",
                "Mantiene una condición corporal adecuada; no debería verse excesivamente gordo.",
                "Camina, corre y juega sin cojear ni mostrar molestias evidentes.",
                "Su pelaje se mantiene limpio y no presenta zonas extensas de pérdida de pelo.",
                "Sus heces tienen una consistencia habitual y no presenta diarrea persistente.",
                "Se recupera normalmente después de jugar y no muestra cansancio exagerado ante actividades suaves.",
                "Responde a los sonidos, las personas y los estímulos de su entorno de acuerdo con su edad."
              ]
            },
            {
              "titulo": "PROBLEMAS DE SALUD A VIGILAR",
              "items": [
                "Displasia de cadera y codo, problemas ortopédicos a los que la raza está predispuesta.",
                "Sobrepeso, que puede aumentar la carga sobre las articulaciones.",
                "Otitis, especialmente si presenta humedad, picor, secreción o mal olor.",
                "Alergias y problemas de piel.",
                "Problemas dentales y acumulación de sarro.",
                "Dilatación-vólvulo gástrico, una urgencia que también puede afectar a perros jóvenes.",
                "Enfermedades hereditarias; conviene hablar con el veterinario sobre los controles preventivos apropiados para la raza.",
                "Cojera o rigidez después del descanso, que puede indicar molestias articulares o lesiones.",
                "Infecciones intestinales y parásitos, que pueden afectar su crecimiento y provocar diarrea, vómitos o pérdida de peso.",
                "Problemas oculares, como irritación, enrojecimiento o secreciones persistentes.",
                "Alteraciones del crecimiento relacionadas con una alimentación inadecuada o un exceso de peso.",
                "Cualquier cambio persistente en su apetito, actividad, comportamiento o forma de caminar debe comentarse con el veterinario."
              ]
            }
          ]
        },
        "primeros": {
          "titulo": "Primeros auxilios",
          "secciones": [
            {
              "titulo": "QUÉ HACER ANTE ACCIDENTES O SÍNTOMAS PREOCUPANTES",
              "items": [
                "Los primeros auxilios sirven para proteger al cachorro mientras recibe atención profesional. No sustituyen la evaluación de un veterinario.",
                "Caída o salto: limita la actividad y observa si cojea o siente dolor. Si la cojera es intensa, no apoya una pata o hay deformidad, acude urgentemente al veterinario. Si es leve pero persiste, consulta ese mismo día.",
                "Herida: si es superficial, enjuaga suavemente con suero fisiológico o agua limpia. Si sangra, aplica presión continua con una gasa limpia. Las heridas profundas, mordeduras o hemorragias importantes requieren atención veterinaria.",
                "Intoxicación: aparta el producto, guarda el envase y contacta de inmediato con un veterinario. No provoques el vómito ni administres remedios caseros.",
                "Vómitos o diarrea: ofrece agua en pequeñas cantidades si puede beber sin vomitar y consulta si los síntomas se repiten. En un cachorro, la sangre, el decaimiento, el dolor, la deshidratación o la incapacidad para retener agua requieren atención urgente. No lo dejes en ayunas sin indicación veterinaria.",
                "Golpe de calor: llévalo a un lugar fresco, comienza a enfriarlo con agua fresca —no helada— y busca atención veterinaria urgente.",
                
              ]
            },
             {
              "titulo": "QUÉ HACER ANTE ACCIDENTES O SÍNTOMAS PREOCUPANTES",
              "items": [
                
                "Abdomen hinchado, arcadas sin vomitar o inquietud intensa: posible dilatación-vólvulo gástrico. Es una emergencia; no esperes a que se le pase.",
                "Picadura de insecto: observa si aparece hinchazón, dolor o picazón. Si presenta hinchazón de la cara, dificultad para respirar o debilidad repentina, necesita atención veterinaria inmediata.",
                "Atragantamiento: si tiene dificultad para respirar o no puede expulsar un objeto, solicita ayuda veterinaria de emergencia. No introduzcas los dedos a ciegas en su garganta.",
                "Convulsiones: retira los objetos cercanos para evitar golpes, no intentes sujetar su lengua ni introduzcas las manos en su boca. Contacta inmediatamente con un veterinario.",
                "Sangrado de una uña: si se lastima una uña, mantén al cachorro tranquilo y solicita orientación veterinaria si el sangrado no se detiene o la lesión parece profunda.",
                "No administres medicamentos humanos, antibióticos, analgésicos ni antiinflamatorios por cuenta propia. Algunos pueden ser peligrosos para los perros."
              ]
            }
          ]
        },
        "cuidados": {
          "titulo": "Cuidados",
          "secciones": [
            {
              "titulo": "CÓMO MANTENERLO BIEN CUIDADO",
              "items": [
                "Cepilla su doble manto varias veces por semana; durante las mudas puede necesitar cepillados más frecuentes.",
                "Báñalo cuando sea necesario con un champú adecuado para perros y sécalo bien, prestando atención a las orejas.",
                "Revisa las uñas regularmente y córtalas cuando lo necesite; la frecuencia depende de cuánto se desgasten al caminar.",
                "Revisa los oídos con frecuencia. Límpialos solo cuando sea necesario y con un producto veterinario apropiado; evita introducir bastoncillos en el canal auditivo.",
                "Acostúmbralo desde pequeño al cepillado dental con pasta para perros.",
                "Ofrécele juego, paseos y ejercicio apropiados para su edad. Evita el ejercicio forzado, los saltos repetidos y las carreras prolongadas mientras crece; no existe una edad exacta que sea segura para todos los perros.",
                "Mantén un peso saludable y aumenta la actividad de manera gradual.",
                "Organiza una socialización positiva y progresiva con personas, sonidos, entornos y perros seguros. Sigue las recomendaciones del veterinario para evitar exposiciones infecciosas antes de completar la vacunación.",
                "Cumple el plan de desparasitación interno y externo recomendado para tu zona y estilo de vida.",
                "Proporciónale una cama cómoda, limpia y ubicada en un lugar protegido del frío, el calor y la humedad.",
                "Mantén sus recipientes de comida y agua limpios y colócalos en un espacio tranquilo.",
                "Utiliza juguetes resistentes y adecuados para su tamaño, evitando aquellos que puedan romperse y convertirse en piezas pequeñas.",
                "Supervisa sus juegos al aire libre y evita que ingiera basura, plantas desconocidas u objetos del suelo.",
                "Protege sus patas de superficies excesivamente calientes y evita los paseos durante las horas de mayor temperatura.",
                "Acostúmbralo gradualmente a los procedimientos de higiene, como revisar sus patas, abrir suavemente su boca y tocar sus orejas."
              ]
            },
            {
              "titulo": "SEÑALES DE CUIDADOS INSUFICIENTES O DE UN POSIBLE PROBLEMA DE SALUD",
              "items": [
                "Aumento excesivo de peso o pérdida de peso.",
                "Orejas con mal olor, secreción o rascado constante.",
                "Mal aliento intenso o dolor al masticar.",
                "Cojera, rigidez o rechazo al juego.",
                "Vómitos o diarrea repetidos.",
                "Pelo muy enredado, piel irritada o picor persistente.",
                "Falta de energía o cambios notorios en el apetito.",
                "Uñas demasiado largas que dificultan el apoyo de las patas.",
                "Acumulación de suciedad en los oídos, los dientes o el pelaje.",
                "Ausencia de agua limpia, un lugar adecuado para descansar o protección frente al clima.",
                "Falta de supervisión, ejercicio apropiado y oportunidades de socialización.",
                "Retraso en las vacunas, desparasitaciones o revisiones veterinarias."
              ]
            }
          ]
        },
        "comportamiento": {
          "titulo": "Comportamiento",
          "secciones": [
            {
              "titulo": "ADIESTRAMIENTO DESDE CACHORRO: PASOS CONCRETOS",
              "items": [
                "El Golden Retriever es inteligente, sociable y suele responder bien al aprendizaje mediante recompensas. La educación debe ser progresiva, positiva y adaptada a su edad.",
                "DE LOS 2 A LOS 4 MESES:",
                "Nombre: di su nombre una vez y prémialo cuando te mire.",
                "«Ven»: aléjate unos pasos, llámalo con voz alegre y prémialo cuando llegue.",
                "«Siéntate»: guía suavemente su atención con un premio y recompénsalo cuando se siente.",
                "Socialización: presenta de forma gradual personas, ruidos, superficies y perros tranquilos y vacunados. Las experiencias deben ser positivas; no lo obligues a acercarse si tiene miedo.",
                "Empieza a acostumbrarlo al collar o arnés, a la correa, al cepillado y a que le revisen las patas y las orejas.",
                "DE LOS 4 A LOS 8 MESES:",
                "«Quieto»: empieza con uno o dos segundos y aumenta poco a poco.",
                "Caminar sin tirar: recompensa cuando la correa esté floja; si tira, detente o cambia de dirección sin dar tirones.",
                "Quedarse solo: practica ausencias muy breves y aumenta la duración gradualmente, sin dejar que entre en pánico.",
                "No saltar sobre las personas: premia los saludos con las cuatro patas en el suelo.",
                "«Deja» y «suelta»: enséñalos mediante intercambios por premios o juguetes, sin perseguirlo ni quitarle objetos a la fuerza.",
                "DE LOS 8 A LOS 12–18 MESES:",
                "Refuerza las órdenes en distintos lugares y con distracciones progresivas.",
                "Practica la llamada con correa larga en zonas seguras antes de confiar en ella sin correa.",
                "Continúa acostumbrándolo a las revisiones de boca, patas y orejas.",
                "Trabaja la espera antes de comer, salir por la puerta o saludar.",
                "Ajusta la actividad al desarrollo físico; la adolescencia puede traer distracciones y una obediencia irregular.",
                "Utiliza sesiones breves y constantes, terminando con una actividad que pueda realizar correctamente.",
                "Todos los integrantes de la familia deben mantener las mismas reglas y utilizar las mismas palabras para las órdenes."
              ]
            },
            {
              "titulo": "CÓMO MEJORAR EL COMPORTAMIENTO SI NO FUE ADIESTRADO",
              "items": [
                "Empieza por habilidades sencillas y practica en un ambiente tranquilo.",
                "Usa premios que le gusten y sesiones cortas, de unos 3–10 minutos, adaptadas a su atención.",
                "Si tira de la correa, recompensa los momentos en que camina contigo con la correa floja. Un arnés bien ajustado puede ayudar.",
                "Si come demasiado rápido, prueba un comedero lento y supervisa su uso.",
                "Si muerde jugando, interrumpe brevemente la interacción y redirígelo hacia un juguete apropiado.",
                "Si protege comida u objetos, no se los arrebates ni lo castigues; busca orientación profesional con métodos respetuosos.",
                "Si muestra miedo intenso o ansiedad al quedarse solo, consulta a un veterinario o a un profesional cualificado en comportamiento.",
                "Si salta sobre las visitas, evita reforzar los saltos con atención y prémialo cuando permanezca tranquilo.",
                "Si ladra por aburrimiento, incorpora juegos de olfato, paseos apropiados y actividades de estimulación mental.",
                "Si no responde a su nombre, practica en lugares sin distracciones y prémialo cada vez que te preste atención.",
                "Evita los golpes, los gritos y los castigos físicos. Pueden generar miedo y empeorar los problemas de comportamiento."
              ]
            }
          ]
        },
        "vacunacion": {
          "titulo": "Vacunación y desparasitación",
          "secciones": [
            {
              "titulo": "CALENDARIO DE VACUNACIÓN",
              "items": [
                "El calendario exacto depende de la zona, los antecedentes y el criterio veterinario. Como orientación general:",
                "Desde las 6–8 semanas: suele comenzar la vacunación básica.",
                "Cada 2–4 semanas hasta al menos las 16 semanas: se repiten las dosis necesarias según la vacuna y el protocolo.",
                "Rabia: según la edad mínima, la normativa local y la indicación veterinaria.",
                "Leptospirosis y otras vacunas: según el riesgo de exposición y las recomendaciones locales.",
                "Desparasitación: programa individualizado según edad, peso, entorno y riesgo.",
                "La vacuna básica suele incluir protección frente a enfermedades como moquillo, parvovirus y adenovirus, según la formulación utilizada.",
                "El veterinario debe registrar cada dosis en su carnet de vacunación y señalar las fechas de los próximos refuerzos.",
                "No debe considerarse protegido por completo solamente por haber recibido una primera dosis. Es importante completar la serie inicial.",
                "Evita llevarlo a lugares de alto riesgo de contagio hasta que el veterinario confirme que cuenta con la protección adecuada."
              ]
            },
            {
              "titulo": "DESPARASITACIÓN INTERNA Y EXTERNA",
              "items": [
                "La desparasitación ayuda a prevenir y controlar parásitos que pueden afectar el crecimiento y la salud del cachorro.",
                "Desparasitación interna: se dirige a parásitos intestinales, como lombrices y tenias, que pueden causar diarrea, abdomen abultado, pérdida de peso o retraso del crecimiento.",
                "La frecuencia debe establecerse según su edad, peso, antecedentes y exposición. En cachorros suele ser más frecuente que en perros adultos.",
                "Desparasitación externa: permite prevenir o controlar pulgas, garrapatas y determinados ácaros.",
                "Utiliza productos apropiados para su edad y peso. No todos los antiparasitarios pueden utilizarse en cachorros pequeños.",
                "Revisa su pelaje después de los paseos, especialmente en las orejas, el cuello, las patas y entre los dedos.",
                "Mantén limpios su cama, los espacios donde descansa y los recipientes de comida y agua.",
                "No combines pipetas, collares, comprimidos u otros productos sin consultar al veterinario."
              ]
            }
          ]
        },
        "veterinario": {
          "titulo": "Atención veterinaria",
          "secciones": [
            {
              "titulo": "REVISIONES Y CONSULTAS PREVENTIVAS",
              "items": [
                "Durante la etapa de cachorro necesita controles periódicos para evaluar su crecimiento, alimentación, desarrollo físico y protección frente a enfermedades.",
                "Primera consulta: debe realizarse al llegar al hogar o tan pronto como sea posible, para revisar su estado general y organizar su calendario preventivo.",
                "Control del crecimiento: el veterinario revisa su peso, condición corporal, desarrollo de los huesos y articulaciones.",
                "Revisión de cadera y codos: debido a la predisposición de la raza a problemas ortopédicos, conviene consultar qué controles son apropiados.",
                "Control dental: se revisa el recambio de los dientes y el desarrollo de la mordida.",
                "Revisión de oídos y piel: permite detectar irritaciones, infecciones y posibles alergias.",
                "Alimentación: se ajustan las raciones según su crecimiento y condición corporal.",
                "Vacunación y desparasitación: se actualizan de acuerdo con el calendario individual.",
                "Consulta sobre esterilización: el momento adecuado debe evaluarse individualmente, considerando que es una raza de tamaño grande y su desarrollo físico."
              ]
            },
            {
              "titulo": "CUÁNDO IR AL VETERINARIO DE URGENCIA",
              "items": [
                "Hemorragia que no se detiene con presión continua.",
                "Dificultad para respirar, colapso o encías pálidas o azuladas.",
                "Abdomen hinchado con arcadas sin vomitar.",
                "Golpe de calor.",
                "Convulsiones, temblores intensos o pérdida de coordinación.",
                "Vómitos repetidos, sangre en el vómito o diarrea con sangre.",
                "Sospecha de ingestión de un tóxico.",
                "Dolor intenso, incapacidad para apoyar una pata o traumatismo importante.",
                "Decaimiento marcado, especialmente si se acompaña de vómitos, diarrea o rechazo del agua.",
                "Reacción alérgica intensa con hinchazón de la cara o dificultad respiratoria.",
                "Incapacidad para orinar o dificultad intensa para hacerlo.",
                "Pérdida repentina del conocimiento o debilidad extrema."
              ]
            }
          ]
        }
      }
    },
    "adulto": {
      "tituloOriginal": "Golden Retriever – Etapa ADULTO (aproximadamente de 1–2 años hasta los 7–8 años)",
      "temas": {
        "alimentacion": {
          "titulo": "Alimentación",
          "secciones": [
            {
              "titulo": "ALIMENTACIÓN SALUDABLE",
              "items": [
                "Usa un alimento completo y equilibrado para perros adultos, adecuado para su tamaño, actividad y condición corporal. No es obligatorio que la carne sea el primer ingrediente.",
                "Mide la ración diaria y ajústala según el peso, la actividad y la forma corporal. Los Golden Retriever suelen tener buen apetito y pueden ganar peso con facilidad.",
                "Divide la comida en 2 tomas al día como pauta práctica. Evita una única comida muy abundante.",
                "Puedes usar parte de su ración habitual o pequeños trozos de pollo o pavo cocidos sin huesos ni condimentos como premios. Procura que todos los premios y extras no superen el 10 % de las calorías diarias.",
                "El aceite de pescado no es imprescindible para todos los perros. Consulta al veterinario antes de añadirlo, especialmente si toma medicamentos o tiene alguna enfermedad.",
                "La comida casera de pollo o pavo con calabaza puede ser un complemento ocasional, pero no constituye por sí sola una dieta completa y equilibrada.",
                "Un comedero lento puede ayudar si engulle la comida; supervisa que sea seguro y adecuado para su tamaño.",
                "Mantén siempre agua limpia y fresca disponible.",
                "Si tiene sobrepeso, ajusta la ración con orientación veterinaria en lugar de reducir drásticamente la comida.",
                "Comprueba regularmente su peso y condición corporal para detectar aumentos antes de que afecten a sus articulaciones.",
                "Si tiene necesidades especiales, alergias o enfermedades, consulta qué alimento se adapta mejor a su situación."
              ]
            },
            {
              "titulo": "ALIMENTACIÓN NO SALUDABLE",
              "items": [
                "Uvas y pasas, chocolate, cafeína, cebolla, ajo, puerro y xilitol.",
                "Huesos cocidos y alimentos que puedan astillarse o causar obstrucciones.",
                "Comida muy grasa, frita, salada o condimentada.",
                "Exceso de premios, sobras y snacks calóricos.",
                "Suplementos articulares o aceites añadidos sin valorar si realmente los necesita.",
                "Ejercicio vigoroso inmediatamente después de comer. Evita especialmente las sesiones intensas alrededor de las comidas, aunque no existe un intervalo universal que garantice prevenir la torsión gástrica.",
                "Dietas caseras sin formulación nutricional, ya que pueden provocar deficiencias o excesos de nutrientes.",
                "Cambios bruscos de alimento que puedan causar alteraciones digestivas.",
                "Alimentos en mal estado o productos destinados a otras especies."
              ]
            }
          ]
        },
        "salud": {
          "titulo": "Salud",
          "secciones": [
            {
              "titulo": "SEÑALES DE BUENA SALUD",
              "items": [
                "Mantiene una energía apropiada para su edad y condición física.",
                "Conserva una condición corporal saludable y una musculatura adecuada.",
                "Tiene apetito normal, heces formadas, piel sana y oídos sin mal olor.",
                "Camina, se levanta y juega sin rigidez ni dolor evidente.",
                "Su pelaje se mantiene limpio y presenta una apariencia saludable.",
                "Respira normalmente durante el descanso y se recupera después de la actividad física.",
                "Mantiene interés por las personas, los paseos y las actividades habituales.",
                "No presenta cambios persistentes en su sed, apetito o eliminación."
              ]
            },
            {
              "titulo": "PROBLEMAS DE SALUD A VIGILAR",
              "items": [
                "Displasia de cadera y codo, y otras enfermedades articulares.",
                "Obesidad, que puede empeorar los problemas de movilidad.",
                "Otitis y problemas de piel o alergias.",
                "Enfermedad dental y acumulación de sarro.",
                "Dilatación-vólvulo gástrico, una urgencia que puede avanzar rápidamente.",
                "Mayor predisposición de la raza a ciertos tipos de cáncer, incluidos el hemangiosarcoma y el linfoma. Esto no significa que todos los Golden Retriever vayan a desarrollarlos; sí conviene consultar por bultos nuevos, pérdida de peso inexplicable, debilidad o cambios persistentes.",
                "Cambios de comportamiento que podrían indicar dolor o enfermedad.",
                "Rigidez al levantarse después de descansar, que puede ser una señal de molestias articulares.",
                "Infecciones de oído recurrentes, especialmente si sacude la cabeza o se rasca con frecuencia.",
                "Alteraciones del apetito, sed excesiva o cambios en la cantidad de orina.",
                "Problemas oculares, como enrojecimiento, secreciones o dificultad para ver.",
                "Cualquier bulto nuevo, herida que no cicatriza o pérdida de peso inexplicable merece una revisión veterinaria."
              ]
            }
          ]
        },
        "primeros": {
          "titulo": "Primeros auxilios",
          "secciones": [
            {
              "titulo": "QUÉ HACER ANTE ACCIDENTES O SÍNTOMAS PREOCUPANTES",
              "items": [
                "Los primeros auxilios permiten actuar mientras se organiza la atención veterinaria. No sustituyen el diagnóstico ni el tratamiento profesional.",
                "Caída o golpe: limita el movimiento y observa cómo camina. Si no apoya una pata, presenta dolor intenso o el golpe fue importante, acude urgentemente al veterinario.",
                "Herida: enjuaga las heridas superficiales con agua limpia o suero fisiológico. Si sangra, aplica presión continua con una gasa limpia. Las heridas profundas, mordeduras y hemorragias importantes necesitan atención veterinaria.",
                "Intoxicación: contacta de inmediato con un veterinario y lleva el envase del producto si lo tienes. No provoques el vómito ni administres remedios caseros.",
                "Vómito o diarrea: si los síntomas se repiten, consulta al veterinario. Acude urgentemente si hay sangre, dolor, debilidad, deshidratación o incapacidad para retener agua. No lo dejes en ayunas sin indicación profesional.",
                "Golpe de calor: trasládalo a un lugar fresco, comienza a enfriarlo con agua fresca —no helada— y busca atención veterinaria urgente.",
                "Abdomen hinchado, arcadas improductivas o inquietud repentina: posible dilatación-vólvulo gástrico. Es una emergencia absoluta.",
                "Picadura: observa si presenta hinchazón o dolor. Si hay hinchazón facial, dificultad para respirar o debilidad repentina, acude inmediatamente a urgencias.",
                "Atragantamiento: si no puede respirar normalmente, necesita asistencia veterinaria inmediata. No introduzcas los dedos a ciegas en su boca.",
                "Convulsiones: despeja el espacio para evitar golpes, no intentes sujetarlo por la fuerza y contacta con un veterinario.",
                "No administres medicamentos humanos ni utilices remedios caseros sin autorización veterinaria."
              ]
            }
          ]
        },
        "cuidados": {
          "titulo": "Cuidados",
          "secciones": [
            {
              "titulo": "CÓMO MANTENERLO BIEN CUIDADO",
              "items": [
                "Cepilla su doble manto varias veces por semana y con mayor frecuencia durante las mudas.",
                "Báñalo cuando lo necesite y sécalo bien, especialmente alrededor de las orejas.",
                "Revisa las uñas y córtalas cuando haga falta; no todos los perros necesitan cortarlas con la misma frecuencia.",
                "Revisa los oídos regularmente. Límpialos si lo necesita con un producto apropiado y evita introducir objetos en el canal auditivo.",
                "Cepilla los dientes a diario si es posible, con pasta dental específica para perros.",
                "Ofrécele ejercicio diario adaptado a su condición física. Muchos adultos disfrutan de paseos, juegos de olfato, cobro controlado y natación supervisada.",
                "La duración del ejercicio depende del perro: no todos necesitan entre una y dos horas de actividad intensa cada día. Aumenta la carga gradualmente y permite descanso.",
                "Evita el ejercicio vigoroso alrededor de las comidas y vigila signos de cansancio o sobrecalentamiento.",
                "Mantén un peso saludable y consulta al veterinario sobre prevención de parásitos según la zona y el estilo de vida.",
                "Realiza una revisión veterinaria al menos una vez al año; puede necesitar visitas más frecuentes según su salud.",
                "Proporciónale un espacio cómodo para dormir, protegido de la humedad y de temperaturas extremas.",
                "Utiliza juguetes resistentes y actividades de olfato para mantenerlo entretenido y estimulado.",
                "Supervisa la natación y evita que entre en aguas contaminadas o con corrientes peligrosas.",
                "Mantén al día su identificación y utiliza correa en lugares públicos donde sea necesario.",
                "Después de pasear por zonas con vegetación, revisa su pelaje y sus patas para detectar espigas, espinas o garrapatas."
              ]
            },
            {
              "titulo": "SEÑALES DE CUIDADOS INSUFICIENTES O DE UN POSIBLE PROBLEMA DE SALUD",
              "items": [
                "Aumento o pérdida de peso sin explicación.",
                "Orejas con olor, secreción o picor.",
                "Mal aliento persistente o dificultad para comer.",
                "Cojera, rigidez o menor tolerancia al ejercicio.",
                "Pelo enredado, piel irritada o picor frecuente.",
                "Vómitos o diarrea repetidos.",
                "Bultos nuevos o cambios persistentes en su energía, apetito o comportamiento.",
                "Uñas excesivamente largas o dificultad para caminar.",
                "Falta de agua limpia, higiene o protección frente al clima.",
                "Ausencia de ejercicio, interacción y estimulación mental.",
                "Falta de revisiones veterinarias o de prevención de parásitos."
              ]
            }
          ]
        },
        "comportamiento": {
          "titulo": "Comportamiento",
          "secciones": [
            {
              "titulo": "ADIESTRAMIENTO EN ETAPA ADULTA",
              "items": [
                "Repasa las órdenes básicas varias veces por semana y también durante las rutinas diarias.",
                "Haz sesiones cortas, de unos 5–10 minutos, adaptadas a su concentración.",
                "Practica en lugares con distracciones graduales, manteniendo una dificultad que pueda manejar.",
                "«Junto» o caminar sin tirar: recompensa la correa floja y la atención hacia ti; evita los tirones.",
                "«Quieto»: aumenta poco a poco la duración y la distancia.",
                "«Deja» y «suelta»: enséñalos mediante intercambios y recompensas.",
                "Trabaja la llamada en lugares seguros antes de practicar sin correa.",
                "Premia la calma al saludar y al encontrarse con otros perros.",
                "Usa métodos de refuerzo positivo y evita castigos físicos o intimidación.",
                "Incorpora juegos de búsqueda, olfato y cobro controlado para aprovechar su inteligencia y energía.",
                "Mantén normas coherentes en casa para que comprenda qué conductas se esperan de él."
              ]
            },
            {
              "titulo": "CÓMO MEJORAR EL COMPORTAMIENTO SI NO FUE ADIESTRADO",
              "items": [
                "Empieza con órdenes sencillas en un entorno tranquilo y aumenta gradualmente las distracciones.",
                "Utiliza premios pequeños y sesiones breves y constantes.",
                "Si tira de la correa, recompensa cuando camine sin tensarla; un arnés bien ajustado puede ayudar.",
                "Si come muy rápido, prueba un comedero lento.",
                "Si salta sobre las personas, premia los saludos tranquilos con las cuatro patas en el suelo.",
                "Si tiene dificultades para quedarse solo, practica ausencias muy cortas y aumenta el tiempo de forma gradual. Si presenta angustia intensa, consulta a un profesional.",
                "Si aparecen agresividad, miedo intenso o cambios repentinos, consulta al veterinario para descartar dolor o enfermedad y busca un profesional cualificado en comportamiento.",
                "Si ladra constantemente por aburrimiento, aumenta las actividades de olfato y los momentos de interacción.",
                "Si no responde a las órdenes en lugares concurridos, vuelve a practicar en un ambiente más tranquilo y aumenta las distracciones progresivamente.",
                "Evita castigos físicos, gritos o métodos intimidantes. La educación debe basarse en la confianza y el refuerzo positivo."
              ]
            }
          ]
        },
        "vacunacion": {
          "titulo": "Vacunación y desparasitación",
          "secciones": [
            {
              "titulo": "VACUNAS Y REFUERZOS",
              "items": [
                "Vacunas básicas: los refuerzos se programan según las vacunas recibidas durante la etapa de cachorro y las recomendaciones veterinarias; algunas se administran cada 1–3 años, según el producto y la normativa.",
                "Rabia: según la legislación local y el calendario indicado.",
                "Leptospirosis y otras vacunas: según el riesgo de exposición y las recomendaciones de la zona.",
                "Desparasitación: ajustada al riesgo individual, no necesariamente con el mismo producto y frecuencia para todos los perros.",
                "No suspendas ni repitas vacunas por tu cuenta; el veterinario revisará su historial y determinará qué refuerzos necesita.",
                "Conserva su carnet de vacunación y presenta el registro en cada consulta.",
                "Si se desconoce su historial de vacunas, el veterinario puede establecer un calendario de actualización según su edad y estado de salud."
              ]
            },
            {
              "titulo": "DESPARASITACIÓN INTERNA Y EXTERNA",
              "items": [
                "La desparasitación interna permite controlar parásitos intestinales que pueden causar molestias digestivas, pérdida de peso y otros problemas.",
                "La desparasitación externa ayuda a prevenir pulgas, garrapatas y ciertos ácaros.",
                "La frecuencia depende del entorno, los paseos, el contacto con otros animales y el riesgo de exposición.",
                "Utiliza productos adecuados para su peso y estado de salud.",
                "Revisa su pelaje después de paseos por parques, jardines o zonas con vegetación.",
                "Mantén limpias sus camas y los lugares donde descansa.",
                "Consulta al veterinario si presenta parásitos visibles, picazón persistente o cambios en las heces."
              ]
            }
          ]
        },
        "veterinario": {
          "titulo": "Atención veterinaria",
          "secciones": [
            {
              "titulo": "REVISIONES RUTINARIAS",
              "items": [
                "Realiza una revisión veterinaria al menos una vez al año; puede necesitar visitas más frecuentes según su salud.",
                "Control del peso: permite detectar sobrepeso y ajustar su alimentación.",
                "Revisión de articulaciones: se evalúan la movilidad, la marcha y posibles signos de dolor.",
                "Revisión dental: permite detectar sarro, inflamación de encías y piezas dañadas.",
                "Control de oídos y piel: ayuda a identificar otitis, alergias e irritaciones.",
                "Revisión de bultos: informa al veterinario sobre cualquier masa nueva o cambio en una que ya existía.",
                "Control preventivo: se revisan las vacunas y la desparasitación según sus antecedentes y estilo de vida.",
                "Análisis complementarios: el veterinario puede recomendarlos cuando existen síntomas, antecedentes familiares o factores de riesgo."
              ]
            },
            {
              "titulo": "CUÁNDO IR AL VETERINARIO DE URGENCIA",
              "items": [
                "Hemorragia abundante o que no se detiene.",
                "Dificultad para respirar, colapso o encías azuladas o muy pálidas.",
                "Abdomen hinchado con arcadas sin vomitar.",
                "Golpe de calor.",
                "Convulsiones o pérdida repentina de coordinación.",
                "Vómitos repetidos, vómito con sangre o diarrea con sangre.",
                "Sospecha de intoxicación.",
                "Cojera intensa, traumatismo importante o dolor intenso.",
                "Debilidad repentina o cambios importantes y bruscos de comportamiento.",
                "Incapacidad repentina para levantarse o caminar.",
                "Reacción alérgica intensa con hinchazón de la cara o dificultad respiratoria.",
                "Cualquier deterioro rápido del estado general."
              ]
            }
          ]
        }
      }
    },
    "senior": {
      "tituloOriginal": "Golden Retriever – Etapa SENIOR (a partir de los 7–8 años aproximadamente)",
      "temas": {
        "alimentacion": {
          "titulo": "Alimentación",
          "secciones": [
            {
              "titulo": "ALIMENTACIÓN SALUDABLE",
              "items": [
                "Elige un alimento completo y equilibrado para perros mayores si se adapta a sus necesidades. No todos los perros senior necesitan una fórmula específica.",
                "Ajusta las calorías según su condición corporal, actividad y masa muscular. No reduzcas automáticamente la comida un 10–20 %: una pérdida excesiva de peso o músculo también puede ser perjudicial.",
                "Pesa las raciones y revisa su peso periódicamente.",
                "Mantén 2 comidas al día si las tolera bien.",
                "Si le cuesta masticar, consulta la causa con el veterinario; puedes humedecer el pienso con agua tibia si resulta apropiado.",
                "Los suplementos de aceite de pescado o para las articulaciones solo deben añadirse después de consultar al veterinario.",
                "Si necesita una dieta terapéutica por enfermedad renal, cardíaca u otra afección, sigue las indicaciones específicas.",
                "Mantén agua fresca disponible en todo momento.",
                "Controla su masa muscular y evita que pierda peso sin una causa identificada.",
                "Si tiene menor apetito, consulta al veterinario antes de cambiar su dieta o añadir complementos.",
                "Los alimentos deben ser fáciles de consumir y adecuados a su capacidad de masticación y digestión."
              ]
            },
            {
              "titulo": "ALIMENTACIÓN NO SALUDABLE",
              "items": [
                "Uvas, pasas, chocolate, cafeína, cebolla, ajo, puerro y xilitol.",
                "Alimentos excesivamente grasos, salados o condimentados.",
                "Huesos cocidos y objetos duros que puedan fracturar los dientes.",
                "Premios en exceso o cambios bruscos de dieta.",
                "Suplementos administrados sin indicación veterinaria.",
                "Reducir demasiado la comida sin vigilar el peso y la masa muscular.",
                "Alimentos en mal estado o sobras que puedan causar problemas digestivos.",
                "Dietas caseras no equilibradas que no cubran sus necesidades nutricionales.",
                "Cambios de alimento sin transición, especialmente si tiene un sistema digestivo sensible."
              ]
            }
          ]
        },
        "salud": {
          "titulo": "Salud",
          "secciones": [
            {
              "titulo": "SEÑALES DE BUENA SALUD",
              "items": [
                "Mantiene el interés por su entorno y disfruta de actividades adaptadas.",
                "Conserva un peso saludable y suficiente masa muscular.",
                "Come, bebe y hace sus necesidades de manera habitual.",
                "Puede levantarse, caminar y descansar cómodamente.",
                "Sus problemas crónicos, si los tiene, están controlados con seguimiento veterinario.",
                "Mantiene una respiración normal durante el descanso.",
                "Responde a las personas y conserva interés por sus rutinas.",
                "Puede realizar paseos adaptados sin mostrar dolor intenso ni agotamiento excesivo."
              ]
            },
            {
              "titulo": "PROBLEMAS DE SALUD A VIGILAR",
              "items": [
                "Artrosis, rigidez y dificultad para levantarse.",
                "Pérdida de masa muscular o aumento de peso.",
                "Otitis y problemas de piel.",
                "Enfermedad periodontal y pérdida de piezas dentales.",
                "Cáncer, al que la raza presenta predisposición para determinados tipos.",
                "Enfermedades renales, cardíacas, endocrinas u otras afecciones propias de la edad.",
                "Cambios en la sed, la cantidad de orina, el apetito o las heces.",
                "Dificultades para ver u oír, desorientación o alteraciones del sueño.",
                "Bultos nuevos, heridas que no cicatrizan o cambios en masas que ya tenía.",
                "Pérdida de peso o apetito sin explicación.",
                "Cambios de comportamiento, irritabilidad o aislamiento que podrían relacionarse con dolor o enfermedad.",
                "Disminución de la movilidad o dificultad para subir escalones y levantarse.",
                "Tos persistente, respiración diferente o cansancio fuera de lo habitual."
              ]
            }
          ]
        },
        "primeros": {
          "titulo": "Primeros auxilios",
          "secciones": [
            {
              "titulo": "QUÉ HACER ANTE ACCIDENTES O SÍNTOMAS PREOCUPANTES",
              "items": [
                "Los perros mayores pueden necesitar cuidados especiales ante accidentes o cambios repentinos. Es importante evitar esfuerzos y buscar atención profesional cuando aparecen señales preocupantes.",
                "Caída: evita que siga haciendo esfuerzos y comprueba si puede levantarse y caminar. Si no puede ponerse de pie, tiene dolor intenso o sufrió un golpe importante, acude urgentemente al veterinario.",
                "Herida: enjuaga suavemente una herida superficial con suero fisiológico o agua limpia. Controla el sangrado con presión continua y consulta si es profunda, extensa o no deja de sangrar.",
                "No quiere comer: si el cambio es repentino, consulta pronto, especialmente si tiene otras enfermedades. Si pasan 24 horas sin comer, necesita valoración veterinaria; no esperes ese tiempo si también está débil, vomita o parece tener dolor.",
                "Dificultad para levantarse: puede deberse a dolor, debilidad u otra enfermedad. No lo obligues a caminar; solicita valoración veterinaria.",
                "Vómitos o diarrea: vigila su estado general y el consumo de agua. Si los síntomas se repiten, hay sangre, dolor, debilidad o no puede retener agua, busca atención urgente.",
                "Abdomen hinchado, arcadas sin vomitar o inquietud repentina: posible dilatación-vólvulo gástrico. Acude inmediatamente a urgencias.",
                "Golpe de calor: empieza a enfriarlo con agua fresca, no helada, y busca atención veterinaria urgente.",
                "Dificultad respiratoria: mantenlo tranquilo, evita que camine y solicita atención veterinaria de emergencia.",
                "Convulsiones: despeja el espacio para evitar golpes, no introduzcas las manos en su boca y contacta inmediatamente con un veterinario.",
                "Sospecha de intoxicación: conserva el envase del producto y contacta inmediatamente con un veterinario. No provoques el vómito ni administres remedios caseros.",
                "No le des medicamentos humanos ni aumentes las dosis de sus tratamientos habituales sin autorización veterinaria."
              ]
            }
          ]
        },
        "cuidados": {
          "titulo": "Cuidados",
          "secciones": [
            {
              "titulo": "CÓMO MANTENERLO BIEN CUIDADO",
              "items": [
                "Cepilla su doble manto con suavidad varias veces por semana y con mayor frecuencia durante las mudas.",
                "Báñalo cuando sea necesario y sécalo bien.",
                "Revisa sus uñas con regularidad y córtalas cuando lo necesite.",
                "Comprueba los oídos y límpialos solo cuando sea necesario con productos adecuados para perros.",
                "Mantén una rutina de higiene dental. Si tiene dolor al masticar o mal aliento intenso, necesita una revisión.",
                "Proporciona una cama cómoda y fácil de alcanzar. Una superficie antideslizante puede ayudarle a desplazarse con mayor seguridad.",
                "Haz paseos más cortos si se cansa, pero conserva la actividad diaria que tolere. La natación puede ser útil para algunos perros, siempre que sea segura y no esté contraindicada.",
                "Evita los saltos altos y las escaleras difíciles si tiene problemas articulares.",
                "Mantén su peso y musculatura bajo control.",
                "Facilita el acceso al agua y a un lugar tranquilo para descansar.",
                "Programa revisiones veterinarias aproximadamente cada 6 meses, o con mayor frecuencia si presenta enfermedades crónicas. Los análisis y otras pruebas se individualizan según su estado.",
                "Coloca alfombras o superficies antideslizantes en las zonas donde camina para reducir el riesgo de resbalones.",
                "Evita cambiar de lugar sus recipientes y su cama constantemente, especialmente si tiene dificultades para ver.",
                "Ayúdalo a entrar y salir de vehículos si tiene movilidad reducida, sin forzar sus articulaciones.",
                "Mantén sus paseos en horarios frescos y ofrece descansos cuando lo necesite.",
                "Adapta las actividades a sus capacidades: puede seguir disfrutando de juegos de olfato y paseos tranquilos."
              ]
            },
            {
              "titulo": "SEÑALES DE CUIDADOS INSUFICIENTES O DE UN POSIBLE PROBLEMA DE SALUD",
              "items": [
                "Pérdida o aumento de peso.",
                "Cojera, rigidez o dificultad para levantarse.",
                "Orejas con mal olor o secreción.",
                "Mal aliento intenso o dificultad para comer.",
                "Pelo opaco, piel irritada o picor.",
                "Aislamiento, desorientación o cambios en el sueño.",
                "Cambios en la sed, la orina o las heces.",
                "Menor apetito o pérdida de interés por sus actividades habituales.",
                "Dificultad para acceder a su cama, agua o comida.",
                "Resbalones frecuentes o miedo a caminar sobre superficies lisas.",
                "Falta de revisiones veterinarias y seguimiento de enfermedades crónicas.",
                "Ausencia de higiene, descanso cómodo y actividad adaptada."
              ]
            }
          ]
        },
        "comportamiento": {
          "titulo": "Comportamiento",
          "secciones": [
            {
              "titulo": "ADIESTRAMIENTO Y MANEJO EN ETAPA SENIOR",
              "items": [
                "Repasa las órdenes conocidas con sesiones cortas y tranquilas.",
                "Utiliza premios pequeños y blandos si le cuesta masticar, teniendo en cuenta sus necesidades nutricionales.",
                "Mantén rutinas predecibles para las comidas, los paseos y el descanso.",
                "Adapta los ejercicios si tiene dolor o movilidad reducida.",
                "Premia las conductas tranquilas y la cooperación durante el cepillado y las revisiones.",
                "Usa superficies antideslizantes y evita exigirle posturas que le resulten dolorosas.",
                "Si oye o ve menos, utiliza señales que pueda percibir y acércate de manera que no se sobresalte.",
                "No interpretes la desorientación, la irritabilidad o los cambios de sueño como algo inevitable de la edad: coméntalos con el veterinario.",
                "Mantén actividades de estimulación mental adecuadas, como juegos de olfato sencillos y búsqueda de premios.",
                "Respeta sus periodos de descanso y evita interrumpirlo bruscamente cuando duerme.",
                "Dale tiempo para responder a las órdenes, ya que puede necesitar más tiempo debido a cambios en la audición, visión o movilidad."
              ]
            },
            {
              "titulo": "CÓMO MEJORAR EL COMPORTAMIENTO SI NUNCA FUE ADIESTRADO",
              "items": [
                "Empieza con métodos positivos, órdenes sencillas y sesiones breves.",
                "Usa un arnés cómodo y paseos adaptados a su movilidad.",
                "Premia la calma y los comportamientos que quieres fomentar.",
                "Divide las nuevas habilidades en pasos pequeños y dale tiempo para responder.",
                "Si se irrita al tocarle alguna parte del cuerpo, no insistas: podría tener dolor.",
                "Adapta el hogar para facilitar sus desplazamientos y el acceso a sus lugares habituales.",
                "Consulta al veterinario ante cambios de conducta, ansiedad nueva o desorientación para descartar problemas médicos.",
                "Si no escucha bien, utiliza señales visuales sencillas y recompensas para enseñarle nuevas conductas.",
                "Si se muestra inseguro en lugares desconocidos, comienza en espacios tranquilos y evita forzarlo.",
                "No utilices castigos físicos ni lo obligues a realizar movimientos que puedan causarle dolor.",
                "Mantén una rutina constante y reconoce sus avances, aunque sean pequeños."
              ]
            }
          ]
        },
        "vacunacion": {
          "titulo": "Vacunación y desparasitación",
          "secciones": [
            {
              "titulo": "VACUNAS Y REFUERZOS",
              "items": [
                "Vacunas básicas: los refuerzos dependen de su historial, las vacunas anteriores y las recomendaciones veterinarias. Ser senior no significa que deba dejar de vacunarse.",
                "Rabia: según la legislación local y el calendario correspondiente.",
                "Leptospirosis y otras vacunas: según su riesgo de exposición y las recomendaciones de la zona.",
                "Desparasitación: ajustada al estilo de vida, los riesgos y las indicaciones veterinarias.",
                "Aprovecha las revisiones periódicas para comprobar qué vacunas y medidas preventivas necesita.",
                "El veterinario debe revisar su historial antes de indicar refuerzos o actualizar vacunas que no estén registradas.",
                "Si tiene una enfermedad crónica o recibe medicamentos, informa al veterinario para que adapte las medidas preventivas."
              ]
            },
            {
              "titulo": "DESPARASITACIÓN INTERNA Y EXTERNA",
              "items": [
                "La desparasitación interna ayuda a controlar parásitos intestinales que pueden afectar su digestión, peso y estado general.",
                "La desparasitación externa permite prevenir o controlar pulgas, garrapatas y otros parásitos de la piel.",
                "La frecuencia debe ajustarse a su entorno, hábitos y antecedentes de salud.",
                "Utiliza productos apropiados para su peso, edad y enfermedades, si las tiene.",
                "Revisa su piel y pelaje con regularidad, especialmente si pasa tiempo al aire libre.",
                "Mantén limpias sus camas y las zonas donde descansa.",
                "Consulta al veterinario si presenta picazón persistente, parásitos visibles o cambios en sus heces."
              ]
            }
          ]
        },
        "veterinario": {
          "titulo": "Atención veterinaria",
          "secciones": [
            {
              "titulo": "REVISIONES RUTINARIAS",
              "items": [
                "Programa revisiones veterinarias aproximadamente cada 6 meses, o con mayor frecuencia si presenta enfermedades crónicas. Los análisis y otras pruebas se individualizan según su estado.",
                "Control de peso y musculatura: permite detectar pérdida de masa muscular, sobrepeso o cambios en su condición corporal.",
                "Revisión de articulaciones: se evalúan la movilidad, la rigidez y los signos de artrosis.",
                "Revisión dental: permite identificar dolor, inflamación de encías, sarro y piezas dañadas.",
                "Control de ojos y oídos: ayuda a detectar alteraciones de la visión, audición e infecciones.",
                "Revisión de piel y bultos: informa sobre cualquier masa nueva, herida persistente o cambio en una lesión existente.",
                "Control de enfermedades crónicas: se revisa si los tratamientos siguen siendo adecuados y si es necesario realizar análisis.",
                "Evaluación de alimentación: permite adaptar la dieta a sus necesidades y conservar una masa muscular adecuada.",
                "Revisión de vacunas y parásitos: se actualizan las medidas preventivas según su historial y exposición."
              ]
            },
            {
              "titulo": "CUÁNDO IR AL VETERINARIO DE URGENCIA",
              "items": [
                "Hemorragia abundante o que no se detiene.",
                "Dificultad para respirar o colapso.",
                "Abdomen hinchado con arcadas sin vomitar.",
                "Golpe de calor.",
                "Convulsiones, desorientación repentina intensa o incapacidad para mantenerse en pie.",
                "Vómitos repetidos, sangre en el vómito o diarrea con sangre.",
                "Sospecha de intoxicación.",
                "Dolor intenso o incapacidad repentina para caminar.",
                "Debilidad súbita, encías muy pálidas o azuladas.",
                "Cualquier cambio brusco importante acompañado de deterioro general.",
                "Dificultad repentina para orinar o ausencia de orina.",
                "Pérdida repentina de la visión, desmayo o pérdida de conocimiento.",
                "Cualquier situación en la que no pueda respirar, caminar o mantenerse consciente con normalidad."
              ]
            }
          ]
        }
      }
    }
  }
},
"labradorretriever": {
  "nombre": "Labrador Retriever",
  "etapas": {
    "cachorro": {
      "tituloOriginal": "LABRADOR RETRIEVER CACHORRO (DE 0 A 12 MESES)",
      "temas": {
        "alimentacion": {
          "titulo": "Alimentación",
          "secciones": [
            {
              "titulo": "ALIMENTACIÓN SALUDABLE",
              "items": [
                "El Labrador Retriever cachorro necesita una alimentación completa y equilibrada que favorezca su crecimiento, el desarrollo de sus músculos, la formación de sus huesos y el fortalecimiento de su sistema inmunológico. Durante esta etapa crece rápidamente y necesita recibir los nutrientes adecuados en cantidades controladas.",
                "Alimento para cachorros: debe consumir un alimento comercial completo y equilibrado formulado para cachorros, preferiblemente adecuado para razas grandes. Este aporta proteínas, grasas, vitaminas y minerales necesarios para su desarrollo.",
                "Proteínas: ayudan a formar y reparar los músculos y los tejidos. Pueden proceder de ingredientes como pollo, pescado, pavo o carne, según la composición del alimento.",
                "Grasas saludables: proporcionan energía y ácidos grasos esenciales que contribuyen al desarrollo cerebral, la salud de la piel y el mantenimiento de un pelaje sano.",
                "Calcio y fósforo: son importantes para el crecimiento de los huesos y los dientes. Deben encontrarse en proporciones equilibradas, ya que el exceso de minerales puede perjudicar el desarrollo esquelético de los cachorros de razas grandes.",
                "Agua fresca: debe tener agua limpia y disponible durante todo el día para mantenerse hidratado, especialmente después de jugar o hacer ejercicio.",
                "Frecuencia de las comidas: entre los 2 y 3 meses puede comer aproximadamente cuatro veces al día; entre los 3 y 6 meses, unas tres veces; y desde los 6 meses, normalmente dos comidas al día. La frecuencia debe adaptarse a sus necesidades.",
                "Porciones controladas: es importante respetar las cantidades recomendadas en el envase y ajustarlas según el crecimiento, la actividad y la condición corporal del cachorro.",
                "Premios saludables: durante el entrenamiento se pueden utilizar premios pequeños específicos para perros, procurando que no representen más del 10 % de sus calorías diarias.",
                "Transición alimentaria: si se cambia de alimento, conviene hacerlo gradualmente durante varios días para reducir el riesgo de diarrea o molestias digestivas."
              ]
            },
            {
              "titulo": "ALIMENTACIÓN NO SALUDABLE",
              "items": [
                "Una alimentación inadecuada puede afectar el crecimiento del cachorro, provocar problemas digestivos y favorecer el desarrollo de enfermedades.",
                "Chocolate: contiene sustancias tóxicas para los perros que pueden afectar el corazón y el sistema nervioso.",
                "Uvas y pasas: pueden provocar daño renal grave, por lo que no deben ofrecerse en ninguna cantidad.",
                "Cebolla, ajo y cebollín: pueden dañar los glóbulos rojos y causar anemia.",
                "Alcohol y cafeína: pueden provocar intoxicaciones y afectar el sistema nervioso y cardiovascular.",
                "Huesos cocidos: pueden astillarse y causar heridas, obstrucciones o lesiones en el aparato digestivo.",
                "Comidas muy grasosas: pueden provocar vómitos, diarrea y aumentar el riesgo de pancreatitis.",
                "Sobras de comida humana: algunas contienen demasiada sal, grasa, condimentos o ingredientes tóxicos.",
                "Exceso de calcio y suplementos: no se deben administrar vitaminas, minerales ni suplementos para el crecimiento sin indicación veterinaria.",
                "Alimentación insuficiente: no proporcionarle la cantidad adecuada puede perjudicar su desarrollo y su condición física.",
                "Sobrealimentación: ofrecer demasiada comida puede favorecer el aumento excesivo de peso y ejercer presión sobre las articulaciones en desarrollo.",
                "Dietas caseras desequilibradas: alimentar al cachorro solamente con carne, arroz o verduras no garantiza que reciba todos los nutrientes necesarios."
              ]
            }
          ]
        },
        "salud": {
          "titulo": "Salud",
          "secciones": [
            {
              "titulo": "SEÑALES DE BUENA SALUD",
              "items": [
                "Un cachorro Labrador Retriever saludable suele mostrar energía, curiosidad y un desarrollo progresivo. Su comportamiento, apetito y aspecto físico permiten observar posibles cambios en su estado general.",
                "Tiene ganas de jugar, explorar y relacionarse con las personas.",
                "Presenta ojos claros y brillantes, sin enrojecimiento persistente ni secreciones abundantes.",
                "Tiene las orejas sin mal olor intenso, secreciones anormales ni molestias constantes.",
                "Su pelaje está limpio y su piel no presenta heridas, irritación marcada ni picazón excesiva.",
                "Come con apetito y bebe agua con normalidad.",
                "Sus heces tienen una consistencia habitual y no presentan sangre ni diarrea persistente.",
                "Aumenta de peso de forma gradual y mantiene un crecimiento adecuado para su edad.",
                "Camina y corre sin cojear ni mostrar dolor evidente.",
                "Duerme durante periodos prolongados, algo normal en los cachorros, y se muestra activo cuando está despierto.",
                "Responde progresivamente a su nombre, a los estímulos del entorno y al entrenamiento.",
                "Respira con normalidad cuando está descansando y no presenta tos persistente.",
                "Sus encías suelen ser rosadas, aunque su color puede variar según la pigmentación natural."
              ]
            },
            {
              "titulo": "SEÑALES DE MALA SALUD",
              "items": [
                "Las alteraciones en el apetito, el comportamiento, la digestión o la movilidad pueden indicar que el cachorro necesita una evaluación veterinaria.",
                "Falta de apetito: si deja de comer o muestra una disminución persistente del apetito, puede estar enfermo o tener molestias.",
                "Vómitos repetidos: pueden producir deshidratación y estar relacionados con infecciones, parásitos, intoxicaciones u otros problemas.",
                "Diarrea persistente: puede ocasionar pérdida de líquidos y nutrientes, especialmente peligrosa en cachorros pequeños.",
                "Pérdida de energía: si está inusualmente débil, no quiere jugar o permanece decaído, necesita atención.",
                "Picazón excesiva: puede deberse a pulgas, ácaros, alergias u otras afecciones de la piel.",
                "Secreciones en los ojos u oídos: pueden indicar irritación o infección.",
                "Tos o dificultad respiratoria: requieren evaluación veterinaria, especialmente si aparecen de forma repentina.",
                "Cojera: puede estar relacionada con una lesión, dolor articular o problemas de desarrollo.",
                "Abdomen muy hinchado: puede deberse a parásitos u otros problemas digestivos y debe evaluarse si es persistente o doloroso.",
                "Retraso en el crecimiento: puede relacionarse con una alimentación inadecuada, parásitos u otras enfermedades.",
                "Encías muy pálidas, azuladas o amarillentas: pueden indicar problemas importantes y requieren atención urgente."
              ]
            }
          ]
        },
        "primeros": {
          "titulo": "Primeros auxilios",
          "secciones": [
            {
              "titulo": "QUÉ HACER CUANDO LE SUCEDEN ACCIDENTES",
              "items": [
                "Los primeros auxilios ayudan a proteger al cachorro mientras recibe atención veterinaria. No sustituyen una evaluación profesional, especialmente porque los cachorros pueden empeorar rápidamente cuando sufren intoxicaciones, traumatismos o deshidratación.",
                "Heridas pequeñas: mantener al cachorro tranquilo y limpiar suavemente la zona con suero fisiológico o agua limpia. Si la herida es profunda, está contaminada o presenta inflamación importante, debe acudir al veterinario.",
                "Sangrado: aplicar presión suave y constante con una gasa o tela limpia. Si el sangrado es abundante, no se detiene o la herida es profunda, necesita atención urgente.",
                "Caídas o golpes: evitar que corra o salte y observar si presenta dolor, cojera, desorientación o dificultad para levantarse. Si el golpe fue fuerte, debe ser evaluado por un veterinario.",
                "Posible fractura: limitar sus movimientos y trasladarlo con cuidado, procurando sostener su cuerpo. No intentar acomodar el hueso ni fabricar una férula apretada.",
                "Atragantamiento: si tiene dificultad para respirar, hace esfuerzos sin poder tomar aire o pierde el conocimiento, se trata de una emergencia. Contactar inmediatamente con un veterinario y seguir sus instrucciones; no introducir los dedos a ciegas en la garganta.",
               ] 
            },
            {
              "titulo": "QUÉ HACER CUANDO LE SUCEDEN ACCIDENTES",
              "items": [
                
                "Ingestión de sustancias tóxicas: retirar el producto del alcance del cachorro, conservar el envase y contactar inmediatamente con un veterinario. No provocar el vómito ni administrar remedios caseros sin indicación profesional.",
                "Golpe de calor: trasladarlo a un lugar fresco, mojar su cuerpo con agua fresca, no helada, y acudir urgentemente al veterinario. No cubrirlo con toallas empapadas que retengan el calor.",
                "Vómitos o diarrea: vigilar su estado y consultar al veterinario si se repiten, hay sangre o el cachorro está decaído. No administrar medicamentos humanos.",
                "Picadura de insecto: observar si aparece hinchazón importante, dolor o picazón. Si presenta hinchazón facial, dificultad para respirar o debilidad repentina, necesita atención de emergencia.",
                "Convulsiones: retirar los objetos cercanos para evitar golpes, mantener el ambiente tranquilo y no introducir las manos en su boca. Contactar inmediatamente con un veterinario, sobre todo si es la primera convulsión o se prolonga.",
                "Pérdida de conocimiento: acudir inmediatamente a un servicio veterinario de urgencias.",
                "Prevención de accidentes: mantener fuera de su alcance cables eléctricos, productos de limpieza, medicamentos, objetos pequeños y alimentos tóxicos."
              ]
            }
          ]
        },
        "cuidados": {
          "titulo": "Cuidados",
          "secciones": [
            {
              "titulo": "CÓMO MANTENERLO BIEN CUIDADO",
              "items": [
                "Los cuidados diarios ayudan a prevenir enfermedades, favorecer el desarrollo y acostumbrar al cachorro a las rutinas que tendrá durante su vida adulta.",
                "Cepillado: cepillar su pelaje varias veces por semana para retirar el pelo suelto y mantenerlo limpio. El Labrador tiene un pelaje doble que muda durante el año.",
                "Baño: bañarlo cuando esté sucio o lo necesite, utilizando champú formulado para perros. Los baños excesivos pueden resecar la piel.",
                "Higiene de los oídos: revisar las orejas con frecuencia, porque su forma puede favorecer la acumulación de humedad. Limpiarlas únicamente con productos adecuados y sin introducir objetos en el conducto auditivo.",
                "Higiene dental: acostumbrarlo progresivamente al cepillado de dientes con cepillo y pasta dental para perros.",
                "Cuidado de las uñas: revisar su longitud y recortarlas cuando sea necesario, evitando cortar la parte sensible.",
                "Ejercicio moderado: ofrecer paseos cortos, juegos controlados y actividades apropiadas para su edad. Evitar el ejercicio forzado, los saltos repetidos y las carreras prolongadas mientras sus huesos y articulaciones están en desarrollo.",
                "Descanso: proporcionarle una cama cómoda, un lugar tranquilo y suficientes horas de sueño.",
                "Socialización: acostumbrarlo de forma positiva y gradual a personas, sonidos, superficies y otros perros sanos y vacunados.",
                "Seguridad: utilizar una correa adecuada, identificación y un espacio cercado. No dejarlo solo en lugares peligrosos.",
                "Protección frente al calor: ofrecer sombra, agua fresca y evitar paseos durante las horas de mayor temperatura.",
                "Estimulación mental: utilizar juguetes seguros, juegos de olfato y sesiones breves de aprendizaje.",
                "Supervisión: vigilarlo cuando juega, especialmente si tiene acceso a objetos pequeños, escaleras o espacios donde pueda quedarse atrapado."
              ]
            },
            {
              "titulo": "CÓMO SABER SI NO TIENE UN BUEN CUIDADO",
              "items": [
                "La falta de higiene, supervisión, alimentación adecuada o atención médica puede afectar su salud física y emocional.",
                "Presenta el pelaje sucio, enredado o con una acumulación excesiva de pelo muerto.",
                "Tiene uñas demasiado largas que dificultan su caminar.",
                "Sus orejas presentan suciedad excesiva, mal olor o secreciones.",
                "Su boca tiene mal olor persistente o acumulación importante de placa.",
                "Vive en un lugar sucio, húmedo, peligroso o sin protección frente al clima.",
                "No tiene agua limpia disponible o recibe una alimentación insuficiente.",
                "Permanece encerrado durante periodos prolongados sin actividad ni interacción.",
                "No recibe oportunidades para aprender, explorar y socializar de manera segura.",
                "Presenta miedo constante, estrés o conductas destructivas que pueden relacionarse con aburrimiento, ansiedad u otras necesidades no atendidas.",
                "No recibe las vacunas, desparasitaciones o revisiones veterinarias necesarias.",
                "Tiene heridas, parásitos o enfermedades que no son atendidos.",
                "Se encuentra constantemente expuesto al calor intenso, al frío o a superficies peligrosas."
              ]
            }
          ]
        },
        "comportamiento": {
          "titulo": "Comportamiento",
          "secciones": [
            {
              "titulo": "ADIESTRAMIENTO DESDE CACHORRO",
              "items": [
                "El Labrador Retriever suele ser inteligente, sociable, activo y motivado por la comida. El entrenamiento temprano permite enseñarle buenos hábitos y desarrollar una relación de confianza con su familia.",
                "Aprender su nombre: llamarlo por su nombre y premiarlo cuando preste atención.",
                "Enseñar a hacer sus necesidades: llevarlo al lugar indicado después de despertarse, comer, beber o jugar, premiándolo cuando lo haga correctamente.",
                "Órdenes básicas: enseñarle progresivamente instrucciones como «siéntate», «quieto», «ven» y «suelta».",
                "Refuerzo positivo: premiar las conductas deseadas con pequeñas recompensas, juguetes o elogios. Evitar los golpes, gritos y castigos que provoquen miedo.",
                "Control de mordidas durante el juego: si muerde las manos, interrumpir brevemente el juego y ofrecerle un juguete apropiado para morder.",
                "Caminar con correa: acostumbrarlo poco a poco a usar collar o arnés y caminar sin tirar constantemente.",
                "Socialización temprana: presentarle personas, sonidos y entornos nuevos de manera gradual y positiva. El veterinario debe orientar sobre cómo hacerlo de forma segura antes de completar sus vacunas.",
                "Evitar saltar sobre las personas: premiarlo cuando mantenga las cuatro patas en el suelo y pedir a las visitas que no refuercen los saltos.",
                "Control de impulsos: enseñarle a esperar antes de salir por una puerta o recibir su comida.",
                "Sesiones cortas: realizar prácticas de pocos minutos, varias veces al día, para mantener su atención.",
                "Juguetes y enriquecimiento: ofrecer actividades de olfato y juguetes seguros que le permitan utilizar su inteligencia.",
                "Consistencia familiar: todos los miembros del hogar deben utilizar las mismas órdenes y normas."
              ]
            },
            {
              "titulo": "CÓMO MEJORAR SU COMPORTAMIENTO SI NO FUE ADIESTRADO",
              "items": [
                "Un cachorro que no ha recibido entrenamiento puede aprender progresivamente con paciencia, constancia y métodos positivos.",
                "Identificar la causa: determinar si el comportamiento se debe a falta de aprendizaje, miedo, aburrimiento, exceso de energía o alguna molestia física.",
                "Establecer rutinas: mantener horarios previsibles para comer, descansar, jugar y salir a hacer sus necesidades.",
                "Corregir los saltos: evitar premiarlos accidentalmente con atención y recompensar la conducta tranquila.",
                "Reducir las mordidas de juego: redirigirlas hacia juguetes apropiados y detener brevemente la interacción cuando sea necesario.",
                "Disminuir los ladridos excesivos: identificar qué los desencadena y premiar los momentos de calma.",
                "Evitar destruir objetos: ofrecer juguetes seguros, supervisar y guardar los objetos que no debe morder.",
                "Practicar órdenes básicas: empezar por una instrucción sencilla y aumentar la dificultad cuando la domine.",
                "Prevenir la ansiedad al quedarse solo: acostumbrarlo gradualmente a separaciones breves y tranquilas, sin castigarlo por mostrar miedo.",
                "Recompensar los avances: reconocer las mejoras pequeñas y mantener expectativas adecuadas para su edad.",
                "Consultar a un profesional: si muestra miedo intenso, agresividad o ansiedad persistente, buscar un veterinario o educador canino que utilice métodos respetuosos."
              ]
            }
          ]
        },
        "vacunacion": {
          "titulo": "Vacunación",
          "secciones": [
            {
              "titulo": "TODAS LAS VACUNAS QUE DEBE TENER DURANTE SU VIDA",
              "items": [
                "Las vacunas protegen al Labrador Retriever frente a enfermedades infecciosas que pueden ser graves o mortales. El calendario exacto depende del país, el riesgo de exposición, la edad y los antecedentes del cachorro.",
                "Moquillo canino: protege frente a una enfermedad viral que puede afectar los sistemas respiratorio, digestivo y nervioso.",
                "Parvovirus canino: ayuda a prevenir una infección muy contagiosa que puede provocar vómitos, diarrea intensa y deshidratación.",
                "Adenovirus canino: contribuye a proteger frente a la hepatitis infecciosa canina y otras enfermedades relacionadas.",
                "Parainfluenza canina: forma parte de las vacunas que pueden utilizarse para reducir el riesgo de determinadas infecciones respiratorias.",
                "Leptospirosis: protege frente a una infección bacteriana que puede afectar los riñones y el hígado y que también puede transmitirse a las personas.",
                "Rabia: es esencial según la normativa del lugar y las recomendaciones sanitarias. La enfermedad es mortal una vez aparecen los síntomas.",
                "Bordetella y otras vacunas respiratorias: pueden recomendarse si el cachorro asistirá a guarderías, residencias caninas, clases grupales o lugares con muchos perros.",
                "Otras vacunas específicas: el veterinario puede recomendar otras según las enfermedades presentes en la región y el estilo de vida del animal.",
                "Calendario orientativo de vacunación:",
                "Entre las 6 y 8 semanas: suele iniciarse la vacunación básica frente a moquillo, parvovirus y otras enfermedades incluidas en la vacuna combinada.",
                "Entre las 9 y 12 semanas: se administran las dosis siguientes de acuerdo con el calendario veterinario.",
                "Entre las 12 y 16 semanas: se completa la serie inicial de vacunas básicas; el número de dosis depende de la edad de inicio y del producto utilizado.",
                "A partir de las 12 semanas aproximadamente: puede administrarse la vacuna contra la rabia, según la legislación local y las instrucciones del veterinario.",
                "Alrededor de los 6 a 12 meses: se recomienda una revisión de la vacunación y, para las vacunas básicas, una dosis de refuerzo según el protocolo veterinario.",
                "Durante la vida adulta: se aplican refuerzos según la duración de la inmunidad, la vacuna utilizada y las recomendaciones sanitarias.",
                "Vacunas adicionales: las vacunas contra leptospirosis, Bordetella y otras enfermedades pueden requerir refuerzos más frecuentes, según el riesgo y el producto.",
                "Es importante no considerar estas edades como un calendario universal. El veterinario debe registrar las dosis y determinar las fechas correctas. Mientras el cachorro no tenga protección suficiente, se debe evitar exponerlo a lugares de alto riesgo de contaminación."
              ]
            },
            {
              "titulo": "DESPARASITACIÓN INTERNA Y EXTERNA",
              "items": [
                "La desparasitación ayuda a controlar los organismos que pueden afectar la salud del cachorro. Debe realizarse con productos adecuados para su edad, peso y estado de salud.",
                "Desparasitación interna:",
                "Lombrices intestinales: pueden causar diarrea, abdomen abultado, pérdida de peso y crecimiento deficiente.",
                "Anquilostomas: pueden provocar pérdida de sangre y anemia, especialmente en cachorros.",
                "Tricocéfalos y otros gusanos intestinales: pueden ocasionar molestias digestivas y problemas de salud.",
                "Tenias: algunos tipos se transmiten mediante pulgas o por la ingestión de huéspedes infectados.",
                "Giardia y coccidios: son organismos intestinales que pueden provocar diarrea y requieren tratamientos específicos, no necesariamente los mismos que se usan contra los gusanos.",
                "Frecuencia orientativa: los cachorros suelen comenzar la desparasitación interna durante las primeras semanas de vida y repetirla periódicamente de acuerdo con el protocolo veterinario. Más adelante, la frecuencia se ajusta según el riesgo y, cuando corresponde, los análisis de heces.",
                "Higiene: recoger las heces rápidamente, lavar los recipientes de comida y agua y mantener limpio el lugar donde duerme.",
                "Desparasitación externa:",
                "Pulgas: pueden provocar picazón, dermatitis y, en infestaciones intensas, anemia.",
                "Garrapatas: pueden transmitir enfermedades y deben retirarse correctamente.",
                "Ácaros: algunos causan sarna, picazón intensa y pérdida de pelo.",
                "Productos preventivos: existen pipetas, comprimidos, collares y otros tratamientos. Deben elegirse según la edad y el peso del cachorro, respetando las instrucciones veterinarias.",
                "Prevención ambiental: lavar su cama, aspirar las zonas donde descansa y revisar su pelaje después de pasear.",
                "Precauciones: nunca utilizar productos destinados a otra especie ni combinar tratamientos sin consultar al veterinario."
              ]
            }
          ]
        },
        "veterinario": {
          "titulo": "Cuándo llevar al veterinario",
          "secciones": [
            {
              "titulo": "REVISIONES RUTINARIAS",
              "items": [
                "Las revisiones veterinarias permiten controlar el crecimiento, detectar enfermedades tempranas y organizar las vacunas y la prevención de parásitos.",
                "Primera revisión: debe realizarse al llegar al hogar o tan pronto como sea posible, para evaluar su estado general.",
                "Controles de crecimiento: el veterinario revisa el peso, la condición corporal, los dientes, los huesos y el desarrollo.",
                "Vacunación: se deben cumplir las citas programadas para completar la protección inicial.",
                "Desparasitación: se establece un calendario según la edad, los antecedentes y el riesgo de exposición.",
                "Alimentación: se revisan las porciones y el tipo de alimento para prevenir un crecimiento excesivamente rápido o un peso inadecuado.",
                "Salud dental: se controla la dentición y el recambio de los dientes de leche.",
                "Esterilización: se puede conversar con el veterinario sobre el momento más apropiado, considerando el desarrollo de una raza grande.",
                "Frecuencia de los controles: durante los primeros meses las visitas pueden ser frecuentes por las vacunas y el crecimiento; después se programan según las necesidades del animal."
              ]
            },
            {
              "titulo": "SEÑALES DE ALERTA",
              "items": [
                "Se debe solicitar una consulta veterinaria si presenta cambios persistentes o síntomas que no parecen normales.",
                "Pérdida de apetito o rechazo persistente de la comida.",
                "Vómitos repetidos o diarrea que no mejora.",
                "Picazón intensa, caída anormal del pelo o heridas en la piel.",
                "Secreciones persistentes en los ojos o los oídos.",
                "Tos, estornudos persistentes o secreción nasal anormal.",
                "Cojera, dificultad para levantarse o dolor al caminar.",
                "Aumento o pérdida de peso sin una explicación clara.",
                "Abdomen persistentemente hinchado.",
                "Sed u orina en cantidades muy diferentes de lo habitual.",
                "Decaimiento, cambios de comportamiento o sueño excesivo acompañado de otros síntomas."
              ]
            },
            {
              "titulo": "EMERGENCIAS VETERINARIAS",
              "items": [
                "Debe acudir a urgencias veterinarias inmediatamente si presenta cualquiera de las siguientes situaciones:",
                "Dificultad para respirar o respiración muy comprometida.",
                "Desmayo, pérdida del conocimiento o convulsiones.",
                "Sangrado abundante o una lesión grave.",
                "Ingestión de venenos, medicamentos humanos u otras sustancias tóxicas.",
                "Vómitos repetidos acompañados de debilidad intensa, especialmente si no puede retener agua.",
                "Abdomen que aumenta de tamaño repentinamente, especialmente si intenta vomitar sin conseguirlo.",
                "Encías muy pálidas, azuladas o amarillentas.",
                "Sospecha de fractura o traumatismo importante.",
                "Diarrea con sangre acompañada de decaimiento intenso.",
                "Signos de golpe de calor, como jadeo extremo, debilidad, desorientación o colapso."
                           ]
            }
          ]
        }
      }
    },
    "adulto": {
      "tituloOriginal": "LABRADOR RETRIEVER ADULTO (DE 1 A 7 AÑOS)",
      "temas": {
        "alimentacion": {
          "titulo": "Alimentación",
          "secciones": [
            {
              "titulo": "ALIMENTACIÓN SALUDABLE",
              "items": [
                "El Labrador Retriever adulto necesita una alimentación equilibrada que mantenga su musculatura, aporte energía para sus actividades diarias y ayude a conservar un peso saludable. Esta raza tiene predisposición a ganar peso si consume más calorías de las que necesita, por lo que el control de las porciones es fundamental.",
                "Alimento para perros adultos: debe recibir un alimento completo y equilibrado formulado para perros adultos, con nutrientes adecuados para mantener sus músculos, huesos, órganos y sistema inmunológico.",
                "Proteínas de calidad: ayudan a mantener la masa muscular y reparar los tejidos. Pueden proceder de ingredientes animales como pollo, pescado, pavo o carne.",
                "Grasas saludables: aportan energía y ácidos grasos esenciales que contribuyen a la salud de la piel y el pelaje.",
                "Carbohidratos y fibra: proporcionan energía y favorecen el funcionamiento digestivo. La fibra también puede contribuir a la sensación de saciedad.",
                "Vitaminas y minerales: son necesarios para el metabolismo, la función inmunitaria y el mantenimiento de los huesos y los dientes.",
                "Agua fresca: debe estar disponible en todo momento, especialmente después de los paseos, el juego o la actividad física.",
                "Frecuencia de alimentación: generalmente, dos comidas al día ayudan a establecer una rutina y controlar mejor las porciones.",
                "Control del peso: se deben ajustar las cantidades según su actividad, condición corporal y necesidades energéticas.",
                "Premios moderados: pueden utilizarse durante el entrenamiento, pero no deben desplazar una parte importante de su alimentación equilibrada.",
                "Cambios alimentarios graduales: cuando sea necesario cambiar de alimento, hacerlo durante varios días puede reducir las molestias digestivas.",
                "Alimentación adaptada a su actividad: un Labrador que realiza ejercicio intenso puede necesitar una cantidad diferente a la de uno que pasa gran parte del día descansando."
              ]
            },
            {
              "titulo": "ALIMENTACIÓN NO SALUDABLE",
              "items": [
                "Una dieta inadecuada puede provocar obesidad, alteraciones digestivas y problemas metabólicos, además de aumentar la carga sobre las articulaciones.",
                "Exceso de comida: es una de las causas de aumento de peso. Las porciones deben medirse y ajustarse según las necesidades reales del perro.",
                "Sobras de la mesa: pueden contener cantidades elevadas de grasa, sal y condimentos.",
                "Chocolate, uvas y pasas: son alimentos tóxicos y no deben ofrecerse.",
                "Cebolla y ajo: pueden dañar los glóbulos rojos y causar anemia.",
                "Alcohol y cafeína: pueden provocar intoxicaciones peligrosas.",
                "Huesos cocidos: pueden causar heridas, obstrucciones y otros daños en el aparato digestivo.",
                "Dulces y productos con xilitol: pueden causar una intoxicación grave.",
                "Exceso de grasas: las comidas muy grasosas pueden aumentar el riesgo de pancreatitis.",
                "Dietas desequilibradas: ofrecer solamente carne, arroz o sobras no garantiza el aporte adecuado de nutrientes.",
                "Suplementos innecesarios: no se deben administrar vitaminas, calcio ni otros suplementos sin indicación veterinaria.",
                "Comer demasiado rápido y recibir premios en exceso puede dificultar el control del peso."
              ]
            }
          ]
        },
 
        "salud": {
          "titulo": "Salud",
          "secciones": [
            {
              "titulo": "SEÑALES DE BUENA SALUD",
              "items": [
                "Un Labrador Retriever adulto saludable mantiene una condición corporal adecuada, una actividad acorde con su edad y una conducta habitual estable.",
                "Mantiene un peso adecuado y una musculatura bien desarrollada.",
                "Tiene apetito regular y bebe agua con normalidad.",
                "Presenta ojos claros y sin secreciones persistentes.",
                "Tiene la piel sin irritaciones importantes y un pelaje limpio.",
                "Camina, corre y juega sin mostrar dolor ni cojera.",
                "Se levanta y se acuesta con facilidad.",
                "Tiene una respiración normal durante el descanso.",
                "Sus heces son relativamente firmes y mantiene hábitos de eliminación regulares.",
                "Muestra interés por los paseos, los juegos y la interacción social.",
                "Sus dientes y encías se mantienen en buenas condiciones con una higiene apropiada.",
                "Mantiene una conducta estable y responde a las rutinas conocidas.",
                "Se recupera de la actividad física de manera normal, sin debilidad excesiva."
              ]
            },
            {
              "titulo": "SEÑALES DE MALA SALUD",
              "items": [
                "Los cambios físicos o de comportamiento pueden indicar una enfermedad y deben evaluarse según su intensidad y duración.",
                "Aumento de peso: puede deberse al exceso de calorías, a la falta de ejercicio o a problemas de salud.",
                "Pérdida de peso involuntaria: puede relacionarse con enfermedades digestivas, metabólicas u otros problemas.",
                "Rigidez o cojera: puede indicar molestias articulares, lesiones o alteraciones musculoesqueléticas.",
                "Dificultad para levantarse: especialmente si aparece de forma reciente, requiere una evaluación.",
                "Picazón persistente: puede estar relacionada con alergias, pulgas, infecciones u otras afecciones.",
                "Mal aliento intenso: puede indicar acumulación de placa, enfermedad periodontal u otros problemas.",
                "Vómitos o diarrea recurrentes: pueden relacionarse con alteraciones digestivas o enfermedades sistémicas.",
                "Sed excesiva y aumento de la orina: pueden ser señales de problemas metabólicos o renales.",
                "Cambios en el apetito: comer mucho más o mucho menos de lo habitual puede requerir evaluación.",
                "Bultos nuevos: deben revisarse, especialmente si crecen, cambian de forma, duelen o sangran.",
                "Tos o intolerancia al ejercicio: pueden estar relacionados con problemas respiratorios, cardíacos u otras enfermedades.",
                "Cambios de conducta: irritabilidad, aislamiento o inquietud pueden ser señales de dolor o malestar."
              ]
            }
          ]
        },
 
        "primeros": {
          "titulo": "Primeros auxilios",
          "secciones": [
            {
              "titulo": "QUÉ HACER CUANDO LE SUCEDEN ACCIDENTES",
              "items": [
                "Los primeros auxilios consisten en proteger al perro y evitar que la situación empeore hasta recibir atención veterinaria.",
                "Heridas superficiales: limpiar con suero fisiológico o agua limpia y evitar que el perro lama la zona. Las heridas profundas, mordeduras o heridas contaminadas deben ser evaluadas por un veterinario.",
                "Sangrado: aplicar presión continua con una gasa o tela limpia. Si el sangrado es abundante o no se detiene, acudir a urgencias.",
                "Golpes o caídas: limitar sus movimientos y observar si presenta dolor, dificultad para caminar o respiración anormal.",
                "Sospecha de fractura: mantenerlo lo más quieto posible y trasladarlo con cuidado. No intentar enderezar la extremidad.",
                "Atragantamiento: si tiene dificultad para respirar, buscar asistencia veterinaria urgente. No introducir los dedos a ciegas en la boca.",
                "Intoxicación: identificar la sustancia, guardar el envase y contactar inmediatamente con el veterinario. No provocar el vómito ni administrar remedios caseros.",
                "Golpe de calor: trasladarlo a un lugar fresco, comenzar a enfriarlo con agua fresca, no helada, y acudir inmediatamente al veterinario.",
                "Picaduras: vigilar la inflamación y el comportamiento. La hinchazón de la cara, la dificultad respiratoria o el colapso requieren atención urgente.",
                "Convulsiones: despejar el área para evitar golpes, no sujetarlo a la fuerza y no introducir objetos en su boca. Buscar atención veterinaria.",
                "Problemas digestivos: si presenta vómitos repetidos, dolor abdominal o sangre en las heces, necesita evaluación veterinaria.",
                "Accidentes de tránsito: incluso si parece estar bien, debe ser evaluado, porque algunas lesiones internas no son evidentes al principio.",
                "Prevención: mantener sustancias peligrosas, medicamentos y objetos cortantes fuera de su alcance."
              ]
            }
          ]
        },
 
        "cuidados": {
          "titulo": "Cuidados",
          "secciones": [
            {
              "titulo": "CÓMO MANTENERLO BIEN CUIDADO",
              "items": [
                "Los cuidados del Labrador adulto deben enfocarse en mantener su higiene, condición física, salud dental y bienestar emocional.",
                "Cepillado regular: cepillar varias veces por semana para retirar el pelo muerto y mantener el pelaje en buenas condiciones.",
                "Baño: bañarlo cuando lo necesite, utilizando productos para perros y secándolo adecuadamente.",
                "Cuidado de los oídos: revisar las orejas con frecuencia y limpiarlas con productos apropiados cuando sea necesario.",
                "Higiene dental: cepillar sus dientes regularmente con pasta dental para perros y consultar si presenta mal aliento persistente o dolor al comer.",
                "Cuidado de las uñas: revisarlas y recortarlas cuando estén demasiado largas.",
                "Ejercicio diario: realizar paseos y actividades adaptados a su condición física. Muchos adultos disfrutan de caminatas, juegos de buscar objetos y actividades de olfato.",
                "Control del peso: medir las raciones, limitar los premios y revisar periódicamente su condición corporal.",
                "Estimulación mental: utilizar juguetes interactivos, entrenamiento y juegos que le permitan resolver pequeños problemas.",
                "Descanso: proporcionarle una cama cómoda y un espacio tranquilo para dormir.",
                "Hidratación: ofrecer agua limpia durante todo el día y llevar agua durante los paseos largos.",
                "Protección climática: evitar el ejercicio intenso durante el calor y proporcionar sombra y ventilación.",
                "Seguridad durante los paseos: utilizar correa en los lugares donde sea necesaria y mantener su identificación actualizada.",
                "Atención preventiva: cumplir las revisiones veterinarias, las vacunas y la prevención de parásitos.",
                "Interacción social: dedicarle tiempo diariamente y ofrecerle oportunidades seguras de interacción con personas y otros perros."
              ]
            },
            {
              "titulo": "CÓMO SABER SI NO TIENE UN BUEN CUIDADO",
              "items": [
                "La falta de atención a sus necesidades puede afectar su salud física y su comportamiento.",
                "Presenta sobrepeso o pérdida excesiva de masa muscular.",
                "Tiene el pelaje sucio o la piel irritada.",
                "Sus uñas están demasiado largas y dificultan el movimiento.",
                "Tiene acumulación importante de sarro o mal aliento persistente.",
                "Sus oídos presentan mal olor o secreciones.",
                "No realiza suficiente actividad física y muestra inquietud o aburrimiento.",
                "Pasa demasiado tiempo aislado y sin interacción.",
                "No dispone de agua limpia, alimento adecuado o un lugar cómodo para descansar.",
                "Permanece expuesto al calor intenso o a condiciones climáticas peligrosas.",
                "No recibe atención veterinaria preventiva.",
                "Presenta dolor, cojera o enfermedades que no son evaluadas.",
                "Muestra conductas destructivas, ansiedad o ladridos excesivos que pueden relacionarse con necesidades físicas o emocionales no atendidas."
              ]
            }
          ]
        },
 
        "comportamiento": {
          "titulo": "Comportamiento",
          "secciones": [
            {
              "titulo": "ADIESTRAMIENTO Y MANTENIMIENTO DE BUENOS HÁBITOS",
              "items": [
                "Aunque el Labrador Retriever adulto suele aprender con facilidad, necesita seguir recibiendo ejercicio, estimulación mental y entrenamiento para mantener una conducta equilibrada.",
                "Repasar órdenes básicas: practicar «ven», «siéntate», «quieto» y «suelta» en diferentes entornos.",
                "Caminar sin tirar de la correa: premiar cuando camine con la correa floja y detenerse cuando tire, siempre con métodos seguros y consistentes.",
                "Controlar los saludos: enseñarle a mantener las cuatro patas en el suelo para evitar saltar sobre las personas.",
                "Esperar antes de comer: utilizar breves ejercicios de autocontrol sin generar frustración.",
                "Practicar la llamada: recompensarlo cuando regrese al escuchar su nombre u orden, practicando inicialmente en lugares seguros.",
                "Estimulación mental: incorporar juegos de olfato, juguetes interactivos y aprendizaje de nuevas habilidades.",
                "Ejercicio apropiado: combinar caminatas, juegos y actividades que correspondan a su condición física.",
                "Socialización continua: mantener experiencias positivas con personas y perros adecuados.",
                "Reforzar la calma: premiar los momentos en los que descansa tranquilamente en su cama o permanece relajado.",
                "Mantener la consistencia: todos los miembros del hogar deben aplicar normas similares.",
                "Evitar castigos físicos: los golpes y gritos pueden aumentar el miedo y empeorar determinados problemas de comportamiento."
              ]
            },
            {
              "titulo": "CÓMO MEJORAR SU COMPORTAMIENTO SI NO FUE ADIESTRADO",
              "items": [
                "Un Labrador adulto también puede aprender nuevos hábitos. El progreso dependerá de la constancia, sus experiencias anteriores y las causas de la conducta.",
                "Evaluar el origen del problema: descartar dolor, enfermedad, miedo, ansiedad o falta de actividad.",
                "Establecer reglas claras: definir dónde puede descansar, cómo debe saludar y cuáles son los comportamientos esperados.",
                "Comenzar con ejercicios sencillos: practicar una orden a la vez y aumentar la dificultad gradualmente.",
                "Controlar los saltos: premiar los saludos tranquilos y evitar reforzar los saltos con atención.",
                "Reducir los tirones de correa: practicar en lugares tranquilos y recompensar el caminar sin tensión.",
                "Manejar los ladridos: identificar los estímulos que los provocan y enseñar una conducta alternativa.",
                "Prevenir la destrucción de objetos: ofrecer juguetes apropiados y aumentar las actividades de olfato y exploración.",
                "Trabajar la soledad: acostumbrarlo progresivamente a quedarse solo, sin castigos por conductas relacionadas con ansiedad.",
                "Recompensar los avances: utilizar premios pequeños, elogios o juegos para reforzar los comportamientos deseados.",
                "Solicitar ayuda profesional: si hay agresividad, miedo intenso o ansiedad persistente, consultar a un veterinario o profesional del comportamiento que trabaje con refuerzo positivo."
              ]
            }
          ]
        },
 
        "vacunacion": {
          "titulo": "Vacunación y desparasitación",
          "secciones": [
            {
              "titulo": "VACUNAS QUE DEBE TENER DURANTE SU VIDA",
              "items": [
                "Las vacunas del Labrador adulto deben mantenerse actualizadas según las dosis recibidas durante la etapa de cachorro, el riesgo de exposición y la normativa local.",
                "Moquillo canino: protege frente a una enfermedad viral que puede afectar los sistemas respiratorio, digestivo y nervioso.",
                "Parvovirus canino: ayuda a prevenir una infección intestinal muy contagiosa.",
                "Adenovirus canino: contribuye a proteger frente a la hepatitis infecciosa canina.",
                "Parainfluenza canina: puede incluirse en la protección frente a enfermedades respiratorias, según el producto y el riesgo.",
                "Leptospirosis: protege frente a una infección bacteriana que puede dañar los riñones y el hígado y transmitirse a las personas.",
                "Rabia: debe mantenerse al día conforme a la legislación local y las recomendaciones veterinarias.",
                "Bordetella: puede recomendarse para perros que acuden a guarderías, residencias, exposiciones o lugares con muchos perros.",
                "Otras vacunas: pueden considerarse según la región, las enfermedades presentes y las actividades del animal.",
                "Frecuencia orientativa: las vacunas básicas suelen recibir un refuerzo durante el primer año después de la serie inicial. Algunas pueden necesitar refuerzos cada tres años, mientras que otras requieren una frecuencia diferente.",
                "La vacuna contra la leptospirosis suele necesitar refuerzos anuales, según el producto. La vacuna contra la rabia se administra de acuerdo con la normativa local y la duración de inmunidad autorizada.",
                "Si se desconoce el historial de vacunación, el veterinario debe establecer un calendario de recuperación.",
                "No todas las vacunas se administran con la misma frecuencia. Es importante conservar el registro de vacunación y no aplicar dosis adicionales sin una evaluación profesional."
              ]
            },
            {
              "titulo": "DESPARASITACIÓN INTERNA Y EXTERNA",
              "items": [
                "La prevención de parásitos continúa durante la edad adulta. El plan depende de la región, el estilo de vida, la convivencia con otros animales y el riesgo de exposición.",
                "Lombrices intestinales: pueden afectar la digestión y, en algunos casos, causar pérdida de peso o diarrea.",
                "Anquilostomas: pueden provocar pérdida de sangre y anemia.",
                "Tricocéfalos: pueden producir alteraciones intestinales.",
                "Tenias: algunos tipos se relacionan con la ingestión de pulgas infectadas.",
                "Giardia y coccidios: pueden provocar diarrea y requieren diagnóstico y tratamiento específicos.",
                "Frecuencia interna: se determina según el riesgo individual y las recomendaciones veterinarias. En algunos perros se utilizan tratamientos periódicos; en otros, análisis de heces y tratamientos dirigidos.",
                "Higiene: recoger las heces, limpiar el lugar donde descansa y evitar que ingiera heces o agua contaminada.",
                "Pulgas: pueden provocar picazón y dermatitis.",
                "Garrapatas: pueden transmitir enfermedades infecciosas.",
                "Ácaros: pueden causar diferentes afecciones de la piel.",
                "Productos preventivos: utilizar tratamientos adecuados para su peso y condiciones de salud.",
                "No combinar tratamientos por cuenta propia. Se deben respetar las instrucciones veterinarias y del producto."
              ]
            }
          ]
        },
 
        "veterinario": {
          "titulo": "Cuándo llevar al veterinario",
          "secciones": [
            {
              "titulo": "REVISIONES RUTINARIAS",
              "items": [
                "Las revisiones permiten controlar la salud general del Labrador adulto y establecer medidas de prevención.",
                "Examen físico: revisar peso, condición corporal, dientes, piel, oídos, corazón, pulmones y movilidad.",
                "Control del peso: vigilar su condición corporal para prevenir el sobrepeso y sus consecuencias articulares.",
                "Salud dental: revisar la presencia de sarro, mal aliento o dolor al comer.",
                "Vacunación: mantener al día las dosis y los refuerzos que correspondan.",
                "Desparasitación: establecer un plan según su exposición y antecedentes.",
                "Alimentación y actividad: consultar si necesita cambios en sus raciones o en su rutina de ejercicio.",
                "Frecuencia: realizar controles periódicos y seguir las fechas que indique el veterinario."
              ]
            },
            {
              "titulo": "SEÑALES DE ALERTA",
              "items": [
                "Solicitar una consulta si presenta pérdida o aumento de peso sin explicación.",
                "Cambios persistentes en el apetito o en el consumo de agua.",
                "Rigidez, cojera o dificultad para levantarse.",
                "Picazón persistente, heridas o pérdida anormal de pelo.",
                "Mal aliento intenso o dificultad para masticar.",
                "Vómitos o diarrea recurrentes.",
                "Sed excesiva o cambios importantes en la cantidad de orina.",
                "Bultos nuevos o lesiones que no cicatrizan.",
                "Tos, respiración anormal o menor tolerancia al ejercicio.",
                "Irritabilidad, aislamiento o cambios repentinos de conducta."
              ]
            },
            {
              "titulo": "EMERGENCIAS VETERINARIAS",
              "items": [
                "Dificultad para respirar o encías azuladas.",
                "Desmayo, pérdida del conocimiento o convulsiones.",
                "Ingestión de venenos, medicamentos humanos o sustancias tóxicas.",
                "Sangrado abundante o heridas profundas.",
                "Abdomen hinchado repentinamente acompañado de arcadas sin vómito.",
                "Golpe de calor con debilidad, desorientación o colapso.",
                "Traumatismos graves, atropellos o sospecha de fractura.",
                "Vómitos repetidos con debilidad intensa o sangre en las heces."
              ]
            }
          ]
        }
      }
    },
 
    "senior": {
      "tituloOriginal": "LABRADOR RETRIEVER SENIOR (DESDE LOS 10 AÑOS)",
      "temas": {
        "alimentacion": {
          "titulo": "Alimentación",
          "secciones": [
            {
              "titulo": "ALIMENTACIÓN SALUDABLE",
              "items": [
                "El Labrador Retriever senior necesita una alimentación adaptada a los cambios que aparecen con la edad. Puede disminuir su actividad física, perder masa muscular o desarrollar problemas articulares y otras enfermedades. Por eso, la dieta debe ayudar a mantener una condición corporal adecuada y cubrir sus necesidades particulares.",
                "Alimento para perros senior: elegir un alimento completo y equilibrado adaptado a su edad y condición de salud.",
                "Proteínas de calidad: ayudan a conservar la masa muscular. La cantidad debe adaptarse a sus necesidades y a posibles enfermedades.",
                "Control de calorías: al disminuir la actividad, puede necesitar menos energía para evitar el aumento de peso.",
                "Fibra: puede favorecer la digestión y ayudar a mantener una buena función intestinal.",
                "Grasas saludables: aportan energía y ácidos grasos que contribuyen al cuidado de la piel y el pelaje.",
                "Agua fresca: debe estar disponible todo el día. Los cambios en el consumo de agua deben observarse y consultarse.",
                "Porciones controladas: ajustar las cantidades según su peso, actividad y condición corporal.",
                "Alimento fácil de consumir: si presenta problemas dentales, consultar sobre una textura adecuada.",
                "Cambios graduales: realizar las transiciones alimentarias poco a poco para evitar molestias digestivas.",
                "Dietas especiales: si tiene enfermedades renales, cardíacas, digestivas u otras, el veterinario puede recomendar una alimentación específica.",
                "Premios moderados: ofrecer pequeñas cantidades y tener en cuenta sus calorías dentro de la alimentación diaria."
              ]
            },
            {
              "titulo": "ALIMENTACIÓN NO SALUDABLE",
              "items": [
                "Una alimentación inadecuada puede empeorar los problemas de peso, movilidad y salud que aparecen durante el envejecimiento.",
                "Exceso de comida: puede provocar sobrepeso y aumentar la carga sobre las articulaciones.",
                "Alimentación insuficiente: puede favorecer la pérdida de peso y masa muscular.",
                "Sobras grasosas o saladas: pueden causar molestias digestivas y no son adecuadas para su alimentación habitual.",
                "Chocolate, uvas y pasas: son alimentos tóxicos para los perros.",
                "Cebolla y ajo: pueden dañar los glóbulos rojos.",
                "Huesos cocidos: pueden causar lesiones y obstrucciones digestivas.",
                "Dietas desequilibradas: ofrecer solamente carne, arroz o sobras no cubre necesariamente sus necesidades nutricionales.",
                "Suplementos sin indicación: no administrar vitaminas, calcio ni otros productos sin consultar al veterinario.",
                "Ignorar la pérdida de apetito: si un perro senior deja de comer, no se debe asumir que es algo normal de la edad.",
                "Premios excesivos: pueden contribuir al aumento de peso y dificultar el control de una dieta terapéutica."
              ]
            }
          ]
        },
 
        "salud": {
          "titulo": "Salud",
          "secciones": [
            {
              "titulo": "SEÑALES DE BUENA SALUD",
              "items": [
                "Un Labrador Retriever senior saludable puede mostrar un ritmo más tranquilo que cuando era joven, pero debería conservar interés por su entorno, movilidad razonable y bienestar general.",
                "Mantiene un peso relativamente estable y una condición corporal adecuada.",
                "Come y bebe con normalidad.",
                "Tiene una respiración tranquila durante el descanso.",
                "Puede levantarse y caminar sin dolor intenso.",
                "Disfruta de paseos adaptados a su capacidad física.",
                "Mantiene interés por las personas, los olores y las actividades habituales.",
                "Presenta ojos sin enrojecimiento intenso ni secreciones anormales.",
                "Su piel no presenta heridas persistentes ni irritación marcada.",
                "Sus hábitos de eliminación se mantienen relativamente estables.",
                "Descansa adecuadamente y puede acomodarse en un lugar confortable.",
                "Conserva una musculatura razonable para su edad.",
                "Responde a las rutinas familiares y mantiene una conducta habitual.",
                "Sus cambios de actividad son graduales y no aparecen acompañados de dolor intenso o debilidad repentina."
              ]
            },
            {
              "titulo": "SEÑALES DE MALA SALUD",
              "items": [
                "Con la edad aumenta la posibilidad de desarrollar enfermedades articulares, dentales, metabólicas, cardíacas y renales. Los cambios no deben atribuirse automáticamente al envejecimiento.",
                "Rigidez al levantarse: puede estar relacionada con artritis u otros problemas musculoesqueléticos.",
                "Dificultad para subir escaleras: puede indicar dolor articular, pérdida de fuerza o problemas de equilibrio.",
                "Pérdida de masa muscular: puede aparecer con la edad, pero también estar relacionada con enfermedades o una alimentación insuficiente.",
                "Aumento o pérdida de peso: los cambios involuntarios requieren evaluación.",
                "Pérdida de apetito: puede relacionarse con dolor dental, enfermedades digestivas u otros problemas.",
                "Sed excesiva y aumento de la orina: pueden ser señales de enfermedad renal, diabetes u otros trastornos.",
                "Mal aliento intenso: puede indicar enfermedad dental o periodontal.",
                "Tos o dificultad respiratoria: requieren evaluación, especialmente si aparecen en reposo.",
                "Bultos o masas: deben revisarse, ya que pueden tener diferentes causas.",
                "Cambios en la visión o el oído: pueden dificultar su orientación y aumentar el riesgo de accidentes.",
                "Desorientación: quedarse mirando fijamente, cambiar sus horarios de sueño o parecer confundido puede indicar un problema que merece evaluación.",
                "Incontinencia: perder orina o heces no debe considerarse inevitable por la edad.",
                "Dolor persistente: gemidos, inquietud, rechazo al movimiento o irritabilidad pueden ser señales de dolor.",
                "Heridas que no cicatrizan: necesitan revisión veterinaria."
              ]
            }
          ]
        },
 
        "primeros": {
          "titulo": "Primeros auxilios",
          "secciones": [
            {
              "titulo": "QUÉ HACER CUANDO LE SUCEDEN ACCIDENTES",
              "items": [
                "Los perros senior pueden necesitar más cuidado al sufrir accidentes debido a cambios en la movilidad y a la posibilidad de padecer enfermedades previas.",
                "Caídas: ayudarlo a mantenerse tranquilo y evitar que vuelva a caminar si presenta dolor, debilidad o dificultad para levantarse. Las caídas importantes requieren evaluación veterinaria.",
                "Heridas: limpiar suavemente las lesiones superficiales con suero fisiológico o agua limpia. Las heridas profundas, infectadas o que no cicatrizan deben ser revisadas.",
                "Sangrado: aplicar presión constante con una gasa limpia y acudir a urgencias si es abundante o no se detiene.",
                "Dificultad para levantarse: no tirar de sus patas ni forzarlo a caminar. Trasladarlo con cuidado si es necesario.",
                "Sospecha de fractura: limitar los movimientos y trasladarlo evitando doblar o manipular la extremidad afectada.",
                "Intoxicación: contactar inmediatamente con el veterinario, identificar la sustancia y conservar su envase. No provocar el vómito ni administrar remedios caseros.",
                "Golpe de calor: trasladarlo a un lugar fresco, enfriarlo con agua fresca, no helada, y acudir urgentemente al veterinario.",
                "Convulsiones: retirar los objetos cercanos, evitar sujetarlo a la fuerza y no introducir nada en su boca. Solicitar atención veterinaria.",
                "Dificultad respiratoria: mantenerlo tranquilo y buscar atención de urgencia inmediatamente.",
                "Desmayo o colapso: necesita evaluación veterinaria inmediata, incluso si parece recuperarse.",
                "Vómitos repetidos: si no puede retener agua, presenta debilidad o dolor abdominal, debe recibir atención urgente.",
                "Dolor repentino: evitar administrar analgésicos humanos, ya que algunos son tóxicos para los perros.",
                "Prevención: colocar superficies antideslizantes, mantener los caminos despejados y evitar que tenga que saltar desde alturas."
              ]
            }
          ]
        },
 
        "cuidados": {
          "titulo": "Cuidados",
          "secciones": [
            {
              "titulo": "CÓMO MANTENERLO BIEN CUIDADO",
              "items": [
                "Los cuidados del Labrador senior deben adaptarse a su movilidad, tolerancia al ejercicio, capacidad sensorial y estado general de salud.",
                "Cepillado: cepillar varias veces por semana para retirar el pelo suelto y observar posibles bultos, heridas o cambios en la piel.",
                "Baño: bañarlo cuando lo necesite, con productos adecuados y evitando que se enfríe durante el proceso.",
                "Cuidado de los oídos: revisar las orejas y limpiarlas con productos apropiados cuando sea necesario.",
                "Higiene dental: mantener el cepillado con pasta para perros y realizar revisiones dentales periódicas.",
                "Cuidado de las uñas: mantenerlas a una longitud adecuada para evitar molestias al caminar.",
                "Ejercicio moderado: ofrecer paseos más cortos o tranquilos si se cansa con facilidad. La actividad debe adaptarse a su condición física.",
                "Control del peso: revisar regularmente su condición corporal y ajustar la alimentación para prevenir tanto la obesidad como la pérdida de músculo.",
                "Cama cómoda: proporcionarle una cama acolchada, fácil de alcanzar y situada en un lugar tranquilo.",
                "Superficies antideslizantes: colocar alfombras o superficies que mejoren el agarre en los lugares donde camina.",
                "Acceso a comida y agua: ubicar los recipientes en lugares accesibles para evitar que tenga que subir escaleras o caminar grandes distancias.",
                "Protección frente al clima: evitar el calor intenso y ofrecer un lugar seco, protegido y confortable.",
                "Estimulación mental: mantener juegos de olfato, juguetes adecuados y actividades tranquilas que estimulen sus capacidades.",
                "Descanso suficiente: permitirle dormir y descansar cuando lo necesite, sin aislarlo de la familia.",
                "Revisiones frecuentes en casa: observar si aparecen bultos, cambios de apetito, dificultad para caminar o modificaciones en sus hábitos.",
                "Ayuda para desplazarse: si tiene problemas de movilidad, pueden ser útiles rampas, arneses de apoyo y adaptaciones del hogar recomendadas por el veterinario.",
                "Controles preventivos: programar revisiones veterinarias más frecuentes de acuerdo con su edad y estado de salud."
              ]
            },
            {
              "titulo": "CÓMO SABER SI NO TIENE UN BUEN CUIDADO",
              "items": [
                "Un perro senior puede tener necesidades adicionales y requiere que sus cuidados se adapten a sus capacidades actuales.",
                "Tiene dificultades para levantarse porque el suelo es resbaladizo.",
                "Su cama es demasiado dura, incómoda o difícil de alcanzar.",
                "Debe subir escaleras con frecuencia pese a tener problemas articulares.",
                "No dispone de agua o comida en un lugar accesible.",
                "Realiza ejercicio excesivo para su condición física o permanece completamente inactivo sin una razón médica.",
                "Presenta uñas demasiado largas que dificultan su caminar.",
                "Tiene problemas dentales sin tratar y dificultad para comer.",
                "Su pelaje está descuidado o presenta heridas que no se revisan.",
                "Pierde peso o masa muscular sin que se investigue la causa.",
                "Tiene sobrepeso que empeora su movilidad.",
                "Se ignoran los cambios en su comportamiento, orientación o hábitos de eliminación.",
                "No recibe revisiones veterinarias periódicas.",
                "Se le administran medicamentos humanos o suplementos sin supervisión.",
                "Permanece aislado y sin interacción con la familia.",
                "No recibe ayuda para desplazarse cuando la necesita."
              ]
            }
          ]
        },
 
        "comportamiento": {
          "titulo": "Comportamiento",
          "secciones": [
            {
              "titulo": "ADIESTRAMIENTO Y ESTIMULACIÓN EN LA ETAPA SENIOR",
              "items": [
                "El Labrador Retriever senior puede seguir aprendiendo y disfrutando de actividades. Sin embargo, el entrenamiento debe ajustarse a su energía, movilidad, capacidad auditiva y estado de salud.",
                "Mantener las rutinas: los horarios previsibles para comer, pasear y descansar pueden ayudarle a sentirse seguro.",
                "Repasar órdenes conocidas: practicar instrucciones sencillas sin exigir movimientos que le causen dolor.",
                "Usar refuerzo positivo: premiar las conductas deseadas con elogios, caricias si las disfruta o pequeñas recompensas apropiadas.",
                "Estimulación olfativa: esconder pequeñas cantidades de alimento en lugares accesibles para que lo encuentre utilizando el olfato.",
                "Juegos tranquilos: ofrecer juguetes seguros y actividades que no requieran saltos ni carreras intensas.",
                "Adaptar las sesiones: realizar ejercicios breves, con descansos frecuentes y sin presionarlo cuando esté cansado.",
                "Mantener la interacción social: dedicarle tiempo y permitirle participar en actividades familiares de manera cómoda.",
                "Evitar cambios bruscos: si tiene problemas de visión u oído, aproximarse con cuidado para no asustarlo.",
                "Facilitar la orientación: mantener los muebles y los caminos habituales en posiciones consistentes cuando presente dificultades sensoriales.",
                "Reforzar la calma: premiar los momentos de relajación y evitar situaciones que le generen estrés innecesario.",
                "Observar las señales de dolor: si deja de realizar una actividad que antes disfrutaba, consultar para descartar problemas de salud."
              ]
            },
            {
              "titulo": "CÓMO MEJORAR SU COMPORTAMIENTO SI NO FUE ADIESTRADO",
              "items": [
                "Un Labrador senior también puede aprender hábitos nuevos, aunque quizá necesite más tiempo, repeticiones y adaptaciones.",
                "Evaluar su salud primero: descartar dolor, pérdida de visión u oído, problemas neurológicos u otras enfermedades que dificulten el aprendizaje.",
                "Utilizar instrucciones sencillas: enseñar una conducta a la vez y mantener las palabras y señales consistentes.",
                "Recompensar los avances: ofrecer premios pequeños y adecuados a su dieta cada vez que realice la conducta deseada.",
                "Reducir las distracciones: comenzar en un lugar tranquilo y familiar.",
                "Adaptar las órdenes al movimiento: evitar ejercicios que impliquen saltar, correr o levantarse repetidamente si tiene problemas articulares.",
                "Mejorar los hábitos de eliminación: establecer horarios regulares y facilitarle el acceso al exterior. Si comienza a orinar dentro de casa, consultar para descartar enfermedades.",
                "Manejar la inquietud: comprobar si necesita salir, beber agua, descansar o recibir atención antes de interpretar su conducta como desobediencia.",
                "Evitar los castigos: los gritos o golpes pueden aumentar la confusión y el miedo, especialmente si presenta dificultades sensoriales.",
                "Proporcionar estimulación mental: utilizar actividades de olfato y juegos sencillos que pueda realizar sin esfuerzo excesivo.",
                "Consultar si hay cambios repentinos: una alteración de conducta que aparece de repente puede ser una señal de dolor o enfermedad y no un problema de adiestramiento."
              ]
            }
          ]
        },
 
        "vacunacion": {
          "titulo": "Vacunación y desparasitación",
          "secciones": [
            {
              "titulo": "VACUNAS QUE DEBE TENER DURANTE SU VIDA",
              "items": [
                "Las necesidades de vacunación del Labrador senior dependen de su historial, su estado de salud, la duración de la inmunidad de cada vacuna y las normas sanitarias locales. La edad avanzada no significa que deba suspender automáticamente sus vacunas.",
                "Moquillo canino: protege frente a una enfermedad viral que puede afectar distintos sistemas del organismo.",
                "Parvovirus canino: ayuda a prevenir una enfermedad infecciosa grave del aparato digestivo.",
                "Adenovirus canino: contribuye a prevenir la hepatitis infecciosa canina.",
                "Parainfluenza canina: puede formar parte de la protección frente a enfermedades respiratorias, según su riesgo de exposición.",
                "Leptospirosis: protege frente a una infección bacteriana que puede afectar los riñones y el hígado.",
                "Rabia: debe mantenerse al día de acuerdo con las normas locales y las recomendaciones veterinarias.",
                "Bordetella: puede ser recomendable si tiene contacto frecuente con otros perros o asiste a residencias y guarderías.",
                "Otras vacunas: pueden indicarse según las enfermedades presentes en la región y sus condiciones de vida.",
                "Frecuencia orientativa: las vacunas básicas se refuerzan de acuerdo con el protocolo seguido durante la etapa de cachorro y los refuerzos posteriores.",
                "Algunas vacunas básicas pueden administrarse cada tres años, mientras que otras requieren una frecuencia diferente.",
                "La vacuna contra la leptospirosis suele necesitar refuerzos anuales, según el producto y el riesgo de exposición.",
                "La vacuna contra la rabia debe aplicarse según la normativa y la duración de inmunidad autorizada.",
                "Si tiene enfermedades crónicas o recibe determinados tratamientos, el veterinario debe valorar el momento y la conveniencia de cada vacuna.",
                "Es importante conservar su registro de vacunación y realizar una revisión veterinaria antes de modificar el calendario."
              ]
            },
            {
              "titulo": "DESPARASITACIÓN INTERNA Y EXTERNA",
              "items": [
                "Los perros senior siguen expuestos a parásitos y pueden sufrir complicaciones si no reciben una prevención adecuada. Los productos deben elegirse teniendo en cuenta su peso, su estado de salud y los medicamentos que utiliza.",
                "Lombrices intestinales: pueden causar molestias digestivas y pérdida de peso.",
                "Anquilostomas: pueden producir pérdida de sangre y anemia.",
                "Tricocéfalos: pueden afectar el intestino y provocar diarrea.",
                "Tenias: algunos tipos se relacionan con la ingestión de pulgas infectadas.",
                "Giardia y coccidios: pueden causar problemas digestivos y necesitan tratamientos específicos.",
                "Frecuencia interna: debe determinarse según el riesgo individual, el estilo de vida y las indicaciones veterinarias.",
                "Análisis de heces: pueden ayudar a detectar determinados parásitos y decidir si necesita tratamiento.",
                "Higiene: recoger las heces y mantener limpios los lugares donde come y descansa.",
                "Precaución con otros medicamentos: si tiene enfermedades renales, hepáticas o recibe otros tratamientos, el veterinario debe comprobar qué producto es apropiado.",
                "Pulgas: pueden causar picazón, dermatitis y otras molestias.",
                "Garrapatas: pueden transmitir enfermedades infecciosas.",
                "Ácaros: pueden producir problemas de piel.",
                "Productos preventivos: utilizar productos veterinarios adecuados para su edad, peso y estado de salud.",
                "Frecuencia externa: depende del producto y del riesgo de exposición; se deben respetar las instrucciones de aplicación.",
                "Control ambiental: limpiar su cama y revisar los lugares donde descansa.",
                "No combinar tratamientos por cuenta propia: algunos productos pueden causar efectos adversos si se utilizan incorrectamente."
              ]
            }
          ]
        },
 
        "veterinario": {
          "titulo": "Cuándo llevar al veterinario",
          "secciones": [
            {
              "titulo": "REVISIONES RUTINARIAS",
              "items": [
                "Las revisiones preventivas son especialmente importantes en la etapa senior porque permiten detectar enfermedades relacionadas con la edad y ajustar los cuidados antes de que los problemas avancen.",
                "Frecuencia de las consultas: muchos perros senior se benefician de una revisión cada seis meses, aunque el veterinario puede recomendar visitas más frecuentes según su estado.",
                "Examen físico completo: revisar el corazón, los pulmones, el abdomen, la piel, los ojos, los oídos y la movilidad.",
                "Control del peso y los músculos: comprobar si mantiene una condición corporal adecuada o si está perdiendo masa muscular.",
                "Salud dental: evaluar la presencia de sarro, enfermedad periodontal, dolor o dientes dañados.",
                "Revisión articular: observar su movilidad, rigidez y posibles signos de dolor.",
                "Análisis de sangre y orina: pueden recomendarse periódicamente para evaluar la función renal, hepática y otros indicadores de salud.",
                "Presión arterial: puede medirse cuando existe riesgo de determinadas enfermedades o cuando el veterinario lo considera necesario.",
                "Vacunación: revisar qué refuerzos corresponden según su historial.",
                "Desparasitación: adaptar el plan preventivo al riesgo de exposición y a su salud.",
                "Evaluación de la vista y el oído: identificar cambios que puedan afectar su seguridad y comportamiento.",
                "Control de enfermedades crónicas: si tiene una afección diagnosticada, cumplir los controles y tratamientos indicados.",
                "Revisión de medicamentos: comprobar periódicamente si los tratamientos siguen siendo adecuados y si es necesario ajustar las dosis."
              ]
            },
            {
              "titulo": "SEÑALES DE ALERTA",
              "items": [
                "Debe solicitar una consulta veterinaria si presenta cambios que no son habituales, aunque parezcan relacionados con la edad.",
                "Pérdida de peso o masa muscular sin explicación.",
                "Disminución persistente del apetito.",
                "Aumento notable de la sed o de la cantidad de orina.",
                "Vómitos o diarrea recurrentes.",
                "Rigidez, cojera o dificultad para levantarse.",
                "Dolor persistente, irritabilidad o rechazo al movimiento.",
                "Cambios en la visión, el oído o la orientación.",
                "Bultos nuevos o heridas que no cicatrizan.",
                "Incontinencia o cambios en sus hábitos de eliminación."
              ]
            },
            {
              "titulo": "EMERGENCIAS VETERINARIAS",
              "items": [
                "Dificultad para respirar o respiración muy comprometida.",
                "Desmayo, pérdida del conocimiento o convulsiones.",
                "Sangrado abundante o una lesión grave.",
                "Ingestión de venenos, medicamentos humanos u otras sustancias tóxicas.",
                "Abdomen que aumenta de tamaño repentinamente, especialmente si intenta vomitar sin conseguirlo.",
                "Encías muy pálidas, azuladas o amarillentas.",
                "Sospecha de fractura o traumatismo importante.",
                "Diarrea con sangre acompañada de decaimiento intenso.",
                "Signos de golpe de calor, como jadeo extremo, debilidad, desorientación o colapso.",
                "Incapacidad para orinar o deterioro rápido del estado general."
              ]
            }
          ]
        }
      }
    }
  }
},
"pastoraleman": {
  "nombre": "Pastor Alemán",
    "etapas": {
      "cachorro": {
        "tituloOriginal": "PASTOR ALEMÁN – CACHORRO (0 A 12 MESES)",
        "temas": {
          "alimentacion": {
            "titulo": "ALIMENTACIÓN",
            "secciones": [
              {
                "titulo": "ALIMENTACIÓN SALUDABLE",
                "items": [
                  "Alimento especial para cachorros de razas grandes: elegir un alimento completo y equilibrado diseñado para cachorros de razas grandes. Debe proporcionar energía, proteínas, grasas, vitaminas y minerales en cantidades adecuadas para un crecimiento saludable.",
                  "Control de las porciones: servir la cantidad recomendada según su edad, peso, condición corporal y nivel de actividad. Ajustar la ración con el veterinario para evitar el sobrepeso, que puede perjudicar sus articulaciones.",
                  "Comidas repartidas durante el día: entre los 2 y 3 meses puede necesitar unas cuatro comidas diarias; entre los 3 y 6 meses, unas tres; y desde aproximadamente los 6 meses, normalmente dos comidas al día. La frecuencia se adapta a cada cachorro.",
                  "Agua limpia y fresca: debe tener agua potable disponible durante todo el día. Lavar el recipiente y cambiar el agua con regularidad.",
                  "Proteínas de buena calidad: necesita proteínas suficientes para desarrollar músculos, órganos y tejidos. Un alimento completo adecuado normalmente cubre estas necesidades sin agregar carne adicional.",
                  "Calcio y fósforo equilibrados: estos minerales son esenciales para el crecimiento óseo, pero deben encontrarse en proporciones apropiadas. No añadir suplementos de calcio sin indicación veterinaria.",
                  "Grasas y ácidos grasos esenciales: ayudan a mantener la piel, el pelaje y el desarrollo general. La cantidad debe corresponder a sus necesidades de crecimiento.",
                  "Premios saludables y pequeños: se pueden utilizar premios para cachorros o pequeñas porciones de alimentos seguros, como zanahoria, si la tolera. Los premios no deberían superar aproximadamente el 10 % de sus calorías diarias.",
                  "Cambios de alimento graduales: si necesita cambiar de marca o fórmula, hacer la transición durante varios días, siempre que no exista una indicación veterinaria diferente, para reducir el riesgo de molestias digestivas.",
                  "Vigilancia del peso y crecimiento: pesarlo regularmente y observar su condición corporal. Las costillas deberían poder palparse sin una capa excesiva de grasa, sin que sobresalgan marcadamente.",
                  "Alimentación después del destete: cuando todavía es muy pequeño, necesita una nutrición apropiada para su etapa. No debe separarse prematuramente de su madre si puede evitarse.",
                  "Dieta casera supervisada: si la familia desea preparar comida en casa, debe contar con una receta formulada por un veterinario especializado en nutrición. Las mezclas improvisadas pueden causar deficiencias durante el crecimiento."
                ]
              },
              {
                "titulo": "ALIMENTACIÓN NO SALUDABLE",
                "items": [
                  "Exceso de comida: darle grandes cantidades para que crezca más rápido puede provocar sobrepeso y aumentar la carga sobre las articulaciones.",
                  "Alimento para perros adultos como dieta principal: puede no proporcionar las cantidades apropiadas de nutrientes que necesita un cachorro de raza grande.",
                  "Suplementos para acelerar el crecimiento: el calcio, las vitaminas y otros productos no deben administrarse por cuenta propia. Los excesos también pueden causar problemas.",
                  "Huesos cocidos: pueden astillarse, provocar atragantamiento, obstrucciones o lesiones internas.",
                  "Chocolate, café y bebidas energéticas: contienen sustancias que pueden ser tóxicas para los perros.",
                  "Uvas y pasas: pueden provocar daño renal grave. No existe una cantidad que pueda considerarse segura para todos los perros.",
                  "Cebolla y ajo: pueden dañar los glóbulos rojos, sobre todo cuando se ingieren en cantidades importantes o repetidamente.",
                  "Productos con xilitol: algunos chicles, caramelos y productos sin azúcar contienen este edulcorante, que puede causar una intoxicación grave.",
                  "Comidas fritas, grasas o muy saladas: los embutidos, las sobras aceitosas y los alimentos condimentados no son apropiados para su dieta habitual.",
                  "Leche de vaca en grandes cantidades: puede causar diarrea, gases o molestias digestivas en perros que no la toleran.",
                  "Alimentación libre sin controlar las porciones: dejar comida disponible en grandes cantidades todo el día dificulta vigilar cuánto consume y puede favorecer el sobrepeso.",
                  "Dietas crudas sin asesoramiento profesional: pueden transmitir bacterias y parásitos al cachorro y a las personas que conviven con él."
                ]
              }
            ]
          },
          "salud": {
            "titulo": "SALUD",
            "secciones": [
              {
                "titulo": "TIENE BUENA SALUD",
                "items": [
                  "Energía apropiada para su edad: juega, explora, descansa y vuelve a jugar sin mostrar debilidad persistente.",
                  "Apetito estable: come con normalidad y no presenta dificultades para masticar o tragar.",
                  "Crecimiento gradual: aumenta de peso y tamaño de forma progresiva, sin adelgazar ni acumular grasa excesiva.",
                  "Ojos limpios: no presenta secreciones abundantes, enrojecimiento persistente ni dolor ocular.",
                  "Respiración normal: respira sin esfuerzo y no tiene tos persistente ni jadeo excesivo mientras está descansando.",
                  "Digestión adecuada: sus heces suelen ser formadas y no contienen sangre; tampoco presenta vómitos repetidos.",
                  "Movimiento cómodo: camina y juega sin cojera persistente, rigidez marcada ni dolor evidente.",
                  "Piel y pelaje en buenas condiciones: no presenta zonas extensas sin pelo, heridas recurrentes ni picazón intensa.",
                  "Vacunas y desparasitación al día: sigue el calendario establecido por el veterinario según su edad y riesgo.",
                  "Conducta equilibrada: muestra curiosidad y aprende gradualmente a relacionarse con su entorno, aunque puede necesitar tiempo para acostumbrarse a nuevas experiencias."
                ]
              },
              {
                "titulo": "TIENE MALA SALUD",
                "items": [
                  "Pérdida del apetito: si deja de comer y además está decaído, vomita o tiene diarrea, necesita valoración veterinaria. En cachorros pequeños no conviene esperar demasiado.",
                  "Vómitos repetidos: pueden deberse a enfermedades, parásitos, ingestión de objetos u otros problemas digestivos.",
                  "Diarrea persistente o con sangre: puede provocar deshidratación rápidamente y ser especialmente peligrosa si todavía no completó su vacunación.",
                  "Cojera o dificultad para levantarse: puede indicar una lesión o un problema ortopédico. El Pastor Alemán puede presentar problemas articulares, pero no toda cojera significa una enfermedad hereditaria.",
                  "Abdomen hinchado o doloroso: si además presenta arcadas sin vomitar, inquietud o debilidad, se trata de una emergencia.",
                  "Tos o dificultad respiratoria: requiere revisión, especialmente si respira con esfuerzo o sus encías cambian de color.",
                  "Picazón intensa o pérdida de pelo: puede relacionarse con parásitos, alergias, infecciones u otros problemas de piel.",
                  "Cambios en la forma de caminar: arrastrar las patas, perder el equilibrio o mostrar debilidad en las extremidades requiere evaluación veterinaria.",
                  "Encías pálidas, azuladas o amarillentas: pueden indicar problemas importantes y requieren atención urgente.",
                  "Decaimiento inusual: si no quiere levantarse, se aísla o deja de responder como de costumbre, no debe ignorarse.",
                  "Convulsiones o desorientación: son signos que necesitan atención inmediata.",
                  "Dificultad para orinar: el esfuerzo repetido sin producir orina puede indicar una obstrucción y requiere atención urgente."
                ]
              }
            ]
          },
          "primeros": {
            "titulo": "PRIMEROS AUXILIOS",
            "secciones": [
              {
                "titulo": "QUÉ HACER CUANDO LE SUCEDEN ACCIDENTES COMO:",
                "items": [
                  "CAÍDAS, GOLPES O LESIONES EN LAS PATAS",
                  "Mantener la calma y evitar que siga corriendo, saltando o subiendo escaleras.",
                  "Observar si puede caminar y respirar normalmente, sin forzarlo a levantarse.",
                  "Si no puede levantarse, presenta dolor intenso o se sospecha una lesión de columna, mantenerlo lo más quieto posible.",
                  "Si necesita traslado, sostener su cuerpo de manera uniforme y utilizar una superficie firme cuando sea posible.",
                  "No intentar acomodar huesos, estirar las articulaciones ni administrar medicamentos humanos.",
                  "Acudir urgentemente al veterinario si no puede apoyar una pata, pierde el conocimiento, presenta dolor intenso o ha sufrido un accidente importante.",
                  "HERIDAS Y SANGRADO",
                  "Alejarlo de la situación que causó la lesión y evitar que lama la herida.",
                  "Colocar una gasa limpia o un paño limpio sobre el área sangrante y mantener una presión constante.",
                  "Si la tela se empapa, colocar otra encima sin retirar la primera.",
                  "No utilizar alcohol, agua oxigenada concentrada, polvos ni remedios caseros dentro de la herida.",
                  "No retirar objetos clavados profundamente; estabilizarlos con cuidado y acudir al veterinario.",
                  "Si la herida es profunda, fue causada por una mordedura o el sangrado es abundante, buscar atención veterinaria urgente.",
                  "ATRAGANTAMIENTO",
                  "Comprobar si puede respirar, toser y emitir sonidos.",
                  "Si tose con fuerza y respira, mantenerlo tranquilo y buscar ayuda veterinaria si el problema no se resuelve rápidamente.",
                  "Solo retirar un objeto si está claramente visible, suelto y puede extraerse sin empujarlo más adentro.",
                  "No introducir los dedos a ciegas en la garganta.",
                  "Si no puede respirar, sus encías se vuelven azuladas o pierde el conocimiento, acudir inmediatamente a urgencias veterinarias y llamar para recibir instrucciones durante el traslado.",
                  "No darle comida ni agua mientras exista sospecha de obstrucción.",
                  "INTOXICACIÓN",
                  "Alejarlo de la sustancia que pudo ingerir o tocar.",
                  "Guardar el envase o tomar una fotografía de la etiqueta para identificar el producto.",
                  "No provocar el vómito ni darle leche, aceite, sal, medicamentos o carbón activado sin indicación veterinaria.",
                  "Llamar inmediatamente al veterinario, aunque todavía parezca encontrarse bien.",
                  "Si presenta convulsiones, dificultad respiratoria o pérdida del conocimiento, trasladarlo a urgencias sin demora.",
                  
                ]
              },
               {
                "titulo": "QUÉ HACER CUANDO LE SUCEDEN ACCIDENTES COMO:",
                "items": [
                  "QUEMADURAS",
                  "Alejarlo de la fuente de calor.",
                  "Enfriar la zona con agua corriente fresca, no helada, durante varios minutos si es posible hacerlo sin retrasar la atención.",
                  "No aplicar hielo, mantequilla, pasta dental, aceites ni cremas caseras.",
                  "No romper ampollas ni retirar piel dañada.",
                  "Cubrir suavemente con una tela limpia y acudir al veterinario. Las quemaduras extensas, profundas o que afectan la cara o la respiración son urgencias.",
                  "PICADURAS Y MORDEDURAS",
                  "Llevarlo a un lugar seguro y observar si aparece hinchazón, dolor o enrojecimiento.",
                  "Si hay un aguijón visible, retirarlo cuidadosamente sin apretar el saco de veneno.",
                  "No administrar antihistamínicos ni otros medicamentos humanos sin orientación veterinaria.",
                  "Las mordeduras pueden causar daños internos aunque la herida externa parezca pequeña.",
                  "Acudir inmediatamente si presenta hinchazón de la cara, dificultad para respirar, vómitos repentinos, debilidad o colapso.",
                  "VÓMITOS Y DIARREA",
                  "Si está alerta, puede tragar y no vomita repetidamente, ofrecer pequeñas cantidades de agua sin obligarlo a beber.",
                  "No administrar antibióticos ni medicamentos antidiarreicos por cuenta propia.",
                  "Observar la frecuencia de los episodios y si hay sangre, dolor abdominal o decaimiento.",
                  "Si es cachorro y los síntomas se repiten, solicitar orientación veterinaria el mismo día.",
                  "Acudir urgentemente si no puede retener líquidos, está muy débil, tiene sangre en las heces o presenta dolor abdominal.",
                  "GOLPE DE CALOR",
                  "Llevarlo inmediatamente a un lugar fresco y ventilado.",
                  "Mojar el cuerpo con agua fresca, no helada, evitando retrasar el traslado.",
                  "No cubrirlo con toallas gruesas mojadas que puedan retener calor.",
                  "No obligarlo a beber si está desorientado, débil o no puede tragar normalmente.",
                  "Trasladarlo inmediatamente al veterinario, aunque parezca recuperarse, porque pueden aparecer complicaciones internas."
                ]
              }
            ]
          },
          "cuidados": {
            "titulo": "CUIDADOS",
            "secciones": [
              {
                "titulo": "CÓMO MANTENERLO BIEN CUIDADO",
                "items": [
                  "Controles veterinarios periódicos: revisar crecimiento, articulaciones, dientes, piel, oídos y estado general. Las revisiones permiten detectar problemas antes de que se agraven.",
                  "Vacunación y desparasitación: mantener un calendario personalizado según su edad, historial, región y exposición a otros animales.",
                  "Ejercicio apropiado para su edad: cuando sea pequeño, realizar juegos y paseos adecuados a su desarrollo. Evitar carreras forzadas, saltos repetidos desde alturas y ejercicios extenuantes mientras crece.",
                  "Paseos diarios cuando esté preparado: como adulto, suele necesitar actividad física regular y estimulación mental. La cantidad depende de su salud, condición física y temperamento.",
                  "Cepillado frecuente: cepillarlo varias veces por semana para retirar pelo suelto. Durante las temporadas de muda puede necesitar cepillado diario.",
                  "Baños cuando sean necesarios: utilizar champú para perros y secar bien el pelaje. Bañarlo en exceso puede resecar o irritar la piel.",
                  "Cuidado dental: acostumbrarlo al cepillado con pasta dental para perros. Revisar si presenta sarro, encías inflamadas o mal aliento intenso.",
                  "Cuidado de las uñas: revisar las uñas regularmente y recortarlas cuando haga falta, evitando cortar la parte sensible.",
                  "Revisión de las orejas: comprobar si hay mal olor, enrojecimiento o secreciones. No introducir bastoncillos ni objetos profundamente en el oído.",
                  "Protección contra el frío y la humedad: ofrecer una cama seca, un refugio protegido y un lugar donde pueda descansar sin permanecer sobre suelo húmedo.",
                  "Protección frente al calor: proporcionar sombra, ventilación y agua fresca. Evitar ejercicio intenso durante las horas más calurosas y nunca dejarlo dentro de un vehículo cerrado.",
                  "Socialización temprana: acostumbrarlo de manera positiva a personas, sonidos, lugares y otros animales. Las presentaciones deben ser graduales y respetar sus señales de miedo.",
                  "Educación con refuerzo positivo: premiar las conductas adecuadas y establecer reglas constantes. No recurrir a golpes, intimidación ni métodos que provoquen miedo.",
                  "Estimulación mental: utilizar juguetes de búsqueda, juegos de olfato, ejercicios de obediencia y actividades que le permitan resolver problemas.",
                  "Un espacio propio: proporcionarle una cama o zona tranquila donde pueda descansar sin ser molestado.",
                  "Prevención de escapes: mantener puertas y cercas seguras. Aunque sea leal a su familia, no debe dejarse suelto en calles o lugares con tráfico.",
                  "Identificación: utilizar una placa con un número de contacto y, si es posible, un microchip registrado.",
                  "Control del peso: pesar al perro regularmente y ajustar la comida a su actividad. El exceso de peso puede agravar problemas articulares.",
                  "Supervisión durante el juego: evitar que los cachorros jueguen sin control con perros mucho más grandes o con objetos que puedan tragar.",
                  "Descanso adecuado: respetar sus periodos de sueño y evitar que los niños lo molesten mientras duerme o come."
                ]
              },
              {
                "titulo": "CÓMO SABER SI NO TIENE UN BUEN CUIDADO",
                "items": [
                  "Por su aspecto físico",
                  "Tiene el pelaje sucio durante largos periodos, mal olor persistente o heridas sin atender.",
                  "Presenta uñas demasiado largas que le dificultan caminar.",
                  "Tiene secreciones en los ojos o los oídos, encías inflamadas o problemas dentales sin revisar.",
                  "Está excesivamente delgado o tiene demasiada grasa corporal.",
                  "Se rasca continuamente, pierde pelo en zonas extensas o presenta parásitos visibles.",
                  "Por su alimentación",
                  "No tiene acceso constante a agua limpia.",
                  "Recibe huesos cocidos, alimentos tóxicos o sobras muy grasosas.",
                  "Come cantidades excesivas y aumenta de peso rápidamente.",
                  "Recibe suplementos sin necesidad o una dieta casera sin formular.",
                  "No recibe un alimento adecuado para su etapa de crecimiento.",
                  "Por su comportamiento",
                  "Tiene miedo constante de las personas o reacciona defensivamente ante situaciones cotidianas.",
                  "Ladra excesivamente, salta sobre la gente o tira de la correa porque no ha aprendido alternativas apropiadas.",
                  "Se muestra muy inquieto por falta de ejercicio o estimulación mental.",
                  "Pasa demasiado tiempo aislado y sin interacción social.",
                  "No puede descansar porque lo molestan constantemente.",
                  "Presenta un cambio brusco de conducta, que también podría indicar dolor o enfermedad.",
                  "Por su salud y seguridad",
                  "No recibe vacunas ni controles veterinarios.",
                  "Pasa largos periodos expuesto al sol, al frío o a la lluvia sin refugio.",
                  "Se le permite salir sin supervisión cerca de vehículos.",
                  "Se le exige ejercicio excesivo durante el crecimiento.",
                  "No se atienden sus lesiones, vómitos, diarrea o dificultades para caminar.",
                  "Se le deja solo durante periodos prolongados sin actividad, contacto ni oportunidades adecuadas para hacer sus necesidades."
                ]
              }
            ]
          },
          "comportamiento": {
            "titulo": "COMPORTAMIENTO",
            "secciones": [
              {
                "titulo": "ADIESTRAMIENTO DESDE CACHORRO",
                "items": [
                  "Enseñarle su nombre: pronunciarlo con voz amable y premiarlo cuando mire hacia la persona.",
                  "Practicar órdenes básicas: empezar con “siéntate”, “ven”, “quieto” y “suelta”, usando premios pequeños y sesiones cortas.",
                  "Enseñarle a acudir a la llamada: comenzar en un lugar seguro y tranquilo. Llamarlo con entusiasmo y recompensarlo cuando regrese.",
                  "Enseñarle a caminar con correa: practicar en un espacio poco concurrido y premiar cuando camine sin tirar.",
                  "Controlar los saltos: si salta sobre las personas, esperar a que tenga las cuatro patas en el suelo y premiarlo cuando salude con calma.",
                  "Reducir las mordidas durante el juego: si muerde manos o ropa, detener brevemente la interacción y ofrecer un juguete apropiado. No golpearlo ni sujetarle el hocico con fuerza.",
                  "Enseñarle dónde hacer sus necesidades: llevarlo al lugar elegido después de dormir, comer, beber y jugar. Felicitarlo inmediatamente cuando lo haga correctamente.",
                  "Socializarlo de forma gradual: presentarle personas, sonidos, superficies y animales seguros. No obligarlo a acercarse si muestra miedo.",
                  "Acostumbrarlo a los cuidados: practicar suavemente el contacto con las patas, orejas y boca, premiándolo para que tolere las revisiones.",
                  "Enseñarle a descansar: recompensarlo cuando se acueste tranquilo en su cama y permitirle relajarse sin interrupciones.",
                  "Evitar la protección excesiva: enseñarle que las visitas y las personas que se acercan de forma tranquila no representan automáticamente una amenaza.",
                  "Estimular su inteligencia: practicar juegos de olfato, búsqueda de juguetes y pequeños ejercicios de obediencia.",
                  "Mantener reglas familiares consistentes: todas las personas deben utilizar las mismas palabras y normas para evitar confundirlo.",
                  "Respetar su crecimiento: no exigirle entrenamientos físicos intensos ni largas sesiones de trabajo cuando todavía es cachorro.",
                  "Evitar el castigo físico: los golpes, gritos e intimidación pueden aumentar el miedo y las reacciones defensivas."
                ]
              },
              {
                "titulo": "CÓMO MEJORAR EL COMPORTAMIENTO DE TU MASCOTA SI NO FUE ADIESTRADO",
                "items": [
                  "Identificar la causa del problema: observar cuándo ocurre, qué lo desencadena y qué sucede después. Si el comportamiento aparece de repente, descartar primero un problema de salud.",
                  "Volver a las órdenes básicas: practicar su nombre, “ven”, “siéntate” y “suelta” en un entorno tranquilo.",
                  "Premiar inmediatamente las conductas correctas: utilizar comida apropiada, elogios o juguetes para que comprenda qué comportamiento le conviene repetir.",
                  "Enseñarle a no saltar: pedirle que se siente antes de saludar y premiarlo cuando mantenga las patas en el suelo.",
                  "Mejorar los paseos: premiar que camine con la correa floja y cambiar de dirección con calma cuando empiece a tirar, evitando tirones bruscos.",
                  "Reducir los ladridos: identificar si ladra por miedo, aburrimiento, alerta o frustración. Enseñarle una conducta alternativa y premiar los momentos de calma.",
                  "Prevenir la destrucción de objetos: guardar zapatos, cables y artículos peligrosos; ofrecer juguetes seguros y actividades de olfato.",
                  "Trabajar la tolerancia a la soledad: practicar ausencias muy cortas y aumentarlas gradualmente. Si presenta angustia intensa, consultar a un veterinario o profesional de conducta.",
                  "Evitar reforzar la persecución: no correr detrás de él si roba un objeto. Si es seguro, intercambiarlo por un premio o juguete; si hay peligro, solicitar ayuda profesional.",
                  "Manejar la conducta protectora: no animarlo a amenazar, perseguir o atacar a personas. Premiar la calma y mantener una distancia segura de las situaciones que lo alteran.",
                  "No castigar los gruñidos: un gruñido puede ser una señal de incomodidad o miedo. Dar espacio, identificar la causa y buscar orientación si se repite.",
                  "Practicar la obediencia a diario: realizar sesiones breves, constantes y adaptadas a su capacidad de concentración.",
                  "Ofrecer ejercicio y estimulación adecuados: un Pastor Alemán necesita oportunidades de movimiento y trabajo mental, pero el ejercicio debe ajustarse a su edad y salud.",
                  "Buscar ayuda profesional cuando sea necesario: si muestra agresividad, miedo intenso, reactividad o problemas difíciles de controlar, acudir a un veterinario y a un educador canino que utilice métodos basados en refuerzo positivo.",
                  "Tener paciencia: los hábitos adquiridos pueden tardar en cambiar. La constancia y la seguridad son más eficaces que los castigos."
                ]
              }
            ]
          },
          "vacunacion": {
            "titulo": "VACUNACIÓN",
            "secciones": [
              {
                "titulo": "TODAS LAS VACUNAS CON LAS QUE DEBERÍA CONTAR LA MASCOTA DURANTE SU VIDA",
                "items": [
                  "El calendario debe establecerlo un veterinario en Bolivia de acuerdo con la edad, el historial de vacunación, el estado de salud, la región donde vive y el riesgo de exposición. No todas las vacunas adicionales son necesarias para todos los perros.",
                  "Vacuna múltiple esencial: protege contra enfermedades importantes como moquillo, parvovirus y adenovirus canino, relacionado con la hepatitis infecciosa. La primera dosis suele administrarse alrededor de las 6–8 semanas, con refuerzos cada 2–4 semanas hasta recibir una dosis a las 16 semanas de edad o después, según el protocolo veterinario.",
                  "Vacuna contra la rabia: es esencial por la gravedad de la enfermedad y las normas sanitarias. La edad de la primera dosis y sus refuerzos deben seguir la normativa boliviana vigente y las indicaciones del veterinario.",
                  "Refuerzos de la vacuna múltiple: después de la serie inicial, suele recomendarse un refuerzo dentro del primer año posterior a la serie de cachorro. Las dosis siguientes dependen de la vacuna utilizada, las recomendaciones veterinarias y el riesgo; no todas las vacunas tienen la misma frecuencia.",
                  "Vacuna contra la leptospirosis: puede recomendarse según la región, la presencia de roedores, el acceso a agua contaminada y otros riesgos ambientales. Generalmente requiere una serie inicial y refuerzos periódicos.",
                  "Vacuna contra la tos de las perreras: las vacunas contra Bordetella y otros agentes respiratorios pueden considerarse si asiste a guarderías, residencias, entrenamientos grupales o lugares donde conviven muchos perros.",
                  "Vacuna contra la influenza canina: se considera si está disponible y existe un riesgo de exposición que justifique su uso.",
                  "Otras vacunas específicas: el veterinario decidirá si alguna es apropiada para su estilo de vida y entorno. No se deben aplicar vacunas adicionales sin evaluar su necesidad.",
                  "Registro de vacunación: conservar la cartilla con las fechas, los nombres de las vacunas, los datos del profesional y las fechas sugeridas para los siguientes refuerzos.",
                  "Si se desconoce su historial: no asumir que está vacunado. El veterinario establecerá un calendario de recuperación según su edad y las dosis documentadas.",
                  "Antes de cada vacuna: informar si está enfermo, recibe algún tratamiento o tuvo una reacción previa a una vacuna. El profesional determinará si es conveniente vacunar ese día.",
                  "Durante toda su vida: mantener los refuerzos esenciales indicados aunque el perro ya sea adulto o senior.",
                  "La desparasitación interna y la prevención de pulgas y garrapatas también son importantes, pero no son vacunas. Deben programarse por separado con orientación veterinaria."
                ]
              }
            ]
          },
          "veterinario": {
            "titulo": "CUÁNDO IR AL VETERINARIO",
            "secciones": [
              {
                "titulo": "EN QUÉ SITUACIONES DE EMERGENCIA DEBES ACUDIR A UN VETERINARIO",
                "items": [
                  "Dificultad para respirar: respiración trabajosa, encías azuladas o incapacidad para respirar normalmente pueden indicar una emergencia grave.",
                  "Abdomen hinchado con arcadas sin vomitar: el Pastor Alemán es una raza grande y de pecho profundo, por lo que estos signos pueden indicar dilatación-torsión gástrica. No esperar a que se le pase.",
                  "Desmayo o pérdida del conocimiento: puede deberse a problemas circulatorios, cardíacos, neurológicos u otras causas graves.",
                  "Convulsiones: especialmente si es la primera vez, duran varios minutos, se repiten o no recupera su estado normal.",
                  "Sangrado abundante: si no se detiene con presión directa o la herida es profunda, necesita atención urgente.",
                  "Accidente de tránsito o caída importante: puede tener lesiones internas aunque aparentemente camine bien.",
                  "Ingestión de venenos o medicamentos: no esperar a que aparezcan síntomas. Llevar el envase o una fotografía del producto.",
                  "Vómitos repetidos con debilidad: puede sufrir deshidratación o una enfermedad importante.",
                  "Diarrea con sangre: especialmente si es cachorro, no ha completado sus vacunas o también presenta vómitos.",
                  "Encías muy pálidas o amarillas: pueden ser señales de anemia, problemas circulatorios o enfermedades graves.",
                  "Dolor intenso o incapacidad para caminar: puede indicar una lesión, fractura o problema ortopédico.",
                  "Debilidad repentina de las patas traseras: necesita evaluación urgente, especialmente si no puede mantenerse en pie, pierde sensibilidad o tiene dolor.",
                  "Dificultad para orinar: intentar orinar repetidamente sin producir orina puede indicar una obstrucción que requiere atención inmediata.",
                  "Golpe de calor: jadeo intenso, desorientación, vómitos, debilidad o colapso después de estar en un ambiente caliente requieren atención inmediata.",
                  "Reacción alérgica grave: hinchazón repentina de la cara, dificultad respiratoria, vómitos repetidos o colapso después de una picadura, alimento o medicamento.",
                  "Herida profunda o mordedura: puede existir daño interno o riesgo de infección aunque la lesión externa sea pequeña.",
                  "Lesión ocular: dolor intenso, ojo cerrado, sangrado o cambios repentinos en la visión requieren atención rápida.",
                  "Incapacidad para retener agua: si vomita cada vez que bebe o muestra signos de deshidratación, necesita valoración urgente.",
                  "Cambios bruscos de comportamiento: desorientación, debilidad marcada, falta de respuesta o agresividad repentina pueden estar relacionados con dolor o enfermedad."
                ]
              },
              {
                "titulo": "CONSULTAS VETERINARIAS QUE NO DEBES POSPONER",
                "items": [
                  "Si cojea repetidamente, se levanta con dificultad o muestra rigidez después de descansar.",
                  "Si pierde pelo en exceso, se rasca continuamente o presenta infecciones recurrentes de la piel.",
                  "Si tiene mal aliento intenso, sarro o dolor al masticar.",
                  "Si bebe u orina mucho más de lo habitual.",
                  "Si aumenta o pierde peso sin una explicación clara.",
                  "Si tiene tos, secreción nasal o problemas digestivos que persisten.",
                  "Si presenta miedo intenso, ansiedad por separación o conductas agresivas nuevas.",
                  "Si necesita una revisión de su peso, alimentación, vacunas o prevención de parásitos.",
                  "Si muestra cambios graduales en la forma de caminar, correr o levantarse, ya que conviene detectar temprano los problemas articulares o neurológicos.",
                  "Recuerda: el Pastor Alemán necesita actividad física apropiada, entrenamiento paciente, socialización, alimentación equilibrada y revisiones veterinarias durante toda su vida. No todos los perros de esta raza desarrollan problemas articulares, pero mantener un peso saludable y evitar esfuerzos excesivos durante el crecimiento ayuda a proteger su bienestar. Ante una emergencia, no le des medicamentos humanos ni esperes a que los síntomas desaparezcan: contacta a un veterinario lo antes posible."
                ]
              }
            ]
          }
        }
      }
    ,
      "adulto": {
      "tituloOriginal": "PASTOR ALEMÁN ADULTO (DE 1 A 7 AÑOS)",
      "temas": {
        "alimentacion": {
          "titulo": "ALIMENTACIÓN",
          "secciones": [
            {
              "titulo": "ALIMENTACIÓN SALUDABLE",
              "items": [
                "Alimento especial para perros adultos de razas grandes: elegir un alimento completo y equilibrado formulado para perros adultos de razas grandes. Debe proporcionar proteínas, grasas, carbohidratos, vitaminas y minerales en cantidades adecuadas para mantener su musculatura, energía y salud general.",
                "Control de las porciones: servir la cantidad recomendada según su peso, condición corporal, edad y nivel de actividad. Ajustar la ración con el veterinario para evitar el sobrepeso, que puede aumentar la presión sobre sus articulaciones.",
                "Comidas repartidas durante el día: normalmente necesita dos comidas diarias, una por la mañana y otra por la tarde o noche. Mantener horarios regulares ayuda a controlar su consumo y evita que pase demasiado tiempo sin alimentarse.",
                "Agua limpia y fresca: debe tener agua potable disponible durante todo el día. Lavar el recipiente y cambiar el agua regularmente, especialmente en regiones cálidas de Bolivia.",
                "Proteínas de buena calidad: necesita proteínas suficientes para conservar la musculatura, reparar tejidos y mantener el funcionamiento de sus órganos. Un alimento completo de buena calidad debe proporcionar los aminoácidos necesarios.",
                "Grasas y ácidos grasos esenciales: contribuyen al mantenimiento de la piel, el pelaje, las articulaciones y el funcionamiento del organismo. Los ácidos grasos omega-3 pueden ser beneficiosos en determinados casos, siempre con orientación veterinaria.",
                "Carbohidratos de fácil digestión: proporcionan energía para sus actividades diarias. Deben formar parte de una alimentación equilibrada y no sustituir las proteínas necesarias para mantener su musculatura.",
                "Fibra alimentaria adecuada: ayuda al funcionamiento intestinal y favorece una digestión regular. Su cantidad debe corresponder a sus necesidades digestivas.",
                "Calcio y fósforo equilibrados: son importantes para conservar los huesos y los dientes. No necesita suplementos adicionales si recibe un alimento completo que cubre sus requerimientos.",
                "Vitaminas y minerales esenciales: necesita vitaminas A, D, E y del complejo B, además de minerales como zinc, hierro y selenio, que participan en diferentes funciones del organismo.",
                "Premios saludables y pequeños: se pueden utilizar premios para perros o pequeñas porciones de alimentos seguros, como zanahoria o manzana sin semillas. Los premios no deberían superar aproximadamente el 10 % de sus calorías diarias.",
                "Alimentación adaptada a su actividad física: si realiza entrenamientos, caminatas largas o actividades exigentes, puede necesitar una cantidad de energía diferente. La ración debe ajustarse según su condición corporal y no únicamente por su nivel de actividad.",
                "Control del peso y la musculatura: pesarlo regularmente y observar su condición corporal. Las costillas deben poder palparse sin una capa excesiva de grasa y debe conservar una musculatura adecuada.",
                "Cambios de alimento graduales: si necesita cambiar de marca o fórmula, realizar la transición durante varios días, siempre que no exista una indicación veterinaria diferente, para reducir el riesgo de molestias digestivas.",
                "Alimentación para proteger las articulaciones: mantener un peso saludable es fundamental para reducir la carga sobre las caderas, los codos y las rodillas. No confiar únicamente en suplementos para prevenir enfermedades articulares.",
                "Dieta casera supervisada: si la familia desea preparar comida en casa, debe contar con una receta completa y equilibrada formulada por un veterinario especializado en nutrición. Las mezclas improvisadas pueden producir deficiencias.",
                "Alimentación según su estado de salud: si presenta alergias, problemas digestivos, enfermedades renales, pancreáticas o articulares, puede necesitar una dieta veterinaria específica.",
                "Alimentación después del ejercicio: mantener una rutina tranquila alrededor de las comidas y evitar carreras, saltos o actividades físicas intensas inmediatamente antes y después de comer, debido a su predisposición a la dilatación-torsión gástrica.",
                "Conservación adecuada del alimento: guardar las croquetas en un recipiente limpio, seco y protegido de la humedad, el calor y los insectos. Revisar las fechas de vencimiento y evitar ofrecer alimentos descompuestos."
              ]
            },
            {
              "titulo": "ALIMENTACIÓN NO SALUDABLE",
              "items": [
                "Exceso de comida: darle grandes cantidades puede provocar sobrepeso, aumentar la carga sobre las articulaciones y favorecer problemas metabólicos.",
                "Alimentación insuficiente: ofrecer menos comida de la necesaria puede ocasionar pérdida de peso, disminución de la musculatura, debilidad y deficiencias nutricionales.",
                "Alimento para cachorros como dieta permanente: después de completar su crecimiento, normalmente necesita una fórmula de mantenimiento para adultos. Continuar con alimento de cachorro puede aportar energía y nutrientes en cantidades inadecuadas.",
                "Sobras de comida familiar: los alimentos preparados con demasiada sal, aceite, condimentos o ingredientes perjudiciales no son apropiados para su dieta habitual.",
                "Huesos cocidos: pueden astillarse y provocar atragantamiento, obstrucciones o lesiones internas.",
                "Chocolate, café y bebidas energéticas: contienen sustancias tóxicas para los perros que pueden afectar el sistema nervioso y el corazón.",
                "Uvas y pasas: pueden provocar daño renal grave. No existe una cantidad que pueda considerarse segura para todos los perros.",
                "Cebolla y ajo: pueden dañar los glóbulos rojos y provocar anemia, especialmente cuando se consumen en cantidades importantes o repetidamente.",
                "Productos con xilitol: algunos chicles, caramelos y productos sin azúcar contienen este edulcorante, que puede causar una intoxicación grave.",
                "Comidas fritas, grasas o muy saladas: los embutidos, las carnes con mucha grasa y las sobras aceitosas pueden ocasionar problemas digestivos y favorecer la pancreatitis.",
                "Leche de vaca en grandes cantidades: puede causar diarrea, gases y molestias digestivas en perros que no toleran bien la lactosa.",
                "Dietas exclusivamente de carne: proporcionar carne sin una formulación equilibrada no cubre todas sus necesidades de vitaminas, minerales y otros nutrientes.",
                "Dietas crudas sin asesoramiento profesional: pueden transmitir bacterias y parásitos al perro y a las personas que conviven con él.",
                "Suplementos para las articulaciones sin indicación veterinaria: administrar calcio, vitaminas, glucosamina u otros productos por cuenta propia no garantiza protección articular y puede provocar desequilibrios.",
                "Alimentación libre sin controlar las porciones: dejar grandes cantidades de comida disponibles todo el día dificulta vigilar cuánto consume y puede favorecer el sobrepeso.",
                "Ejercicio intenso inmediatamente después de comer: realizar carreras, saltos o actividades exigentes alrededor de las comidas no es recomendable debido al riesgo de problemas gástricos.",
                "Premios en exceso: ofrecer demasiadas golosinas puede desequilibrar su alimentación y aumentar su peso.",
                "Alimentos en mal estado: la comida descompuesta, contaminada o almacenada incorrectamente puede provocar intoxicaciones y enfermedades digestivas.",
                "Cambios bruscos de alimentación: cambiar repentinamente de marca, fórmula o ingredientes puede producir diarrea, vómitos y molestias digestivas.",
                "Alimentos condimentados: las preparaciones con ají, salsas, pimienta y otros condimentos pueden irritar su aparato digestivo y no deben formar parte de su alimentación habitual."
              ]
            }
          ]
        },
 
        "salud": {
          "titulo": "SALUD",
          "secciones": [
            {
              "titulo": "SEÑALES DE BUENA SALUD",
              "items": [
                "Energía apropiada para su edad: participa en paseos, juegos y actividades habituales sin mostrar debilidad persistente ni cansancio excesivo.",
                "Apetito estable: consume sus alimentos con normalidad y no presenta dificultades para masticar o tragar.",
                "Peso equilibrado: conserva una condición corporal adecuada, sin acumulación excesiva de grasa ni pérdida marcada de musculatura.",
                "Ojos limpios: no presenta secreciones abundantes, enrojecimiento persistente, opacidad repentina ni dolor ocular.",
                "Respiración normal: respira sin esfuerzo, no presenta tos persistente y puede descansar tranquilamente.",
                "Digestión adecuada: sus heces suelen ser formadas y no presenta vómitos repetidos, diarrea persistente ni sangre en las deposiciones.",
                "Movimiento cómodo: camina, corre y se levanta sin cojera persistente, rigidez marcada ni dificultad para apoyar las patas.",
                "Articulaciones funcionales: puede realizar sus actividades habituales sin mostrar dolor evidente en las caderas, codos o rodillas.",
                "Piel y pelaje en buenas condiciones: mantiene un pelaje limpio y brillante, sin pérdida excesiva de pelo, heridas recurrentes ni picazón intensa.",
                "Encías y dientes saludables: presenta encías de color rosado, sin inflamación importante, sangrado ni acumulación excesiva de sarro.",
                "Oídos limpios: no presenta mal olor, secreciones abundantes, enrojecimiento ni sacudidas constantes de la cabeza.",
                "Orina normal: orina con una frecuencia habitual, sin sangre, dolor ni esfuerzo excesivo.",
                "Buena condición muscular: conserva fuerza y musculatura en las patas y el cuerpo, sin pérdida progresiva de masa muscular.",
                "Conducta equilibrada: se relaciona adecuadamente con su familia y puede permanecer tranquilo ante situaciones cotidianas.",
                "Buena respuesta al entrenamiento: comprende órdenes conocidas, presta atención y responde de manera apropiada a las indicaciones.",
                "Vacunas y desparasitación al día: sigue el calendario establecido por el veterinario según su edad, historial y exposición a otros animales.",
                "Resistencia física adecuada: puede realizar actividad diaria acorde con su condición física y recuperarse normalmente después del ejercicio.",
                "Descanso normal: duerme tranquilamente y no presenta inquietud persistente, dolor o dificultades frecuentes para encontrar una posición cómoda."
              ]
            },
            {
              "titulo": "SEÑALES DE MALA SALUD",
              "items": [
                "Pérdida o aumento inexplicable de peso: puede relacionarse con alteraciones digestivas, hormonales, metabólicas o enfermedades internas.",
                "Pérdida del apetito: si deja de comer o presenta cambios persistentes en su alimentación, necesita valoración veterinaria.",
                "Vómitos repetidos: pueden relacionarse con enfermedades digestivas, pancreatitis, parásitos, intoxicaciones u otros problemas.",
                "Diarrea persistente o con sangre: puede provocar deshidratación y ser señal de infecciones, inflamación intestinal u otras enfermedades.",
                "Dificultad para caminar o levantarse: puede indicar dolor articular, displasia de cadera, problemas de columna o lesiones musculares.",
                "Cojera recurrente: puede estar relacionada con displasia de codo o cadera, artrosis, lesiones o inflamación de las articulaciones.",
                "Debilidad de las patas traseras: arrastrar las patas, perder coordinación o presentar dificultad progresiva para caminar puede indicar un problema neurológico, como mielopatía degenerativa, u otras enfermedades.",
                "Dolor en la espalda o zona lumbar: puede manifestarse mediante rigidez, rechazo al movimiento, dificultad para levantarse o sensibilidad al tocar determinadas zonas.",
                "Abdomen hinchado o doloroso: especialmente si presenta arcadas sin vomitar, inquietud o salivación abundante, puede indicar dilatación-torsión gástrica.",
                "Tos o dificultad respiratoria: puede relacionarse con enfermedades respiratorias, cardíacas u otras alteraciones.",
                "Picazón intensa o pérdida de pelo: puede deberse a alergias, infecciones, parásitos o enfermedades de la piel.",
                "Infecciones recurrentes de los oídos: el mal olor, la secreción, el dolor y las sacudidas frecuentes de la cabeza requieren revisión.",
                "Encías pálidas, azuladas o amarillentas: pueden indicar problemas circulatorios, respiratorios, sanguíneos o hepáticos.",
                "Sed y orina excesivas: pueden relacionarse con enfermedades renales, diabetes, alteraciones hormonales u otros trastornos.",
                "Dificultad para defecar: el estreñimiento persistente, el esfuerzo excesivo o la presencia de sangre necesitan evaluación.",
                "Cambios de comportamiento: irritabilidad, aislamiento, miedo repentino o rechazo al contacto pueden ser señales de dolor o enfermedad.",
                "Pérdida de resistencia física: cansarse mucho más rápido que antes o no poder completar actividades habituales requiere una revisión.",
                "Heridas que no cicatrizan: pueden indicar infecciones, problemas circulatorios, alteraciones metabólicas o enfermedades de la piel.",
                "Bultos o masas nuevas: cualquier crecimiento debajo de la piel debe ser revisado por el veterinario, aunque no parezca causar molestias.",
                "Heces abundantes y pérdida de peso a pesar de comer: pueden ser señales de insuficiencia pancreática exocrina, una enfermedad que afecta la digestión y absorción de nutrientes.",
                "Convulsiones o desorientación: son signos que necesitan atención veterinaria inmediata.",
                "Dificultad para orinar: intentar orinar repetidamente sin conseguirlo puede indicar una obstrucción urinaria y requiere atención urgente.",
                "Cambios en la forma de caminar: arrastrar las patas, cruzarlas de manera anormal o perder el equilibrio requiere evaluación neurológica.",
                "Dolor al masticar: puede deberse a problemas dentales, fracturas, infecciones o enfermedades de las encías."
              ]
            }
          ]
        },
 
        "primeros": {
          "titulo": "PRIMEROS AUXILIOS",
          "secciones": [
            {
              "titulo": "QUÉ HACER CUANDO LE SUCEDEN ACCIDENTES COMO:",
              "items": [
                "Caídas, golpes o lesiones en las patas",
                "Mantener la calma y evitar que siga corriendo, saltando o realizando movimientos bruscos.",
                "Observar si puede caminar, apoyar las patas y respirar normalmente, sin obligarlo a levantarse.",
                "Si presenta dolor intenso, dificultad para caminar o sospecha de lesión en la columna, mantenerlo lo más quieto posible.",
                "Si necesita traslado, solicitar ayuda para sostener su cuerpo de manera uniforme, teniendo en cuenta su tamaño y peso.",
                "No intentar acomodar huesos, estirar articulaciones ni masajear una zona dolorida.",
                "No administrar medicamentos humanos para aliviar el dolor.",
                "Acudir urgentemente al veterinario si no puede apoyar una pata, pierde el conocimiento, presenta dolor intenso o ha sufrido un accidente importante.",
                "Heridas y sangrado",
                "Alejarlo de la situación que causó la lesión y evitar que lama la herida.",
                "Colocar una gasa limpia o un paño limpio sobre el área sangrante y mantener una presión constante.",
                "Si la tela se empapa, colocar otra encima sin retirar la primera.",
                "No utilizar alcohol, agua oxigenada concentrada, polvos ni remedios caseros dentro de la herida.",
                "No retirar objetos clavados profundamente; estabilizarlos con cuidado y acudir al veterinario.",
                "Si la herida es profunda, fue causada por una mordedura o el sangrado es abundante, buscar atención veterinaria urgente.",
                "Observar si presenta debilidad, encías pálidas o respiración acelerada, porque pueden indicar una pérdida importante de sangre.",
                "Atragantamiento",
                "Comprobar si puede respirar, toser y emitir sonidos.",
                "Si puede toser con fuerza y respirar, mantenerlo tranquilo y buscar ayuda veterinaria si el problema no se resuelve rápidamente.",
                "Solo retirar un objeto si está claramente visible, suelto y puede extraerse sin empujarlo más adentro.",
                "No introducir los dedos a ciegas en su garganta.",
                "Si no puede respirar, sus encías se vuelven azuladas o pierde el conocimiento, acudir inmediatamente a urgencias veterinarias y llamar para recibir instrucciones durante el traslado.",
                "No darle comida ni agua mientras exista sospecha de obstrucción.",
                "Intoxicación",
                "Alejarlo de la sustancia que pudo ingerir o tocar.",
                "Guardar el envase o tomar una fotografía de la etiqueta para identificar el producto.",
                "No provocar el vómito ni darle leche, aceite, sal, medicamentos o carbón activado sin indicación veterinaria.",
                "Llamar inmediatamente al veterinario, aunque todavía parezca encontrarse bien.",
                "Informar qué sustancia pudo consumir, cuánto aproximadamente y hace cuánto tiempo.",
                "Si presenta convulsiones, dificultad respiratoria o pérdida del conocimiento, trasladarlo a urgencias sin demora.",
                "Quemaduras",
                "Alejarlo de la fuente de calor.",
                "Enfriar la zona con agua corriente fresca, no helada, durante varios minutos si es posible hacerlo sin retrasar la atención.",
                "No aplicar hielo, mantequilla, pasta dental, aceites ni cremas caseras.",
                "No romper ampollas ni retirar piel dañada.",
                "Cubrir suavemente con una tela limpia y acudir al veterinario.",
                "Las quemaduras extensas, profundas o que afectan la cara o la respiración son urgencias.",
                "Picaduras y mordeduras",
                "Llevarlo a un lugar seguro y observar si aparece hinchazón, dolor o enrojecimiento.",
                "Si hay un aguijón visible, retirarlo cuidadosamente sin apretar el saco de veneno.",
                "No administrar antihistamínicos ni otros medicamentos humanos sin orientación veterinaria.",
                "Las mordeduras pueden causar daños internos aunque la herida externa parezca pequeña.",
                "Acudir inmediatamente si presenta hinchazón de la cara, dificultad para respirar, vómitos repentinos, debilidad o colapso.",
                "Vómitos y diarrea",
                "Observar la frecuencia de los episodios y si hay sangre, dolor abdominal o decaimiento.",
                "Si está alerta, puede tragar y no vomita repetidamente, ofrecer pequeñas cantidades de agua sin obligarlo a beber.",
                "No administrar antibióticos ni medicamentos antidiarreicos por cuenta propia.",
                "Evitar ofrecer comidas grasosas, sobras o premios mientras se solicita orientación veterinaria.",
                "Si los vómitos se repiten, presenta sangre o no puede retener agua, acudir al veterinario.",
                "Si el abdomen está hinchado y tiene arcadas sin vomitar, acudir inmediatamente a urgencias por posible torsión gástrica.",
                "Golpe de calor",
                "Llevarlo inmediatamente a un lugar fresco y ventilado.",
                "Mojar el cuerpo con agua fresca, no helada, evitando retrasar el traslado.",
                "No cubrirlo con toallas gruesas mojadas que puedan retener calor.",
                "No obligarlo a beber si está desorientado, débil o no puede tragar normalmente.",
                "Trasladarlo inmediatamente al veterinario, aunque parezca recuperarse, porque pueden aparecer complicaciones internas.",
                "Dolor o problemas en la columna",
                "Evitar que suba escaleras, salte o continúe caminando si presenta debilidad o dolor.",
                "Mantenerlo en una superficie cómoda y limitar sus movimientos.",
                "No manipular ni presionar la columna para intentar descubrir dónde le duele.",
                "No realizar masajes ni ejercicios de rehabilitación sin indicación profesional.",
                "Si pierde coordinación, arrastra las patas traseras o no puede levantarse, necesita atención veterinaria urgente.",
                "Problemas digestivos y sospecha de torsión gástrica",
                "Observar si presenta abdomen aumentado de tamaño, inquietud, salivación abundante o arcadas sin expulsar contenido.",
                "No intentar darle comida, agua ni medicamentos para aliviar los síntomas.",
                "No esperar a que el abdomen disminuya por sí solo.",
                "Trasladarlo inmediatamente a urgencias veterinarias, ya que la dilatación-torsión gástrica puede avanzar rápidamente."
              ]
            }
          ]
        },
 
        "cuidados": {
          "titulo": "CUIDADOS",
          "secciones": [
            {
              "titulo": "CÓMO MANTENERLO BIEN CUIDADO",
              "items": [
                "Controles veterinarios periódicos: realizar al menos una revisión general anual si está sano. El veterinario debe evaluar su peso, musculatura, articulaciones, dientes, oídos, piel y estado general.",
                "Vacunación y desparasitación: mantener un calendario actualizado según su historial, región, exposición a otros animales y riesgos ambientales.",
                "Alimentación equilibrada: ofrecer alimento completo para perros adultos de razas grandes y ajustar las cantidades a sus necesidades energéticas.",
                "Ejercicio diario: proporcionarle paseos, juegos y actividades físicas que mantengan su musculatura y resistencia. La intensidad debe adaptarse a su condición física.",
                "Paseos variados: alternar caminatas, exploración de lugares seguros y juegos de búsqueda para evitar el aburrimiento.",
                "Calentamiento antes del ejercicio: comenzar con caminatas suaves antes de realizar actividades más exigentes, especialmente si participa en entrenamientos.",
                "Evitar el ejercicio en temperaturas extremas: adaptar los paseos al clima de cada región de Bolivia. Durante los días calurosos, elegir las primeras horas de la mañana o las últimas de la tarde.",
                "Cepillado frecuente: cepillarlo varias veces por semana para retirar el pelo suelto y mantener el pelaje limpio. Durante las temporadas de muda puede necesitar cepillado diario.",
                "Baños cuando sean necesarios: utilizar champú para perros y secar bien el pelaje. Bañarlo en exceso puede resecar o irritar la piel.",
                "Cuidado dental: cepillar sus dientes con pasta dental para perros. Revisar si presenta sarro, encías inflamadas o mal aliento intenso.",
                "Cuidado de las uñas: revisar las uñas regularmente y recortarlas cuando haga falta, evitando cortar la parte sensible.",
                "Revisión de las orejas: comprobar si hay mal olor, enrojecimiento o secreciones. No introducir bastoncillos ni objetos profundamente en el oído.",
                "Revisión de la piel: observar si presenta bultos, heridas, parásitos, zonas sin pelo o irritaciones.",
                "Protección de las articulaciones: mantener un peso adecuado, evitar esfuerzos excesivos y consultar si presenta rigidez, cojera o dificultad para levantarse.",
                "Prevención de problemas digestivos: mantener horarios de alimentación regulares y evitar el ejercicio intenso alrededor de las comidas.",
                "Protección contra el frío y la humedad: ofrecer una cama seca, un refugio protegido y un lugar donde pueda descansar sin permanecer sobre suelo húmedo.",
                "Protección frente al calor: proporcionar sombra, ventilación y agua fresca. Evitar ejercicio intenso durante las horas más calurosas y nunca dejarlo dentro de un vehículo cerrado.",
                "Socialización continua: acostumbrarlo de manera positiva a personas, sonidos, lugares y otros animales, respetando sus señales de incomodidad.",
                "Educación con refuerzo positivo: premiar las conductas adecuadas y establecer reglas constantes dentro del hogar.",
                "Estimulación mental: utilizar juguetes de búsqueda, juegos de olfato, ejercicios de obediencia y actividades que le permitan resolver problemas.",
                "Un espacio propio: proporcionarle una cama cómoda y una zona tranquila donde pueda descansar sin ser molestado.",
                "Prevención de escapes: mantener puertas y cercas seguras. Aunque sea leal a su familia, no debe dejarse suelto en calles o lugares con tráfico.",
                "Identificación: utilizar una placa con un número de contacto y, si es posible, un microchip registrado.",
                "Control del peso: pesarlo regularmente y ajustar la comida a su actividad. El exceso de peso puede agravar problemas articulares.",
                "Supervisión durante el juego: evitar actividades demasiado bruscas que puedan provocar lesiones en las patas, espalda o articulaciones.",
                "Descanso adecuado: respetar sus periodos de sueño y permitirle recuperarse después de realizar ejercicio.",
                "Revisión de la movilidad: observar periódicamente cómo camina, corre, se levanta y sube pequeñas pendientes. Los cambios progresivos pueden ser importantes.",
                "Atención a la salud digestiva: si presenta heces anormales, pérdida de peso o hambre excesiva, consultar para descartar problemas de absorción o insuficiencia pancreática.",
                "Convivencia familiar: ofrecerle compañía, atención e interacción diaria. No debe pasar largos periodos aislado sin estimulación ni contacto."
              ]
            },
            {
              "titulo": "CÓMO SABER SI NO TIENE UN BUEN CUIDADO",
              "items": [
                "Por su aspecto físico",
                "Tiene el pelaje sucio durante largos periodos, mal olor persistente o heridas sin atender.",
                "Presenta uñas demasiado largas que le dificultan caminar.",
                "Tiene secreciones en los ojos o los oídos, encías inflamadas o problemas dentales sin revisar.",
                "Está excesivamente delgado o tiene demasiada grasa corporal.",
                "Se rasca continuamente, pierde pelo en zonas extensas o presenta parásitos visibles.",
                "Presenta cojera o dificultad para levantarse que no recibe atención.",
                "Tiene bultos, lesiones o irritaciones que permanecen sin evaluación.",
                "Por su alimentación",
                "No tiene acceso constante a agua limpia.",
                "Recibe huesos cocidos, alimentos tóxicos o sobras muy grasosas.",
                "Come cantidades excesivas y aumenta de peso.",
                "Recibe una dieta insuficiente o poco equilibrada.",
                "Se le administran suplementos sin necesidad ni orientación veterinaria.",
                "No recibe un alimento adecuado para su etapa de vida y condición física.",
                "No se controlan los cambios de peso ni las alteraciones digestivas.",
                "Por su comportamiento",
                "Tiene miedo constante de las personas o reacciona defensivamente ante situaciones cotidianas.",
                "Ladra excesivamente, salta sobre la gente o tira de la correa porque no ha aprendido alternativas apropiadas.",
                "Se muestra muy inquieto por falta de ejercicio o estimulación mental.",
                "Pasa demasiado tiempo aislado y sin interacción social.",
                "No puede descansar porque lo molestan constantemente.",
                "Presenta comportamientos agresivos que no reciben orientación profesional.",
                "Muestra aburrimiento, frustración o ansiedad de manera frecuente.",
                "Presenta un cambio brusco de conducta, que también podría indicar dolor o enfermedad.",
                "Por su salud y seguridad",
                "No recibe vacunas ni controles veterinarios.",
                "Pasa largos periodos expuesto al sol, al frío o a la lluvia sin refugio.",
                "Se le permite salir sin supervisión cerca de vehículos.",
                "Realiza ejercicio excesivo o inadecuado para su condición física.",
                "No se atienden sus lesiones, vómitos, diarrea o dificultades para caminar.",
                "No recibe prevención contra pulgas, garrapatas y parásitos internos.",
                "Permanece durante muchas horas sin compañía, actividad ni oportunidades adecuadas para hacer sus necesidades.",
                "No se revisan sus articulaciones pese a presentar dificultades de movilidad."
              ]
            }
          ]
        },
 
        "comportamiento": {
          "titulo": "COMPORTAMIENTO",
          "secciones": [
            {
              "titulo": "ADIESTRAMIENTO Y EDUCACIÓN DURANTE LA ETAPA ADULTA",
              "items": [
                "Reforzar su nombre: continuar utilizando su nombre de manera positiva y premiarlo cuando preste atención a la persona que lo llama.",
                "Practicar órdenes básicas: mantener el aprendizaje de “siéntate”, “ven”, “quieto”, “suelta” y “junto”, utilizando premios y sesiones cortas.",
                "Fortalecer la llamada: practicar en espacios seguros y premiarlo cuando regrese inmediatamente al escuchar su nombre o la orden.",
                "Enseñarle a caminar con correa: premiar cuando camine tranquilamente sin tirar y mantener una conducción segura durante los paseos.",
                "Controlar los saltos: pedirle que se siente antes de saludar y recompensarlo cuando mantenga las cuatro patas en el suelo.",
                "Reducir las mordidas durante el juego: ofrecer juguetes apropiados y detener brevemente la interacción cuando utilice la boca de manera brusca.",
                "Enseñarle a recibir visitas: acostumbrarlo a las personas que ingresan al hogar, premiando la tranquilidad y evitando situaciones que puedan generarle miedo.",
                "Socializarlo de manera positiva: permitirle relacionarse con perros equilibrados y personas respetuosas, sin obligarlo a interactuar.",
                "Controlar su instinto de persecución: enseñarle a responder a la llamada y a detenerse ante situaciones que puedan ponerlo en peligro.",
                "Evitar la protección excesiva: no estimular conductas de amenaza, persecución o intimidación hacia visitantes o personas desconocidas.",
                "Practicar la obediencia en diferentes lugares: reforzar las órdenes en espacios seguros con distintos sonidos, personas y distracciones.",
                "Estimular su inteligencia: realizar juegos de olfato, búsqueda de objetos y actividades que requieran concentración.",
                "Enseñarle a permanecer tranquilo: premiarlo cuando descanse en su cama y pueda relajarse sin necesitar atención constante.",
                "Mantener reglas familiares consistentes: todas las personas del hogar deben utilizar las mismas órdenes y normas.",
                "Practicar el autocontrol: enseñarle a esperar antes de salir por una puerta, recibir comida o comenzar un juego.",
                "Acostumbrarlo a los cuidados veterinarios: permitir revisiones suaves de patas, orejas, boca y cuerpo, utilizando premios para facilitar la manipulación.",
                "Evitar el castigo físico: los golpes, gritos e intimidación pueden generar miedo y empeorar las reacciones defensivas.",
                "Mantener actividades regulares: combinar ejercicio físico con entrenamiento y estimulación mental para evitar el aburrimiento."
              ]
            },
            {
              "titulo": "CÓMO MEJORAR EL COMPORTAMIENTO DE TU MASCOTA SI NO FUE ADIESTRADO",
              "items": [
                "Identificar la causa del problema: observar cuándo aparece la conducta, qué la desencadena y qué sucede después. Si comienza repentinamente, descartar primero un problema de salud.",
                "Volver a las órdenes básicas: practicar su nombre, “ven”, “siéntate”, “quieto” y “suelta” en un entorno tranquilo.",
                "Premiar inmediatamente las conductas correctas: utilizar premios pequeños, elogios o juguetes para que comprenda qué comportamiento debe repetir.",
                "Enseñarle a no saltar: pedirle que se siente antes de saludar y premiarlo cuando permanezca tranquilo.",
                "Mejorar los paseos: premiar cuando camine con la correa floja y cambiar de dirección con calma cuando comience a tirar, evitando tirones bruscos.",
                "Reducir los ladridos: identificar si ladra por miedo, aburrimiento, alerta o frustración. Enseñarle una conducta alternativa y premiar los momentos de calma.",
                "Prevenir la destrucción de objetos: guardar zapatos, cables y artículos peligrosos; ofrecer juguetes seguros y actividades de olfato.",
                "Trabajar la tolerancia a la soledad: practicar ausencias muy cortas y aumentarlas gradualmente. Si presenta angustia intensa, consultar a un veterinario o profesional de conducta.",
                "Controlar la conducta de persecución: enseñarle a responder a la llamada y utilizar espacios seguros para practicar. No permitir que persiga personas, vehículos u otros animales.",
                "Manejar la conducta protectora: no animarlo a amenazar, perseguir o atacar a personas. Premiar la calma y mantener una distancia segura de las situaciones que lo alteran.",
                "No castigar los gruñidos: un gruñido puede ser una señal de incomodidad, miedo o dolor. Darle espacio, identificar la causa y buscar orientación si se repite.",
                "Evitar la agresividad durante la comida: establecer rutinas tranquilas y no molestarlo mientras come. Si protege sus alimentos, buscar orientación profesional.",
                "Practicar la obediencia a diario: realizar sesiones breves, constantes y adaptadas a su capacidad de concentración.",
                "Ofrecer ejercicio y estimulación adecuados: combinar caminatas, juegos y ejercicios mentales para reducir la inquietud y el aburrimiento.",
                "Buscar ayuda profesional cuando sea necesario: si muestra agresividad, miedo intenso, reactividad o problemas difíciles de controlar, acudir a un veterinario y a un educador canino que utilice métodos basados en refuerzo positivo.",
                "Tener paciencia: los hábitos adquiridos pueden tardar en cambiar. La constancia y la seguridad son más eficaces que los castigos."
              ]
            }
          ]
        },
 
        "vacunacion": {
          "titulo": "VACUNACIÓN",
          "secciones": [
            {
              "titulo": "TODAS LAS VACUNAS CON LAS QUE DEBERÍA CONTAR LA MASCOTA DURANTE SU VIDA",
              "items": [
                "Vacuna múltiple esencial: protege contra enfermedades importantes como moquillo, parvovirus y adenovirus canino, relacionado con la hepatitis infecciosa. En la etapa adulta debe recibir los refuerzos indicados según el historial de vacunación y el tipo de vacuna utilizada.",
                "Vacuna contra la rabia: es esencial por la gravedad de la enfermedad y las normas sanitarias. En Bolivia debe mantenerse de acuerdo con la normativa sanitaria vigente y las campañas oficiales de vacunación antirrábica.",
                "Refuerzos de la vacuna múltiple: después de completar la serie de cachorro y el refuerzo correspondiente durante el primer año, las siguientes dosis dependen de los componentes de la vacuna, las recomendaciones veterinarias y el riesgo de exposición. Algunos componentes esenciales pueden tener intervalos de hasta tres años.",
                "Vacuna contra la leptospirosis: puede recomendarse según la región, la presencia de roedores, el acceso a agua contaminada y otros riesgos ambientales. Generalmente requiere una serie inicial y refuerzos periódicos.",
                "Vacuna contra la tos de las perreras: las vacunas contra Bordetella y otros agentes respiratorios pueden considerarse si asiste a guarderías, residencias, entrenamientos grupales o lugares donde conviven muchos perros.",
                "Vacuna contra la influenza canina: puede considerarse si está disponible y existe riesgo de exposición, especialmente cuando convive con numerosos perros.",
                "Otras vacunas específicas: el veterinario decidirá si alguna es apropiada para su estilo de vida, región y entorno. No todas las vacunas adicionales son necesarias para todos los perros.",
                "Registro de vacunación: conservar la cartilla con las fechas, los nombres de las vacunas, los datos del profesional y las fechas sugeridas para los siguientes refuerzos.",
                "Si se desconoce su historial: no asumir que está vacunado. El veterinario establecerá un calendario de recuperación según su edad y las dosis documentadas.",
                "Antes de cada vacuna: informar si está enfermo, recibe algún tratamiento o tuvo una reacción previa a una vacuna. El profesional determinará si es conveniente vacunar ese día.",
                "Durante toda su vida: mantener los refuerzos esenciales indicados, aunque el perro ya sea adulto o senior.",
                "La desparasitación interna y la prevención de pulgas y garrapatas también son importantes, pero no son vacunas. Deben programarse por separado con orientación veterinaria, teniendo en cuenta los parásitos presentes en la región donde vive."
              ]
            }
          ]
        },
 
        "veterinario": {
          "titulo": "CUÁNDO IR AL VETERINARIO",
          "secciones": [
            {
              "titulo": "EN QUÉ SITUACIONES DE EMERGENCIA DEBES ACUDIR A UN VETERINARIO",
              "items": [
                "Dificultad para respirar: respiración trabajosa, encías azuladas o incapacidad para respirar normalmente pueden indicar una emergencia grave.",
                "Abdomen hinchado con arcadas sin vomitar: el Pastor Alemán es una raza grande y de pecho profundo, por lo que estos signos pueden indicar dilatación-torsión gástrica. No esperar a que se le pase.",
                "Desmayo o pérdida del conocimiento: puede deberse a problemas circulatorios, cardíacos, neurológicos u otras causas graves.",
                "Convulsiones: especialmente si es la primera vez, duran varios minutos, se repiten o no recupera su estado normal.",
                "Sangrado abundante: si no se detiene con presión directa o la herida es profunda, necesita atención urgente.",
                "Accidente de tránsito o caída importante: puede tener lesiones internas aunque aparentemente camine bien.",
                "Ingestión de venenos o medicamentos: no esperar a que aparezcan síntomas. Llevar el envase o una fotografía del producto.",
                "Vómitos repetidos con debilidad: puede sufrir deshidratación o presentar una enfermedad importante.",
                "Diarrea con sangre: especialmente si también presenta vómitos, debilidad o dolor abdominal.",
                "Encías muy pálidas o amarillas: pueden ser señales de anemia, problemas circulatorios o enfermedades graves.",
                "Dolor intenso o incapacidad para caminar: puede indicar una lesión, fractura o problema ortopédico.",
                "Debilidad repentina de las patas traseras: necesita evaluación urgente, especialmente si no puede mantenerse en pie, pierde coordinación o presenta dolor.",
                "Dificultad para orinar: intentar orinar repetidamente sin producir orina puede indicar una obstrucción que requiere atención inmediata.",
                "Golpe de calor: jadeo intenso, desorientación, vómitos, debilidad o colapso después de estar en un ambiente caliente requieren atención inmediata.",
                "Reacción alérgica grave: hinchazón repentina de la cara, dificultad respiratoria, vómitos repetidos o colapso después de una picadura, alimento o medicamento.",
                "Herida profunda o mordedura: puede existir daño interno o riesgo de infección aunque la lesión externa sea pequeña.",
                "Lesión ocular: dolor intenso, ojo cerrado, sangrado o cambios repentinos en la visión requieren atención rápida.",
                "Incapacidad para retener agua: si vomita cada vez que bebe o muestra signos de deshidratación, necesita valoración urgente.",
                "Cambios bruscos de comportamiento: desorientación, debilidad marcada, falta de respuesta o agresividad repentina pueden estar relacionados con dolor o enfermedad.",
                "Pérdida repentina de coordinación: si camina de forma inestable, se cae o no puede controlar sus extremidades, necesita evaluación inmediata.",
                "Dolor abdominal intenso: si se muestra inquieto, adopta posturas extrañas o no permite que le toquen el abdomen, requiere atención veterinaria urgente."
              ]
            },
            {
              "titulo": "CONSULTAS VETERINARIAS QUE NO DEBES POSPONER",
              "items": [
                "Si cojea repetidamente, se levanta con dificultad o muestra rigidez después de descansar.",
                "Si pierde pelo en exceso, se rasca continuamente o presenta infecciones recurrentes de la piel.",
                "Si tiene mal aliento intenso, sarro o dolor al masticar.",
                "Si bebe u orina mucho más de lo habitual.",
                "Si aumenta o pierde peso sin una explicación clara.",
                "Si tiene tos, secreción nasal o problemas digestivos que persisten.",
                "Si presenta miedo intenso, ansiedad por separación o conductas agresivas nuevas.",
                "Si necesita una revisión de su peso, alimentación, vacunas o prevención de parásitos.",
                "Si muestra cambios graduales en la forma de caminar, correr o levantarse, ya que conviene detectar temprano los problemas articulares o neurológicos.",
                "Si presenta debilidad progresiva en las patas traseras, aunque todavía pueda caminar.",
                "Si tiene heces abundantes, pérdida de peso y hambre excesiva, para descartar insuficiencia pancreática exocrina.",
                "Si aparecen bultos, masas o inflamaciones debajo de la piel.",
                "Si presenta infecciones frecuentes de los oídos o sacude constantemente la cabeza.",
                "Si tiene heridas que tardan demasiado en cicatrizar.",
                "Si pierde resistencia física y se cansa con actividades que antes realizaba sin dificultad.",
                "Si presenta cambios persistentes en el apetito o en sus hábitos de descanso.",
                "Si muestra dolor al subir escaleras, saltar o levantarse después de permanecer acostado."
              ]
            }
          ]
        }
      }
    },
      "senior": {
      "tituloOriginal": "PASTOR ALEMÁN SENIOR O GERIÁTRICO (7 AÑOS EN ADELANTE)",
      "temas": {
        "alimentacion": {
          "titulo": "ALIMENTACIÓN",
          "secciones": [
            {
              "titulo": "ALIMENTACIÓN SALUDABLE",
              "items": [
                "Alimento especial para perros senior de razas grandes: elegir un alimento completo y equilibrado formulado para perros mayores de razas grandes. Debe proporcionar proteínas de buena calidad, grasas moderadas, vitaminas, minerales y nutrientes que ayuden a conservar su musculatura y mantener su salud.",
                "Control de las porciones: servir la cantidad recomendada según su peso, condición corporal, edad y nivel de actividad. Los perros mayores suelen gastar menos energía, por lo que pueden necesitar ajustes en sus raciones para evitar el sobrepeso.",
                "Comidas repartidas durante el día: normalmente puede recibir dos comidas diarias. Si tiene poco apetito, dificultades para masticar o problemas digestivos, el veterinario puede recomendar dividir su ración en porciones más pequeñas.",
                "Agua limpia y fresca: debe tener agua potable disponible durante todo el día. Los perros mayores pueden presentar enfermedades que aumentan la sed o modifican su consumo de agua, por lo que es importante observar cualquier cambio.",
                "Proteínas de buena calidad: necesita proteínas suficientes y de fácil digestión para conservar la masa muscular y evitar la pérdida de fuerza que puede aparecer con la edad. No se deben reducir las proteínas automáticamente por ser senior; cualquier modificación debe depender de su estado de salud.",
                "Grasas en cantidades adecuadas: aportan energía y ayudan a mantener la piel, el pelaje y diferentes funciones del organismo. La cantidad debe adaptarse a su actividad física y condición corporal.",
                "Ácidos grasos omega-3: pueden contribuir al mantenimiento de la salud de las articulaciones y ayudar en determinados procesos inflamatorios. Su administración mediante alimentos o suplementos debe consultarse con el veterinario.",
                "Fibra alimentaria adecuada: favorece el funcionamiento intestinal y puede ayudar a controlar el estreñimiento, que puede presentarse con mayor frecuencia en perros mayores.",
                "Carbohidratos de fácil digestión: proporcionan energía para sus actividades cotidianas. Deben formar parte de una dieta equilibrada y no sustituir las proteínas necesarias para conservar la musculatura.",
                "Vitaminas y minerales equilibrados: necesita nutrientes como vitaminas A, D, E y del complejo B, además de zinc, hierro y otros minerales. No administrar suplementos sin comprobar primero sus necesidades.",
                "Alimentación adaptada a la salud renal: si presenta enfermedad renal, el veterinario puede recomendar una dieta específica que controle determinados nutrientes, como el fósforo, según el grado de afectación.",
                "Alimentación adaptada a la salud digestiva: si presenta problemas de absorción, diarreas frecuentes o enfermedades pancreáticas, puede necesitar alimentos de fácil digestión y una distribución diferente de las comidas.",
                "Comida de textura adecuada: si tiene desgaste dental, pérdida de piezas dentales o dificultades para masticar, se puede utilizar alimento húmedo o croquetas humedecidas, siempre que sean nutricionalmente completas.",
                "Control del peso y la musculatura: pesarlo regularmente y observar si pierde masa muscular, especialmente en las patas traseras y la espalda. No debe adelgazar excesivamente ni acumular grasa que dificulte su movilidad.",
                "Premios saludables y pequeños: se pueden ofrecer premios para perros mayores o pequeñas porciones de alimentos seguros, como zanahoria cocida sin condimentos. Los premios no deberían superar aproximadamente el 10 % de sus calorías diarias.",
                "Alimentación en horarios regulares: mantener una rutina estable ayuda a controlar su apetito y facilita detectar cambios en la cantidad de comida que consume.",
                "Cambios de alimento graduales: si necesita cambiar a una fórmula senior o veterinaria, realizar una transición progresiva durante varios días, salvo que el veterinario indique una modificación inmediata por motivos médicos.",
                "Dieta casera supervisada: si la familia desea preparar comida en casa, debe contar con una receta completa y equilibrada formulada por un veterinario especializado en nutrición. Las dietas improvisadas pueden producir deficiencias importantes.",
                "Alimentación para conservar las articulaciones: mantener un peso saludable y ofrecer una dieta equilibrada ayuda a reducir la carga sobre las caderas, los codos y la columna. Los suplementos articulares solo deben utilizarse cuando el veterinario los considere apropiados.",
                "Alimentación según sus enfermedades: si presenta diabetes, problemas renales, cardíacos, hepáticos, pancreáticos o digestivos, puede necesitar una dieta veterinaria específica.",
                "Vigilancia del apetito: observar diariamente cuánto come y si necesita más tiempo para terminar sus alimentos. Una disminución persistente del apetito puede ser una señal temprana de enfermedad.",
                "Conservación adecuada del alimento: guardar las croquetas en un recipiente limpio, seco y protegido de la humedad, el calor y los insectos. Revisar las fechas de vencimiento y evitar ofrecer alimentos descompuestos."
              ]
            },
            {
              "titulo": "ALIMENTACIÓN NO SALUDABLE",
              "items": [
                "Exceso de comida: darle cantidades superiores a sus necesidades puede provocar sobrepeso y agravar los problemas articulares, cardíacos y metabólicos.",
                "Alimentación insuficiente: ofrecer muy poca comida puede acelerar la pérdida de musculatura, provocar debilidad y favorecer la desnutrición.",
                "Alimento para cachorros como dieta permanente: no está formulado para las necesidades de mantenimiento de un perro senior y puede aportar energía y nutrientes en cantidades inadecuadas.",
                "Alimento inadecuado para su estado de salud: continuar con una dieta que no corresponde a sus necesidades puede dificultar el control de enfermedades renales, cardíacas, digestivas o metabólicas.",
                "Huesos cocidos: pueden astillarse y provocar atragantamiento, obstrucciones, fracturas dentales o lesiones internas.",
                "Chocolate, café y bebidas energéticas: contienen sustancias tóxicas para los perros y pueden afectar el corazón y el sistema nervioso.",
                "Uvas y pasas: pueden provocar daño renal grave. No existe una cantidad que pueda considerarse segura para todos los perros.",
                "Cebolla y ajo: pueden dañar los glóbulos rojos y producir anemia, especialmente cuando se consumen en cantidades importantes o repetidamente.",
                "Productos con xilitol: algunos chicles, caramelos y productos sin azúcar contienen este edulcorante, que puede causar una intoxicación grave.",
                "Comidas fritas, grasas o muy saladas: los embutidos, las frituras y las carnes con mucha grasa pueden favorecer trastornos digestivos y pancreatitis.",
                "Leche de vaca en grandes cantidades: puede provocar diarrea, gases y molestias digestivas si no tolera bien la lactosa.",
                "Dietas exclusivamente de carne: no proporcionan todos los nutrientes necesarios para mantener su organismo en buenas condiciones.",
                "Dietas crudas sin asesoramiento profesional: pueden transmitir bacterias y parásitos al perro y a las personas que conviven con él.",
                "Suplementos de calcio sin indicación veterinaria: administrar minerales innecesarios puede producir desequilibrios y no mejora automáticamente la salud de los huesos.",
                "Suplementos para las articulaciones sin supervisión: no todos los productos son apropiados para perros mayores y algunos pueden interferir con sus tratamientos.",
                "Alimentación libre sin controlar las porciones: dejar grandes cantidades de comida disponibles permanentemente dificulta vigilar su consumo y puede favorecer el sobrepeso.",
                "Cambios bruscos de alimentación: modificar repentinamente su dieta puede provocar vómitos, diarrea y rechazo de los alimentos.",
                "Premios demasiado duros: los alimentos excesivamente duros pueden ocasionar fracturas dentales o dificultades para masticar.",
                "Sobras de comida familiar: las preparaciones con demasiada sal, aceite, condimentos o ingredientes tóxicos no son apropiadas para su alimentación.",
                "Alimentos en mal estado: pueden provocar intoxicaciones y trastornos digestivos, especialmente cuando el organismo ya presenta enfermedades relacionadas con la edad.",
                "Reducir demasiado las proteínas: hacerlo sin indicación veterinaria puede favorecer la pérdida de masa muscular y debilidad.",
                "Ofrecer comida grasosa para estimular el apetito: puede provocar molestias digestivas y aumentar el riesgo de pancreatitis.",
                "Ignorar los cambios en el consumo de agua: no observar si bebe mucho más o menos de lo habitual puede retrasar la detección de enfermedades importantes."
              ]
            }
          ]
        },
 
        "salud": {
          "titulo": "SALUD",
          "secciones": [
            {
              "titulo": "TIENE BUENA SALUD",
              "items": [
                "Energía adecuada para su edad: mantiene interés por los paseos y actividades tranquilas, aunque puede necesitar más descanso que cuando era adulto.",
                "Apetito estable: consume sus alimentos con normalidad y no presenta dificultades importantes para masticar o tragar.",
                "Peso equilibrado: conserva una condición corporal saludable, sin exceso de grasa ni pérdida marcada de musculatura.",
                "Movimiento cómodo: puede levantarse, caminar y acostarse sin dolor evidente, aunque sus movimientos sean más lentos que en etapas anteriores.",
                "Articulaciones funcionales: puede realizar caminatas moderadas y desplazarse por su entorno sin mostrar cojera persistente.",
                "Buena estabilidad al caminar: mantiene el equilibrio y no presenta caídas frecuentes, arrastre de patas ni pérdida progresiva de coordinación.",
                "Ojos en buenas condiciones: no presenta secreciones abundantes, enrojecimiento persistente, dolor ni cambios repentinos en la visión.",
                "Respiración normal: respira tranquilamente mientras descansa y no presenta tos persistente ni dificultad respiratoria.",
                "Digestión adecuada: mantiene deposiciones formadas y no presenta vómitos repetidos, diarrea persistente ni sangre en las heces.",
                "Piel y pelaje saludables: conserva un pelaje limpio, sin heridas recurrentes, infecciones ni picazón intensa.",
                "Dientes y encías cuidados: no presenta dolor al masticar, sangrado de encías ni inflamación importante.",
                "Oídos sin molestias: no presenta mal olor, secreciones abundantes ni sacudidas constantes de la cabeza.",
                "Orina normal: mantiene hábitos de micción habituales, sin sangre, dolor ni esfuerzo excesivo.",
                "Buena respuesta a su entorno: reconoce a las personas familiares y responde a sonidos, llamadas y situaciones cotidianas.",
                "Comportamiento estable: mantiene sus hábitos habituales y no presenta desorientación frecuente ni cambios bruscos de personalidad.",
                "Descanso adecuado: duerme tranquilamente y puede encontrar una posición cómoda para descansar.",
                "Vacunas y controles veterinarios al día: recibe las revisiones preventivas y los refuerzos indicados según su edad y estado de salud.",
                "Buena condición muscular: conserva una cantidad adecuada de musculatura en las extremidades y el tronco.",
                "Sed y consumo de agua habituales: bebe una cantidad relativamente estable y no presenta cambios repentinos.",
                "Interés por la convivencia: continúa buscando compañía, atención y contacto con su familia, de acuerdo con su temperamento.",
                "Recuperación adecuada después de caminar: puede descansar después de realizar actividad moderada sin presentar agotamiento prolongado."
              ]
            },
            {
              "titulo": "TIENE MALA SALUD",
              "items": [
                "Pérdida de peso involuntaria: puede indicar problemas digestivos, renales, hormonales, pancreáticos, enfermedades crónicas o tumores.",
                "Pérdida de masa muscular: especialmente en las patas traseras, puede relacionarse con envejecimiento, menor actividad, enfermedades articulares o problemas neurológicos.",
                "Disminución del apetito: puede deberse a dolor dental, enfermedades digestivas, problemas renales, alteraciones metabólicas o dolor generalizado.",
                "Sed excesiva: beber mucha más agua de lo habitual puede ser señal de enfermedad renal, diabetes, alteraciones hormonales u otros problemas.",
                "Orina excesiva o cambios en la micción: pueden relacionarse con enfermedades renales, diabetes, infecciones urinarias o problemas de próstata en machos.",
                "Dificultad para levantarse: puede indicar artrosis, displasia de cadera, dolor de columna o pérdida de fuerza muscular.",
                "Rigidez después de descansar: puede relacionarse con enfermedades articulares, especialmente cuando mejora parcialmente después de caminar unos minutos.",
                "Cojera persistente: puede indicar artrosis, lesiones, inflamación o enfermedades de las articulaciones.",
                "Debilidad de las patas traseras: arrastrar las patas, cruzarlas al caminar o perder coordinación puede estar relacionado con mielopatía degenerativa, enfermedades de columna u otros trastornos neurológicos.",
                "Pérdida de equilibrio: caerse, caminar en círculos o inclinar la cabeza puede indicar alteraciones neurológicas, vestibulares u otros problemas.",
                "Dolor en la espalda o cuello: puede manifestarse mediante rigidez, rechazo a mover la cabeza, dificultad para levantarse o sensibilidad al contacto.",
                "Dilatación-torsión gástrica: un abdomen hinchado, inquietud y arcadas sin vomitar constituyen una emergencia, incluso en perros mayores.",
                "Vómitos repetidos: pueden deberse a enfermedades digestivas, renales, hepáticas, pancreáticas o intoxicaciones.",
                "Diarrea persistente o con sangre: puede producir deshidratación y relacionarse con infecciones, inflamación intestinal o enfermedades internas.",
                "Estreñimiento frecuente: puede aparecer por falta de actividad, deshidratación, dolor o alteraciones del aparato digestivo.",
                "Tos persistente: puede estar relacionada con enfermedades respiratorias, cardíacas o alteraciones de la tráquea y los pulmones.",
                "Dificultad respiratoria: respirar con esfuerzo, presentar jadeo excesivo en reposo o tener encías azuladas requiere atención inmediata.",
                "Cambios en la visión: puede desarrollar cataratas, enfermedades de la retina u otras alteraciones oculares que dificulten su desplazamiento.",
                "Pérdida de audición: puede responder menos a los sonidos o no escuchar cuando lo llaman, aunque también deben descartarse problemas en los oídos.",
                "Problemas dentales: el mal aliento intenso, el dolor al masticar, el sarro y las encías inflamadas pueden dificultar su alimentación.",
                "Bultos o masas nuevas: pueden corresponder a lesiones benignas o tumores. Es necesario que el veterinario los examine y determine si requieren pruebas.",
                "Heridas que no cicatrizan: pueden relacionarse con infecciones, enfermedades metabólicas o alteraciones de la piel.",
                "Infecciones recurrentes: presentar repetidamente problemas urinarios, cutáneos o de oído puede indicar una enfermedad que necesita investigación.",
                "Desorientación: olvidar rutinas conocidas, quedarse mirando fijamente lugares o perderse dentro del hogar puede relacionarse con deterioro cognitivo u otros problemas médicos.",
                "Cambios en el sueño: dormir durante el día y permanecer inquieto por la noche puede relacionarse con dolor, alteraciones cognitivas o enfermedades.",
                "Ansiedad o irritabilidad nuevas: puede reaccionar de forma diferente al contacto o mostrar inquietud debido a dolor, pérdida sensorial o deterioro cognitivo.",
                "Convulsiones: pueden estar relacionadas con alteraciones neurológicas, metabólicas o enfermedades internas y necesitan valoración veterinaria inmediata.",
                "Pérdida de coordinación: puede indicar problemas neurológicos, especialmente si afecta progresivamente las extremidades posteriores.",
                "Cambios en las heces: deposiciones negras, muy pálidas, con sangre o con consistencia anormal persistente requieren revisión.",
                "Debilidad generalizada: puede deberse a anemia, enfermedades cardíacas, problemas metabólicos o procesos crónicos.",
                "Pérdida de resistencia física: cansarse con caminatas muy cortas o no poder realizar actividades habituales puede indicar un problema de salud.",
                "Dolor persistente: aunque no llore, puede manifestarse mediante jadeo, aislamiento, cambios de postura, dificultad para dormir o rechazo al movimiento."
              ]
            }
          ]
        },
 
        "primeros": {
          "titulo": "PRIMEROS AUXILIOS",
          "secciones": [
            {
              "titulo": "CAÍDAS, GOLPES O LESIONES EN LAS PATAS",
              "items": [
                "Mantener la calma y evitar que continúe caminando o realizando movimientos innecesarios.",
                "Observar si puede respirar normalmente, mantenerse consciente y apoyar las patas sin obligarlo a levantarse.",
                "Si presenta dolor intenso, debilidad o dificultad para moverse, mantenerlo lo más quieto posible.",
                "Si se sospecha una lesión de columna, evitar doblar su espalda o cuello y solicitar ayuda para trasladarlo sobre una superficie firme.",
                "Debido a su tamaño y peso, pedir ayuda para moverlo sin realizar esfuerzos que puedan agravar la lesión.",
                "No intentar acomodar huesos, estirar articulaciones ni realizar masajes sobre las zonas doloridas.",
                "No administrar medicamentos humanos para aliviar el dolor.",
                "Acudir urgentemente al veterinario si no puede levantarse, presenta dolor intenso, pierde el conocimiento o ha sufrido una caída importante."
              ]
            },
            {
              "titulo": "HERIDAS Y SANGRADO",
              "items": [
                "Alejarlo de la situación que causó la lesión y evitar que lama la herida.",
                "Colocar una gasa limpia o un paño limpio sobre el área sangrante y mantener una presión constante.",
                "Si la tela se empapa, colocar otra encima sin retirar la primera.",
                "No utilizar alcohol, agua oxigenada concentrada, polvos ni remedios caseros dentro de la herida.",
                "No retirar objetos clavados profundamente.",
                "Si la herida es profunda, fue causada por una mordedura o el sangrado es abundante, acudir urgentemente al veterinario.",
                "Observar si presenta encías pálidas, respiración acelerada o debilidad, ya que pueden indicar una pérdida importante de sangre."
              ]
            },
            {
              "titulo": "ATRAGANTAMIENTO",
              "items": [
                "Comprobar si puede respirar, toser y emitir sonidos.",
                "Si puede toser con fuerza y respirar, mantenerlo tranquilo y buscar ayuda veterinaria.",
                "Solo retirar un objeto si está claramente visible, suelto y puede extraerse sin empujarlo más adentro.",
                "No introducir los dedos a ciegas en la garganta.",
                "Si no puede respirar, presenta encías azuladas o pierde el conocimiento, acudir inmediatamente a urgencias veterinarias y llamar para recibir instrucciones durante el traslado.",
                "No darle comida ni agua mientras exista sospecha de obstrucción."
              ]
            },
            {
              "titulo": "INTOXICACIÓN",
              "items": [
                "Alejarlo de la sustancia que pudo ingerir o tocar.",
                "Identificar el producto y guardar su envase o una fotografía de la etiqueta.",
                "No provocar el vómito ni administrarle leche, aceite, sal, medicamentos o carbón activado sin indicación veterinaria.",
                "Llamar inmediatamente al veterinario, aunque todavía parezca encontrarse bien.",
                "Informar qué sustancia pudo consumir, cuánto aproximadamente y hace cuánto tiempo.",
                "Si presenta convulsiones, dificultad respiratoria o pérdida del conocimiento, trasladarlo a urgencias sin demora."
              ]
            },
            {
              "titulo": "QUEMADURAS",
              "items": [
                "Alejarlo de la fuente de calor.",
                "Enfriar la zona afectada con agua corriente fresca, no helada, durante varios minutos si es posible hacerlo sin retrasar la atención.",
                "No aplicar hielo, mantequilla, pasta dental, aceites ni cremas caseras.",
                "No romper ampollas ni retirar piel dañada.",
                "Cubrir suavemente con una tela limpia y acudir al veterinario.",
                "Las quemaduras extensas, profundas o que afectan la cara y las vías respiratorias son emergencias."
              ]
            },
            {
              "titulo": "PICADURAS Y MORDEDURAS",
              "items": [
                "Llevarlo a un lugar seguro y observar si presenta hinchazón, dolor o enrojecimiento.",
                "Si hay un aguijón visible, retirarlo cuidadosamente sin apretar el saco de veneno.",
                "No administrar antihistamínicos ni otros medicamentos humanos sin orientación veterinaria.",
                "Las mordeduras pueden causar daños internos aunque la herida externa parezca pequeña.",
                "Acudir inmediatamente si presenta hinchazón de la cara, dificultad para respirar, vómitos repentinos, debilidad o colapso."
              ]
            },
            {
              "titulo": "VÓMITOS Y DIARREA",
              "items": [
                "Observar la frecuencia de los episodios y si presenta sangre, dolor abdominal o decaimiento.",
                "Si está alerta, puede tragar y no vomita repetidamente, ofrecer pequeñas cantidades de agua sin obligarlo a beber.",
                "No administrar antibióticos ni medicamentos antidiarreicos por cuenta propia.",
                "No realizar cambios bruscos de alimentación para intentar detener los síntomas.",
                "Si los vómitos se repiten, presenta sangre, no puede retener agua o está muy débil, acudir al veterinario.",
                "Si presenta abdomen hinchado y arcadas sin vomitar, acudir inmediatamente a urgencias por posible torsión gástrica."
              ]
            },
            {
              "titulo": "GOLPE DE CALOR",
              "items": [
                "Llevarlo inmediatamente a un lugar fresco, ventilado y protegido del sol.",
                "Mojar el cuerpo con agua fresca, no helada, evitando retrasar el traslado.",
                "No cubrirlo con toallas gruesas mojadas que puedan retener calor.",
                "No obligarlo a beber si está desorientado, débil o no puede tragar normalmente.",
                "No esperar a que se recupere por completo en casa.",
                "Trasladarlo inmediatamente al veterinario, aunque parezca mejorar, porque pueden aparecer complicaciones internas."
              ]
            },
            {
              "titulo": "DOLOR O PROBLEMAS EN LAS ARTICULACIONES",
              "items": [
                "Evitar que suba escaleras, salte o realice actividades que aumenten el dolor.",
                "Proporcionarle una superficie cómoda y permitirle descansar.",
                "No masajear ni manipular con fuerza las articulaciones afectadas.",
                "No administrar analgésicos humanos ni medicamentos sobrantes de otros tratamientos.",
                "Si no puede levantarse, presenta dolor intenso o pierde repentinamente la movilidad, acudir a urgencias veterinarias."
              ]
            },
            {
              "titulo": "DEBILIDAD O PÉRDIDA DE COORDINACIÓN",
              "items": [
                "Evitar que camine por escaleras o superficies resbaladizas.",
                "Mantenerlo en un lugar seguro donde no pueda caerse ni golpearse.",
                "No obligarlo a realizar movimientos para comprobar su fuerza.",
                "No intentar ejercicios de rehabilitación sin una evaluación profesional.",
                "Si arrastra las patas, pierde el equilibrio repentinamente o no puede mantenerse en pie, acudir inmediatamente al veterinario."
              ]
            },
            {
              "titulo": "DIFICULTAD PARA ORINAR",
              "items": [
                "Observar si intenta orinar repetidamente, si presenta dolor o si aparece sangre en la orina.",
                "No presionar el abdomen ni intentar vaciar la vejiga manualmente.",
                "No administrar medicamentos por cuenta propia.",
                "Si intenta orinar y no produce orina, trasladarlo inmediatamente a urgencias veterinarias.",
                "Si presenta dolor, sangre o cambios persistentes en la micción, solicitar una revisión sin demora."
              ]
            },
            {
              "titulo": "DESORIENTACIÓN O CAMBIOS REPENTINOS DE COMPORTAMIENTO",
              "items": [
                "Mantenerlo en un lugar tranquilo, seguro y sin obstáculos.",
                "Evitar gritarle o forzarlo a realizar actividades.",
                "Observar si reconoce a las personas, responde a sonidos y puede caminar normalmente.",
                "No administrar sedantes ni medicamentos humanos.",
                "Si la desorientación aparece repentinamente, se acompaña de convulsiones o pierde el equilibrio, acudir inmediatamente al veterinario."
              ]
            }
          ]
        },
 
        "cuidados": {
          "titulo": "CUIDADOS",
          "secciones": [
            {
              "titulo": "CÓMO MANTENERLO BIEN CUIDADO",
              "items": [
                "Controles veterinarios frecuentes: realizar revisiones al menos cada seis meses, o con mayor frecuencia si presenta enfermedades crónicas. El veterinario debe evaluar su peso, articulaciones, corazón, dientes, ojos, oídos y estado general.",
                "Exámenes preventivos: según su edad y condición, pueden recomendarse análisis de sangre, análisis de orina, evaluación cardíaca y otros estudios para detectar enfermedades antes de que presenten síntomas evidentes.",
                "Vacunación y desparasitación: mantener un calendario actualizado según su historial, estado inmunitario, región y exposición a otros animales.",
                "Alimentación para perros senior: ofrecer alimento completo y equilibrado adaptado a su edad, condición corporal y posibles enfermedades.",
                "Control del peso: pesarlo regularmente y vigilar la pérdida de musculatura o la acumulación excesiva de grasa.",
                "Ejercicio moderado y constante: realizar caminatas tranquilas y actividades adaptadas a su movilidad. Es mejor mantener una rutina regular que exigirle esfuerzos intensos.",
                "Paseos cortos y frecuentes: si se cansa fácilmente, dividir la actividad diaria en varios paseos breves en lugar de realizar caminatas demasiado largas.",
                "Evitar saltos y esfuerzos excesivos: reducir las actividades que puedan sobrecargar sus caderas, codos, rodillas y columna.",
                "Superficies antideslizantes: colocar alfombras o superficies que faciliten el desplazamiento dentro de casa, especialmente si tiene artrosis o debilidad en las patas.",
                "Acceso fácil a sus espacios: evitar que tenga que subir y bajar escaleras constantemente. Colocar su cama, agua y comida en lugares accesibles.",
                "Cama cómoda y acolchada: proporcionarle una cama que amortigüe la presión sobre sus articulaciones y evite que permanezca directamente sobre suelos duros.",
                "Cepillado frecuente: cepillarlo varias veces por semana para retirar el pelo suelto y observar si presenta bultos, heridas o irritaciones.",
                "Baños cuando sean necesarios: utilizar champú para perros y secar bien el pelaje. Evitar baños excesivos que puedan resecar la piel.",
                "Cuidado dental: cepillar sus dientes con pasta dental para perros y realizar revisiones para detectar sarro, infecciones y piezas dentales dañadas.",
                "Cuidado de las uñas: revisar su longitud regularmente. Los perros mayores pueden desgastarlas menos porque realizan menos actividad física.",
                "Revisión de las orejas: comprobar si hay mal olor, enrojecimiento o secreciones. No introducir bastoncillos ni objetos profundamente en el oído.",
                "Cuidado de los ojos: observar si presenta secreciones, opacidad, enrojecimiento o dificultad para orientarse.",
                "Protección contra el frío y la humedad: ofrecer una cama seca y un refugio protegido del viento, la lluvia y el suelo húmedo. Evitar que permanezca durante mucho tiempo sobre superficies frías.",
                "Protección frente al calor: proporcionar sombra, ventilación y agua fresca. Evitar los paseos durante las horas más calurosas y nunca dejarlo dentro de un vehículo cerrado.",
                "Estimulación mental: utilizar juegos de olfato, búsqueda de premios y actividades sencillas que pueda realizar sin exigencias físicas.",
                "Mantener rutinas estables: conservar horarios similares para comer, pasear, descansar y realizar sus necesidades. Los cambios bruscos pueden generar confusión o ansiedad.",
                "Compañía familiar: ofrecerle atención, contacto y compañía diaria. Los perros mayores pueden necesitar más tranquilidad y cercanía.",
                "Identificación: utilizar una placa con un número de contacto y, si es posible, un microchip registrado.",
                "Prevención de caídas: evitar pisos mojados, escaleras sin protección y obstáculos que dificulten su desplazamiento.",
                "Ayuda para levantarse: si tiene dificultades de movilidad, consultar con el veterinario sobre el uso de arneses de soporte o ayudas adecuadas.",
                "Control de enfermedades crónicas: si tiene problemas renales, cardíacos, articulares, hormonales o digestivos, cumplir los tratamientos y revisiones establecidos.",
                "Administración responsable de medicamentos: respetar las dosis, horarios y duración de los tratamientos indicados por el veterinario.",
                "Vigilancia de la sed y la orina: observar cuánto bebe y con qué frecuencia orina. Los cambios importantes deben comunicarse al veterinario.",
                "Revisión de la musculatura: observar si pierde volumen en las patas traseras, la espalda o los hombros, ya que puede necesitar una evaluación nutricional, ortopédica o neurológica.",
                "Descanso adecuado: permitirle dormir durante más tiempo si lo necesita y no interrumpir constantemente sus periodos de descanso.",
                "Adaptación de los juegos: elegir actividades tranquilas y seguras, evitando juegos bruscos, persecuciones prolongadas y saltos.",
                "Atención a los cambios de conducta: observar si se desorienta, duerme de manera diferente, se aísla o deja de reconocer rutinas.",
                "Protección durante los paseos: mantenerlo con correa y evitar lugares con tráfico, terrenos irregulares o superficies que puedan provocar caídas.",
                "Aseo después de salir: revisar sus patas y pelaje para retirar suciedad, humedad, espinas o parásitos.",
                "Calidad de vida: procurar que pueda comer, beber, descansar, desplazarse y relacionarse con su familia con la mayor comodidad posible."
              ]
            },
            {
              "titulo": "CÓMO SABER SI NO TIENE UN BUEN CUIDADO",
              "items": [
                "Por su aspecto físico:",
                "Tiene el pelaje sucio durante largos periodos, mal olor persistente o heridas sin atender.",
                "Presenta uñas demasiado largas que le dificultan caminar.",
                "Tiene secreciones en los ojos o los oídos, encías inflamadas o problemas dentales sin revisar.",
                "Está excesivamente delgado o tiene demasiada grasa corporal.",
                "Presenta pérdida marcada de musculatura, especialmente en las patas traseras.",
                "Se rasca continuamente, pierde pelo en zonas extensas o presenta parásitos visibles.",
                "Tiene bultos, inflamaciones o heridas que no reciben atención.",
                "Presenta dificultad para levantarse o caminar sin recibir ayuda o evaluación.",
                "Tiene zonas de la piel irritadas por permanecer demasiado tiempo acostado sobre superficies inadecuadas.",
                "Por su alimentación:",
                "No tiene acceso constante a agua limpia.",
                "Recibe huesos cocidos, alimentos tóxicos o sobras muy grasosas.",
                "Come cantidades excesivas y aumenta de peso.",
                "Recibe muy poca comida y pierde peso o musculatura.",
                "No recibe un alimento apropiado para su edad y condición de salud.",
                "Se le administran suplementos o medicamentos sin orientación veterinaria.",
                "No se controlan los cambios de apetito, sed y peso.",
                "Tiene dificultades para masticar y no se adapta la textura de sus alimentos cuando es necesario.",
                "Por su comportamiento:",
                "Se muestra desorientado frecuentemente y no recibe evaluación.",
                "Tiene miedo constante, ansiedad o irritabilidad que no se atienden.",
                "Se aísla de su familia y permanece sin interacción durante largos periodos.",
                "No puede descansar tranquilamente porque lo molestan constantemente.",
                "Presenta cambios importantes en sus hábitos de sueño sin investigar la causa.",
                "Deja de interesarse por sus actividades habituales y no se evalúa si existe dolor o enfermedad.",
                "Se le exige realizar actividades físicas que ya no puede soportar.",
                "No recibe compañía, estimulación mental ni atención diaria.",
                "Por su salud y seguridad:",
                "No recibe controles veterinarios periódicos.",
                "No tiene vacunas ni prevención de parásitos actualizadas.",
                "Pasa largos periodos expuesto al sol, frío o lluvia sin refugio.",
                "Permanece sobre suelos resbaladizos que dificultan su movilidad.",
                "Tiene que subir y bajar escaleras constantemente pese a presentar problemas articulares.",
                "No se atienden sus dificultades para caminar, levantarse o respirar.",
                "No recibe tratamiento para enfermedades crónicas diagnosticadas.",
                "Se le administran medicamentos humanos sin indicación veterinaria.",
                "Permanece durante muchas horas sin compañía ni supervisión.",
                "No dispone de una cama cómoda y accesible.",
                "No se atienden los cambios repentinos de comportamiento, apetito o movilidad.",
                "Se ignoran las señales de dolor porque se considera que son normales por su edad."
              ]
            }
          ]
        },
 
        "comportamiento": {
          "titulo": "COMPORTAMIENTO",
          "secciones": [
            {
              "titulo": "ADIESTRAMIENTO Y EDUCACIÓN DURANTE LA ETAPA SENIOR",
              "items": [
                "Mantener las órdenes conocidas: continuar practicando “ven”, “siéntate”, “quieto” y otras órdenes que ya conoce, respetando su capacidad física.",
                "Utilizar sesiones cortas: realizar ejercicios breves para evitar el cansancio y no exigirle periodos prolongados de concentración.",
                "Reforzar su nombre: llamarlo con voz tranquila y premiarlo cuando responda o dirija su atención hacia la persona.",
                "Practicar la llamada en lugares seguros: utilizar espacios tranquilos y accesibles para evitar que corra o realice movimientos bruscos.",
                "Adaptar las órdenes a su movilidad: si tiene artrosis o dificultades para sentarse, utilizar indicaciones que pueda cumplir sin experimentar dolor.",
                "Enseñarle a esperar: reforzar la calma antes de recibir comida, salir a pasear o comenzar una actividad.",
                "Mantener una socialización tranquila: permitirle relacionarse con personas y animales conocidos, evitando encuentros demasiado intensos o situaciones que puedan generarle estrés.",
                "Respetar sus limitaciones sensoriales: si escucha o ve menos, acercarse suavemente para evitar asustarlo y utilizar señales visuales o gestos conocidos.",
                "Evitar los sobresaltos: no despertarlo bruscamente ni tocarlo sin avisar, especialmente si tiene problemas de audición o visión.",
                "Estimular su inteligencia: realizar juegos de olfato, búsqueda de premios y actividades sencillas que pueda completar sin demasiado esfuerzo.",
                "Enseñarle a descansar: premiarlo cuando permanezca tranquilo en su cama y permitirle dormir sin interrupciones.",
                "Mantener sus rutinas: conservar horarios similares para paseos, alimentación, descanso y actividades diarias.",
                "Reforzar el comportamiento tranquilo: premiar cuando se relaje ante visitas, sonidos o situaciones cotidianas.",
                "Evitar la protección excesiva: no fomentar amenazas ni reacciones defensivas hacia personas o animales.",
                "Acostumbrarlo a las revisiones: practicar suavemente el contacto con sus patas, orejas y boca, utilizando premios para facilitar los controles.",
                "No obligarlo a jugar: permitirle participar voluntariamente en actividades que le resulten agradables y cómodas.",
                "Evitar el castigo físico: los golpes, gritos e intimidación pueden provocar miedo, confusión y reacciones defensivas.",
                "Respetar sus periodos de descanso: evitar que los niños u otros animales lo molesten mientras duerme o come.",
                "Adaptar los paseos: realizar caminatas moderadas y permitirle detenerse cuando necesite descansar.",
                "Mantener el vínculo familiar: continuar ofreciéndole atención, cariño y compañía, sin exigirle el mismo nivel de actividad que tenía cuando era joven."
              ]
            },
            {
              "titulo": "CÓMO MEJORAR EL COMPORTAMIENTO DE TU MASCOTA SI NO FUE ADIESTRADO",
              "items": [
                "Identificar la causa del problema: observar cuándo aparece la conducta y qué situaciones la desencadenan. En perros mayores, los cambios repentinos pueden estar relacionados con dolor, pérdida de visión, problemas auditivos o enfermedades cognitivas.",
                "Volver a las órdenes básicas: practicar su nombre, “ven”, “quieto” y otras indicaciones sencillas en un ambiente tranquilo.",
                "Utilizar premios apropiados: recompensar inmediatamente las conductas correctas con pequeñas porciones de alimentos adecuados o elogios.",
                "Adaptar el aprendizaje a su capacidad física: evitar ejercicios que impliquen saltos, carreras, giros bruscos o posiciones dolorosas.",
                "Enseñarle a permanecer tranquilo: premiar cuando se relaje en su cama y pueda descansar sin mostrar inquietud.",
                "Reducir los ladridos excesivos: identificar si ladra por miedo, dolor, desorientación, pérdida de audición o necesidad de atención. Buscar la causa antes de intentar corregir la conducta.",
                "Manejar la ansiedad: mantener horarios estables, ofrecer compañía y preparar un espacio tranquilo donde pueda descansar.",
                "Evitar los cambios bruscos de entorno: si se desorienta fácilmente, mantener sus muebles, cama, recipientes de agua y comida en lugares conocidos.",
                "Ayudarlo si pierde la audición: utilizar señales visuales sencillas y acercarse dentro de su campo de visión antes de darle una indicación.",
                "Ayudarlo si pierde la visión: evitar mover los muebles constantemente y mantener despejados los caminos hacia su cama, agua y comida.",
                "Trabajar la tolerancia a la soledad: si presenta ansiedad cuando queda solo, realizar ausencias graduales y consultar con un veterinario si muestra angustia intensa.",
                "Evitar castigar los accidentes dentro del hogar: si comienza a hacer sus necesidades en lugares inadecuados, investigar si tiene problemas urinarios, digestivos, de movilidad o cognitivos.",
                "Facilitar sus necesidades: establecer horarios de salida y ofrecerle un espacio accesible donde pueda hacer sus necesidades sin tener que recorrer grandes distancias.",
                "No castigar los gruñidos: pueden ser señales de dolor, miedo o incomodidad. Darle espacio y consultar si aparecen con frecuencia.",
                "Manejar la irritabilidad: evitar manipularlo cuando está descansando o siente dolor. Si reacciona de forma diferente, buscar primero una posible causa médica.",
                "Ofrecer estimulación mental moderada: utilizar juegos de olfato, juguetes apropiados y actividades sencillas que no provoquen cansancio excesivo.",
                "Evitar obligarlo a socializar: respetar sus tiempos y permitirle alejarse cuando una persona, animal o situación le genere incomodidad.",
                "Buscar ayuda profesional cuando sea necesario: si presenta agresividad nueva, desorientación frecuente, ansiedad intensa o cambios importantes de conducta, acudir a un veterinario y, cuando corresponda, a un profesional de comportamiento canino.",
                "Tener paciencia: el aprendizaje puede ser más lento en esta etapa. La tranquilidad, la constancia y la adaptación de las actividades son fundamentales."
              ]
            }
          ]
        },
 
        "vacunacion": {
          "titulo": "VACUNACIÓN",
          "secciones": [
            {
              "titulo": "TODAS LAS VACUNAS CON LAS QUE DEBERÍA CONTAR LA MASCOTA DURANTE SU VIDA",
              "items": [
                "Vacuna múltiple esencial: protege contra enfermedades importantes como moquillo, parvovirus y adenovirus canino, relacionado con la hepatitis infecciosa. En esta etapa debe continuar recibiendo los refuerzos correspondientes según su historial y el protocolo veterinario.",
                "Vacuna contra la rabia: es esencial por la gravedad de la enfermedad y las normas sanitarias. En Bolivia debe mantenerse de acuerdo con la normativa sanitaria vigente y las campañas oficiales de vacunación antirrábica.",
                "Refuerzos de la vacuna múltiple: después de completar la serie de cachorro y los refuerzos correspondientes, algunas vacunas esenciales pueden administrarse con intervalos de hasta tres años. La frecuencia depende de los componentes utilizados y de las recomendaciones veterinarias.",
                "Vacuna contra la leptospirosis: puede recomendarse según la región, la presencia de roedores, el acceso a agua contaminada y otros riesgos ambientales. Generalmente necesita refuerzos periódicos para mantener la protección.",
                "Vacuna contra la tos de las perreras: las vacunas contra Bordetella y otros agentes respiratorios pueden considerarse si convive con muchos perros, asiste a residencias o participa en actividades grupales.",
                "Vacuna contra la influenza canina: puede considerarse si está disponible y existe un riesgo de exposición que justifique su aplicación.",
                "Otras vacunas específicas: el veterinario decidirá si alguna es apropiada para su estilo de vida, región y estado de salud. No todas las vacunas adicionales son necesarias para todos los perros.",
                "Evaluación antes de vacunar: comprobar su estado general, enfermedades crónicas, tratamientos actuales y antecedentes de reacciones a vacunas. La edad avanzada por sí sola no significa que deba dejar de recibir vacunas.",
                "Registro de vacunación: conservar la cartilla con las fechas, los nombres de las vacunas, los datos del profesional y las fechas sugeridas para los siguientes refuerzos.",
                "Si se desconoce su historial: no asumir que está vacunado. El veterinario establecerá un calendario de recuperación según su edad, estado inmunitario y dosis documentadas.",
                "Vacunación durante enfermedades crónicas: si presenta una enfermedad renal, cardíaca, hepática o inmunitaria, el veterinario evaluará el momento y las vacunas apropiadas.",
                "Durante toda su vida: mantener las vacunas esenciales indicadas y revisar periódicamente si necesita protección adicional según su exposición y estado de salud.",
                "La desparasitación interna y la prevención de pulgas y garrapatas también son importantes, pero no son vacunas. Deben programarse por separado con orientación veterinaria, teniendo en cuenta su edad, estado de salud y los parásitos presentes en la región donde vive."
              ]
            }
          ]
        },
 
        "veterinario": {
          "titulo": "CUÁNDO IR AL VETERINARIO",
          "secciones": [
            {
              "titulo": "EN QUÉ SITUACIONES DE EMERGENCIA DEBES ACUDIR A UN VETERINARIO",
              "items": [
                "Dificultad para respirar: respiración trabajosa, encías azuladas o incapacidad para respirar normalmente pueden indicar una emergencia grave.",
                "Abdomen hinchado con arcadas sin vomitar: el Pastor Alemán es una raza grande y de pecho profundo, por lo que estos signos pueden indicar dilatación-torsión gástrica. No esperar a que se le pase.",
                "Desmayo o pérdida del conocimiento: puede deberse a problemas circulatorios, cardíacos, neurológicos u otras causas graves.",
                "Convulsiones: especialmente si es la primera vez, duran varios minutos, se repiten o no recupera su estado normal.",
                "Sangrado abundante: si no se detiene con presión directa o la herida es profunda, necesita atención urgente.",
                "Accidente de tránsito o caída importante: puede tener lesiones internas aunque aparentemente camine bien.",
                "Ingestión de venenos o medicamentos: no esperar a que aparezcan síntomas. Llevar el envase o una fotografía del producto.",
                "Vómitos repetidos con debilidad: puede sufrir deshidratación o presentar una enfermedad importante.",
                "Diarrea con sangre: especialmente si también presenta vómitos, debilidad o dolor abdominal.",
                "Encías muy pálidas o amarillas: pueden ser señales de anemia, problemas circulatorios o enfermedades graves.",
                "Dolor intenso o incapacidad para caminar: puede indicar una lesión, fractura o problema ortopédico.",
                "Debilidad repentina de las patas traseras: necesita evaluación urgente, especialmente si no puede mantenerse en pie, pierde coordinación o presenta dolor.",
                "Dificultad para orinar: intentar orinar repetidamente sin producir orina puede indicar una obstrucción que requiere atención inmediata.",
                "Golpe de calor: jadeo intenso, desorientación, vómitos, debilidad o colapso después de estar en un ambiente caliente requieren atención inmediata.",
                "Reacción alérgica grave: hinchazón repentina de la cara, dificultad respiratoria, vómitos repetidos o colapso después de una picadura, alimento o medicamento.",
                "Herida profunda o mordedura: puede existir daño interno o riesgo de infección aunque la lesión externa sea pequeña.",
                "Lesión ocular: dolor intenso, ojo cerrado, sangrado o cambios repentinos en la visión requieren atención rápida.",
                "Incapacidad para retener agua: si vomita cada vez que bebe o muestra signos de deshidratación, necesita valoración urgente.",
                "Cambios bruscos de comportamiento: desorientación repentina, falta de respuesta, debilidad marcada o agresividad repentina pueden estar relacionados con dolor o enfermedad.",
                "Pérdida repentina del equilibrio: si se cae, inclina la cabeza, camina en círculos o no puede mantenerse de pie, necesita evaluación inmediata.",
                "Dolor abdominal intenso: si se muestra inquieto, adopta posturas extrañas o no permite que le toquen el abdomen, requiere atención veterinaria urgente.",
                "Dificultad repentina para caminar: si deja de apoyar las patas, arrastra las extremidades o pierde la capacidad de levantarse, no debe esperarse a que mejore por sí solo.",
                "Sangre en la orina o imposibilidad de orinar: pueden indicar problemas urinarios graves que requieren atención inmediata."
              ]
            },
            {
              "titulo": "CONSULTAS VETERINARIAS QUE NO DEBES POSPONER",
              "items": [
                "Si pierde peso o musculatura sin una explicación clara.",
                "Si come menos de lo habitual o presenta dificultades para masticar.",
                "Si bebe mucha más agua o comienza a orinar con mayor frecuencia.",
                "Si cojea repetidamente, se levanta con dificultad o muestra rigidez después de descansar.",
                "Si presenta debilidad progresiva en las patas traseras, aunque todavía pueda caminar.",
                "Si pierde el equilibrio o muestra cambios en su coordinación.",
                "Si tiene mal aliento intenso, sarro, encías inflamadas o dolor dental.",
                "Si pierde pelo en exceso, se rasca continuamente o presenta infecciones recurrentes de la piel.",
                "Si tiene tos, secreción nasal o problemas digestivos que persisten.",
                "Si presenta estreñimiento frecuente o cambios importantes en sus deposiciones.",
                "Si aparecen bultos, masas o inflamaciones debajo de la piel.",
                "Si duerme mucho más de lo habitual o permanece inquieto durante la noche.",
                "Si se desorienta en lugares conocidos o parece olvidar rutinas familiares.",
                "Si presenta cambios de personalidad, irritabilidad o miedo que antes no tenía.",
                "Si muestra dificultades para escuchar o reconocer sonidos habituales.",
                "Si presenta cambios en la visión, choca con objetos o tiene dificultad para orientarse.",
                "Si necesita una revisión de su peso, alimentación, vacunas o prevención de parásitos.",
                "Si presenta enfermedades crónicas que necesitan controles y ajustes de tratamiento.",
                "Si pierde resistencia física y se cansa con caminatas cortas.",
                "Si tiene heridas que tardan en cicatrizar o infecciones que aparecen repetidamente.",
                "Si presenta cambios persistentes en el apetito, sed, sueño o hábitos de eliminación.",
                "Si muestra signos de dolor al acostarse, levantarse, subir pequeños desniveles o caminar.",
                "Si presenta pérdida progresiva de masa muscular, especialmente en las extremidades posteriores.",
                "Si deja de disfrutar actividades que antes le gustaban y no se identifica la causa.",
                "Si necesita una evaluación de su calidad de vida para adaptar sus cuidados a sus necesidades actuales."
              ]
            }
          ]
        }
      }
    }
    }
  },
  "chihuahua": {
    "nombre": "Chihuahua",
    "etapas": {
      "cachorro": {
        "tituloOriginal": "CHIHUAHUA CACHORRO (DE 0 A 12 MESES)",
        "temas": {
          "alimentacion": {
            "titulo": "ALIMENTACIÓN",
            "secciones": [
              
              {
                "titulo": "ALIMENTACIÓN SALUDABLE",
                "items": [
                  "Alimento para cachorros de razas pequeñas: debe ser completo y equilibrado para su crecimiento.",
                  "Comidas frecuentes: normalmente necesitan entre 3 y 4 comidas al día; los más pequeños pueden requerir un horario más frecuente indicado por el veterinario.",
                  "Agua limpia: debe tener agua fresca disponible permanentemente.",
                  "Proteínas de calidad: un alimento completo para cachorros debe proporcionar las proteínas necesarias para desarrollar músculos y tejidos.",
                  "Grasas saludables: ayudan a aportar energía y ácidos grasos esenciales para el desarrollo.",
                  "Calcio y fósforo equilibrados: son importantes para sus huesos y dientes; no agregues suplementos sin indicación veterinaria.",
                  "Transición gradual de alimento: si cambias de marca o fórmula, hazlo progresivamente durante varios días para reducir molestias digestivas.",
                  "Premios pequeños: utiliza premios apropiados para cachorros y dáselos en cantidades moderadas.",
                  "Porciones controladas: sigue la guía del alimento y ajusta las cantidades con ayuda del veterinario según su crecimiento.",
                  "Alimentación segura: si todavía no puede masticar bien, elige una textura apropiada para su edad y tamaño."
                ]
              },
              {
                "titulo": "ALIMENTACIÓN NO SALUDABLE",
                "items": [
                  "Chocolate: es tóxico para los perros.",
                  "Uvas y pasas: pueden causar daño renal.",
                  "Cebolla, ajo y cebollín: pueden dañar los glóbulos rojos.",
                  "Xilitol: edulcorante presente en algunos chicles, caramelos y productos sin azúcar; puede provocar una emergencia.",
                  "Huesos cocidos: pueden astillarse y causar lesiones u obstrucciones.",
                  "Comida muy salada, frita o grasosa: puede provocar problemas digestivos y no es apropiada como alimentación habitual.",
                  "Leche de vaca: puede causar diarrea en algunos perros.",
                  "Restos de comida condimentada: pueden contener ingredientes tóxicos o demasiada grasa.",
                  "Suplementos por cuenta propia: el exceso de vitaminas y minerales puede perjudicar su desarrollo.",
                  "Pierde peso, aumenta demasiado de peso o no crece como se espera.",
                  "Tiene diarrea frecuente o recibe demasiados premios y restos de comida.",
                  "No dispone de agua limpia.",
                  "Seguridad",
                  "Salta desde muebles altos sin protección.",
                  "Se queda expuesto al frío, al calor intenso o a la lluvia.",
                  "Puede acceder a productos químicos, medicamentos o alimentos tóxicos.",
                  "Bienestar emocional",
                  "Pasa casi todo el día aislado.",
                  "Tiene miedo constante porque lo fuerzan a interactuar.",
                  "No dispone de juguetes apropiados, descanso ni interacción positiva."
                ]
              }
            ]
          },
          "salud": {
            "titulo": "SALUD",
            "secciones": [
              {
                "titulo": "Información",
                "items": [
                  "Los Chihuahua son perros pequeños y delicados. Durante el crecimiento necesitan controles veterinarios, protección contra enfermedades y cuidado especial para evitar golpes y caídas."
                ]
              },
              {
                "titulo": "SEÑALES DE BUENA SALUD",
                "items": [
                  "Tiene energía y responde normalmente a las personas.",
                  "Come y bebe de acuerdo con su edad y rutina.",
                  "Sus ojos están limpios, sin secreciones abundantes.",
                  "Su nariz y respiración no presentan problemas persistentes.",
                  "Sus heces son formadas y no hay vómitos repetidos.",
                  "Camina de manera estable, sin cojear.",
                  "Su piel está limpia y no presenta picazón intensa.",
                  "Gana peso y crece de manera progresiva.",
                  "Tiene las vacunas y desparasitaciones indicadas por el veterinario.",
                  "Sus dientes, encías y mordida reciben revisiones periódicas."
                ]
              },
              {
                "titulo": "SEÑALES DE MALA SALUD",
                "items": [
                  "Debilidad repentina, temblores, desorientación o somnolencia inusual.",
                  "Rechazo de la comida, especialmente si es muy pequeño.",
                  "Vómitos repetidos o diarrea persistente.",
                  "Dificultad para respirar o encías pálidas, azuladas o grises.",
                  "Dolor, cojera o incapacidad para apoyar una pata.",
                  "Abdomen hinchado o doloroso.",
                  "Picazón intensa, heridas o pérdida anormal de pelo.",
                  "Tos persistente o secreción abundante por ojos y nariz.",
                  "Convulsiones, desmayos o falta de respuesta.",
                  "Problemas para orinar o presencia de sangre en la orina.",
                  "Importante: si el cachorro presenta temblores acompañados de debilidad, desorientación o falta de respuesta, podría tener una bajada de azúcar u otro problema grave. Necesita atención veterinaria urgente."
                ]
              }
            ]
          },
          "primeros": {
            "titulo": "PRIMEROS AUXILIOS",
            "secciones": [
              {
                "titulo": "Información",
                "items": [
                  "Los primeros auxilios sirven para protegerlo mientras consigues atención veterinaria; no sustituyen el tratamiento profesional."
                ]
              },
              {
                "titulo": "QUÉ HACER CUANDO LE OCURRE UN ACCIDENTE",
                "items": [
                  "CAIDAS O GOLPESs",
                  "Mantenlo quieto y evita que salte o camine innecesariamente.",
                  "Muévelo con cuidado, sosteniendo su cuerpo y manteniendo la espalda lo más estable posible.",
                  "No presiones el abdomen ni intentes acomodar huesos.",
                  "Si pierde el conocimiento, presenta dolor intenso, dificultad respiratoria o no puede caminar, acude inmediatamente al veterinario.",
                  "HERIDAS Y SANGRADO",
                  "Si sangra, coloca una gasa o tela limpia y ejerce presión suave y constante.",
                  "Si la tela se empapa, coloca otra encima sin retirar la primera.",
                  "No uses alcohol ni agua oxigenada dentro de la herida.",
                  "Si el sangrado es abundante, la herida es profunda o fue causada por una mordedura, busca atención veterinaria urgente.",
                  "ATRAGANTAMIENO",
                  "Si tose y todavía puede respirar, deja que intente expulsar el objeto y busca asistencia veterinaria.",
                  "No introduzcas los dedos a ciegas en su garganta.",
                  "Si no puede respirar, se desploma o sus encías cambian de color, es una emergencia inmediata. Llama a una clínica veterinaria para recibir instrucciones mientras lo trasladas.",
                  
                ]
              },
              {
                "titulo": "SQUÉ HACER CUANDO LE OCURRE UN ACCIDENTE",
                "items": [
              "ENVENENAMIENTO",
                  "Aléjalo de la sustancia y guarda el envase o una fotografía de la etiqueta.",
                  "Contacta inmediatamente a un veterinario, aunque todavía parezca estar bien.",
                  "No provoques el vómito ni le des leche, aceite, sal o remedios caseros.",
                  "QUEMADURAS",
                  "Si es seguro hacerlo, enfría la zona con agua corriente fresca durante unos 20 minutos.",
                  "No uses hielo, mantequilla, pasta dental ni cremas caseras.",
                  "No desprendas piel ni ampollas.",
                  "Busca atención veterinaria, especialmente si la quemadura es extensa o está en la cara, las patas o la boca.",
                  "PICADURAS O MORDEDURAS",
                  "Mantén al cachorro tranquilo y observa si aparece hinchazón.",
                  "Si presenta dificultad para respirar, hinchazón de la cara, debilidad o colapso, acude a urgencias.",
                  "No le administres antihistamínicos ni otros medicamentos sin indicación veterinaria.",
                  "VÓMITOS O DIARREA",
                  "Vigila si puede beber, su energía y la frecuencia de los episodios.",
                  "No lo obligues a comer ni le des medicamentos humanos.",
                  "En un cachorro Chihuahua, los vómitos, la diarrea o el rechazo de comida pueden volverse graves rápidamente. Consulta pronto al veterinario; si está débil, tiembla o no puede retener agua, acude a urgencias."
                ]
              }
            ]
          },
          "cuidados": {
            "titulo": "CUIDADOS",
            "secciones": [
              {
                "titulo": "CÓMO MANTENERLO BIEN CUIDADO",
                "items": [
                  "Temperatura: protégelo del frío y de las corrientes de aire. Puede necesitar una prenda cómoda si hace frío, siempre que no le impida moverse o respirar.",
                  "Descanso: prepara una cama suave, seca y protegida.",
                  "Seguridad en casa: coloca barreras en escaleras y evita que salte de sofás o camas.",
                  "Manipulación cuidadosa: sostén su pecho y sus patas traseras al levantarlo; nunca lo alces solo de las patas delanteras.",
                  "Cepillado: los Chihuahua de pelo corto necesitan cepillados periódicos; los de pelo largo requieren más frecuencia para evitar nudos.",
                  "Baño: utiliza champú para perros y agua tibia. Sécalo bien para evitar que pase frío.",
                  "Dientes: acostúmbralo desde pequeño al cepillado dental con pasta formulada para perros.",
                  "Uñas: revísalas regularmente y córtalas con cuidado, sin llegar a la parte viva.",
                  "Orejas y ojos: revisa que estén limpios. No introduzcas objetos en el canal auditivo ni uses productos sin indicación."
                  
                ]
              },
              {
                "titulo": "CÓMO SABER SI NO TIENE UN BUEN CUIDADO",
                "items": [
                  "Higiene",
                  "Tiene el pelo enredado, sucio o con mal olor persistente.",
                  "Sus uñas están demasiado largas.",
                  "Presenta sarro, mal aliento intenso o encías inflamadas.",
                  "Sus orejas tienen secreciones, mal olor o irritación."
                ]
              },
              {
                "titulo": "CÓMO MANTENERLO BIEN CUIDADO",
                "items": [
                  "Actividad física: ofrece juegos cortos y paseos apropiados para su edad, evitando saltos desde alturas y ejercicio excesivo.",
                  "Socialización: preséntale personas, sonidos y ambientes nuevos de manera gradual y positiva.",
                  "Prevención: sigue el calendario veterinario de vacunas, desparasitación y protección contra parásitos.",
                  "Clima de Bolivia: en zonas frías, protégelo de las bajas temperaturas; en zonas cálidas, ofrece sombra, agua y un espacio ventilado.",
                  "Identificación: utiliza collar ligero o arnés seguro y mantenlo identificado para reducir el riesgo de pérdida."
                ]
              }
            ]
          },
          "comportamiento": {
            "titulo": "COMPORTAMIENTO",
            "secciones": [
              {
                "titulo": "ADIESTRAMIENTO DESDE CACHORRO",
                "items": [
                  "Aprender su nombre: dilo con voz amable y prémialo cuando te mire.",
                  "Hacer sus necesidades: llévalo al lugar elegido al despertar, después de comer y después de jugar. Premia los aciertos.",
                  "Aprender a venir: llámalo desde una distancia corta y recompensa cuando se acerque.",
                  "Acostumbrarse al arnés: introdúcelo poco a poco, asociándolo con premios y experiencias agradables.",
                  "Socialización segura: permite que conozca personas, sonidos y perros tranquilos y saludables. Consulta al veterinario sobre los lugares seguros antes de completar sus vacunas.",
                  "Manejo suave: acostúmbralo gradualmente a que le revisen las patas, las orejas y la boca.",
                  "Evitar mordisqueos: redirige sus mordiscos hacia juguetes adecuados y detén el juego brevemente si se vuelve demasiado brusco.",
                  "Enseñar a estar solo: practica separaciones cortas y graduales, sin dejarlo angustiado durante largos períodos.",
                  "Practicar órdenes sencillas: enseña “siéntate”, “ven” y “quieto” en sesiones breves.",
                  "Recompensar la calma: premia cuando descansa tranquilamente o saluda sin saltar."
                ]
              },
              {
                "titulo": "CÓMO MEJORAR SU COMPORTAMIENTO SI NO FUE ADIESTRADO",
                "items": [
                  "Establece una rutina constante para comer, jugar, pasear y dormir.",
                  "Recompensa el comportamiento que deseas repetir.",
                  "Si ladra para llamar la atención, identifica primero si tiene miedo, dolor, hambre o necesita salir.",
                  "Si gruñe cuando lo levantan, no lo castigues: podría sentirse inseguro o tener dolor.",
                  "Enséñale a aceptar el contacto de forma gradual, respetando sus señales.",
                  "Evita los gritos, golpes, sacudidas y collares que causen dolor.",
                  "Si muestra miedo intenso, agresividad o ansiedad persistente, consulta con un veterinario y un profesional de conducta que utilice métodos respetuosos."
                ]
              }
            ]
          },
          "vacunacion": {
            "titulo": "VACUNACIÓN",
            "secciones": [
              {
                "titulo": "VACUNAS QUE DEBE RECIBIR DURANTE SU VIDA",
                "items": [
                  "El calendario exacto depende de su edad, historial, estado de salud, vacunas previas y riesgo de exposición. El veterinario debe ajustarlo a las recomendaciones vigentes en Bolivia.",
                  "Moquillo canino: vacuna esencial para prevenir una enfermedad grave.",
                  "Parvovirus canino: especialmente importante en cachorros, porque puede causar una enfermedad intestinal severa.",
                  "Adenovirus canino o hepatitis infecciosa: suele estar incluido en las vacunas combinadas esenciales.",
                  "Rabia: debe administrarse de acuerdo con la normativa y el calendario sanitario vigente en Bolivia.",
                  "Leptospirosis: puede recomendarse según la exposición, el entorno y el criterio veterinario.",
                  "Bordetella y otras vacunas respiratorias: pueden considerarse si asiste a guarderías, peluquerías, residencias o lugares con muchos perros.",
                  "Otras vacunas: el veterinario determinará si alguna es adecuada para su región y estilo de vida.",
                  "Esquema orientativo para cachorros",
                  "La serie de vacunas esenciales suele comenzar alrededor de las 6–8 semanas de edad.",
                  "Se repiten dosis cada 2–4 semanas, según el producto y el protocolo veterinario, hasta al menos las 16 semanas de edad.",
                  "Los refuerzos posteriores dependen de la vacuna utilizada y de las recomendaciones profesionales.",
                  "La vacuna antirrábica se aplica según la edad autorizada y la normativa local.",
                  "Las desparasitaciones también deben planificarse con el veterinario.",
                  "No dupliques vacunas ni reinicies el esquema por tu cuenta si no tienes su cartilla. Pide al veterinario que revise su historial y establezca las fechas siguientes."
                ]
              }
            ]
          },
          "veterinario": {
            "titulo": "CUÁNDO IR AL VETERINARIO",
            "secciones": [
              {
                "titulo": "Información",
                "items": [
                  "Controles rutinarios",
                  "Al llegar a casa o al ser adoptado.",
                  "Para controlar su crecimiento, dientes, peso y desarrollo.",
                  "Para recibir vacunas y desparasitaciones.",
                  "Si tiene picazón persistente, mal aliento, tos o molestias que no desaparecen.",
                  "Emergencias",
                  "Dificultad para respirar.",
                  "Desmayo, convulsiones o falta de respuesta.",
                  "Temblores con debilidad o desorientación.",
                  "Vómitos o diarrea repetidos, especialmente con sangre.",
                  "Sospecha de intoxicación.",
                  "Sangrado importante, golpe fuerte o caída desde una altura.",
                  "Incapacidad para caminar o dolor intenso.",
                  "Abdomen hinchado y doloroso."
                ]
              }
            ]
          }
        }
      },
      "adulto": {
        "tituloOriginal": "CHIHUAHUA ADULTO (APROXIMADAMENTE DE 1 A 9 AÑOS)",
        "temas": {
          "alimentacion": {
            "titulo": "ALIMENTACIÓN",
            "secciones": [
              {
                "titulo": "Información",
                "items": [
                  "Un Chihuahua adulto necesita una dieta completa para perros adultos de raza pequeña. La cantidad depende de su peso, edad, actividad, esterilización y condición corporal."
                ]
              },
              {
                "titulo": "ALIMENTACIÓN SALUDABLE",
                "items": [
                  "Alimento completo para adultos: elige una fórmula de calidad adecuada para perros pequeños.",
                  "Porciones medidas: utiliza la cantidad recomendada como punto de partida y ajústala con el veterinario.",
                  "Comidas regulares: muchos adultos se benefician de dos comidas diarias; algunos necesitan un horario diferente por motivos médicos.",
                  "Agua fresca: mantenla disponible todo el día.",
                  "Proteínas adecuadas: un alimento equilibrado ayuda a mantener los músculos.",
                  "Grasas y ácidos grasos esenciales: contribuyen a una piel y un pelaje saludables.",
                  "Fibra apropiada: favorece el funcionamiento digestivo.",
                  "Premios moderados: evita que los premios sustituyan una parte importante de su dieta.",
                  "Control de peso: revisa su peso periódicamente y pide orientación si aumenta o disminuye sin explicación.",
                  "Cambios graduales: introduce nuevos alimentos poco a poco y vigila la tolerancia digestiva."
                ]
              },
              {
                "titulo": "ALIMENTACIÓN NO SALUDABLE",
                "items": [
                  "Chocolate, café y productos con cafeína.",
                  "Uvas y pasas.",
                  "Cebolla, ajo y cebollín.",
                  "Productos con xilitol.",
                  "Huesos cocidos y alimentos que puedan causar atragantamiento.",
                  "Comidas muy saladas, fritas o grasosas.",
                  "Sobras condimentadas o con salsas desconocidas.",
                  "Suplementos de vitaminas, calcio o minerales sin indicación.",
                  "Alimentación exclusivamente casera sin una formulación nutricional profesional.",
                  "Darle comida en exceso o permitir que gane peso continuamente."
                ]
              },
              {
                "titulo": "Información",
                "items": [
                  "Sobrepeso, pérdida de peso o comidas sin horarios consistentes.",
                  "Premios en exceso o comida humana como base de la dieta.",
                  "Falta de agua limpia.",
                  "Ejercicio y seguridad",
                  "Pasa todo el día sin actividad ni interacción.",
                  "Realiza saltos arriesgados desde muebles altos.",
                  "Se expone a temperaturas extremas.",
                  "Utiliza un collar o arnés que le causa molestias.",
                  "Bienestar emocional",
                  "Ladra excesivamente por miedo o angustia.",
                  "Se esconde de manera persistente o reacciona con temor al contacto.",
                  "No tiene oportunidades de explorar, jugar y descansar.",
                  "Es castigado físicamente por comportamientos que necesitan entrenamiento."
                ]
              }
            ]
          },
          "salud": {
            "titulo": "SALUD",
            "secciones": [
              {
                "titulo": "SEÑALES DE BUENA SALUD",
                "items": [
                  "Mantiene un peso adecuado para su tamaño y constitución.",
                  "Camina, corre y juega sin dolor.",
                  "Come y bebe normalmente.",
                  "Tiene respiración tranquila en reposo.",
                  "Sus ojos están limpios y su mirada es habitual.",
                  "Su piel y pelaje no muestran irritación persistente.",
                  "Sus heces y su orina no presentan cambios preocupantes.",
                  "Sus dientes y encías reciben atención regular.",
                  "Mantiene su calendario preventivo.",
                  "Tiene un comportamiento y un nivel de energía habituales."
                ]
              },
              {
                "titulo": "SEÑALES DE MALA SALUD",
                "items": [
                  "Tos frecuente, respiración ruidosa o dificultad respiratoria.",
                  "Dientes flojos, encías inflamadas o dolor al masticar.",
                  "Cojera, rigidez o dolor al subir y bajar.",
                  "Vómitos repetidos o diarrea persistente.",
                  "Aumento de sed u orina sin explicación.",
                  "Pérdida o aumento de peso inesperado.",
                  "Bultos nuevos o cambios en los existentes.",
                  "Picazón intensa, heridas o pérdida de pelo.",
                  "Desorientación, debilidad o cambios bruscos de conducta.",
                  "Dificultad para orinar, sangre en la orina o incapacidad para hacerlo."
                ]
              }
            ]
          },
          "primeros": {
            "titulo": "PRIMEROS AUXILIOS",
            "secciones": [
              {
                "titulo": "QUÉ HACER CUANDO LE OCURRE UN ACCIDENTE",
                "items": [
                  "CAIDAS O GOLPES",
                  "Limita sus movimientos y evita que salte.",
                  "Observa si hay dolor, cojera, sangrado o cambios de comportamiento.",
                  "No manipules una articulación lesionada ni intentes recolocar huesos.",
                  "Si el golpe fue fuerte o tiene dificultades para caminar o respirar, acude inmediatamente al veterinario.",
                  "HERIDAS Y SANGRADO",
                  "Aplica presión constante con una gasa limpia.",
                  "No retires objetos incrustados.",
                  "No pongas alcohol, agua oxigenada ni polvos caseros en la herida.",
                  "Si es profunda, extensa o no deja de sangrar, busca atención urgente.",
                  "ATRAGANTAMIENTO",
                  "No introduzcas los dedos a ciegas en la boca.",
                  "Si no puede respirar, se desploma o sus encías cambian de color, necesita atención inmediata.",
                  "Llama a una clínica veterinaria para recibir instrucciones durante el traslado.",
                  "ENVENENAMIENTO",
                  "Aparta el producto y conserva su envase.",
                  "Llama inmediatamente al veterinario.",
                  "No provoques el vómito ni le des leche, aceite, carbón activado o medicamentos salvo indicación profesional.",
                  "QUEMADURAS",
                  "Enfría la zona con agua corriente fresca durante unos 20 minutos si puedes hacerlo con seguridad.",
                  "No apliques hielo ni cremas caseras.",
                  "Solicita valoración veterinaria, especialmente si la quemadura es extensa o afecta la cara, boca o patas.",
                  "PICADURA O MORDEDURA",
                  "Observa la aparición de hinchazón, dolor o cambios de conducta.",
                  "La dificultad respiratoria, el colapso o la hinchazón facial son emergencias.",
                  "No administres medicamentos humanos por tu cuenta.",
                  "VÓMITO O DIARREA",
                  "Vigila la frecuencia y el estado general.",
                  "Ofrece acceso a agua, pero no lo obligues a beber.",
                  "Consulta al veterinario si los episodios se repiten o persisten.",
                  "Acude urgentemente si hay sangre, debilidad marcada, dolor abdominal o incapacidad para retener agua."
                ]
              }
            ]
          },
          "cuidados": {
            "titulo": "CUIDADOS",
            "secciones": [
              {
                "titulo": "CÓMO MANTENERLO BIEN CUIDADO",
                "items": [
                  "Temperatura: protégelo del frío y evita cambios bruscos de temperatura.",
                  "Paseos: realiza paseos diarios acordes con su energía y condición física.",
                  "Juego: ofrece juegos seguros que le permitan explorar y usar su olfato.",
                  "Arnés: utiliza un arnés bien ajustado en vez de tirar de su cuello con la correa.",
                  "Cepillado: adapta la frecuencia al tipo de pelo; el de pelo largo necesita más atención.",
                  "Baño: báñalo cuando lo necesite con productos específicos para perros y sécalo bien.",
                  "Salud dental: cepilla sus dientes regularmente con pasta canina y programa revisiones dentales.",
                  "Uñas: revisa y recorta sus uñas periódicamente.",
                  "Orejas y ojos: observa si hay secreciones, irritación o mal olor.",
                  "Prevención de parásitos: sigue las indicaciones veterinarias según el ambiente en que vive.",
                  "Enriquecimiento: ofrece juguetes apropiados, aprendizaje y contacto social.",
                  "Seguridad: evita que salte de lugares altos y mantén productos tóxicos fuera de su alcance.",
                  "Clima boliviano: en zonas frías, proporciona abrigo y un lugar interior templado; en zonas cálidas, sombra, agua y ventilación.",
                  "Identificación: utiliza una placa o identificación actualizada."
                ]
              },
              {
                "titulo": "CÓMO SABER SI NO TIENE UN BUEN CUIDADO",
                "items": [
                  "Higiene",
                  "Pelaje enmarañado, suciedad persistente o mal olor.",
                  "Uñas demasiado largas.",
                  "Dientes con sarro evidente o encías inflamadas.",
                  "Orejas irritadas o con secreciones."
                ]
              }
            ]
          },
          "comportamiento": {
            "titulo": "COMPORTAMIENTO",
            "secciones": [
              {
                "titulo": "ADIESTRAMIENTO Y EDUCACIÓN DEL ADULTO",
                "items": [
                  "Refuerzo positivo: recompensa con premios pequeños, juguetes o elogios.",
                  "Órdenes básicas: practica “ven”, “siéntate”, “espera” y “deja”.",
                  "Paseos tranquilos: enséñale a caminar sin tirar de la correa.",
                  "Control de ladridos: identifica el desencadenante antes de entrenar una respuesta alternativa.",
                  "Saludar sin saltar: recompensa cuando mantiene las cuatro patas en el suelo.",
                  "Tolerar el manejo: acostúmbralo gradualmente al cepillado, corte de uñas y revisión dental.",
                  "Quedarse solo: practica ausencias breves y aumenta el tiempo gradualmente si está tranquilo.",
                  "Juegos de olfato: esconde premios seguros en lugares fáciles de encontrar.",
                  "Consistencia: todos los miembros del hogar deben aplicar las mismas reglas.",
                  "Descanso: respeta sus horas de sueño y no lo fuerces a interactuar cuando necesita espacio."
                ]
              },
              {
                "titulo": "CÓMO MEJORAR EL COMPORTAMIENTO SI NO FUE ADIESTRADO",
                "items": [
                  "Empieza con una sola conducta y practica en un lugar tranquilo.",
                  "Divide las tareas en pasos fáciles y aumenta la dificultad poco a poco.",
                  "Premia la conducta deseada inmediatamente.",
                  "No grites ni golpees al perro.",
                  "Si ladra a desconocidos, aumenta la distancia y recompensa la calma; no lo obligues a acercarse.",
                  "Si gruñe al tocarlo, detén el contacto y considera una evaluación veterinaria para descartar dolor.",
                  "Si destruye objetos cuando queda solo, evalúa su rutina y posibles signos de ansiedad.",
                  "Si hay mordidas, miedo intenso o agresividad persistente, solicita ayuda profesional basada en métodos sin castigo."
                ]
              }
            ]
          },
          "vacunacion": {
            "titulo": "VACUNACIÓN",
            "secciones": [
              {
                "titulo": "VACUNAS QUE DEBE TENER DURANTE SU VIDA",
                "items": [
                  "Moquillo canino: vacuna esencial.",
                  "Parvovirus canino: vacuna esencial.",
                  "Adenovirus canino: generalmente forma parte de la combinación esencial.",
                  "Rabia: debe mantenerse conforme al calendario veterinario y a la normativa boliviana.",
                  "Leptospirosis: según exposición y recomendación veterinaria.",
                  "Bordetella y otras vacunas respiratorias: si su estilo de vida o exposición lo justifican.",
                  "Otras vacunas: según riesgos locales y criterio profesional.",
                  "Refuerzos",
                  "Revisa su cartilla para comprobar qué vacunas recibió de cachorro.",
                  "Los refuerzos de las vacunas esenciales se programan según el producto, el historial y las recomendaciones veterinarias.",
                  "La vacuna contra la rabia debe mantenerse vigente según las reglas aplicables.",
                  "Si no hay registros fiables, no decidas por tu cuenta qué dosis necesita: el veterinario puede establecer un plan de recuperación.",
                  "Mantén también al día la desparasitación y la prevención de pulgas y garrapatas según su exposición."
                ]
              }
            ]
          },
          "veterinario": {
            "titulo": "CUÁNDO IR AL VETERINARIO",
            "secciones": [
              {
                "titulo": "Información",
                "items": [
                  "Consulta rutinaria",
                  "Para revisiones generales y dentales.",
                  "Para controles de peso y alimentación.",
                  "Para actualizar vacunas y prevención de parásitos.",
                  "Si notas cambios persistentes en la piel, el pelaje, la movilidad o el apetito.",
                  "Emergencias",
                  "Dificultad para respirar o encías azuladas o muy pálidas.",
                  "Desmayo, convulsiones o debilidad intensa.",
                  "Sospecha de intoxicación.",
                  "Sangrado abundante o lesión importante.",
                  "Dolor intenso o incapacidad para caminar.",
                  "Vómitos repetidos, sangre en vómitos o heces, o abdomen muy doloroso.",
                  "Incapacidad para orinar.",
                  "Reacción alérgica con hinchazón facial o dificultad respiratoria."
                ]
              }
            ]
          }
        }
      },
      "senior": {
        "tituloOriginal": "CHIHUAHUA SENIOR O GERIÁTRICO (APROXIMADAMENTE DESDE LOS 8–10 AÑOS)",
        "temas": {
          "alimentacion": {
            "titulo": "ALIMENTACIÓN",
            "secciones": [
              {
                "titulo": "Información",
                "items": [
                  "Un Chihuahua mayor necesita una dieta que ayude a mantener su masa muscular, peso adecuado, digestión y salud general. No todos necesitan alimento “senior”; la elección debe basarse en sus necesidades individuales."
                ]
              },
              {
                "titulo": "ALIMENTACIÓN SALUDABLE",
                "items": [
                  "Dieta completa y equilibrada: elige una fórmula para adultos mayores o una dieta veterinaria si está indicada.",
                  "Proteínas de buena calidad: ayudan a conservar los músculos, salvo que exista una enfermedad que requiera ajustes específicos.",
                  "Porciones controladas: evita el sobrepeso, que puede dificultar la movilidad.",
                  "Comidas regulares: divide su ración en horarios que tolere bien.",
                  "Agua fresca: mantenla accesible y observa si cambia su consumo.",
                  "Textura adecuada: si tiene problemas dentales, el veterinario puede recomendar alimento húmedo o una textura más fácil de masticar.",
                  "Fibra apropiada: ayuda a la regularidad intestinal cuando la dieta está bien formulada.",
                  "Ajustes según enfermedades: los problemas renales, cardíacos u otras afecciones pueden requerir dietas específicas prescritas.",
                  "Premios pequeños: utiliza premios adecuados y reduce la cantidad si gana peso.",
                  "Control periódico: revisa el peso y la condición corporal con el veterinario."
                ]
              },
              {
                "titulo": "ALIMENTACIÓN NO SALUDABLE",
                "items": [
                  "Chocolate, uvas, pasas, cebolla, ajo y xilitol.",
                  "Huesos cocidos y objetos duros que puedan fracturar sus dientes.",
                  "Comidas grasosas o muy condimentadas.",
                  "Exceso de premios y sobras.",
                  "Suplementos articulares, vitamínicos o minerales sin asesoramiento.",
                  "Cambios bruscos de dieta.",
                  "Restringir el agua para reducir la orina.",
                  "Dietas caseras no equilibradas.",
                  "Dar por hecho que debe comer mucho menos solo por su edad, sin evaluar su estado corporal."
                ]
              }
            ]
          },
          "salud": {
            "titulo": "SALUD",
            "secciones": [
              {
                "titulo": "SEÑALES DE BUENA SALUD",
                "items": [
                  "Mantiene un peso relativamente estable.",
                  "Puede levantarse, caminar y cambiar de posición sin dolor importante.",
                  "Come y bebe normalmente para su situación.",
                  "Respira con comodidad en reposo.",
                  "Conserva interés por la familia, los paseos y los juegos suaves.",
                  "Tiene una piel cuidada y un pelaje acorde con su edad.",
                  "Orina y defeca sin dificultad.",
                  "Sus dientes y encías reciben evaluación profesional.",
                  "Los cambios de visión u oído se revisan y se manejan de manera segura.",
                  "Acude a controles veterinarios con la frecuencia recomendada."
                ]
              },
              {
                "titulo": "SEÑALES DE MALA SALUD",
                "items": [
                  "Pérdida de peso o de masa muscular sin explicación.",
                  "Aumento importante de sed u orina.",
                  "Tos, dificultad respiratoria o cansancio inusual.",
                  "Cojera, rigidez o dificultad para levantarse.",
                  "Mal aliento intenso, dolor al comer o dientes flojos.",
                  "Bultos nuevos o cambios en tamaño, forma o textura de los existentes.",
                  "Desorientación, cambios del sueño o inquietud nocturna.",
                  "Vómitos, diarrea o estreñimiento persistentes.",
                  "Cambios bruscos de conducta, irritabilidad o aislamiento.",
                  "Desmayos, convulsiones, debilidad marcada o incapacidad para orinar."
                ]
              },
              {
                "titulo": "Información",
                "items": [
                  "Sus cambios de sed, peso o movilidad pasan inadvertidos.",
                  "Se omiten revisiones y tratamientos prescritos.",
                  "Se le administran medicamentos humanos sin supervisión.",
                  "Se asume que todos los síntomas son “normales por la edad”.",
                  "Bienestar emocional",
                  "Se le aísla porque juega menos que antes.",
                  "No recibe interacción amable ni estimulación mental.",
                  "Se le obliga a convivir con otros animales si está asustado o incómodo."
                ]
              }
            ]
          },
          "primeros": {
            "titulo": "PRIMEROS AUXILIOS",
            "secciones": [
              {
                "titulo": "QUÉ HACER CUANDO LE OCURRE UN ACCIDENTE",
                "items": [
                  "CAÍDAS O GOLPES",
                  "Evita que siga caminando o saltando.",
                  "Sostén su cuerpo con suavidad al trasladarlo.",
                  "No manipules una articulación ni intentes recolocar huesos.",
                  "Si hay dolor intenso, pérdida de conciencia, dificultad respiratoria o incapacidad para caminar, acude de inmediato al veterinario.",
                  "HERIDAS Y SANGRADO",
                  "Coloca una gasa limpia y ejerce presión constante.",
                  "No retires objetos incrustados ni apliques productos irritantes.",
                  "Si el sangrado no se detiene, es abundante o la herida es profunda, busca atención urgente.",
                  "ATRAGANTAMIENTO",
                  "No introduzcas los dedos a ciegas en su garganta.",
                  "Si no puede respirar o se desploma, necesita atención de emergencia.",
                  "Llama a una clínica veterinaria mientras organizas el traslado.",
                  "ENVENENAMIENTO",
                  "Aparta la sustancia y lleva el envase o una fotografía.",
                  "Contacta inmediatamente al veterinario.",
                  "No induzcas el vómito ni administres remedios caseros.",
                  "QUEMADURAS",
                  "Enfría la zona con agua corriente fresca durante unos 20 minutos si es seguro.",
                  "No uses hielo ni cremas caseras.",
                  "Busca valoración veterinaria, especialmente si la quemadura es extensa o afecta la cara o la boca.",
                  "PICADURAS O MORDEDURAS",
                  "Observa si aparecen hinchazón, debilidad o dificultad respiratoria.",
                  "Si se hincha la cara, le cuesta respirar o se desploma, acude a urgencias.",
                  "No le des medicamentos humanos sin instrucciones profesionales.",
                  "VÓMITOS O DIARREA",
                  "Vigila su energía, frecuencia de los episodios y capacidad para beber.",
                  "No lo obligues a comer ni le des medicamentos por tu cuenta.",
                  "Busca atención pronto si los síntomas persisten, especialmente si tiene enfermedades previas.",
                  "Si hay sangre, dolor intenso, debilidad marcada o no puede retener agua, acude urgentemente."
                ]
              }
            ]
          },
          "cuidados": {
            "titulo": "CUIDADOS",
            "secciones": [
              {
                "titulo": "CÓMO MANTENERLO BIEN CUIDADO",
                "items": [
                  "Revisiones veterinarias: los controles pueden necesitar mayor frecuencia según su salud y los hallazgos clínicos.",
                  "Chequeos dentales: vigila el dolor al masticar y solicita tratamiento si hay enfermedad dental.",
                  "Ejercicio suave: ofrece paseos cortos y regulares según su movilidad.",
                  "Temperatura: proporciona una cama cálida, seca y alejada de corrientes de aire.",
                  "Accesibilidad: coloca agua, comida y cama en lugares fáciles de alcanzar.",
                  "Prevención de caídas: utiliza rampas o escalones seguros y evita que salte desde muebles altos.",
                  "Uñas: mantenlas a una longitud adecuada para ayudarle a caminar con estabilidad.",
                  "Cepillado: adapta la frecuencia al tipo de pelaje y a la sensibilidad de su piel.",
                  "Baño cuidadoso: evita que pase frío y sécalo bien.",
                  "Descanso: permite que duerma sin interrupciones.",
                  "Estimulación mental: utiliza juegos de olfato sencillos y sesiones breves de aprendizaje.",
                  "Observación diaria: vigila cambios de apetito, sed, respiración, movilidad y conducta.",
                  "Visión y oído: mantén los muebles en posiciones estables y acércate de forma suave para no sobresaltarlo.",
                  "Medicación: administra únicamente los medicamentos prescritos y sigue las dosis veterinarias.",
                  "Clima de Bolivia: en lugares fríos, mantenlo abrigado y seco; en lugares calurosos, evita el sobrecalentamiento y ofrece agua y sombra."
                ]
              },
              {
                "titulo": "CÓMO SABER SI NO TIENE UN BUEN CUIDADO",
                "items": [
                  "Higiene",
                  "Tiene las uñas tan largas que alteran su forma de caminar.",
                  "Presenta dolor dental o mal olor persistente en la boca.",
                  "Su pelaje está descuidado o la piel presenta lesiones.",
                  "Permanece húmedo o expuesto al frío después del baño.",
                  "Movilidad y comodidad",
                  "Debe saltar para llegar a su cama o comida.",
                  "Resbala en superficies lisas sin disponer de zonas antideslizantes.",
                  "Se le obliga a hacer ejercicio pese al dolor o al cansancio.",
                  "No tiene un lugar tranquilo para descansar."
                ]
              }
            ]
          },
          "comportamiento": {
            "titulo": "COMPORTAMIENTO",
            "secciones": [
              {
                "titulo": "ADIESTRAMIENTO Y ESTIMULACIÓN EN LA VEJEZ",
                "items": [
                  "Sesiones breves: practica durante unos minutos y deja que descanse.",
                  "Órdenes conocidas: refuerza “ven”, “espera” y otras señales que ya comprenda.",
                  "Premios adecuados: usa cantidades pequeñas que encajen en su dieta.",
                  "Estimulación olfativa: permite que busque premios en lugares fáciles y seguros.",
                  "Rutinas previsibles: conserva horarios consistentes para pasear, comer y dormir.",
                  "Adaptación física: evita exigir saltos o posturas que le causen molestias.",
                  "Paciencia: si tarda más en responder, dale tiempo y utiliza señales claras.",
                  "Contacto respetuoso: no lo despiertes bruscamente ni lo manipules si parece dolorido.",
                  "Cambios graduales: introduce nuevas rutinas lentamente.",
                  "Evaluación de cambios: consulta al veterinario si parece confundido, deja de responder a señales conocidas o muestra una alteración repentina de conducta."
                ]
              },
              {
                "titulo": "CÓMO MEJORAR SU COMPORTAMIENTO SI NO FUE ADIESTRADO",
                "items": [
                  "Mantén una rutina sencilla y constante.",
                  "Enséñale una habilidad cada vez con recompensas positivas.",
                  "Adapta el entrenamiento a su movilidad, vista y oído.",
                  "Si hace sus necesidades dentro de casa, aumenta las oportunidades de salir y consulta si hay cambios urinarios.",
                  "Si ladra o se inquieta de noche, revisa primero si necesita salir, tiene dolor o está desorientado.",
                  "No castigues la confusión, los accidentes ni los cambios relacionados con la edad.",
                  "Si presenta desorientación persistente, dolor o ansiedad, solicita una evaluación veterinaria antes de atribuirlo únicamente a la vejez."
                ]
              }
            ]
          },
          "vacunacion": {
            "titulo": "VACUNACIÓN",
            "secciones": [
              {
                "titulo": "VACUNAS QUE DEBE TENER DURANTE SU VIDA",
                "items": [
                  "Moquillo canino: refuerzos de acuerdo con su historial y las recomendaciones veterinarias.",
                  "Parvovirus canino: mantener la protección según el esquema indicado.",
                  "Adenovirus canino: seguir el calendario de vacunas esenciales.",
                  "Rabia: mantener la vacunación vigente conforme a las reglas aplicables en Bolivia.",
                  "Leptospirosis: si el veterinario considera que su exposición lo justifica.",
                  "Bordetella y otras vacunas respiratorias: según contacto con otros perros y estilo de vida.",
                  "Otras vacunas: solo cuando correspondan a los riesgos de la zona y a su situación individual.",
                  "Cuidados especiales para el senior",
                  "Lleva su cartilla a las revisiones.",
                  "El veterinario debe revisar las dosis anteriores y decidir los refuerzos necesarios.",
                  "La edad avanzada, por sí sola, no significa que deba suspender todas las vacunas.",
                  "Si tiene una enfermedad crónica, el veterinario adaptará el calendario según su estado.",
                  "Mantén la prevención de parásitos y los controles dentales y generales."
                ]
              }
            ]
          },
          "veterinario": {
            "titulo": "CUÁNDO IR AL VETERINARIO",
            "secciones": [
              {
                "titulo": "Información",
                "items": [
                  "Consulta programada",
                  "Para controles de salud y evaluación de movilidad.",
                  "Para revisar dientes, peso, piel y pelaje.",
                  "Para evaluar cambios de visión, oído, sed o apetito.",
                  "Para revisar medicamentos y ajustar la alimentación.",
                  "Para mantener las vacunas y la prevención de parásitos.",
                  "Emergencias",
                  "Dificultad para respirar.",
                  "Desmayo, convulsiones o falta de respuesta.",
                  "Debilidad intensa o incapacidad repentina para levantarse.",
                  "Sospecha de intoxicación.",
                  "Sangrado abundante o lesión importante.",
                  "Vómitos repetidos, sangre en las heces o dolor abdominal intenso.",
                  "Incapacidad para orinar.",
                  "Hinchazón facial con dificultad respiratoria.",
                  "Dolor intenso o deterioro repentino."
                ]
              },
              {
                "titulo": "RECOMENDACIONES FINALES PARA TODAS LAS EDADES",
                "items": [
                  "El Chihuahua es pequeño, pero necesita ejercicio, educación, compañía y atención veterinaria como cualquier otro perro.",
                  "Protégelo de las caídas, los saltos desde alturas y la manipulación brusca.",
                  "Evita que pase frío, especialmente si es cachorro, mayor o tiene poco pelo.",
                  "No le des medicamentos humanos ni remedios caseros sin indicación veterinaria.",
                  "Mantén su cartilla de vacunación actualizada y consulta qué vacunas corresponden según su entorno en Bolivia.",
                  "No todos los Chihuahua tienen los mismos problemas de salud: observa sus necesidades individuales y pide ayuda profesional ante cambios importantes.",
                  "Si muestra signos de emergencia, no esperes a que desaparezcan por sí solos.",
                  "La mejor manera de cuidar a un Chihuahua es combinar una alimentación adecuada, un ambiente seguro, educación amable, prevención veterinaria y mucho respeto por su tamaño y sus necesidades."
                ]
              }
            ]
          }
        },
        "introduccion": {
          "titulo": "Información de esta etapa",
          "items": [
            "La edad a la que un Chihuahua se considera senior varía según su estado de salud. Muchos viven bastantes años, pero necesitan revisiones más cuidadosas a medida que envejecen. No todos desarrollan las mismas enfermedades."
          ]
        }
      }
    }
  }
};
